function getCategoryIcon(category: string): React.ElementType {
  switch (category) {
    case "veiculos":
      return Car;
    case "imoveis":
      return Home;
    case "eletronicos":
      return Laptop;
    case "roupas":
      return Shirt;
    case "moveis":
      return Sofa;
    case "esportes":
      return Bike;
    case "outros":
      return Package;
    default:
      return Package;
  }
}

function getStatusConfig(status: string): { label: string; color: string; dot: string } {
  switch (status) {
    case "active":
      return STATUS_CONFIG.active;
    case "reserved":
      return STATUS_CONFIG.reserved;
    case "sold":
      return STATUS_CONFIG.sold;
    default:
      return STATUS_CONFIG.active;
  }
}

function getCategoryName(category: string): string {
  switch (category) {
    case "veiculos":
      return CATEGORY_NAMES.veiculos;
    case "imoveis":
