/**
 * Email Logs Page
 * 
 * View email history and status.
 */

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/shared/components/ui/card';
import { Badge } from '@/shared/components/ui/badge';
import { Button } from '@/shared/components/ui/button';
import { useEmail } from '@/core/notifications/hooks/useEmail';
import { useAuth } from '@/core/auth/hooks/useAuth';
import { Mail, RefreshCw, CheckCircle, XCircle, AlertCircle } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { ptBR } from 'date-fns/locale';

export default function EmailLogsPage() {
  const { user } = useAuth();
  const { emailLogs, isLoadingLogs, refetchLogs } = useEmail(user?.id);

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'sent':
        return <CheckCircle className="h-4 w-4 text-green-500" />;
      case 'failed':
        return <XCircle className="h-4 w-4 text-red-500" />;
      case 'bounced':
        return <AlertCircle className="h-4 w-4 text-yellow-500" />;
      default:
        return <Mail className="h-4 w-4 text-gray-500" />;
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'sent':
        return <Badge variant="default" className="bg-green-500">Enviado</Badge>;
      case 'failed':
        return <Badge variant="destructive">Falhou</Badge>;
      case 'bounced':
        return <Badge variant="secondary" className="bg-yellow-500">Devolvido</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  const getCategoryBadge = (category: string) => {
    const colors: Record<string, string> = {
      transactional: 'bg-blue-500',
      social: 'bg-purple-500',
      system: 'bg-orange-500',
      marketing: 'bg-pink-500',
    };

    return (
      <Badge variant="secondary" className={colors[category] || 'bg-gray-500'}>
        {category}
      </Badge>
    );
  };

  return (
    <div className="container mx-auto py-8 px-4">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-bold flex items-center gap-2">
              <Mail className="h-8 w-8" />
              Histórico de Emails
            </h1>
            <p className="text-muted-foreground mt-1">
              Visualize todos os emails enviados para sua conta
            </p>
          </div>
          <Button
            onClick={() => refetchLogs()}
            disabled={isLoadingLogs}
            variant="outline"
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${isLoadingLogs ? 'animate-spin' : ''}`} />
            Atualizar
          </Button>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-muted-foreground">
                Total
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{emailLogs.length}</div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-muted-foreground">
                Enviados
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-green-500">
                {emailLogs.filter((log) => log.status === 'sent').length}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-muted-foreground">
                Falharam
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-red-500">
                {emailLogs.filter((log) => log.status === 'failed').length}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-muted-foreground">
                Devolvidos
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-yellow-500">
                {emailLogs.filter((log) => log.status === 'bounced').length}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Email List */}
        <Card>
          <CardHeader>
            <CardTitle>Emails Enviados</CardTitle>
            <CardDescription>
              Últimos 50 emails enviados para sua conta
            </CardDescription>
          </CardHeader>
          <CardContent>
            {isLoadingLogs ? (
              <div className="text-center py-8 text-muted-foreground">
                Carregando...
              </div>
            ) : emailLogs.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                <Mail className="h-12 w-12 mx-auto mb-4 opacity-50" />
                <p>Nenhum email enviado ainda</p>
              </div>
            ) : (
              <div className="space-y-4">
                {emailLogs.map((log) => (
                  <div
                    key={log.id}
                    className="flex items-start gap-4 p-4 border rounded-lg hover:bg-accent/50 transition-colors"
                  >
                    <div className="mt-1">{getStatusIcon(log.status)}</div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <h3 className="font-medium truncate">{log.subject}</h3>
                        {getStatusBadge(log.status)}
                        {getCategoryBadge(log.category)}
                      </div>

                      <p className="text-sm text-muted-foreground mb-2">
                        Para: {log.recipient_email}
                      </p>

                      {log.error_message && (
                        <div className="bg-red-50 dark:bg-red-950 border border-red-200 dark:border-red-800 rounded p-2 mb-2">
                          <p className="text-sm text-red-600 dark:text-red-400">
                            <strong>Erro:</strong> {log.error_message}
                          </p>
                        </div>
                      )}

                      <p className="text-xs text-muted-foreground">
                        {formatDistanceToNow(new Date(log.sent_at), {
                          addSuffix: true,
                          locale: ptBR,
                        })}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Info */}
        <Card className="mt-6">
          <CardHeader>
            <CardTitle className="text-sm">Sobre os Emails</CardTitle>
          </CardHeader>
          <CardContent className="text-sm text-muted-foreground space-y-2">
            <p>
              <strong>Transacionais:</strong> Emails importantes relacionados à sua conta
              (confirmações, redefinição de senha, etc.)
            </p>
            <p>
              <strong>Sistema:</strong> Notificações do sistema (alertas de segurança, MFA, etc.)
            </p>
            <p>
              <strong>Sociais:</strong> Notificações de interações sociais (mensagens, comentários, etc.)
            </p>
            <p>
              <strong>Marketing:</strong> Promoções e novidades (pode ser desativado nas preferências)
            </p>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

/**
 * NearbyPage — Hub central "Perto de Mim"
 *
 * Página principal de descoberta do usuário, reunindo empresas, gastronomia,
 * serviços, classificados e pontos turísticos de forma organizada e contextual.
 *
 * REFATORADO: Usa useResolvedUserLocation (SSOT) com fallback territorial.
 * GPS não é obrigatório — a página funciona sempre.
 *
 * @module pages
 */

import React, { useState, useMemo, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { motion } from 'framer-motion';
import { CanonicalHero } from '@/shared/components/hero/CanonicalHero';
import { useNearbyEntities } from '@/modules/community/nearby/hooks/useNearbyEntities';
import type { NearbyEntity } from '@/modules/community/nearby/hooks/useNearbyEntities';
import {
  NearbyCard,
  NearbySection,
  NearbyMiniMap,
  NearbyClassifiedsSection,
  NearbyFilters,
  QUICK_CATEGORIES,
} from '@/modules/community/nearby/components';
import type { QuickCategoryKey } from '@/modules/community/nearby/components';
import { Button } from '@/shared/components/ui/button';
import {
  useLocationContext,
  useTerritoryLabels,
  TerritoryIndicator,
  useResolvedUserLocation,
} from '@/core/location';
import { TerritorySelectorV2 } from '@/core/location/components/TerritorySelectorV2';
import type { ResolvedTerritory } from '@/core/routing/hooks/useResolveTerritoryFromUrl';
import { useFriendlyModuleUrls } from '@/core/routing/hooks/useFriendlyModuleUrls';
import {
  MapPin, Navigation, Loader2, Store, Calendar, AlertTriangle,
  Landmark, Compass, ChevronRight, TrendingUp, Sparkles,
  UtensilsCrossed, Briefcase, Map, Info,
} from 'lucide-react';

// ============================================================================
// TYPES & CONSTANTS
// ============================================================================

const ALL_ENTITY_TYPES = ['business', 'event', 'alert', 'tourist_point'] as const;

const CATEGORY_TO_TYPES: Record<QuickCategoryKey, typeof ALL_ENTITY_TYPES[number][]> = {
  all: [...ALL_ENTITY_TYPES],
  food: ['business'],
  shopping: ['business'],
  services: ['business'],
  health: ['business'],
  education: ['business'],
  leisure: ['event', 'tourist_point'],
  fitness: ['business'],
  tourism: ['tourist_point'],
  events: ['event'],
  alerts: ['alert'],
};

// ============================================================================
// ANIMATIONS
// ============================================================================

const fadeIn = {
  hidden: { opacity: 0, y: 24 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.5 } },
};

const stagger = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.05, delayChildren: 0.1 } },
};

const itemVariants = {
  hidden: { opacity: 0, y: 16 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.3 } },
};

// ============================================================================
// HELPERS
// ============================================================================

function groupByType(entities: NearbyEntity[]) {
  const groups: Record<string, NearbyEntity[]> = {};
  for (const e of entities) {
    (groups[e.type] ??= []).push(e);
  }
  return groups;
}

// ============================================================================
// COMPONENT
// ============================================================================

export default function NearbyPage() {
  const navigate = useNavigate();
  const moduleUrls = useFriendlyModuleUrls();

  // ── SSOT: Contexto territorial ativo ───────────────────────────────
  const { activeLocation, activeTerritory } = useLocationContext();
  
  const resolved: ResolvedTerritory | null = activeTerritory?.location
    ? { kind: 'location', location: activeTerritory.location }
    : null;
  
  const territoryLabels = useTerritoryLabels(resolved);

  // ── SSOT: Posição do usuário com fallback territorial ──────────────
  const {
    coords: userLocation,
    status: locationStatus,
    isGps,
    isGoodForProximity,
    sourceMessage,
    resolve: resolveLocation,
    isLoading: locationLoading,
  } = useResolvedUserLocation({ autoResolve: true, tryGps: true });

  // ── State ──────────────────────────────────────────────────────────
  const [radiusKm, setRadiusKm] = useState(5);
  const [activeCategory, setActiveCategory] = useState<QuickCategoryKey>('all');
  const [visibleCount, setVisibleCount] = useState(12);
  const [highlightedItemId, setHighlightedItemId] = useState<string | null>(null);

  // ── Derived entity types from category ─────────────────────────────
  const entityTypes = useMemo(
    () => CATEGORY_TO_TYPES[activeCategory] || [...ALL_ENTITY_TYPES],
    [activeCategory],
  );

  // ── Data (SSOT) ────────────────────────────────────────────────────
  const { entities, isLoading: entitiesLoading, isError } = useNearbyEntities({
    radiusKm,
    entityTypes: entityTypes as any,
    center: userLocation,
    locationId: activeLocation?.id,
    limit: 100,
  });

  const isLoading = entitiesLoading;

  // ── Grouped entities ───────────────────────────────────────────────
  const grouped = useMemo(() => groupByType(entities), [entities]);
  const businesses = grouped.business || [];
  const events = grouped.event || [];
  const alerts = grouped.alert || [];
  const touristPoints = grouped.tourist_point || [];

  // ── Visible for "all results" list ──────────────────────────────────
  const displayedEntities = entities.slice(0, visibleCount);
  const canLoadMore = visibleCount < entities.length;

  // ── Handlers ───────────────────────────────────────────────────────
  const handleCategoryChange = useCallback((key: QuickCategoryKey) => {
    setActiveCategory(key);
    setVisibleCount(12);
  }, []);

  const handleRadiusChange = useCallback((r: number) => {
    setRadiusKm(r);
    setVisibleCount(12);
  }, []);

  const handleLoadMore = useCallback(() => {
    setVisibleCount((v) => v + 12);
  }, []);

  const handleShowClassifiedInMap = useCallback((ad: any) => {
    const mapSection = document.querySelector('[aria-label="Mapa"]');
    if (mapSection) {
      mapSection.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setHighlightedItemId(ad.id);
      setTimeout(() => setHighlightedItemId(null), 3000);
    }
  }, []);

  // ── Contexto de distância (GPS vs territorial) ─────────────────────
  const distanceContext = isGps ? 'proximity' : 'territorial';
  const proximityLabel = isGps ? 'perto de você' : territoryLabels.inTerritory;

  return (
    <>
      <Helmet>
        <title>{`${territoryLabels.nearbyLabel} — ${entities.length} resultados em ${radiusKm}km`}</title>
        <meta
          name="description"
          content={`Descubra empresas, eventos, serviços e pontos turísticos ${proximityLabel} em um raio de ${radiusKm}km.`}
        />
      </Helmet>

      <div className="min-h-screen bg-background">
        {/* ================================================================
            HERO (CanonicalHero SSOT)
        ================================================================ */}
        <CanonicalHero
          moduleName={territoryLabels.nearbyLabel}
          moduleIcon={Compass}
          title="Descubra o que está"
          titleHighlight={proximityLabel}
          subtitle={`Empresas, gastronomia, serviços, eventos e pontos turísticos — tudo organizado ${
            isGps ? 'por proximidade' : `${territoryLabels.inTerritory}`
          }.`}
          stats={[
            { value: `${radiusKm}km`, label: 'raio' },
            { value: String(entities.length), label: entities.length === 1 ? 'resultado' : 'resultados' },
            { value: String(businesses.length), label: 'empresas' },
          ]}
        />

        {/* ================================================================
            TERRITORY SELECTOR & LOCATION SOURCE INDICATOR
        ================================================================ */}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 py-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 border-b border-border/30">
          <div className="flex items-center gap-3">
            <TerritorySelectorV2 compact={false} />
          </div>
          <div className="flex items-center gap-3">
            {activeLocation && (
              <TerritoryIndicator resolved={resolved} />
            )}
          </div>
        </div>

        {/* ── Location source banner ──────────────────────────────── */}
        {locationStatus !== 'idle' && locationStatus !== 'resolving' && (
          <div className={`max-w-7xl mx-auto px-4 sm:px-6 py-2 ${
            isGps ? 'bg-green-500/5' : 'bg-amber-500/5'
          }`}>
            <div className="flex items-center justify-between gap-2 text-sm">
              <div className="flex items-center gap-2">
                {isGps ? (
                  <Navigation className="h-3.5 w-3.5 text-green-600" />
                ) : (
                  <Info className="h-3.5 w-3.5 text-amber-600" />
                )}
                <span className={isGps ? 'text-green-700' : 'text-amber-700'}>
                  {sourceMessage}
                </span>
              </div>
              {!isGps && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="text-xs h-7 px-3"
                  onClick={() => resolveLocation()}
                >
                  <Navigation className="h-3 w-3 mr-1" />
                  Usar GPS
                </Button>
              )}
            </div>
          </div>
        )}

        {/* ================================================================
            FILTERS (sticky)
        ================================================================ */}
        <div className="sticky top-0 z-40 border-b border-border/50 bg-background/95 backdrop-blur-lg">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 py-4">
            <NearbyFilters
              radiusKm={radiusKm}
              onRadiusChange={handleRadiusChange}
              activeCategory={activeCategory}
              onCategoryChange={handleCategoryChange}
              resultCount={entities.length}
            />
          </div>
        </div>

        {/* ================================================================
            LOADING
        ================================================================ */}
        {isLoading && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 py-16 text-center">
            <Loader2 className="h-10 w-10 animate-spin text-primary mx-auto mb-4" />
            <p className="text-muted-foreground">
              {locationLoading ? 'Obtendo sua localização...' : 'Buscando locais próximos...'}
            </p>
          </div>
        )}

        {/* ================================================================
            ERROR
        ================================================================ */}
        {isError && !isLoading && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 py-16 text-center">
            <div className="p-4 rounded-full bg-destructive/10 inline-block mb-4">
              <AlertTriangle className="h-10 w-10 text-destructive" />
            </div>
            <h3 className="text-xl font-display font-bold text-foreground mb-2">
              Erro ao buscar locais
            </h3>
            <p className="text-muted-foreground mb-6">
              Não foi possível buscar entidades próximas. Tente novamente.
            </p>
            <Button onClick={() => window.location.reload()} variant="outline" className="rounded-full">
              Tentar Novamente
            </Button>
          </div>
        )}

        {/* ================================================================
            CONTENT SECTIONS
        ================================================================ */}
        {!isLoading && !isError && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 divide-y divide-border/30">

            {/* ── Mini Mapa ───────────────────────────────────────── */}
            <NearbySection
              title={territoryLabels.mapLabel}
              subtitle={isGps ? `Seus arredores em ${radiusKm}km` : `Mapa ${territoryLabels.inTerritory}`}
              icon={Map}
              iconColorClass="bg-accent/10 text-accent-foreground"
            >
              <NearbyMiniMap
                userLocation={userLocation}
                entities={entities}
                radiusKm={radiusKm}
              />
            </NearbySection>

            {/* ── Empresas ────────────────────────────────────────── */}
            <NearbySection
              title={`Empresas ${proximityLabel}`}
              subtitle="Lojas, restaurantes e mais"
              icon={Store}
              iconColorClass="bg-blue-500/10 text-blue-500"
              count={businesses.length}
              isEmpty={businesses.length === 0}
              isLoading={isLoading}
              onSeeAll={businesses.length > 6 ? () => navigate(moduleUrls.business) : undefined}
            >
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {businesses.slice(0, 6).map((e) => (
                  <NearbyCard key={e.id} entity={e} onNavigate={navigate} />
                ))}
              </div>
            </NearbySection>

            {/* ── Gastronomia ─────────────────────────────────────── */}
            <NearbySection
              title={`Gastronomia ${proximityLabel}`}
              subtitle={isGps ? "O que comer por perto" : `Onde comer ${territoryLabels.inTerritory}`}
              icon={UtensilsCrossed}
              iconColorClass="bg-orange-500/10 text-orange-500"
              count={businesses.filter((b) => b.metadata?.category === 'food' || b.metadata?.gastronomy_profile).length}
              isEmpty={businesses.filter((b) => b.metadata?.category === 'food' || b.metadata?.gastronomy_profile).length === 0}
              onSeeAll={() => navigate(moduleUrls.gastronomy)}
            >
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {businesses
                  .filter((b) => b.metadata?.category === 'food' || b.metadata?.gastronomy_profile)
                  .slice(0, 6)
                  .map((e) => (
                    <NearbyCard key={e.id} entity={e} onNavigate={navigate} />
                  ))}
              </div>
            </NearbySection>

            {/* ── Serviços / Profissionais ─────────────────────────── */}
            <NearbySection
              title={`Serviços ${proximityLabel}`}
              subtitle={isGps ? "Encontre quem resolve por perto" : `Profissionais ${territoryLabels.inTerritory}`}
              icon={Briefcase}
              iconColorClass="bg-indigo-500/10 text-indigo-500"
              count={businesses.filter((b) => b.metadata?.category === 'services').length}
              isEmpty={businesses.filter((b) => b.metadata?.category === 'services').length === 0}
              onSeeAll={() => navigate(moduleUrls.services)}
            >
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {businesses
                  .filter((b) => b.metadata?.category === 'services')
                  .slice(0, 6)
                  .map((e) => (
                    <NearbyCard key={e.id} entity={e} onNavigate={navigate} />
                  ))}
              </div>
            </NearbySection>

            {/* ── Classificados ────────────────────────────────────── */}
            <NearbyClassifiedsSection
              userLocation={userLocation}
              radiusKm={radiusKm}
              limit={6}
              resolved={resolved}
              onShowInMap={handleShowClassifiedInMap}
            />

            {/* ── Eventos ─────────────────────────────────────────── */}
            <NearbySection
              title={`Eventos ${proximityLabel}`}
              subtitle={isGps ? "O que está acontecendo por perto" : `Eventos ${territoryLabels.inTerritory}`}
              icon={Calendar}
              iconColorClass="bg-green-500/10 text-green-500"
              count={events.length}
              isEmpty={events.length === 0}
              isLoading={isLoading}
              onSeeAll={events.length > 6 ? () => navigate(moduleUrls.events) : undefined}
            >
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {events.slice(0, 6).map((e) => (
                  <NearbyCard key={e.id} entity={e} onNavigate={navigate} />
                ))}
              </div>
            </NearbySection>

            {/* ── Pontos Turísticos ────────────────────────────────── */}
            <NearbySection
              title={`Pontos turísticos ${proximityLabel}`}
              subtitle={isGps ? "Explore os arredores" : `Lugares para conhecer ${territoryLabels.inTerritory}`}
              icon={Landmark}
              iconColorClass="bg-purple-500/10 text-purple-500"
              count={touristPoints.length}
              isEmpty={touristPoints.length === 0}
              isLoading={isLoading}
              onSeeAll={touristPoints.length > 6 ? () => navigate(moduleUrls.touristPoints) : undefined}
            >
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {touristPoints.slice(0, 6).map((e) => (
                  <NearbyCard key={e.id} entity={e} onNavigate={navigate} />
                ))}
              </div>
            </NearbySection>

            {/* ── Alertas ─────────────────────────────────────────── */}
            <NearbySection
              title={`Alertas ${proximityLabel}`}
              subtitle={isGps ? "Fique informado sobre o que acontece por perto" : `Alertas ${territoryLabels.inTerritory}`}
              icon={AlertTriangle}
              iconColorClass="bg-red-500/10 text-red-500"
              count={alerts.length}
              isEmpty={alerts.length === 0}
              isLoading={isLoading}
            >
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {alerts.slice(0, 6).map((e) => (
                  <NearbyCard key={e.id} entity={e} onNavigate={navigate} />
                ))}
              </div>
            </NearbySection>

            {/* ── Todos os Resultados ──────────────────────────────── */}
            {entities.length > 0 && (
              <NearbySection
                title="Todos os resultados"
                subtitle={`${entities.length} locais encontrados ${isGps ? `em ${radiusKm}km` : territoryLabels.inTerritory}`}
                icon={TrendingUp}
                count={entities.length}
              >
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                  {displayedEntities.map((e) => (
                    <motion.div key={`${e.type}-${e.id}`} variants={itemVariants}>
                      <NearbyCard entity={e} onNavigate={navigate} />
                    </motion.div>
                  ))}
                </div>
                {canLoadMore && (
                  <div className="flex justify-center mt-8">
                    <Button
                      onClick={handleLoadMore}
                      variant="outline"
                      size="lg"
                      className="rounded-full px-8 gap-2"
                    >
                      Carregar mais <ChevronRight className="h-4 w-4" />
                    </Button>
                  </div>
                )}
              </NearbySection>
            )}

            {/* ── Empty state global ──────────────────────────────── */}
            {entities.length === 0 && (
              <div className="py-16 text-center">
                <div className="p-4 rounded-full bg-muted/50 inline-block mb-4">
                  <MapPin className="h-10 w-10 text-muted-foreground" />
                </div>
                <h3 className="text-xl font-display font-bold text-foreground mb-2">
                  Nenhum local encontrado
                </h3>
                <p className="text-muted-foreground mb-6 max-w-md mx-auto">
                  {isGps
                    ? `Não há locais em um raio de ${radiusKm}km. Tente aumentar o raio.`
                    : `Não encontramos resultados ${territoryLabels.inTerritory}. Tente outro território ou ative o GPS.`
                  }
                </p>
                <div className="flex flex-col sm:flex-row gap-3 justify-center">
                  <Button
                    onClick={() => { setRadiusKm(20); setActiveCategory('all'); }}
                    variant="outline"
                    className="rounded-full"
                  >
                    Ampliar busca para 20km
                  </Button>
                  {!isGps && (
                    <Button
                      onClick={() => resolveLocation()}
                      variant="default"
                      className="rounded-full gap-2"
                    >
                      <Navigation className="h-4 w-4" />
                      Ativar GPS
                    </Button>
                  )}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </>
  );
}

/**
 * ══════════════════════════════════════════════════════════════════════════
 * PRIVACY SETTINGS PAGE
 * ══════════════════════════════════════════════════════════════════════════
 *
 * Página de configurações de privacidade e LGPD.
 * Permite exportar dados, solicitar exclusão de conta e gerenciar consentimentos.
 *
 * LGPD: Art. 18 - Direitos do titular de dados
 * ══════════════════════════════════════════════════════════════════════════
 */

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  Download,
  Trash2,
  Shield,
  FileText,
  AlertTriangle,
  Clock,
  ChevronRight,
  Loader2,
  CheckCircle,
  XCircle,
  Cookie,
  MapPin,
  Bell,
  Mail,
} from 'lucide-react';
import { Button } from '@/shared/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  CardFooter,
} from '@/shared/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/shared/components/ui/dialog';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/shared/components/ui/alert-dialog';
import { Label } from '@/shared/components/ui/label';
import { Switch } from '@/shared/components/ui/switch';
import { Separator } from '@/shared/components/ui/separator';
import { useToast } from '@/shared/hooks/use-toast';
import { useAuth } from '@/core/auth/hooks/useAuth';
import {
  PrivacySettingsService,
  type UserConsentRecord,
  type DeletionStatusRecord,
} from '@/core/privacy/services/PrivacySettingsService';

type UserConsent = UserConsentRecord;
type DeletionStatus = DeletionStatusRecord;

export default function PrivacySettingsPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isExporting, setIsExporting] = useState(false);
  const [deleteReason, setDeleteReason] = useState('');
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  // Buscar consentimentos do usuário
  const { data: consents, isLoading: consentsLoading } = useQuery({
    queryKey: ['user-consents', user?.id],
    queryFn: async () => PrivacySettingsService.getUserConsents(user!.id),
    enabled: !!user?.id,
  });

  // Buscar status de deleção
  const { data: deletionStatus, isLoading: deletionLoading } = useQuery({
    queryKey: ['deletion-status', user?.id],
    queryFn: async () => PrivacySettingsService.getDeletionStatus(user!.id),
    enabled: !!user?.id,
  });

  // Mutação para atualizar consentimento
  const updateConsentMutation = useMutation({
    mutationFn: async ({
      consentType,
      granted,
    }: {
      consentType: string;
      granted: boolean;
    }) => {
      await PrivacySettingsService.recordConsent({
        userId: user!.id,
        consentType,
        granted,
        userAgent: navigator.userAgent,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['user-consents', user?.id] });
      toast({
        title: 'Preferência atualizada',
        description: 'Sua preferência de privacidade foi salva.',
      });
    },
    onError: (error) => {
      toast({
        title: 'Erro',
        description: 'Não foi possível atualizar a preferência.',
        variant: 'destructive',
      });
    },
  });

  // Exportar dados (LGPD Art. 18, I)
  const handleExportData = async () => {
    setIsExporting(true);
    try {
      const accessToken = await PrivacySettingsService.getAccessToken();
      const blob = await PrivacySettingsService.exportUserData(
        import.meta.env.VITE_SUPABASE_URL,
        accessToken,
      );
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `meus-dados-${user?.id?.slice(0, 8)}-${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);

      toast({
        title: 'Dados exportados!',
        description: 'Seus dados foram exportados com sucesso (LGPD Art. 18).',
      });
    } catch (error) {
      toast({
        title: 'Erro na exportação',
        description: 'Não foi possível exportar seus dados. Tente novamente.',
        variant: 'destructive',
      });
    } finally {
      setIsExporting(false);
    }
  };

  // Solicitar exclusão de conta (LGPD Art. 18, VI)
  const handleDeleteAccount = async () => {
    try {
      const accessToken = await PrivacySettingsService.getAccessToken();
      const result = await PrivacySettingsService.requestAccountDeletion({
        supabaseUrl: import.meta.env.VITE_SUPABASE_URL,
        accessToken,
        reason: deleteReason,
      });

      queryClient.invalidateQueries({
        queryKey: ['deletion-status', user?.id],
      });

      toast({
        title: 'Conta agendada para exclusão',
        description: `Sua conta será excluída em ${result.days_until_purge} dias. Você pode cancelar até lá.`,
      });

      setShowDeleteConfirm(false);
    } catch (error: any) {
      toast({
        title: 'Erro',
        description:
          error.message || 'Não foi possível solicitar a exclusão da conta.',
        variant: 'destructive',
      });
    }
  };

  // Cancelar exclusão
  const handleCancelDeletion = async () => {
    try {
      await PrivacySettingsService.cancelAccountDeletion(user!.id);

      queryClient.invalidateQueries({
        queryKey: ['deletion-status', user?.id],
      });

      toast({
        title: 'Exclusão cancelada',
        description: 'Sua conta não será mais excluída.',
      });
    } catch (error) {
      toast({
        title: 'Erro',
        description: 'Não foi possível cancelar a exclusão.',
        variant: 'destructive',
      });
    }
  };

  const consentIcons: Record<string, React.ReactNode> = {
    cookies: <Cookie className="h-5 w-5" />,
    analytics: <FileText className="h-5 w-5" />,
    marketing: <Mail className="h-5 w-5" />,
    geolocation: <MapPin className="h-5 w-5" />,
    notifications: <Bell className="h-5 w-5" />,
    data_processing: <Shield className="h-5 w-5" />,
    third_party: <FileText className="h-5 w-5" />,
    terms_of_service: <FileText className="h-5 w-5" />,
    privacy_policy: <Shield className="h-5 w-5" />,
  };

  const consentLabels: Record<string, string> = {
    cookies: 'Cookies não essenciais',
    analytics: 'Analytics e métricas',
    marketing: 'Marketing e promoções',
    geolocation: 'Geolocalização precisa',
    notifications: 'Notificações push',
    data_processing: 'Processamento de dados',
    third_party: 'Compartilhamento com terceiros',
    terms_of_service: 'Termos de uso',
    privacy_policy: 'Política de privacidade',
  };

  return (
    <div className="container max-w-4xl mx-auto py-8 px-4">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold mb-2">Privacidade e Dados</h1>
        <p className="text-muted-foreground">
          Gerencie seus dados pessoais e exercite seus direitos conforme a LGPD.
        </p>
      </div>

      {/* Alerta de exclusão agendada */}
      {deletionStatus?.status === 'scheduled' && (
        <Card className="mb-6 border-destructive/50 bg-destructive/5">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-destructive">
              <Clock className="h-5 w-5" />
              Conta agendada para exclusão
            </CardTitle>
            <CardDescription>
              Sua conta será permanentemente excluída em{' '}
              {deletionStatus.days_remaining} dias (
              {new Date(deletionStatus.scheduled_purge_at!).toLocaleDateString('pt-BR')}
              ).
            </CardDescription>
          </CardHeader>
          <CardContent>
            <p className="text-sm text-muted-foreground mb-4">
              Durante este período você pode cancelar a exclusão. Após a data de
              purge, seus dados serão permanentemente removidos e não poderão
              ser recuperados.
            </p>
            <Button
              variant="outline"
              onClick={handleCancelDeletion}
              className="border-destructive text-destructive hover:bg-destructive/10"
            >
              <XCircle className="h-4 w-4 mr-2" />
              Cancelar exclusão da conta
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Seção: Meus Dados (LGPD Art. 18) */}
      <Card className="mb-6">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Download className="h-5 w-5" />
            Meus Dados
          </CardTitle>
          <CardDescription>
            LGPD Art. 18, I - Direito de acesso aos dados pessoais.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground mb-4">
            Exporte uma cópia completa de todos os seus dados pessoais
            armazenados em nossa plataforma. O arquivo será baixado em formato
            JSON e conterá dados de perfil, endereços, negócios, mensagens,
            notificações e histórico de atividades.
          </p>
        </CardContent>
        <CardFooter>
          <Button
            onClick={handleExportData}
            disabled={isExporting}
            className="w-full sm:w-auto"
          >
            {isExporting ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Exportando...
              </>
            ) : (
              <>
                <Download className="h-4 w-4 mr-2" />
                Exportar meus dados
              </>
            )}
          </Button>
        </CardFooter>
      </Card>

      {/* Seção: Consentimentos */}
      <Card className="mb-6">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CheckCircle className="h-5 w-5" />
            Consentimentos
          </CardTitle>
          <CardDescription>
            Gerencie seus consentimentos de uso de dados.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {consentsLoading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="h-6 w-6 animate-spin" />
            </div>
          ) : (
            <div className="space-y-4">
              {Object.entries(consentLabels).map(([type, label]) => {
                const consent = consents?.find((c) => c.consent_type === type);
                const isGranted = consent?.granted ?? false;

                return (
                  <div
                    key={type}
                    className="flex items-center justify-between py-3"
                  >
                    <div className="flex items-center gap-3">
                      <div className="text-muted-foreground">
                        {consentIcons[type]}
                      </div>
                      <div>
                        <Label
                          htmlFor={`consent-${type}`}
                          className="font-medium"
                        >
                          {label}
                        </Label>
                        {consent?.granted_at && (
                          <p className="text-xs text-muted-foreground">
                            {isGranted
                              ? `Concedido em ${new Date(consent.granted_at).toLocaleDateString('pt-BR')}`
                              : 'Revogado'}
                          </p>
                        )}
                      </div>
                    </div>
                    <Switch
                      id={`consent-${type}`}
                      checked={isGranted}
                      onCheckedChange={(checked) =>
                        updateConsentMutation.mutate({
                          consentType: type,
                          granted: checked,
                        })
                      }
                      disabled={updateConsentMutation.isPending}
                    />
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Seção: Excluir Conta (LGPD Art. 18, VI) */}
      <Card className="border-destructive/50">
