import { useState, useMemo, useCallback } from "react";
import { PostType, POST_TYPE_CONFIG } from "@/shared/constants/postTypeConfig";

interface UsePostCardProps {
  postId: string;
  postType: PostType;
  tags?: string[];
  content?: string;
  description?: string;
  images?: string[];
  imageUrl?: string;
  location?: string | { name: string; type?: string };
  authorName?: string;
  createdAt: string;
  upvotes?: number;
}

export function usePostCard({
  postType,
  tags,
  content,
  description,
  images,
  imageUrl,
  location,
  authorName,
  createdAt,
  upvotes = 0,
}: UsePostCardProps) {
  const [upvotesCount, setUpvotesCount] = useState(upvotes);

  const effectiveType = useMemo((): PostType => {
    if (postType !== "discussao" || !tags) return postType;
    const newTypeTags: PostType[] = ["achados", "favor", "evento", "desapego"];
    const foundNewType = tags.find((tag) => newTypeTags.includes(tag as PostType));
    return (foundNewType as PostType) || postType;
  }, [postType, tags]);

  const typeConfig = useMemo(
    () => POST_TYPE_CONFIG[effectiveType] || POST_TYPE_CONFIG["discussao"],
    [effectiveType],
  );

  const postContent = useMemo(
    () => content || description || "",
    [content, description],
  );

  const postImage = useMemo(() => {
    if (images && images.length > 0) return images[0];
    return imageUrl;
  }, [images, imageUrl]);

  // ✅ SSOT: usa location.name do JOIN — sem fallback em campos legados
  const formattedLocation = useMemo(() => {
    if (location && typeof location === 'object' && 'name' in location) {
      return location.name;
    }
    if (location && typeof location === 'string') {
      return location;
    }
    return "Localização não informada";
  }, [location]);

  const authorInitials = useMemo(() => {
    if (!authorName) return "U";
    return authorName
      .split(" ")
      .map((n) => n[0])
      .join("")
      .toUpperCase()
      .slice(0, 2);
  }, [authorName]);

  const handleUpvote = useCallback(() => {
    setUpvotesCount((prev) => prev + 1);
  }, []);

  return {
    effectiveType,
    typeConfig,
    postContent,
    postImage,
    formattedLocation,
    authorInitials,
    upvotesCount,
    handleUpvote,
  };
}

import { useState } from "react";
import {
  CommunityService,
  InteractionType,
} from "@/core/community/services/CommunityService";
import { useSessionContext } from "@/core/session"; // ✅ SSOT Regra 1
import { toast } from "sonner";
import { logger } from "@/shared/utils/logger";

/**
 * Hook para registrar interações comunitárias
 *
 * Uso:
 * const { recordInteraction, recording } = useCommunityInteractions();
 *
 * await recordInteraction('post_created', 'post', postId);
 */
export function useCommunityInteractions() {
  const { user, activeProfile } = useSessionContext();
  const [recording, setRecording] = useState(false);

  /**
   * Registra uma interação
   */
  async function recordInteraction(
    interactionType: InteractionType,
    targetType?: string,
    targetId?: string,
    metadata?: Record<string, any>,
    options?: {
      showToast?: boolean;
      showBadgeNotification?: boolean;
    },
  ) {
    if (!user || !activeProfile) {
      logger.warn("No authenticated user or active profile");
      return { success: false, error: "No authenticated user" };
    }

    try {
      setRecording(true);

      // ✅ Contrato: CommunityService.recordInteraction(userId, ...) - tabela community_interactions usa user_id
      const result = await CommunityService.recordInteraction(
        user.id,
        interactionType,
        targetType,
        targetId,
        metadata,
      );

      if (result.success) {
        // Mostrar toast de pontos ganhos
        if (options?.showToast && result.points) {
          toast.success(`+${result.points} pontos!`, {
            description: getInteractionMessage(interactionType),
          });
        }

        // Verificar se ganhou algum badge novo
        if (options?.showBadgeNotification) {
          // Aqui você pode adicionar lógica para mostrar notificação de badge
          // Por exemplo, verificar se o número de badges aumentou
        }
      }

      return result;
    } catch (error: any) {
      logger.error("Error recording interaction:", error);
      return { success: false, error: error.message };
    } finally {
      setRecording(false);
    }
  }

  /**
   * Registra múltiplas interações de uma vez
   */
  async function recordBulkInteractions(
    interactions: Array<{
      type: InteractionType;
      targetType?: string;
      targetId?: string;
      metadata?: Record<string, any>;
    }>,
  ) {
    if (!user || !activeProfile)
      return { success: false, error: "No authenticated user" };

    try {
      setRecording(true);

      const results = await Promise.all(
        interactions.map((interaction) =>
          CommunityService.recordInteraction(
            user.id, // ✅ Contrato: community_interactions.user_id é auth user_id
            interaction.type,
            interaction.targetType,
            interaction.targetId,
            interaction.metadata,
          ),
        ),
      );

      const totalPoints = results.reduce((sum, r) => sum + (r.points || 0), 0);

      if (totalPoints > 0) {
        toast.success(`+${totalPoints} pontos!`, {
          description: `${interactions.length} ações registradas`,
        });
      }

      return { success: true, results, totalPoints };
    } catch (error: any) {
      logger.error("Error recording bulk interactions:", error);
      return { success: false, error: error.message };
    } finally {
      setRecording(false);
    }
  }

  return {
    recordInteraction,
    recordBulkInteractions,
    recording,
  };
}

/**
 * Mensagens amigáveis para cada tipo de interação
 */
function getInteractionMessage(type: InteractionType): string {
  const messages: Record<InteractionType, string> = {
