        color: "#CD7F32",
        minPoints: 0,
        maxPoints: 100,
      },
      {
        level: "silver",
        name: "Prata",
        icon: "🥈",
        color: "#C0C0C0",
        minPoints: 100,
        maxPoints: 500,
      },
      {
        level: "gold",
        name: "Ouro",
        icon: "🥇",
        color: "#FFD700",
        minPoints: 500,
        maxPoints: 1000,
      },
      {
        level: "platinum",
        name: "Platina",
        icon: "💎",
        color: "#E5E4E2",
        minPoints: 1000,
        maxPoints: 5000,
      },
      {
        level: "diamond",
        name: "Diamante",
        icon: "💎",
        color: "#B9F2FF",
        minPoints: 5000,
        maxPoints: Infinity,
      },
    ];

    const currentLevel =
      levels.find(
        (l) => totalPoints >= l.minPoints && totalPoints < l.maxPoints,
      ) || levels[0];

    const currentIndex = levels.indexOf(currentLevel);
    const nextLevel = levels[currentIndex + 1] || currentLevel;

    const progress =
      nextLevel.maxPoints === Infinity
        ? 100
        : Math.min(
            ((totalPoints - currentLevel.minPoints) /
              (nextLevel.minPoints - currentLevel.minPoints)) *
              100,
            100,
          );

    return {
      level: currentLevel.level,
      name: currentLevel.name,
      icon: currentLevel.icon,
      color: currentLevel.color,
      nextLevel: nextLevel.name,
      nextLevelPoints: nextLevel.minPoints,
      progress: Math.round(progress),
    };
  }
}

export const CommunityService = new CommunityServiceClass();
export { CommunityService as communityService };

/**
 * GamificationService - SSOT para sistema de gamificação
 *
 * Responsável por:
 * - Pontuação e níveis
 * - Badges e conquistas
 * - Leaderboards
 * - Recompensas
 *
 * Arquitetura: Component → Hook → GamificationService → Supabase
 */

import { supabase } from "@/integrations/supabase";
import { trackError } from "@/shared/utils/errorTracking";
import { PAGINATION } from "@/shared/constants";

// Helper para verificar erros do Postgres de forma type-safe
interface PostgresError {
  code?: string;
  message: string;
}

function isPostgresError(error: unknown): error is PostgresError {
  return typeof error === "object" && error !== null && "code" in error;
}

function isTableNotFoundError(error: unknown): boolean {
  if (!isPostgresError(error)) return false;
  const code = error.code;
  return code === "PGRST204" || code === "PGRST116" || code === "42P01";
}

export interface UserLevel {
  user_id: string;
  level: number;
  experience_points: number;
  total_points: number;
  current_streak: number;
  longest_streak: number;
  created_at: string;
  updated_at: string;
}

export interface Achievement {
  id: string;
  code: string;
  name: string;
  description: string;
  icon: string;
  category: string;
  points_reward: number;
  requirements: Record<string, any>;
  is_active: boolean;
  created_at: string;
}

export interface UserAchievement {
  id: string;
  user_id: string;
  achievement_id: string;
  achievement_code: string;
  earned_at?: string;
  progress: number;
}

export interface PointTransaction {
  id: string;
  user_id: string;
  points: number;
  transaction_type: "earned" | "spent" | "bonus" | "penalty";
  source: string;
  description: string;
  metadata: Record<string, any>;
  created_at: string;
}

export interface UserGamificationStats {
  level: number;
  total_points: number;
  experience_points: number;
  achievements_count: number;
  achievements_total: number;
  recent_transactions: PointTransaction[];
  level_progress: number;
  points_to_next_level: number;
  current_streak: number;
  longest_streak: number;
}

export class GamificationService {
  /**
   * Busca nível do usuário
   */
  static async getUserLevel(userId: string): Promise<UserLevel | null> {
    try {
      const { data, error } = await (supabase as any)
        .from("user_levels")
        .select("*")
        .eq("user_id", userId)
        .single();

      if (error && error.code !== "PGRST116") throw error;
      return data || null;
    } catch (error) {
      trackError(error as Error, {
        component: "GamificationService",
        action: "getUserLevel",
        metadata: { userId },
      });
      return null;
    }
  }

  /**
   * Adiciona pontos ao usuário
   */
  static async addPoints(
    userId: string,
    points: number,
    source: string,
    description: string,
    metadata: Record<string, any> = {},
  ): Promise<boolean> {
    try {
      // Registrar transação
      const { error: transactionError } = await (supabase as any)
        .from("point_transactions")
        .insert({
          user_id: userId,
          points,
          transaction_type: "earned",
          source,
          description,
          metadata,
        });

      if (transactionError) throw transactionError;

      // Atualizar nível do usuário
      const { error: levelError } = await (supabase as any).rpc(
        "update_user_level",
        {
          p_user_id: userId,
          p_points: points,
        },
      );

      if (levelError) throw levelError;

      return true;
    } catch (error) {
      trackError(error as Error, {
        component: "GamificationService",
        action: "addPoints",
        metadata: { userId, points, source },
      });
      return false;
    }
  }

  /**
   * Busca achievements disponíveis
   */
  static async getAvailableAchievements(): Promise<Achievement[]> {
    try {
      const { data, error } = await (supabase as any)
        .from("achievements")
        .select("*")
        .eq("is_active", true)
        .order("category", { ascending: true });

      if (error) {
        // Tabela não existe ainda - retornar vazio silenciosamente
        // PGRST116 = relation does not exist (404)
        if (
          error.code === "PGRST204" ||
          error.code === "PGRST116" ||
          error.code === "42P01"
        ) {
          return [];
        }
        throw error;
      }
      return data || [];
    } catch (error) {
      // Só logar se não for erro de tabela inexistente
      if (!isTableNotFoundError(error)) {
        trackError(error as Error, {
          component: "GamificationService",
          action: "getAvailableAchievements",
        });
      }
      return [];
    }
  }

  /**
   * Busca achievements do usuário
   */
  static async getUserAchievements(userId: string): Promise<UserAchievement[]> {
    try {
      const { data, error } = await (supabase as any)
        .from("user_achievements")
        .select(
          `
          *,
          achievement:achievements(code)
        `,
        )
        .eq("user_id", userId)
        .order("earned_at", { ascending: false });

      if (error) {
        // Tabela não existe ainda - retornar vazio silenciosamente
        // PGRST116 = relation does not exist (404)
        if (
          error.code === "PGRST204" ||
          error.code === "PGRST116" ||
          error.code === "42P01"
        ) {
          return [];
        }
        throw error;
      }

      // Mapear achievement_code para compatibilidade
      return (data || []).map((ua) => ({
        ...ua,
        achievement_code: ua.achievement?.code || ua.achievement_id,
      }));
    } catch (error) {
      // Só logar se não for erro de tabela inexistente
      if (!isTableNotFoundError(error)) {
        trackError(error as Error, {
          component: "GamificationService",
          action: "getUserAchievements",
          userId,
        });
      }
      return [];
    }
  }

  /**
   * Concede achievement ao usuário
   */
  static async grantAchievement(
    userId: string,
    achievementCode: string,
  ): Promise<boolean> {
    try {
      // Buscar achievement
      const { data: achievement, error: achievementError } = await (
        supabase as any
      )
        .from("achievements")
        .select("id, points_reward")
        .eq("code", achievementCode)
        .eq("is_active", true)
        .single();

      if (achievementError || !achievement)
        throw new Error("Achievement not found");

      // Verificar se já possui
      const { data: existing } = await (supabase as any)
        .from("user_achievements")
        .select("id")
        .eq("user_id", userId)
        .eq("achievement_id", achievement.id)
        .single();

      if (existing) return true; // Já possui

      // Conceder achievement
      const { error: grantError } = await (supabase as any)
        .from("user_achievements")
        .insert({
          user_id: userId,
          achievement_id: achievement.id,
          progress: 100,
          earned_at: new Date().toISOString(),
        });

      if (grantError) throw grantError;

      // Adicionar pontos de recompensa
      if (achievement.points_reward > 0) {
        await this.addPoints(
          userId,
          achievement.points_reward,
          "achievement",
          `Achievement: ${achievementCode}`,
          { achievement_code: achievementCode },
        );
      }

      return true;
    } catch (error) {
      trackError(error as Error, {
        component: "GamificationService",
        action: "grantAchievement",
        metadata: { userId, achievementCode },
      });
      return false;
    }
  }

  /**
   * Busca leaderboard de pontuação
   */
  static async getLeaderboard(limit: number = PAGINATION.SMALL_LIMIT): Promise<any[]> {
    try {
      const { data, error } = await (supabase as any)
        .from("user_levels")
        .select(
          `
          user_id,
          total_points,
          level,
          profiles:user_id(name, avatar_url)
        `,
        )
        .order("total_points", { ascending: false })
        .limit(limit);

      if (error) throw error;
      return data || [];
    } catch (error) {
      trackError(error as Error, {
        component: "GamificationService",
        action: "getLeaderboard",
        metadata: { limit },
      });
      return [];
    }
  }

  /**
   * Busca top users por localização usando RPC
   */
  static async getTopUsersByLocation(
    city: string,
    neighborhood: string | null = null,
    limit: number = PAGINATION.SMALL_LIMIT / 2,
  ): Promise<any[]> {
    try {
      const { data, error } = await (supabase as any).rpc(
        "get_top_users_by_location",
        {
          p_city: city,
          p_neighborhood: neighborhood,
          p_limit: limit,
        },
      );

      if (error) throw error;
      return data || [];
    } catch (error) {
      trackError(error as Error, {
        component: "GamificationService",
        action: "getTopUsersByLocation",
        metadata: { city, neighborhood, limit },
      });
      return [];
    }
  }

  /**
   * Busca transações de pontos do usuário
   */
  static async getPointTransactions(
    userId: string,
    limit: number = PAGINATION.DEFAULT_LIMIT,
  ): Promise<PointTransaction[]> {
    try {
      const { data, error } = await (supabase as any)
        .from("point_transactions")
        .select("*")
        .eq("user_id", userId)
        .order("created_at", { ascending: false })
        .limit(limit);

      if (error) throw error;
      return data || [];
    } catch (error) {
      trackError(error as Error, {
        component: "GamificationService",
        action: "getPointTransactions",
        metadata: { userId, limit },
      });
      return [];
    }
  }

  /**
   * Calcula nível baseado em pontos
   */
  static calculateLevel(totalPoints: number): {
    level: number;
    pointsToNext: number;
    progress: number;
  } {
    // Fórmula: level = floor(sqrt(points / 100))
    const level = Math.floor(Math.sqrt(totalPoints / 100));
    const currentLevelPoints = level * level * 100;
    const nextLevelPoints = (level + 1) * (level + 1) * 100;
    const pointsToNext = nextLevelPoints - totalPoints;
    const progress =
      ((totalPoints - currentLevelPoints) /
        (nextLevelPoints - currentLevelPoints)) *
      100;

    return {
      level: Math.max(1, level),
      pointsToNext: Math.max(0, pointsToNext),
      progress: Math.min(100, Math.max(0, progress)),
    };
  }

  /**
   * Busca estatísticas completas de gamificação do usuário
   */
  static async getUserGamificationStats(
    userId: string,
  ): Promise<UserGamificationStats> {
    try {
      const [levelData, achievementsData, transactionsData] = await Promise.all(
        [
          this.getUserLevel(userId),
          this.getUserAchievements(userId),
          this.getPointTransactions(userId, PAGINATION.SMALL_LIMIT / 2),
        ],
      );

      const level = levelData || {
        level: 1,
        total_points: 0,
        experience_points: 0,
        current_streak: 0,
        longest_streak: 0,
      };
      const levelInfo = this.calculateLevel(level.total_points);

      return {
        level: levelInfo.level,
        total_points: level.total_points,
        experience_points: level.experience_points || 0,
        achievements_count: achievementsData.filter((a) => a.earned_at).length,
        achievements_total: achievementsData.length,
        recent_transactions: transactionsData,
        level_progress: levelInfo.progress,
        points_to_next_level: levelInfo.pointsToNext,
        current_streak: level.current_streak || 0,
        longest_streak: level.longest_streak || 0,
      };
    } catch (error) {
      trackError(error as Error, {
        component: "GamificationService",
        action: "getUserGamificationStats",
        metadata: { userId },
      });
      return {
        level: 1,
        total_points: 0,
        experience_points: 0,
        achievements_count: 0,
        achievements_total: 0,
        recent_transactions: [],
        level_progress: 0,
        points_to_next_level: 100,
        current_streak: 0,
        longest_streak: 0,
      };
    }
  }

  /**
   * Processa ação do usuário e atribui pontos/achievements automaticamente
   */
  static async processUserAction(
    userId: string,
    action: string,
    metadata: Record<string, any> = {},
  ): Promise<{ points: number; achievements: string[] }> {
    try {
      const result = { points: 0, achievements: [] as string[] };

      // Mapeamento de ações para pontos
      const actionPoints: Record<string, number> = {
        post_created: 10,
        comment_added: 5,
        helpful_vote: 2,
        review_written: 15,
        business_created: 50,
        profile_completed: 25,
        daily_login: 1,
        share_content: 3,
        like_given: 1,
      };

      const points = actionPoints[action] || 0;

      if (points > 0) {
        const success = await this.addPoints(
          userId,
          points,
          action,
          `Action: ${action}`,
          metadata,
        );

        if (success) {
          result.points = points;
        }
      }

      return result;
    } catch (error) {
      trackError(error as Error, {
        component: "GamificationService",
        action: "processUserAction",
        metadata: { userId, action, metadata },
      });
      return { points: 0, achievements: [] };
    }
  }
}

export const gamificationService = new GamificationService();

/**
 * NominatimProvider - Provider de geocoding usando OpenStreetMap Nominatim
 * 
 * Responsável por:
 * - Geocoding direto de endereços
 * - Reverse geocoding
 * - Busca de limites (bounds)
 * 
 * Usa proxy Supabase para evitar CORS e rate limiting.
 */

import { BaseGeocodingProvider } from './BaseGeocodingProvider';
import type {
  GeocodeRequest,
  GeocodeResult,
  ReverseGeocodeRequest,
  ReverseGeocodeResult,
  PostalCodeLookupRequest,
  PostalCodeLookupResult,
  GeocodingError
} from '../types';

interface NominatimResult {
  place_id: number;
  osm_type: string;
  osm_id: number;
  lat: string;
  lon: string;
  display_name: string;
  address?: {
    road?: string;
    house_number?: string;
    suburb?: string;
    neighbourhood?: string;
    quarter?: string;
    city?: string;
    town?: string;
    municipality?: string;
    state?: string;
    postcode?: string;
    country?: string;
    country_code?: string;
  };
  boundingbox?: [string, string, string, string]; // [south, north, west, east]
  geojson?: {
    type: string;
    coordinates: any;
  };
}

export class NominatimProvider extends BaseGeocodingProvider {
  readonly id = 'nominatim';
  readonly name = 'OpenStreetMap Nominatim';
  readonly isAvailable = true;

  private proxyUrl: string;
  private apiKey: string | null;

  constructor() {
    super();
    
    // Usa proxy Supabase para evitar CORS
    this.proxyUrl = `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/nominatim-proxy`;
    this.apiKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY || null;
    
    this.config.cacheTtlSeconds = 3600; // 1 hora para dados OSM
  }

  /**
   * Geocoding direto de endereços
   */
  async geocode(request: GeocodeRequest): Promise<GeocodeResult[]> {
    const cacheKey = this.generateCacheKey('geocode', request);
    const cached = this.getFromCache<GeocodeResult[]>(cacheKey);
    if (cached) {
      this.log('info', 'Cache hit for geocode', { query: request.query });
      return cached;
    }

    try {
      const params = new URLSearchParams({
        q: request.query,
        format: 'json',
        addressdetails: '1',
        limit: String(request.limit || 10),
      });

      if (request.city) params.append('city', request.city);
      if (request.state) params.append('state', request.state);
      if (request.country) params.append('country', request.country);

      const url = `${this.proxyUrl}?${params.toString()}`;
      const headers: Record<string, string> = {};
      
      if (this.apiKey) {
        headers['apikey'] = this.apiKey;
      }

      const response = await this.withTimeout(
        fetch(url, { headers })
      );

      if (!response.ok) {
        this.log('warn', 'Nominatim geocode request failed', {
          status: response.status,
          query: request.query,
        });
        return [];
      }

      const results: NominatimResult[] = await response.json();

      if (!results || results.length === 0) {
        return [];
      }

      const geocodeResults = results.map(result => this.nominatimToGeocodeResult(result));
      
      // Cache dos resultados
      this.setToCache(cacheKey, geocodeResults);
      
      this.log('info', 'Geocode successful', {
        query: request.query,
        resultsCount: geocodeResults.length,
      });

      return geocodeResults;
    } catch (error) {
      this.log('error', 'Geocode failed', {
        error: error instanceof Error ? error.message : String(error),
        query: request.query,
      });

      if (error instanceof GeocodingError) {
        throw error;
      }

      throw new GeocodingError(
        'Falha no geocoding. Verifique sua conexão.',
        'NETWORK_ERROR',
        { originalError: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  /**
   * Reverse geocoding
   */
  async reverseGeocode(request: ReverseGeocodeRequest): Promise<ReverseGeocodeResult | null> {
    // Validação de coordenadas
    if (!this.validateCoordinates(request.latitude, request.longitude)) {
      throw new GeocodingError(
        'Coordenadas inválidas',
        'INVALID_INPUT',
        { latitude: request.latitude, longitude: request.longitude }
      );
    }

    const cacheKey = this.generateCacheKey('reverseGeocode', request);
    const cached = this.getFromCache<ReverseGeocodeResult>(cacheKey);
    if (cached) {
      this.log('info', 'Cache hit for reverse geocode', {
        lat: request.latitude,
        lng: request.longitude,
      });
      return cached;
    }

    try {
      const headers: Record<string, string> = {};
      
      if (this.apiKey) {
        headers['apikey'] = this.apiKey;
      }

      const requestParams = (includeZoom: boolean) => {
        const params = new URLSearchParams({
          reverse: '1',
          lat: String(request.latitude),
          lon: String(request.longitude),
          format: 'json',
          addressdetails: '1',
        });

        if (includeZoom) {
          params.set('zoom', this.getZoomLevelForDetail(request.detailLevel));
        }

        return params;
      };

      const attemptParams = [requestParams(true), requestParams(false)];

      for (let attempt = 0; attempt < attemptParams.length; attempt++) {
        const params = attemptParams[attempt];
        const url = `${this.proxyUrl}?${params.toString()}`;

        const response = await this.withTimeout(fetch(url, { headers }));

        if (!response.ok) {
          const responseBody = await response.text().catch(() => '');
          this.log('warn', 'Nominatim reverse geocode request failed', {
            status: response.status,
            lat: request.latitude,
            lng: request.longitude,
            attempt: attempt + 1,
            withZoom: attempt === 0,
            responseBody: responseBody.slice(0, 180),
          });
          continue;
        }

        const result: NominatimResult = await response.json();

        if (!result) {
          continue;
        }

        const geocodeResult = this.nominatimToGeocodeResult(result);
        const reverseResult: ReverseGeocodeResult = {
          address: geocodeResult,
          distanceMeters: 0, // Nominatim retorna o ponto exato
          locationType: this.getLocationTypeFromNominatim(result),
        };

        // Cache do resultado
        this.setToCache(cacheKey, reverseResult);

        this.log('info', 'Reverse geocode successful', {
          lat: request.latitude,
          lng: request.longitude,
          address: geocodeResult.formattedAddress,
          attempt: attempt + 1,
          withZoom: attempt === 0,
        });

        return reverseResult;
      }
      return null;
    } catch (error) {
      this.log('error', 'Reverse geocode failed', {
        error: error instanceof Error ? error.message : String(error),
        lat: request.latitude,
        lng: request.longitude,
      });

      if (error instanceof GeocodingError) {
        throw error;
      }

      throw new GeocodingError(
        'Falha no reverse geocoding. Verifique sua conexão.',
        'NETWORK_ERROR',
        { originalError: error instanceof Error ? error.message : String(error) }
      );
    }
  }

  /**
   * Busca por CEP (limitado - Nominatim tem suporte básico)
   */
  async lookupPostalCode(request: PostalCodeLookupRequest): Promise<PostalCodeLookupResult | null> {
    // Nominatim tem suporte limitado a CEP
    // Podemos tentar geocoding com o CEP como query
    const geocodeResults = await this.geocode({
      query: request.postalCode,
      country: 'BR',
      limit: 1,
    });

    if (geocodeResults.length === 0) {
      return null;
    }

    const result = geocodeResults[0];
    const address = result.addressComponents;

    return {
      postalCode: address.postalCode || request.postalCode,
      street: address.street || '',
      complement: '',
      neighborhood: address.neighborhood || '',
      city: address.city,
      state: address.state,
      ibgeCode: '', // Nominatim não fornece IBGE
      coordinates: {
        latitude: result.coordinates.latitude,
        longitude: result.coordinates.longitude,
      },
    };
  }

  /**
   * Converte resultado Nominatim para GeocodeResult
   */
  private nominatimToGeocodeResult(nominatim: NominatimResult): GeocodeResult {
    const address = nominatim.address || {};
    
    // Determina cidade (pode ser city, town ou municipality)
    const city = address.city || address.town || address.municipality || '';
    
    // Determina bairro (pode ser suburb, neighbourhood ou quarter)
    const neighborhood = address.suburb || address.neighbourhood || address.quarter || '';
    
    // Determina rua e número
    const street = address.road || '';
    const number = address.house_number || '';
    
    // Monta endereço formatado
    const formattedAddress = nominatim.display_name;
    
    // Se tiver bounding box, calcula bounds
    let bounds = undefined;
    if (nominatim.boundingbox) {
      const [south, north, west, east] = nominatim.boundingbox.map(parseFloat);
      bounds = {
        northeast: { latitude: north, longitude: east },
        southwest: { latitude: south, longitude: west },
      };
    }

    // Calcula confiança baseada no tipo de resultado
    const confidence = this.calculateConfidence(nominatim);

    return {
      formattedAddress,
      addressComponents: {
        street: street || undefined,
        number: number || undefined,
        neighborhood: neighborhood || undefined,
        city,
        state: address.state || '',
        postalCode: address.postcode || undefined,
        country: address.country || 'BR',
      },
      coordinates: {
        latitude: parseFloat(nominatim.lat),
        longitude: parseFloat(nominatim.lon),
      },
      confidence,
      source: this.id,
      providerPlaceId: String(nominatim.place_id),
      bounds,
    };
  }

  /**
   * Calcula confiança baseada no tipo de resultado OSM
   */
  private calculateConfidence(nominatim: NominatimResult): number {
    const address = nominatim.address || {};
    
    // Alta confiança para resultados com house_number
    if (address.house_number) return 0.9;
    
    // Média confiança para resultados com road
    if (address.road) return 0.7;
    
    // Baixa confiança para resultados apenas de cidade/bairro
    if (address.city || address.town || address.suburb) return 0.5;
    
    // Muito baixa confiança para outros
    return 0.3;
  }

  /**
   * Obtém zoom level baseado no nível de detalhe
   */
  private getZoomLevelForDetail(detailLevel?: string): string {
    switch (detailLevel) {
      case 'full': return '18'; // House number level
      case 'suburb': return '16'; // Street level
      case 'city': return '14'; // City level
      case 'state': return '10'; // State level
      default: return '16'; // Default street level
    }
  }

  /**
   * Obtém tipo de local do resultado Nominatim
   */
  private getLocationTypeFromNominatim(nominatim: NominatimResult): string {
    const osmType = nominatim.osm_type;
    
    switch (osmType) {
      case 'node':
        return 'point';
      case 'way':
        return 'way';
      case 'relation':
        return 'relation';
      default:
        return 'unknown';
    }
  }
}

import { describe, expect, it, vi } from 'vitest';
import {
  BoundaryServiceClass,
  type BoundaryServiceDeps,
} from '../BoundaryService';
import {
  type ILocationRepository,
  type Location,
} from '@/core/location';
import { LocationStatus, LocationType } from '@/core/location/types';

function buildLocation(partial: Partial<Location>): Location {
  return {
    id: partial.id ?? crypto.randomUUID(),
    parent_id: partial.parent_id ?? null,
    type: partial.type ?? LocationType.CITY,
    slug: partial.slug ?? 'location',
    name: partial.name ?? 'Location',
    full_name: partial.full_name ?? partial.name ?? 'Location',
    geographic_path: partial.geographic_path ?? '/br/ba/location',
    status: partial.status ?? LocationStatus.ACTIVE,
    metadata: partial.metadata ?? {},
    created_at: partial.created_at ?? '2026-01-01T00:00:00.000Z',
    updated_at: partial.updated_at ?? '2026-01-01T00:00:00.000Z',
  };
}

function createRepository(locations: Location[]): ILocationRepository {
  const byId = new Map(locations.map((location) => [location.id, location]));

  return {
    findById: vi.fn(async (id: string) => byId.get(id) ?? null),
    findByPath: vi.fn(),
    findBySlugWithinParent: vi.fn(),
    findAncestors: vi.fn(),
    findDescendants: vi.fn(),
    findChildren: vi.fn(),
    findAll: vi.fn(async () => locations),
  } as unknown as ILocationRepository;
}

function createSupabaseStub(boundaryRows: Record<string, unknown>) {
  return {
    from: vi.fn(() => ({
      select: vi.fn(() => ({
        eq: vi.fn((_: string, locationId: string) => ({
          maybeSingle: vi.fn(async () => ({
            data: boundaryRows[locationId] ?? null,
            error: null,
          })),
        })),
      })),
    })),
  };
}

function createService(
  locations: Location[],
  boundaryRows: Record<string, unknown> = {},
  customBoundariesEnabled = false,
): BoundaryServiceClass {
  const deps: BoundaryServiceDeps = {
    locationRepository: createRepository(locations),
    supabaseClient: createSupabaseStub(boundaryRows) as BoundaryServiceDeps['supabaseClient'],
    locationCacheTtlMs: 60_000,
    customBoundariesEnabled,
  };

  return new BoundaryServiceClass(deps);
}

