/**
 * useCityNeighborhoodsPolygons
 *
 * Busca os pol�gonos de todos os bairros ativos de uma cidade.
 * S� executa quando `enabled` � true � evita chamadas desnecess�rias.
 *
 * Fluxo:
 *   1. Busca os filhos diretos da cidade (type=district, status=active)
 *   2. Para cada bairro, busca o boundary can�nico via SSOT territorial
 *   3. Retorna um TerritoryPolygon[] com todos os an�is encontrados
 *
 * @module core/maps/hooks
 */
import { logger } from '@/shared/utils/logger';
import { useState, useEffect, useRef } from 'react';
import { createLocationRepository } from '@/core/location/repositories/createLocationRepository';
import { boundaryService } from '@/core/geospatial';
import { NEIGHBORHOOD_COLORS } from '../providers/MapProvider';
import type { TerritoryPolygon } from './useTerritoryPolygon';
import type { Location } from '@/core/location';
import { LocationType, LocationStatus } from '@/core/location/types';

interface UseCityNeighborhoodsPolygonsOptions {
  /** ID da cidade no banco */
  cityId: string | null | undefined;
  /** Path geogr�fico da cidade, ex: /br/ba/salvador */
  cityGeoPath: string | null | undefined;
  /** Ativa ou desativa a busca */
  enabled: boolean;
}

interface UseCityNeighborhoodsPolygonsResult {
  polygons: TerritoryPolygon[];
  isLoading: boolean;
}

// Cache key para localStorage
const CACHE_KEY_PREFIX = 'city-neighborhoods-cache-';
const CACHE_VERSION = 'v1';
const CACHE_EXPIRY_DAYS = 7; // Cache v�lido por 7 dias

interface CachedData {
  version: string;
  timestamp: number;
  polygons: TerritoryPolygon[];
}

function getCacheKey(cityId: string): string {
  return `${CACHE_KEY_PREFIX}${CACHE_VERSION}-${cityId}`;
}

function loadFromCache(cityId: string): TerritoryPolygon[] | null {
  try {
    const key = getCacheKey(cityId);
    const cached = localStorage.getItem(key);
    if (!cached) return null;

    const data: CachedData = JSON.parse(cached);

    if (data.version !== CACHE_VERSION) return null;

    const now = Date.now();
    const expiryMs = CACHE_EXPIRY_DAYS * 24 * 60 * 60 * 1000;
    if (now - data.timestamp > expiryMs) {
      localStorage.removeItem(key);
      return null;
    }

    return data.polygons;
  } catch {
    return null;
  }
}

function saveToCache(cityId: string, polygons: TerritoryPolygon[]): void {
  try {
    const key = getCacheKey(cityId);
    const data: CachedData = {
      version: CACHE_VERSION,
      timestamp: Date.now(),
      polygons,
    };
    localStorage.setItem(key, JSON.stringify(data));
  } catch (error) {
    logger.warn('[useCityNeighborhoodsPolygons] Failed to save to cache:', error);
  }
}

/**
 * Limpa o cache de uma cidade espec�fica ou de todas as cidades.
 * �til para for�ar re-fetch quando os dados mudam.
 */
export function clearNeighborhoodsCache(cityId?: string): void {
  try {
    if (cityId) {
      const key = getCacheKey(cityId);
      localStorage.removeItem(key);
    } else {
      const keys = Object.keys(localStorage);
      keys.forEach((key) => {
        if (key.startsWith(CACHE_KEY_PREFIX)) {
          localStorage.removeItem(key);
        }
      });
    }
  } catch (error) {
    logger.warn('[useCityNeighborhoodsPolygons] Failed to clear cache:', error);
  }
}

export function useCityNeighborhoodsPolygons({
  cityId,
  cityGeoPath,
  enabled,
}: UseCityNeighborhoodsPolygonsOptions): UseCityNeighborhoodsPolygonsResult {
  const [polygons, setPolygons] = useState<TerritoryPolygon[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const cacheRef = useRef<Map<string, TerritoryPolygon[]>>(new Map());

  useEffect(() => {
    if (!enabled || !cityId || !cityGeoPath) {
      setPolygons([]);
      return;
    }

    if (cacheRef.current.has(cityId)) {
      setPolygons(cacheRef.current.get(cityId)!);
      return;
    }

    const cachedPolygons = loadFromCache(cityId);
    if (cachedPolygons) {
      cacheRef.current.set(cityId, cachedPolygons);
      setPolygons(cachedPolygons);
      return;
    }

    let cancelled = false;
    setIsLoading(true);

    const run = async () => {
      try {
        const repo = createLocationRepository();
        const { locations: neighborhoods } = await repo.findChildren(cityId, {
          type: LocationType.DISTRICT,
          status: LocationStatus.ACTIVE,
          page_size: 200,
        });

        if (cancelled) return;

        const results = await Promise.allSettled(
          neighborhoods.map((neighborhood: Location) =>
            boundaryService
              .getNeighborhoodBounds({
                neighborhood: neighborhood.name,
                city: '',
                state: '',
                locationId: neighborhood.id,
              })
              .then((result) => ({ neighborhood, result })),
          ),
        );

        if (cancelled) return;

        const built: TerritoryPolygon[] = [];
        let successCount = 0;
        let failureCount = 0;
        const unresolvedNeighborhoods: string[] = [];

        results.forEach((settled, index) => {
          if (settled.status !== 'fulfilled') {
            failureCount++;
            unresolvedNeighborhoods.push(neighborhoods[index].name);
            return;
          }

          const { neighborhood, result } = settled.value;
          if (result.rings.length === 0) {
            failureCount++;
            unresolvedNeighborhoods.push(neighborhood.name);
            return;
          }

          successCount++;
          const color = NEIGHBORHOOD_COLORS[index % NEIGHBORHOOD_COLORS.length];
          result.rings.forEach((ring) => {
            built.push({
              name: neighborhood.name,
              coordinates: ring,
              center: result.center,
              color,
            });
          });
        });

        if (failureCount > 0) {
          logger.warn('[useCityNeighborhoodsPolygons] Neighborhoods without stored boundary', {
            cityId,
            successCount,
            failureCount,
            unresolvedNeighborhoods,
          });
        }

        cacheRef.current.set(cityId, built);
        saveToCache(cityId, built);

        if (!cancelled) setPolygons(built);
      } finally {
        if (!cancelled) setIsLoading(false);
      }
    };

    run();
    return () => { cancelled = true; };
  }, [enabled, cityId, cityGeoPath]);

  return { polygons, isLoading };
}

if (typeof window !== 'undefined') {
  (window as any).clearNeighborhoodsCache = clearNeighborhoodsCache;
}

/**
 * GeolocationService - SSOT para geolocalizacao.
 *
 * Estrategia:
 * 1. Cache local (resposta imediata)
 * 2. GPS com tentativas adaptativas (mobile/desktop)
 * 3. Fallback para IP geolocation quando aplicavel
 */
import { logger } from '@/shared/utils/logger';
import { TIMEOUTS } from '@/shared/constants';

export interface GeolocationCoords {
  latitude: number;
  longitude: number;
  accuracy: number;
  altitude: number | null;
  altitudeAccuracy: number | null;
  heading: number | null;
  speed: number | null;
  timestamp: number;
}

export interface GeolocationResult {
  coords: GeolocationCoords;
  source: 'gps' | 'ip' | 'cache';
  isHighAccuracy: boolean;
}

export interface GeolocationOptions {
  useCache?: boolean;
  timeout?: number;
  maxRetries?: number;
  onProgress?: (attempt: number, maxAttempts: number) => void;
  forcePrompt?: boolean;
}

const CACHE_KEY = 'geolocation_cache_v1';
const CACHE_DURATION = 5 * 60 * 1000;

class GeolocationServiceClass {
  private requestInFlight = false;
  private abortController: AbortController | null = null;

  private createGeolocationError(code: string, message: string): Error {
    const error = new Error(message) as Error & { code?: string };
    error.code = code;
    return error;
  }

  private isSecureRuntime(): boolean {
    if (typeof window === 'undefined') {
      return false;
    }

    if (window.isSecureContext) {
      return true;
    }

    const host = window.location.hostname;
    return host === 'localhost' || host === '127.0.0.1' || host === '[::1]';
  }

  private isInsecureContextError(error: unknown): boolean {
    const message = String((error as { message?: string } | null)?.message ?? '').toLowerCase();
    return (
      message.includes('secure origin') ||
      message.includes('secure context') ||
      message.includes('only secure')
    );
  }

  private isMobileDevice(): boolean {
    return (
      /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(
        navigator.userAgent,
      ) ||
      'ontouchstart' in window ||
      navigator.maxTouchPoints > 0
    );
  }

  private getCachedLocation(): GeolocationResult | null {
    try {
      const cached = localStorage.getItem(CACHE_KEY);
      if (!cached) {
        return null;
      }

      const data = JSON.parse(cached);
      if (Date.now() - data.timestamp > CACHE_DURATION) {
        localStorage.removeItem(CACHE_KEY);
        return null;
      }

      logger.info('[GeolocationService] Using cache', {
        age: `${Math.round((Date.now() - data.timestamp) / 1000)}s`,
        accuracy: `${data.result.coords.accuracy}m`,
      });

      return data.result;
    } catch {
      return null;
    }
  }

  private setCachedLocation(result: GeolocationResult): void {
    try {
      localStorage.setItem(
        CACHE_KEY,
        JSON.stringify({
          result,
          timestamp: Date.now(),
        }),
      );
    } catch (error) {
      logger.warn('[GeolocationService] Could not persist cache', error);
    }
  }

  private positionToCoords(position: GeolocationPosition): GeolocationCoords {
    return {
      latitude: position.coords.latitude,
      longitude: position.coords.longitude,
      accuracy: position.coords.accuracy,
      altitude: position.coords.altitude,
      altitudeAccuracy: position.coords.altitudeAccuracy,
      heading: position.coords.heading,
      speed: position.coords.speed,
      timestamp: position.timestamp,
    };
  }

  private async singleGPSAttempt(
    highAccuracy: boolean,
    timeout: number,
    maxAge: number,
  ): Promise<GeolocationCoords> {
    return new Promise((resolve, reject) => {
      if (!('geolocation' in navigator)) {
        reject(this.createGeolocationError('NOT_SUPPORTED', 'Geolocation is not supported'));
        return;
      }

      const safetyTimer = setTimeout(() => {
        reject(new Error(`Safety timeout after ${timeout + 2000}ms`));
      }, timeout + 2000);

      navigator.geolocation.getCurrentPosition(
        (position) => {
          clearTimeout(safetyTimer);
          resolve(this.positionToCoords(position));
        },
        (error) => {
          clearTimeout(safetyTimer);
          reject(error);
        },
        {
          enableHighAccuracy: highAccuracy,
          timeout,
          maximumAge: maxAge,
        },
      );
    });
  }

  private async getGPSLocation(options: GeolocationOptions): Promise<GeolocationCoords | null> {
    const { timeout = TIMEOUTS.GPS_LOCATION, maxRetries = 3, onProgress } = options;
    const isMobile = this.isMobileDevice();

    const attempts = isMobile
      ? [
          { highAccuracy: false, timeout: TIMEOUTS.USER_LOCATION - 2000, maxAge: 60000, label: 'mobile-fast' },
          { highAccuracy: true, timeout: TIMEOUTS.GPS_LOCATION, maxAge: 0, label: 'mobile-precise' },
          { highAccuracy: false, timeout: TIMEOUTS.GPS_LOCATION + 5000, maxAge: 0, label: 'mobile-fallback' },
        ]
      : [
          { highAccuracy: true, timeout, maxAge: 0, label: 'desktop-precise' },
          { highAccuracy: false, timeout: timeout + 5000, maxAge: 30000, label: 'desktop-fallback' },
        ];

    for (let i = 0; i < Math.min(attempts.length, maxRetries); i++) {
      const attempt = attempts[i];

      try {
        logger.info(
          `[GeolocationService] GPS attempt ${i + 1}/${Math.min(attempts.length, maxRetries)} (${attempt.label})`,
        );
        onProgress?.(i + 1, Math.min(attempts.length, maxRetries));

        const coords = await this.singleGPSAttempt(
          attempt.highAccuracy,
          attempt.timeout,
          attempt.maxAge,
        );

        logger.info('[GeolocationService] GPS success', {
          accuracy: `${Math.round(coords.accuracy)}m`,
        });
        return coords;
      } catch (error: any) {
        logger.warn(`[GeolocationService] GPS attempt ${i + 1} failed`, {
          code: error?.code,
          message: error?.message,
        });

        if (this.isInsecureContextError(error)) {
          throw this.createGeolocationError(
            'INSECURE_CONTEXT',
            'Automatic location requires HTTPS or localhost.',
          );
        }

        if (error?.code === 1) {
          throw this.createGeolocationError(
            'PERMISSION_DENIED',
            'Location permission denied by browser.',
          );
        }

        if (i < Math.min(attempts.length, maxRetries) - 1) {
          await new Promise((resolve) => setTimeout(resolve, 500));
        }
      }
    }

    return null;
  }

  private async getLocationFromIP(signal?: AbortSignal): Promise<GeolocationCoords | null> {
    try {
      logger.info('[GeolocationService] Trying IP geolocation fallback');

      const response = await fetch('https://ipapi.co/json/', { 
        signal,
        // Adicionar timeout para requisição HTTP
        ...(signal ? {} : { signal: AbortSignal.timeout(TIMEOUTS.IP_GEOLOCATION) })
      });
      if (!response.ok) {
        throw new Error('IP geolocation failed');
      }

      const data = await response.json();
      if (!data.latitude || !data.longitude) {
        throw new Error('Invalid IP geolocation payload');
      }

      const coords: GeolocationCoords = {
        latitude: data.latitude,
        longitude: data.longitude,
        accuracy: 5000,
        altitude: null,
        altitudeAccuracy: null,
        heading: null,
        speed: null,
        timestamp: Date.now(),
      };

      logger.info('[GeolocationService] IP geolocation success', {
        latitude: coords.latitude,
        longitude: coords.longitude,
        city: data.city,
      });

      return coords;
    } catch (error) {
      if ((error as Error).name !== 'AbortError') {
        logger.error('[GeolocationService] IP geolocation failed', error);
      }
      return null;
    }
  }

  async checkPermission(): Promise<PermissionState | 'unknown'> {
    if (!('permissions' in navigator)) {
      return 'unknown';
    }

    try {
      const result = await navigator.permissions.query({
        name: 'geolocation' as PermissionName,
      });
      return result.state;
    } catch {
      return 'unknown';
    }
  }

  async getCurrentLocation(options: GeolocationOptions = {}): Promise<GeolocationResult> {
    const { useCache = true, forcePrompt = false } = options;

    if (this.requestInFlight) {
      throw new Error('Location request already in progress');
    }

    this.requestInFlight = true;
    this.abortController = new AbortController();

    try {
      logger.info('[GeolocationService] Starting location lookup');

      if (!('geolocation' in navigator)) {
        throw this.createGeolocationError(
          'NOT_SUPPORTED',
          'Geolocation is not supported in this browser.',
        );
      }

      if (!this.isSecureRuntime()) {
        throw this.createGeolocationError(
          'INSECURE_CONTEXT',
          'Automatic location requires HTTPS or localhost. Provide address manually.',
        );
      }

      if (useCache && !forcePrompt) {
        const cached = this.getCachedLocation();
        if (cached) {
          logger.info('[GeolocationService] Returning cached location and refreshing in background');
          this.updateLocationInBackground(options);
          return cached;
        }
      }

      if (forcePrompt) {
        logger.info('[GeolocationService] forcePrompt enabled, skipping cache');
      }

      let coords: GeolocationCoords | null = null;
      let source: GeolocationResult['source'] | null = null;
      let permissionDenied = false;

      try {
        coords = await this.getGPSLocation(options);
        if (coords) {
          source = 'gps';
        }
      } catch (error: any) {
        if (error?.code === 'INSECURE_CONTEXT') {
          logger.warn('[GeolocationService] Blocked by insecure context');
          throw error;
        }

        if (error?.code === 'PERMISSION_DENIED' || error?.code === 1) {
          permissionDenied = true;
          logger.warn('[GeolocationService] Permission denied');
          throw this.createGeolocationError(
            'PERMISSION_DENIED',
            'Location permission denied by browser.',
          );
        }

        logger.warn('[GeolocationService] GPS failed, will try fallback', {
          code: error?.code,
          message: error?.message,
        });
      }

      if (!coords && !permissionDenied) {
        logger.warn('[GeolocationService] Falling back to IP geolocation');
        coords = await this.getLocationFromIP(this.abortController.signal);
        if (coords) {
          source = 'ip';
        }
      }

      if (!coords) {
        if (permissionDenied) {
          throw this.createGeolocationError(
            'PERMISSION_DENIED',
            'Location permission denied. Provide address manually.',
          );
        }

        throw this.createGeolocationError(
          'POSITION_UNAVAILABLE',
          'Could not determine location.',
        );
      }

      const result: GeolocationResult = {
        coords,
        source: source ?? 'gps',
        isHighAccuracy: coords.accuracy < 100,
      };

      this.setCachedLocation(result);

      logger.info('[GeolocationService] Location resolved', {
        source: result.source,
        accuracy: `${Math.round(result.coords.accuracy)}m`,
        isHighAccuracy: result.isHighAccuracy,
      });

      return result;
    } finally {
      this.requestInFlight = false;
      this.abortController = null;
    }
  }

  private async updateLocationInBackground(options: GeolocationOptions): Promise<void> {
    try {
      await new Promise((resolve) => setTimeout(resolve, 100));

      const coords = await this.getGPSLocation(options);
      if (coords) {
        const result: GeolocationResult = {
          coords,
          source: 'gps',
          isHighAccuracy: coords.accuracy < 100,
        };
        this.setCachedLocation(result);
        logger.info('[GeolocationService] Background cache refresh completed');
      }
    } catch (error) {
      logger.debug('[GeolocationService] Background cache refresh failed', error);
    }
  }

  clearCache(): void {
    localStorage.removeItem(CACHE_KEY);
    logger.info('[GeolocationService] Cache cleared');
  }

  abort(): void {
    if (this.abortController) {
      this.abortController.abort();
      this.requestInFlight = false;
      logger.info('[GeolocationService] Request aborted');
    }
  }
}

export const GeolocationService = new GeolocationServiceClass();

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/shared/components/ui/dialog";
import { Button } from "@/shared/components/ui/button";
import { Textarea } from "@/shared/components/ui/textarea";
import { cn } from "@/shared/utils/cn";
import { useSessionContext } from "@/core/session";
import { ModerationService } from "@/core/moderation";
import { toast } from "sonner";
import { Loader2 } from "lucide-react";

const motivos = [
  { id: "difamacao", label: "Difamacao ou acusacao" },
  { id: "falso", label: "Informacao falsa" },
  { id: "spam", label: "Spam ou propaganda abusiva" },
  { id: "ofensivo", label: "Conteudo ofensivo" },
  { id: "outro", label: "Outro" },
];

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  targetId: string | null;
  targetType: "post" | "comment" | "profile";
}

export function ReportContentDialog({
  open,
  onOpenChange,
  targetId,
  targetType,
}: Props) {
  const { activeProfile } = useSessionContext();
  const [motivo, setMotivo] = useState("");
  const [detalhes, setDetalhes] = useState("");
  const [enviando, setEnviando] = useState(false);

  const titleMap = {
    post: "Denunciar post",
    comment: "Denunciar comentario",
    profile: "Denunciar perfil",
  };

  const handleEnviar = async () => {
    if (!motivo || !targetId || !activeProfile) return;

    setEnviando(true);
    try {
      await ModerationService.reportContent({
        targetType,
        targetId,
        reporterId: activeProfile.id,
        reason: motivo,
        details: detalhes.trim(),
      });
      toast.success("Denuncia enviada. Obrigado por ajudar a comunidade.");
      onOpenChange(false);
      setMotivo("");
      setDetalhes("");
    } catch {
      toast.error("Erro ao enviar denuncia.");
    } finally {
      setEnviando(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle className="font-display">{titleMap[targetType]}</DialogTitle>
          <DialogDescription>Por que este conteudo e inadequado?</DialogDescription>
        </DialogHeader>

        <div className="flex flex-col gap-2">
          {motivos.map((m) => (
            <button
              key={m.id}
              onClick={() => setMotivo(m.id)}
              className={cn(
                "rounded-lg border px-3 py-2.5 text-left text-sm font-medium transition-all",
                motivo === m.id
                  ? "border-destructive/30 bg-destructive/10 text-destructive"
                  : "border-border bg-secondary text-foreground hover:bg-secondary/80",
              )}
            >
              {m.label}
            </button>
          ))}
        </div>

        <Textarea
          value={detalhes}
          onChange={(e) => setDetalhes(e.target.value.slice(0, 300))}
          placeholder="Detalhes adicionais (opcional)"
          className="min-h-[80px] resize-none text-sm"
        />

        <Button
          onClick={handleEnviar}
          disabled={!motivo || enviando}
          variant="destructive"
          className="w-full"
        >
          {enviando ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
          Enviar denuncia
        </Button>
      </DialogContent>
    </Dialog>
  );
}

/**
 * Push Service
 * 
 * Handles push notification subscriptions and sending.
 * Uses Firebase Cloud Messaging (FCM) for delivery.
 */

import { logger } from '@/shared/utils/logger';
import { supabase } from '@/integrations/supabase/supabase';
export interface PushSubscription {
  endpoint: string;
  keys: {
    p256dh: string;
    auth: string;
  };
}

export interface PushNotificationPayload {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  image?: string;
  data?: Record<string, any>;
  actions?: Array<{
    action: string;
    title: string;
    icon?: string;
  }>;
  tag?: string;
  requireInteraction?: boolean;
}

export interface StoredPushSubscription {
  id: string;
  user_id: string;
  endpoint: string;
  p256dh: string;
  auth: string;
  user_agent: string | null;
  device_name: string | null;
  is_active: boolean;
  created_at: string;
  last_used_at: string | null;
}

export class PushService {
  /**
   * Check if push notifications are supported
   */
  static isSupported(): boolean {
    return 'serviceWorker' in navigator && 'PushManager' in window;
  }

  /**
   * Check if user has granted permission
   */
  static async hasPermission(): Promise<boolean> {
    if (!this.isSupported()) return false;
    return Notification.permission === 'granted';
  }

  /**
   * Request permission for push notifications
   */
  static async requestPermission(): Promise<boolean> {
    if (!this.isSupported()) {
      throw new Error('Push notifications are not supported in this browser');
    }

    const permission = await Notification.requestPermission();
    return permission === 'granted';
  }

  /**
   * Subscribe to push notifications
   */
  static async subscribe(userId: string): Promise<{ success: boolean; error?: string }> {
    try {
      // Check support
      if (!this.isSupported()) {
        return { success: false, error: 'Push notifications not supported' };
      }

      // Request permission
      const hasPermission = await this.requestPermission();
      if (!hasPermission) {
        return { success: false, error: 'Permission denied' };
      }

      // Register service worker
      const registration = await navigator.serviceWorker.register('/sw.js');
      await navigator.serviceWorker.ready;

      // Get VAPID public key from edge function
      const { data: configData, error: configError } = await supabase.functions.invoke(
        'get-push-config'
      );

      if (configError || !configData?.vapidPublicKey) {
        logger.error('Error getting push config:', configError);
        return { success: false, error: 'Failed to get push configuration' };
      }

      // Subscribe to push
      const subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: this.urlBase64ToUint8Array(configData.vapidPublicKey),
      });

      // Convert to JSON
      const subscriptionJson = subscription.toJSON();

      // Store subscription in database via edge function
      const { data, error } = await supabase.functions.invoke('subscribe-push', {
        body: {
          userId,
          subscription: {
            endpoint: subscriptionJson.endpoint!,
            p256dh: subscriptionJson.keys!.p256dh!,
            auth: subscriptionJson.keys!.auth!,
          },
          userAgent: navigator.userAgent,
          deviceName: this.getDeviceName(),
        },
      });

      if (error) {
        logger.error('Error storing push subscription:', error);
        return { success: false, error: error.message };
      }

      return { success: true };
    } catch (error) {
      logger.error('Exception subscribing to push:', error);
      return { success: false, error: String(error) };
    }
  }

  /**
   * Unsubscribe from push notifications
   */
  static async unsubscribe(subscriptionId: string): Promise<{ success: boolean; error?: string }> {
    try {
      // Unsubscribe from browser
      if (this.isSupported()) {
        const registration = await navigator.serviceWorker.getRegistration();
        if (registration) {
          const subscription = await registration.pushManager.getSubscription();
          if (subscription) {
            await subscription.unsubscribe();
          }
        }
      }

      // Remove from database via edge function
      const { error } = await supabase.functions.invoke('unsubscribe-push', {
        body: { subscriptionId },
      });

      if (error) {
        logger.error('Error removing push subscription:', error);
        return { success: false, error: error.message };
      }

      return { success: true };
    } catch (error) {
      logger.error('Exception unsubscribing from push:', error);
      return { success: false, error: String(error) };
    }
  }

  /**
   * Get user's push subscriptions
   */
  static async getSubscriptions(userId: string): Promise<StoredPushSubscription[]> {
    const { data, error } = await supabase
      .from('push_subscriptions')
      .select('*')
      .eq('user_id', userId)
      .eq('is_active', true)
      .order('created_at', { ascending: false });

    if (error) {
      logger.error('Error fetching push subscriptions:', error);
      return [];
    }

    return data || [];
  }

  /**
   * Send push notification to user
   */
  static async sendToUser(
    userId: string,
    notification: PushNotificationPayload
  ): Promise<{ success: boolean; error?: string }> {
    try {
      const { data, error } = await supabase.functions.invoke('send-push', {
        body: {
          userId,
          notification,
        },
      });

      if (error) {
        logger.error('Error sending push notification:', error);
        return { success: false, error: error.message };
      }

      return { success: true };
    } catch (error) {
      logger.error('Exception sending push notification:', error);
      return { success: false, error: String(error) };
    }
  }

  /**
   * Send push notification to multiple users
   */
  static async sendToUsers(
    userIds: string[],
    notification: PushNotificationPayload
  ): Promise<{ success: boolean; error?: string }> {
    try {
      const { data, error } = await supabase.functions.invoke('send-push-bulk', {
        body: {
          userIds,
          notification,
        },
      });

      if (error) {
        logger.error('Error sending bulk push notifications:', error);
        return { success: false, error: error.message };
      }

      return { success: true };
    } catch (error) {
      logger.error('Exception sending bulk push notifications:', error);
      return { success: false, error: String(error) };
    }
  }

  /**
   * Test push notification (sends to current user)
   */
  static async sendTestNotification(userId: string): Promise<{ success: boolean; error?: string }> {
    return this.sendToUser(userId, {
      title: 'Notificação de Teste 🎉',
      body: 'Se você está vendo isso, as notificações push estão funcionando!',
      icon: '/icon-192x192.png',
      badge: '/badge-72x72.png',
      tag: 'test-notification',
      data: {
        type: 'test',
        timestamp: Date.now(),
      },
    });
  }

  // ============================================================================
  // HELPER METHODS
  // ============================================================================

  /**
   * Convert VAPID key from base64 to Uint8Array
   */
  private static urlBase64ToUint8Array(base64String: string): Uint8Array {
    const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');

    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);

    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }

  /**
   * Get device name from user agent
   */
  private static getDeviceName(): string {
    const ua = navigator.userAgent;

    // Mobile devices
    if (/iPhone/.test(ua)) return 'iPhone';
    if (/iPad/.test(ua)) return 'iPad';
    if (/Android/.test(ua)) {
      const match = ua.match(/Android.*?;\s*([^)]+)/);
      return match ? match[1] : 'Android Device';
    }

    // Desktop browsers
    if (/Chrome/.test(ua)) return 'Chrome';
    if (/Firefox/.test(ua)) return 'Firefox';
    if (/Safari/.test(ua)) return 'Safari';
    if (/Edge/.test(ua)) return 'Edge';

    return 'Unknown Device';
  }
}

/**
 * PricingService - SSOT para precificação e estimativas
 *
 * Responsabilidades:
 * - Calcular estimativas de preço
 * - Gerenciar regras de precificação
 * - Aplicar multiplicadores (horário de pico, etc.)
 * - Calcular detalhamento de preço
 *
 * Regras:
 * - Separação clara: routing fornece distância/tempo, pricing calcula preço
 * - Suporte a múltiplos modos (ride, delivery, mototaxi, motoboy)
 * - Preparado para pricing dinâmico futuro
 *
 * Padrão: Service → Hook → Component
 */
import { logger } from '@/shared/utils/logger';
import { supabase } from '@/integrations/supabase';
import { trackError } from '@/shared/utils/errorTracking';
import { calculateDistance } from '@/shared/utils/geolocation';
import { PricingError } from '../types';
import type {
  PricingMode,
  PricingContext,
  PriceEstimateRequest,
  PriceEstimateResponse,
  PricingBreakdown,
  PricingBreakdownItem,
  AdditionalFee,
  PricingRule,
  PricingServiceConfig,
  PRICING_CONSTANTS,
  PricingError,
} from '../types';

export class PricingService {
  private static instance: PricingService;
  private config: PricingServiceConfig;
  private rulesCache: Map<PricingMode, { rule: PricingRule; cachedAt: number }>;
  private readonly CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutos

  private constructor() {
    this.config = {
      defaultMode: 'ride',
      currency: 'BRL',
      enablePeakHours: true,
      enableDynamicPricing: false,
      cacheEstimates: false,
      cacheTtlSeconds: 300,
    };

    this.rulesCache = new Map();
  }

  static getInstance(): PricingService {
    if (!PricingService.instance) {
      PricingService.instance = new PricingService();
    }
    return PricingService.instance;
  }

  /**
   * Configura o serviço
   */
  configure(config: Partial<PricingServiceConfig>): void {
    this.config = { ...this.config, ...config };
  }

  // ============================================
  // PRICE ESTIMATION
  // ============================================

  /**
   * Calcula estimativa de preço
   */
  async calculateEstimate(
    request: PriceEstimateRequest
  ): Promise<PriceEstimateResponse> {
    try {
      // 1. Calcular distância
      const distanceMeters = calculateDistance(
        request.origin.latitude,
        request.origin.longitude,
        request.destination.latitude,
        request.destination.longitude
      );
      const distanceKm = distanceMeters / 1000;

      // 2. Estimar duração
      const durationMinutes = this.estimateDuration(distanceKm);

      // 3. Obter regra de precificação
      const rule = await this.getRule(request.mode);

      // 4. Calcular preço base
      const basePrice = this.calculateBasePrice(
        distanceKm,
        durationMinutes,
        rule
      );

      // 5. Aplicar multiplicadores
      let finalPrice = basePrice;
      let peakHourMultiplier = 1.0;

      if (request.options?.applyPeakHours !== false && this.config.enablePeakHours) {
        peakHourMultiplier = this.getPeakHourMultiplier(request.timestamp);
        finalPrice *= peakHourMultiplier;
      }

      if (request.options?.customMultiplier) {
        finalPrice *= request.options.customMultiplier;
      }

      // 6. Aplicar mínimo
      finalPrice = Math.max(finalPrice, rule.minimumFare);

      // 7. Aplicar máximo (se definido)
      if (rule.maximumFare) {
        finalPrice = Math.min(finalPrice, rule.maximumFare);
      }

      // 8. Gerar breakdown se solicitado
      let breakdown: PricingBreakdown | undefined;
      if (request.options?.includeBreakdown) {
        breakdown = this.generateBreakdown(
          distanceKm,
          durationMinutes,
          rule,
          peakHourMultiplier,
          request.options?.customMultiplier
        );
      }

      return {
        estimatedPrice: Number(finalPrice.toFixed(2)),
        minimumPrice: rule.minimumFare,
        maximumPrice: rule.maximumFare,
        currency: this.config.currency,
        breakdown,
        metadata: {
          distanceKm: Number(distanceKm.toFixed(2)),
          durationMinutes: Math.round(durationMinutes),
          peakHourMultiplier: peakHourMultiplier !== 1.0 ? peakHourMultiplier : undefined,
          mode: request.mode,
        },
      };
    } catch (error) {
      logger.error('[PricingService] Error calculating estimate:', error);
      throw error;
    }
  }

  /**
   * Calcula estimativa rápida (sem breakdown)
   */
  async calculateQuickEstimate(
    mode: PricingMode,
    distanceKm: number,
    durationMinutes: number
  ): Promise<number> {
    const rule = await this.getRule(mode);
    const basePrice = this.calculateBasePrice(distanceKm, durationMinutes, rule);
    
    let finalPrice = basePrice;
    if (this.config.enablePeakHours) {
      finalPrice *= this.getPeakHourMultiplier();
    }
    
    return Math.max(Number(finalPrice.toFixed(2)), rule.minimumFare);
  }

  // ============================================
  // PRICING RULES
  // ============================================

  /**
   * Obtém regra de precificação para um modo (com cache)
   */
  async getRule(mode: PricingMode): Promise<PricingRule> {
    // Verificar cache
    const cached = this.rulesCache.get(mode);
    if (cached && Date.now() - cached.cachedAt < this.CACHE_TTL_MS) {
      return cached.rule;
    }

    // Buscar do banco
    try {
      const now = new Date().toISOString();
      
      const { data: ruleData, error: ruleError } = await supabase
        .from('pricing_rules')
        .select('*')
        .eq('mode', mode)
        .eq('is_active', true)
        .or(`valid_from.is.null,valid_from.lte.${now}`)
        .or(`valid_until.is.null,valid_until.gte.${now}`)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();

      if (ruleError) throw ruleError;

      if (!ruleData) {
        logger.warn(`[PricingService] No active rule found for mode: ${mode}, using fallback`);
        return this.getFallbackRule(mode);
      }

      // Buscar multiplicadores de horário de pico
      const { data: multipliersData } = await supabase
        .from('pricing_peak_hour_multipliers')
        .select('*')
        .eq('rule_id', ruleData.id)
        .eq('is_active', true);

      // Buscar taxas adicionais
      const { data: feesData } = await supabase
        .from('pricing_additional_fees')
        .select('*')
        .eq('rule_id', ruleData.id)
        .eq('is_active', true);

      const rule = this.mapToRule(ruleData, multipliersData || [], feesData || []);

      // Atualizar cache
      this.rulesCache.set(mode, { rule, cachedAt: Date.now() });

      return rule;
    } catch (error) {
      logger.error('[PricingService] Error fetching rule from database:', error);
      trackError(error as Error, {
        component: 'PricingService',
        action: 'getRule',
        metadata: { mode },
      });
      return this.getFallbackRule(mode);
    }
  }

  /**
   * Atualiza regra de precificação
   */
  async updateRule(
    ruleId: string,
    updates: Partial<PricingRule>,
    performedBy: string
  ): Promise<void> {
    try {
      // Se está ativando uma regra, usar RPC para evitar conflito com trigger
      if (updates.isActive === true) {
        const { error: rpcError } = await supabase.rpc('activate_pricing_rule', {
          p_rule_id: ruleId,
          p_performed_by: performedBy,
        });

        if (rpcError) {
          throw new Error(rpcError.message || 'Erro ao ativar regra');
        }

        // Se só está ativando, não precisa fazer mais nada
        if (Object.keys(updates).length === 1) {
          this.rulesCache.clear();
          return;
        }
      }

      // Atualizar outros campos (se houver)
      const updateData: any = {};
      
      if (updates.name !== undefined) updateData.name = updates.name;
      if (updates.baseFare !== undefined) updateData.base_fare = updates.baseFare;
      if (updates.pricePerKm !== undefined) updateData.price_per_km = updates.pricePerKm;
      if (updates.pricePerMinute !== undefined) updateData.price_per_minute = updates.pricePerMinute;
      if (updates.minimumFare !== undefined) updateData.minimum_fare = updates.minimumFare;
      if (updates.maximumFare !== undefined) updateData.maximum_fare = updates.maximumFare;
      if (updates.isActive === false) updateData.is_active = false; // Desativar é seguro
      if (updates.validFrom !== undefined) updateData.valid_from = updates.validFrom?.toISOString();
      if (updates.validUntil !== undefined) updateData.valid_until = updates.validUntil?.toISOString();
      if (updates.metadata !== undefined) updateData.metadata = updates.metadata;
      
      if (Object.keys(updateData).length > 0) {
        updateData.updated_by = performedBy;

        const { error } = await supabase
          .from('pricing_rules')
          .update(updateData)
          .eq('id', ruleId);

        if (error) {
          const errorMessage = error.message || JSON.stringify(error);
          const errorCode = error.code || '';
          const errorHint = error.hint || '';
          
          if (errorCode === '23514' || errorHint.includes('validate_single_active_rule')) {
            throw PricingError.conflict('Não é possível desativar a única regra ativa desta modalidade');
          }
          if (errorMessage.includes('Conflito') || errorMessage.includes('conflito')) {
            throw PricingError.conflict(errorMessage);
          }
          throw new Error(errorMessage);
        }
      }

      // Limpar cache
      this.rulesCache.clear();
    } catch (error: any) {
      const errorMessage = error?.message || String(error);
      const errorCode = error?.code || '';
      const errorHint = error?.hint || '';
      
      logger.error('[PricingService] Error updating rule:', errorMessage);
      
      // Re-lançar PricingError
      if (error instanceof PricingError) {
        throw error;
      }
      
      // Detectar conflito de regra ativa
      if (errorCode === '23514' || errorHint.includes('validate_single_active_rule')) {
        throw PricingError.conflict('Não é possível desativar a única regra ativa desta modalidade');
      }
      if (errorMessage.includes('Conflito') || errorMessage.includes('conflito') || errorMessage.includes('já existe regra ativa')) {
        throw PricingError.conflict('Já existe uma regra ativa para este modo no período especificado');
      }
      
      throw new Error(errorMessage);
    }
  }

  /**
   * Lista todas as regras ativas
   */
  async listRules(includeInactive: boolean = false): Promise<PricingRule[]> {
    try {
      let query = supabase
        .from('pricing_rules')
        .select(`
          *,
          peak_hour_multipliers:pricing_peak_hour_multipliers(*),
          additional_fees:pricing_additional_fees(*)
        `)
        .order('created_at', { ascending: false });

      if (!includeInactive) {
        query = query.eq('is_active', true);
      }

      const { data, error } = await query;

      if (error) throw error;

      return (data || []).map((item) =>
        this.mapToRule(
          item,
          item.peak_hour_multipliers || [],
          item.additional_fees || []
        )
      );
    } catch (error) {
      logger.error('[PricingService] Error listing rules:', error);
      return [];
    }
  }

  /**
   * Cria nova regra de precificação
   */
  async createRule(
    rule: Omit<PricingRule, 'id'>,
    performedBy: string
  ): Promise<string> {
    try {
      // Usar RPC para criar regra ativa (desativa outras automaticamente)
      if (rule.isActive) {
        const { data: ruleId, error: rpcError } = await supabase.rpc('create_active_pricing_rule', {
          p_mode: rule.mode,
          p_name: rule.name,
          p_base_fare: rule.baseFare,
          p_price_per_km: rule.pricePerKm,
          p_price_per_minute: rule.pricePerMinute,
          p_minimum_fare: rule.minimumFare,
          p_maximum_fare: rule.maximumFare || null,
          p_is_active: rule.isActive,
          p_valid_from: rule.validFrom?.toISOString() || null,
          p_valid_until: rule.validUntil?.toISOString() || null,
          p_metadata: rule.metadata || {},
          p_performed_by: performedBy,
        });

        if (rpcError) {
          throw new Error(rpcError.message || 'Erro ao criar regra');
        }

        const newRuleId = ruleId as string;

        // Inserir multiplicadores se houver
        if (rule.peakHourMultipliers) {
          const multipliers = [];
          if (rule.peakHourMultipliers.morning) {
            multipliers.push({
              rule_id: newRuleId,
              period_type: 'morning',
              multiplier: rule.peakHourMultipliers.morning,
              start_hour: 7,
              end_hour: 9,
              days_of_week: [1, 2, 3, 4, 5],
            });
          }
          if (rule.peakHourMultipliers.afternoon) {
            multipliers.push({
              rule_id: newRuleId,
              period_type: 'afternoon',
              multiplier: rule.peakHourMultipliers.afternoon,
              start_hour: 17,
              end_hour: 19,
              days_of_week: [1, 2, 3, 4, 5],
            });
          }
          if (rule.peakHourMultipliers.night) {
            multipliers.push({
              rule_id: newRuleId,
              period_type: 'night',
              multiplier: rule.peakHourMultipliers.night,
              start_hour: 22,
              end_hour: 24,
              days_of_week: [1, 2, 3, 4, 5],
            });
          }

          if (multipliers.length > 0) {
            await supabase.from('pricing_peak_hour_multipliers').insert(multipliers);
          }
        }

        // Inserir taxas adicionais se houver
        if (rule.additionalFees && rule.additionalFees.length > 0) {
          const fees = rule.additionalFees.map((fee) => ({
            rule_id: newRuleId,
            label: fee.label,
            amount: fee.amount,
            fee_type: fee.type,
            reason: fee.reason,
          }));

          await supabase.from('pricing_additional_fees').insert(fees);
        }

        // Limpar cache
        this.rulesCache.clear();

        return newRuleId;
      }

      // Criar regra inativa (não precisa de RPC)
      const ruleData = {
        mode: rule.mode,
        name: rule.name,
        base_fare: rule.baseFare,
        price_per_km: rule.pricePerKm,
        price_per_minute: rule.pricePerMinute,
        minimum_fare: rule.minimumFare,
        maximum_fare: rule.maximumFare,
        is_active: false,
        valid_from: rule.validFrom?.toISOString(),
        valid_until: rule.validUntil?.toISOString(),
        metadata: rule.metadata || {},
        created_by: performedBy,
        updated_by: performedBy,
      };

      const { data, error } = await supabase
        .from('pricing_rules')
        .insert(ruleData)
        .select('id')
        .single();

      if (error) throw error;

      // Inserir multiplicadores se houver
      if (rule.peakHourMultipliers) {
        const multipliers = [];
        if (rule.peakHourMultipliers.morning) {
          multipliers.push({
            rule_id: data.id,
            period_type: 'morning',
            multiplier: rule.peakHourMultipliers.morning,
            start_hour: 7,
            end_hour: 9,
            days_of_week: [1, 2, 3, 4, 5],
          });
        }
        if (rule.peakHourMultipliers.afternoon) {
          multipliers.push({
            rule_id: data.id,
            period_type: 'afternoon',
            multiplier: rule.peakHourMultipliers.afternoon,
            start_hour: 17,
            end_hour: 19,
            days_of_week: [1, 2, 3, 4, 5],
          });
        }
        if (rule.peakHourMultipliers.night) {
          multipliers.push({
            rule_id: data.id,
            period_type: 'night',
            multiplier: rule.peakHourMultipliers.night,
            start_hour: 22,
            end_hour: 24,
            days_of_week: [1, 2, 3, 4, 5],
          });
        }

        if (multipliers.length > 0) {
          await supabase.from('pricing_peak_hour_multipliers').insert(multipliers);
        }
      }

      // Inserir taxas adicionais se houver
      if (rule.additionalFees && rule.additionalFees.length > 0) {
        const fees = rule.additionalFees.map((fee) => ({
          rule_id: data.id,
          label: fee.label,
          amount: fee.amount,
          fee_type: fee.type,
          reason: fee.reason,
        }));

        await supabase.from('pricing_additional_fees').insert(fees);
      }

      // Limpar cache
      this.rulesCache.clear();

      return data.id;
    } catch (error: any) {
      const errorMessage = error?.message || String(error);
      const errorCode = error?.code || '';
      const errorHint = error?.hint || '';
      
      logger.error('[PricingService] Error creating rule:', errorMessage);
      
      // Detectar conflito de regra ativa
      if (errorCode === '23514' || errorHint.includes('validate_single_active_rule')) {
        throw PricingError.conflict('Já existe uma regra ativa para este modo no período especificado');
      }
      if (errorMessage.includes('Conflito') || errorMessage.includes('conflito') || errorMessage.includes('já existe regra ativa')) {
        throw PricingError.conflict('Já existe uma regra ativa para este modo no período especificado');
      }
      
      throw new Error(errorMessage);
    }
  }

  /**
   * Limpa cache de regras
   */
  clearCache(): void {
    this.rulesCache.clear();
  }

