  /**
   * Mapeia dados do banco para PricingRule
   */
  private mapToRule(
    data: any,
    multipliers: any[],
    fees: any[]
  ): PricingRule {
    const peakHourMultipliers: any = {};
    
    multipliers.forEach((m) => {
      if (m.period_type === 'morning') peakHourMultipliers.morning = Number(m.multiplier);
      if (m.period_type === 'afternoon') peakHourMultipliers.afternoon = Number(m.multiplier);
      if (m.period_type === 'night') peakHourMultipliers.night = Number(m.multiplier);
    });

    const additionalFees: AdditionalFee[] = fees.map((f) => ({
      id: f.id,
      label: f.label,
      amount: Number(f.amount),
      type: f.fee_type,
      reason: f.reason,
    }));

    return {
      id: data.id,
      mode: data.mode,
      name: data.name,
      baseFare: Number(data.base_fare),
      pricePerKm: Number(data.price_per_km),
      pricePerMinute: Number(data.price_per_minute),
      minimumFare: Number(data.minimum_fare),
      maximumFare: data.maximum_fare ? Number(data.maximum_fare) : undefined,
      peakHourMultipliers: Object.keys(peakHourMultipliers).length > 0 ? peakHourMultipliers : undefined,
      additionalFees: additionalFees.length > 0 ? additionalFees : undefined,
      isActive: data.is_active,
      validFrom: data.valid_from ? new Date(data.valid_from) : undefined,
      validUntil: data.valid_until ? new Date(data.valid_until) : undefined,
      metadata: data.metadata || {},
    };
  }

  /**
   * Calcula preço base (sem multiplicadores)
   */
  private calculateBasePrice(
    distanceKm: number,
    durationMinutes: number,
    rule: PricingRule
  ): number {
    const distanceFare = distanceKm * rule.pricePerKm;
    const timeFare = durationMinutes * rule.pricePerMinute;
    return rule.baseFare + distanceFare + timeFare;
  }

  /**
   * Estima duração baseada em distância
   */
  private estimateDuration(distanceKm: number): number {
    const AVERAGE_SPEED_KMH = 40;
    const durationHours = distanceKm / AVERAGE_SPEED_KMH;
    return durationHours * 60; // minutos
  }

  /**
   * Obtém multiplicador de horário de pico
   */
  private getPeakHourMultiplier(date: Date = new Date()): number {
    const hour = date.getHours();
    const dayOfWeek = date.getDay(); // 0 = domingo, 6 = sábado

    // Fim de semana: sem multiplicador
    if (dayOfWeek === 0 || dayOfWeek === 6) {
      return 1.0;
    }

    // Horários de pico manhã (7h-9h)
    if (hour >= 7 && hour < 9) {
      return 1.3;
    }

    // Horários de pico tarde (17h-19h)
    if (hour >= 17 && hour < 19) {
      return 1.5;
    }

    // Horários de pico noite (22h-2h)
    if (hour >= 22 || hour < 2) {
      return 1.2;
    }

    return 1.0;
  }

  /**
   * Gera detalhamento de preço
   */
  private generateBreakdown(
    distanceKm: number,
    durationMinutes: number,
    rule: PricingRule,
    peakHourMultiplier: number,
    customMultiplier?: number
  ): PricingBreakdown {
    const distanceFare = distanceKm * rule.pricePerKm;
    const timeFare = durationMinutes * rule.pricePerMinute;
    const subtotal = rule.baseFare + distanceFare + timeFare;

    const items: PricingBreakdownItem[] = [
      {
        label: 'Tarifa base',
        value: Number(rule.baseFare.toFixed(2)),
        type: 'base',
      },
      {
        label: `Distância (${distanceKm.toFixed(1)}km)`,
        value: Number(distanceFare.toFixed(2)),
        type: 'distance',
      },
      {
        label: `Tempo (${Math.round(durationMinutes)}min)`,
        value: Number(timeFare.toFixed(2)),
        type: 'time',
      },
    ];

    let total = subtotal;

    // Multiplicador de horário de pico
    if (peakHourMultiplier > 1.0) {
      const peakFee = subtotal * (peakHourMultiplier - 1);
      items.push({
        label: `Horário de pico (${peakHourMultiplier}x)`,
        value: Number(peakFee.toFixed(2)),
        type: 'multiplier',
      });
      total *= peakHourMultiplier;
    }

    // Multiplicador customizado
    if (customMultiplier && customMultiplier > 1.0) {
      const customFee = total * (customMultiplier - 1);
      items.push({
        label: `Ajuste (${customMultiplier}x)`,
        value: Number(customFee.toFixed(2)),
        type: 'multiplier',
      });
      total *= customMultiplier;
    }

    // Taxas adicionais
    const additionalFees: AdditionalFee[] = rule.additionalFees || [];
    const totalFees = additionalFees.reduce((sum, fee) => {
      const amount = fee.type === 'percentage' ? total * (fee.amount / 100) : fee.amount;
      return sum + amount;
    }, 0);

    if (additionalFees.length > 0) {
      additionalFees.forEach((fee) => {
        const amount = fee.type === 'percentage' ? total * (fee.amount / 100) : fee.amount;
        items.push({
          label: fee.label,
          value: Number(amount.toFixed(2)),
          type: 'fee',
        });
      });
    }

    total += totalFees;

    // Aplicar mínimo
    if (total < rule.minimumFare) {
      items.push({
        label: 'Ajuste para valor mínimo',
        value: Number((rule.minimumFare - total).toFixed(2)),
        type: 'fee',
      });
      total = rule.minimumFare;
    }

    return {
      baseFare: rule.baseFare,
      distanceFare: Number(distanceFare.toFixed(2)),
      timeFare: Number(timeFare.toFixed(2)),
      subtotal: Number(subtotal.toFixed(2)),
      additionalFees,
      totalFees: Number(totalFees.toFixed(2)),
      total: Number(total.toFixed(2)),
      items,
    };
  }

  /**
   * Obtém log de auditoria de pricing
   */
  async getAuditLog(limit: number = 20): Promise<any[]> {
    try {
      const { data, error } = await supabase
        .from('pricing_audit_log')
        .select('*')
        .order('created_at', { ascending: false })
        .limit(limit);

      if (error) throw error;

      return data || [];
    } catch (error) {
      logger.error('[PricingService] Error fetching audit log:', error);
      trackError(error as Error, { context: 'PricingService.getAuditLog' });
      throw error;
    }
  }
}

// Singleton instance
export const pricingService = PricingService.getInstance();

import { Building2, Briefcase, Car, User, type LucideIcon } from "lucide-react";
import { BusinessService } from "@/core/profiles/services/multi-profile/businessService";
import { DriverService } from "@/core/profiles/services/multi-profile/driverService";
import { ProfessionalService } from "@/core/profiles/services/multi-profile/professionalService";
import type {
  BusinessData,
  DriverData,
  ProfessionalData,
  Profile,
  ProfileType,
} from "@/core/profiles/services/multi-profile/types";

export type ProfileVerificationStatus =
  | "not_requested"
  | "pending"
  | "approved"
  | "rejected";

export function getProfileType(
  profileOrType?: Pick<Profile, "profile_type"> | ProfileType | null,
): ProfileType | null {
  if (!profileOrType) {
    return null;
  }

  return typeof profileOrType === "string" ? profileOrType : profileOrType.profile_type;
}

export function getProfileTypeIcon(
  profileOrType?: Pick<Profile, "profile_type"> | ProfileType | null,
): LucideIcon {
  const profileType = getProfileType(profileOrType);

  return {
    personal: User,
    business: Building2,
    professional: Briefcase,
    driver: Car,
  }[profileType ?? "personal"];
}

export function getProfileTypeLabel(
  profileOrType?: Pick<Profile, "profile_type"> | ProfileType | null,
): string {
  const profileType = getProfileType(profileOrType) ?? "personal";

  return {
    personal: "Pessoal",
    business: "Empresa",
    professional: "Profissional",
    driver: "Motorista",
  }[profileType];
}

export function canProfileHaveMembers(
  profileOrType?: Pick<Profile, "profile_type"> | ProfileType | null,
): boolean {
  const profileType = getProfileType(profileOrType);

  return profileType === "business" || profileType === "professional";
}

export function isProfileVerified(
  activeProfile?: Pick<Profile, "verified"> | null,
  fallbackProfile?: { is_verified?: boolean | null } | null,
): boolean {
  return Boolean(activeProfile?.verified || fallbackProfile?.is_verified);
}

export function getEditablePersonalHandle(
  profile?: Pick<Profile, "profile_type" | "handle"> | null,
): string | null {
  if (!profile || profile.profile_type !== "personal") {
    return null;
  }

  return profile.handle ?? "";
}

export function resolveVerificationStatus(
  verification?: { verified?: boolean | null; rejection_reason?: string | null } | null,
): { status: ProfileVerificationStatus; rejectionReason?: string } {
  if (!verification) {
    return { status: "not_requested" };
  }

  if (verification.verified) {
    return { status: "approved" };
  }

  if (verification.rejection_reason) {
    return {
      status: "rejected",
      rejectionReason: verification.rejection_reason,
    };
  }

  return { status: "pending" };
}

export async function saveProfileExtensionByType(
  profile: Pick<Profile, "id" | "profile_type">,
  forms: {
    bizForm: Partial<BusinessData>;
    proForm: Partial<ProfessionalData>;
    drvForm: Partial<DriverData>;
  },
): Promise<void> {
  if (profile.profile_type === "business") {
    const {
      profile_id: _unusedProfileId,
      created_at: _unusedCreatedAt,
      updated_at: _unusedUpdatedAt,
      ...bizUpdates
    } = forms.bizForm as BusinessData & {
      created_at?: string;
      updated_at?: string;
    };
    const result = await BusinessService.updateBusinessData(profile.id, bizUpdates);
    if (!result.success) {
      throw new Error(result.error);
    }
    return;
  }

  if (profile.profile_type === "professional") {
    const {
      profile_id: _unusedProfileId,
      created_at: _unusedCreatedAt,
      updated_at: _unusedUpdatedAt,
      ...proUpdates
    } = forms.proForm as ProfessionalData & {
      created_at?: string;
      updated_at?: string;
    };
    const result = await ProfessionalService.updateProfessionalData(profile.id, proUpdates);
    if (!result.success) {
      throw new Error(result.error);
    }
    return;
  }

  if (profile.profile_type === "driver") {
    const {
      profile_id: _unusedProfileId,
      created_at: _unusedCreatedAt,
      updated_at: _unusedUpdatedAt,
      ...drvUpdates
    } = forms.drvForm as DriverData & {
      created_at?: string;
      updated_at?: string;
    };
    const result = await DriverService.updateDriverData(profile.id, drvUpdates);
    if (!result.success) {
      throw new Error(result.error);
    }
  }
}

export async function loadProfileExtensionByType(
  profile: Pick<Profile, "id" | "profile_type">,
): Promise<{
  bizForm?: BusinessData;
  proForm?: ProfessionalData;
  drvForm?: DriverData;
}> {
  if (profile.profile_type === "business") {
    const bizForm = await BusinessService.getBusinessData(profile.id);
    return bizForm ? { bizForm } : {};
  }

  if (profile.profile_type === "professional") {
    const proForm = await ProfessionalService.getProfessionalData(profile.id);
    return proForm ? { proForm } : {};
  }

  if (profile.profile_type === "driver") {
    const drvForm = await DriverService.getDriverData(profile.id);
    return drvForm ? { drvForm } : {};
  }

  return {};
}

/**
 * IdentityChangeConfirmDialog
 * Dialog de confirmação explícita ao salvar mudança de slug/username.
 * Exigido quando há mudança real de identificador.
 */
import { logger } from '@/shared/utils/logger';
import { useEffect } from 'react';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/shared/components/ui/alert-dialog';
import type { EntityType } from '@/core/public-identity/domain/types';

interface IdentityChangeConfirmDialogProps {
  open: boolean;
  entityType: EntityType;
  onConfirm: () => void;
  onCancel: () => void;
  oldIdentifier?: string;
  newIdentifier?: string;
}

const DIALOG_CONFIG: Record<EntityType, { title: string; description: string }> = {
  business: {
    title: 'Confirmar alteração de link público',
    description:
      'Você está alterando o link público da empresa. Links antigos continuarão funcionando e serão redirecionados para o novo endereço.',
  },
  profile: {
    title: 'Confirmar alteração de nome de usuário',
    description:
      'Você está alterando seu nome de usuário público. Links antigos podem deixar de funcionar. Use essa troca apenas se for realmente necessário.',
  },
  professional: {
    title: 'Confirmar alteração de link público',
    description:
      'Você está alterando o link público profissional. Links antigos podem deixar de funcionar. Revise bem antes de confirmar.',
  },
};

export function IdentityChangeConfirmDialog({
  open,
  entityType,
  onConfirm,
  onCancel,
  oldIdentifier,
  newIdentifier,
}: IdentityChangeConfirmDialogProps) {
  const config = DIALOG_CONFIG[entityType];

  useEffect(() => {
    if (open) {
      logger.info('[IdentityChangeConfirmDialog] opened', {
        entityType,
        oldIdentifier,
        newIdentifier,
      });
