          <AlertDialogCancel onClick={handleCancel}>Cancelar</AlertDialogCancel>
          <AlertDialogAction onClick={handleConfirm}>Confirmar alteração</AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
