 * Aviso persistente de impacto de mudança de identidade pública.
 */

import { Info, AlertTriangle, ArrowRight } from 'lucide-react';
import type { EntityType } from '@/core/public-identity/domain/types';

interface IdentityImpactNoticeProps {
  entityType: EntityType;
  originalValue: string;
  currentValue: string;
  originalUrl?: string;
  newUrl?: string;
}

const NOTICE_CONFIG: Record<
  EntityType,
  {
    variant: 'info' | 'warning';
    persistentMessage: string;
    changeMessage: string;
  }
> = {
  business: {
    variant: 'info',
    persistentMessage:
      'Seu link público da empresa pode ser alterado. Se isso acontecer, links antigos continuarão sendo redirecionados automaticamente.',
    changeMessage: 'O link público da empresa será alterado.',
  },
  profile: {
    variant: 'warning',
    persistentMessage:
      'Atenção: se você mudar seu nome de usuário, links antigos podem parar de funcionar em perfil, bio, QR Code, cartão ou materiais já compartilhados.',
    changeMessage:
      'Seu nome de usuário público será alterado. Links antigos podem deixar de funcionar.',
  },
  professional: {
    variant: 'warning',
    persistentMessage:
      'Atenção: se você mudar o link público profissional, links antigos podem parar de funcionar em cartões, anúncios, QR Codes e materiais já divulgados.',
    changeMessage:
      'O link público profissional será alterado. Links antigos podem deixar de funcionar.',
  },
};

export function IdentityImpactNotice({
  entityType,
  originalValue,
  currentValue,
  originalUrl,
  newUrl,
}: IdentityImpactNoticeProps) {
  const config = NOTICE_CONFIG[entityType];
  const hasChange =
    !!originalValue &&
    !!currentValue &&
    originalValue.trim() !== currentValue.trim();

  const isInfo = config.variant === 'info';

  const baseClass = isInfo
    ? 'border-blue-200 bg-blue-50 text-blue-800'
    : 'border-amber-200 bg-amber-50 text-amber-800';

  const Icon = isInfo ? Info : AlertTriangle;

  return (
    <div
      className={`rounded-md border px-3 py-2.5 text-xs space-y-2 ${baseClass}`}
      role="note"
      aria-label={hasChange ? config.changeMessage : config.persistentMessage}
    >
      <div className="flex items-start gap-2">
        <Icon className="h-3.5 w-3.5 mt-0.5 shrink-0" aria-hidden="true" />
        <span>{hasChange ? config.changeMessage : config.persistentMessage}</span>
      </div>

      {hasChange && originalUrl && newUrl && (
        <div className="flex items-center gap-1.5 font-mono text-[11px] pl-5 flex-wrap">
          <span className="line-through opacity-60">{originalUrl}</span>
          <ArrowRight className="h-3 w-3 shrink-0" aria-hidden="true" />
          <span className="font-semibold">{newUrl}</span>
        </div>
      )}
    </div>
  );
}

/**
 * useIdentityUrlPreview
 * Hook puro (sem IO) que computa a URL pública de um identificador.
 * Cada domínio injeta sua própria função de preview.
 */

import { useMemo } from 'react';
import type { EntityType } from '@/core/public-identity/domain/types';

export type UrlPreviewFn = (identifier: string) => string;

/** Funções de preview por domínio - sem estado, sem IO */
export const URL_PREVIEW_FNS: Record<EntityType, UrlPreviewFn> = {
  business: (slug) => (slug ? `/empresas/:uf/:cidade/:bairro/${slug}` : ''),
  profile: (username) => (username ? `/u/${username}` : ''),
  professional: (slug) => (slug ? `/profissionais/:uf/:cidade/${slug}` : ''),
};

export interface UseIdentityUrlPreviewOptions {
  entityType: EntityType;
  identifier: string;
  /** Sobrescreve a função de preview padrão (ex: business premium usa /p/:slug) */
  previewFn?: UrlPreviewFn;
}

export function useIdentityUrlPreview({
  entityType,
  identifier,
  previewFn,
}: UseIdentityUrlPreviewOptions): string {
  return useMemo(() => {
    const fn = previewFn ?? URL_PREVIEW_FNS[entityType];
    return fn(identifier);
  }, [entityType, identifier, previewFn]);
}

/**
 * TerritorialLayout
 *
 * Layout base para rotas territoriais.
 * Resolve o território a partir da URL, gerencia estados e
 * expõe identidade territorial + navegação de módulos.
 *
 * Etapa 8: expõe groupAvailability no contexto do Outlet e exibe
 * banner de cobertura parcial quando availability === 'partial'.
 */

import { Loader2, AlertTriangle } from 'lucide-react';
import { Outlet, useOutletContext, useParams, useLocation } from 'react-router-dom';
import { useEffect } from 'react';
import { useResolveTerritoryFromUrl } from '../hooks/useResolveTerritoryFromUrl';
import { TerritorialNotFound } from './TerritorialNotFound';
import { TerritorialSEO } from '../seo/TerritorialSEO';
import { MODULE_SLUGS, isEntityDetailRoute } from '../utils/territoryUrls';
import { useGroupAvailability } from '@/core/territorial/hooks/useGroupAvailability';
import { ModuleKey } from '@/core/rollout/types';
import { lastTerritoryStore } from '../stores/LastTerritoryStore';
import { TERRITORY_CONFIG } from '@/config/territory';
import { ErrorBoundary } from '@/shared/components/errors/ErrorBoundary';
import type { ResolvedTerritory } from '../hooks/useResolveTerritoryFromUrl';
import type { GroupModuleAvailability } from '@/core/territorial/types';

// ── Contexto do Outlet ───────────────────────────────────────────────────────

export type TerritorialLayoutContext = {
  resolved: ResolvedTerritory;
  /**
   * URL base do território atual, calculada deterministicamente via useParams.
   * Ex: /ba/salvador/nordeste-de-amaralina
   *     /ba/salvador/complexo-do-nordeste-de-amaralina
   *
   * NUNCA depende da ordem dos membros do grupo.
   * Usar este valor em vez de recalcular baseUrl dentro dos filhos.
   */
  baseUrl: string;
  /**
   * Disponibilidade do módulo atual no grupo.
   * Apenas relevante quando resolved.kind === 'group'.
   * Para location, sempre 'full' (rollout é por bairro individual).
   */
  groupAvailability: GroupModuleAvailability;
  /**
   * IDs dos membros do grupo com rollout ativo para o módulo atual.
   * Usar em useTerritoryFilter(resolved, activeMemberIds) para filtrar queries.
   */
  activeMemberIds: string[];
};

export function useTerritorialContext() {
  return useOutletContext<TerritorialLayoutContext>();
}

export function useTerritorialContextOptional() {
  return useOutletContext<TerritorialLayoutContext | null>() ?? null;
}

// ── Mapeamento de slug de módulo para ModuleKey ──────────────────────────────

const SLUG_TO_MODULE_KEY: Record<string, ModuleKey> = {
  [MODULE_SLUGS.community]:   ModuleKey.COMMUNITY,
  [MODULE_SLUGS.business]:    ModuleKey.BUSINESS,
  [MODULE_SLUGS.services]:    ModuleKey.SERVICES,
  [MODULE_SLUGS.classifieds]: ModuleKey.CLASSIFIEDS,
  [MODULE_SLUGS.mobility]:    ModuleKey.MOBILITY,
  [MODULE_SLUGS.gastronomy]:  ModuleKey.GASTRONOMY,
  [MODULE_SLUGS.events]:      ModuleKey.EVENTS,
  [MODULE_SLUGS.jobs]:        ModuleKey.JOBS,
};

// ── Banner de cobertura parcial ──────────────────────────────────────────────

function PartialCoverageBanner({
  activeCount,
  totalCount,
}: {
  activeCount: number;
  totalCount: number;
}) {
  return (
    <div className="flex items-center gap-2 px-4 py-2 bg-amber-500/10 border-b border-amber-500/20 text-xs text-amber-700 dark:text-amber-400">
      <AlertTriangle className="h-3.5 w-3.5 flex-shrink-0" />
      <span>
        Cobertura parcial — {activeCount} de {totalCount} bairros disponíveis neste módulo.
      </span>
    </div>
  );
}

// ── Banner de módulo indisponível ────────────────────────────────────────────

function UnavailableModuleBanner() {
  return (
    <div className="flex items-center gap-2 px-4 py-3 bg-muted/60 border-b border-border text-xs text-muted-foreground">
      <AlertTriangle className="h-3.5 w-3.5 flex-shrink-0" />
      <span>Este módulo ainda não está disponível neste território.</span>
    </div>
  );
}

// ── Layout principal ─────────────────────────────────────────────────────────

export function TerritorialLayout() {
  const { status, resolved, error } = useResolveTerritoryFromUrl();
  const { pathname } = useLocation();
  const params = useParams<{
    country?: string; state?: string; city?: string;
    groupSlugOrDistrict?: string;
  }>();

  const state = params.state;
  const city = params.city;
  const slug = params.groupSlugOrDistrict;

  const isFriendlyModule = pathname.startsWith('/empresas/') || 
      pathname.startsWith('/servicos/') || 
      pathname.startsWith('/classificados/') ||
      pathname.startsWith('/comunidade/');

  const country = params.country ?? TERRITORY_CONFIG.defaultCountry;

  // Resolve o módulo atual a partir do pathname
  const currentModuleSlug = pathname.split('/').filter(Boolean)[0] ?? '';
  const currentModuleKey = SLUG_TO_MODULE_KEY[currentModuleSlug] ?? null;

  // Resolve availability do grupo (só relevante quando resolved.kind === 'group')
  const groupId = resolved?.kind === 'group' ? resolved.group.id : null;
  const { availability, active_member_ids, result: availabilityResult, isLoading: availabilityLoading } = useGroupAvailability(
    groupId,
    currentModuleKey,
  );

  // baseUrl = landing do território (sem módulo)
  // SSOT: usa geographic_path da location resolvida, não os params da URL
  const baseUrl = resolved
    ? resolved.kind === 'group'
      ? (() => {
          // Para grupo: pega a cidade âncora do primeiro membro
          const firstMember = resolved.group.members[0];
          if (!firstMember?.geographic_path) return `/${state}/${city}/${resolved.group.slug}`;
          const parts = firstMember.geographic_path.split('/').filter(Boolean);
          return `/${parts[1]}/${parts[2]}/${resolved.group.slug}`;
        })()
      : (() => {
          // Para location: usa geographic_path removendo /br
          const parts = resolved.location.geographic_path.split('/').filter(Boolean);
          return '/' + parts.slice(1).join('/');
        })()
    : slug
      ? `/${state}/${city}/${slug}`
      : `/${state}/${city}`;

  const territoryName = resolved
    ? resolved.kind === 'group'
      ? resolved.group.name
      : resolved.location.name
    : '';

  // Persiste o território resolvido para uso fora das rotas territoriais (header, sidebar)
  // useEffect deve ficar ANTES de qualquer early return — Rules of Hooks
  // 
  useEffect(() => {
    if (status === 'resolved_location' || status === 'resolved_group') {
      if (territoryName && baseUrl && !isEntityDetailRoute(pathname)) {
        lastTerritoryStore.set({ name: territoryName, baseUrl });
      }
    }
  }, [status, territoryName, baseUrl, pathname]);

  if (status === 'idle' || status === 'loading') {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  if (status === 'not_found') {
    return <TerritorialNotFound message={error ?? undefined} />;
  }

  if (status === 'inactive') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-2 p-8 text-center">
        <p className="text-lg font-medium">Território inativo</p>
        <p className="text-sm text-muted-foreground max-w-sm">
          {error ?? 'Este território não está disponível no momento.'}
        </p>
      </div>
    );
  }

  if (status === 'restricted') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-4 p-8 text-center">
        <div className="bg-amber-500/10 border border-amber-500/20 rounded-full p-4">
          <AlertTriangle className="h-12 w-12 text-amber-600 dark:text-amber-500" />
        </div>
        <div className="space-y-2 max-w-md">
          <p className="text-xl font-semibold text-foreground">Território indisponível</p>
          <p className="text-sm text-muted-foreground leading-relaxed">
            {error ?? 'Este território não está disponível para navegação pública no momento.'}
          </p>
          <p className="text-xs text-muted-foreground mt-4">
            Você pode voltar ou navegar para a visão mais ampla da cidade.
          </p>
        </div>
        <div className="flex gap-3 mt-4">
          <button
            onClick={() => window.history.back()}
            className="px-4 py-2 text-sm font-medium text-muted-foreground hover:text-foreground border border-border rounded-lg hover:bg-muted/50 transition-colors"
          >
            Voltar
          </button>
          <button
            onClick={() => window.location.href = `/${state}/${city}`}
            className="px-4 py-2 text-sm font-medium text-primary-foreground bg-primary hover:bg-primary/90 rounded-lg transition-colors"
          >
            Ver Cidade Completa
          </button>
        </div>
      </div>
    );
  }

  if (status === 'error') {
    // Render outlet anyway so pages with mock data can still render
    const fallbackContext: TerritorialLayoutContext = {
      resolved: resolved as any,
      baseUrl,
      groupAvailability: 'full',
      activeMemberIds: [],
    };
    return (
      <ErrorBoundary>
        <Outlet context={fallbackContext} />
      </ErrorBoundary>
    );
  }

  // Para location, availability é sempre 'full' (rollout é por bairro individual)
  const effectiveAvailability: GroupModuleAvailability =
    resolved?.kind === 'group' ? availability : 'full';

  const outletContext: TerritorialLayoutContext = {
    resolved,
    baseUrl,
    groupAvailability: effectiveAvailability,
    activeMemberIds: resolved?.kind === 'group' ? active_member_ids : [],
  };

  return (
    <>
      <TerritorialSEO resolved={resolved} baseUrl={baseUrl} />

      {/* Banners de disponibilidade — apenas em contexto de grupo */}
      {resolved?.kind === 'group' && currentModuleKey && (
        <>
          {effectiveAvailability === 'partial' && availabilityResult && (
            <PartialCoverageBanner
              activeCount={availabilityResult.active_module_members}
              totalCount={availabilityResult.total_active_members}
            />
          )}
          {effectiveAvailability === 'none' && !availabilityLoading && <UnavailableModuleBanner />}
        </>
      )}

      <ErrorBoundary>
        <Outlet context={outletContext} />
      </ErrorBoundary>
    </>
  );
}

/**
 * RoutingService - SSOT para roteamento
 * 
 * Service transversal para cálculo de rotas, ETA e distâncias.
 * Abstrai provider específico e fornece interface unificada.
 * 
 * @module core/routing/services
 */
import { logger } from '@/shared/utils/logger';
import type {
  RouteRequest,
  RouteResponse,
  ETARequest,
  ETAResponse,
  DistanceMatrixRequest,
  DistanceMatrixResponse,
  RoutingProvider,
  TransportProfile,
  PROFILE_MAPPING,
} from '../types';
import type { Coordinates } from '@/core/maps/types';
/**
 * Configuração do RoutingService
 */
interface RoutingServiceConfig {
  provider: RoutingProvider;
  defaultProfile?: TransportProfile;
}

/**
 * Service SSOT de roteamento
 * 
 * Responsabilidades:
 * - Calcular rotas entre pontos
 * - Calcular ETA (tempo estimado)
 * - Calcular matriz de distâncias
 * - Abstrair provider específico
 * - Validar requisições
 * - Normalizar respostas
 */
export class RoutingService {
  private provider: RoutingProvider;
  private defaultProfile: TransportProfile;

  constructor(config: RoutingServiceConfig) {
    this.provider = config.provider;
    this.defaultProfile = config.defaultProfile || 'car';
  }

  /**
   * Calcular rota entre origem e destino
   */
  async calculateRoute(request: RouteRequest): Promise<RouteResponse> {
    this.validateRouteRequest(request);
    
    try {
      const response = await this.provider.calculateRoute(request);
      return this.normalizeRouteResponse(response);
    } catch (error) {
      logger.error('[RoutingService] Erro ao calcular rota:', error);
      throw new Error('Falha ao calcular rota');
    }
  }

  /**
   * Calcular ETA entre origem e destino
   */
  async calculateETA(request: ETARequest): Promise<ETAResponse> {
    this.validateETARequest(request);
    
    try {
      const response = await this.provider.calculateETA(request);
      return this.normalizeETAResponse(response);
    } catch (error) {
      logger.error('[RoutingService] Erro ao calcular ETA:', error);
      throw new Error('Falha ao calcular ETA');
    }
  }

  /**
   * Calcular ETA simples (apenas coordenadas)
   */
  async calculateSimpleETA(
    origin: Coordinates,
    destination: Coordinates,
    profile?: TransportProfile
  ): Promise<ETAResponse> {
    return this.calculateETA({
      origin,
      destination,
      profile: profile || this.defaultProfile,
    });
  }

  /**
   * Calcular matriz de distâncias
   */
  async calculateDistanceMatrix(
    request: DistanceMatrixRequest
  ): Promise<DistanceMatrixResponse> {
    this.validateDistanceMatrixRequest(request);
    
    if (!this.provider.calculateDistanceMatrix) {
      throw new Error('Provider não suporta matriz de distâncias');
    }

    try {
      const response = await this.provider.calculateDistanceMatrix(request);
      return response;
    } catch (error) {
      logger.error('[RoutingService] Erro ao calcular matriz:', error);
      throw new Error('Falha ao calcular matriz de distâncias');
    }
  }

  /**
   * Verificar se provider está disponível
   */
  async isAvailable(): Promise<boolean> {
    try {
      return await this.provider.validate();
    } catch {
      return false;
    }
  }

  /**
   * Obter perfil padrão
   */
  getDefaultProfile(): TransportProfile {
    return this.defaultProfile;
  }

  /**
   * Definir perfil padrão
   */
  setDefaultProfile(profile: TransportProfile): void {
    this.defaultProfile = profile;
  }

  /**
   * Mapear perfil legado para novo
   */
  mapLegacyProfile(legacyProfile: string): TransportProfile {
    const mapping: Record<string, TransportProfile> = {
      'driving': 'car',
      'walking': 'foot',
      'cycling': 'bicycle',
      'transit': 'car',
    };
    return mapping[legacyProfile] || this.defaultProfile;
  }

  // ============================================
  // VALIDATIONS
  // ============================================

  private validateRouteRequest(request: RouteRequest): void {
    if (!request.origin || !request.destination) {
      throw new Error('Origem e destino são obrigatórios');
    }

    this.validateCoordinates(request.origin);
    this.validateCoordinates(request.destination);

    if (request.waypoints) {
      request.waypoints.forEach((wp) => this.validateCoordinates(wp));
    }

    if (!request.options?.profile) {
      throw new Error('Perfil de transporte é obrigatório');
    }
  }

  private validateETARequest(request: ETARequest): void {
    if (!request.origin || !request.destination) {
      throw new Error('Origem e destino são obrigatórios');
    }

    this.validateCoordinates(request.origin);
    this.validateCoordinates(request.destination);

    if (!request.profile) {
      throw new Error('Perfil de transporte é obrigatório');
    }
  }

  private validateDistanceMatrixRequest(request: DistanceMatrixRequest): void {
    if (!request.origins?.length || !request.destinations?.length) {
      throw new Error('Origens e destinos são obrigatórios');
    }

    request.origins.forEach((origin) => this.validateCoordinates(origin));
    request.destinations.forEach((dest) => this.validateCoordinates(dest));

    if (!request.profile) {
      throw new Error('Perfil de transporte é obrigatório');
    }
  }

  private validateCoordinates(coords: Coordinates): void {
    if (
      typeof coords.latitude !== 'number' ||
      typeof coords.longitude !== 'number'
    ) {
      throw new Error('Coordenadas inválidas');
    }

    if (coords.latitude < -90 || coords.latitude > 90) {
      throw new Error('Latitude deve estar entre -90 e 90');
    }

    if (coords.longitude < -180 || coords.longitude > 180) {
      throw new Error('Longitude deve estar entre -180 e 180');
    }
  }

  // ============================================
  // NORMALIZATION
  // ============================================

  private normalizeRouteResponse(response: RouteResponse): RouteResponse {
    // Garantir que primaryRoute existe
    if (!response.primaryRoute && response.routes.length > 0) {
      response.primaryRoute = response.routes[0];
    }

    // Arredondar valores
    response.routes = response.routes.map((route) => ({
      ...route,
      distanceMeters: Math.round(route.distanceMeters),
      durationSeconds: Math.round(route.durationSeconds),
      legs: route.legs.map((leg) => ({
        ...leg,
        distanceMeters: Math.round(leg.distanceMeters),
        durationSeconds: Math.round(leg.durationSeconds),
      })),
    }));

    return response;
  }

  private normalizeETAResponse(response: ETAResponse): ETAResponse {
    return {
      ...response,
      distanceMeters: Math.round(response.distanceMeters),
      durationSeconds: Math.round(response.durationSeconds),
      durationInTrafficSeconds: response.durationInTrafficSeconds
        ? Math.round(response.durationInTrafficSeconds)
        : undefined,
    };
  }
}

/**
 * Factory para criar instância do RoutingService
 */
export function createRoutingService(
  provider: RoutingProvider,
  defaultProfile?: TransportProfile
): RoutingService {
  return new RoutingService({ provider, defaultProfile });
}

/**
 * territoryUrls — Helpers canônicos de URL territorial
 *
 * SSOT para construção de URLs territoriais públicas (sem /br).
 * Nunca concatenar paths manualmente no app — usar estas funções.
 *
 * Padrões canônicos (públicos):
 *   Cidade:  /:state/:city
 *   Bairro:  /:state/:city/:district
 *   Grupo:   /:state/:city/:groupSlug
 *   Módulo:  /[modulo]/:state/:city/:district?
 */

import type { Location, TerritorialGroup } from '@/core/location/types';
import { TERRITORY_CONFIG } from '@/config/territory';

// ── Slugs de módulo canônicos ────────────────────────────────────────────────
export const MODULE_SLUGS = {
  community:    'comunidade',
  business:     'empresas',
  services:     'servicos',
  classifieds:  'classificados',
  mobility:     'mobilidade',
  gastronomy:   'gastronomia',
  events:       'eventos',
  jobs:         'vagas',
  alerts:       'alertas',
  map:          'mapa',
  guide:        'guia',
  ranking:      'ranking',
} as const;

export type ModuleSlug = typeof MODULE_SLUGS[keyof typeof MODULE_SLUGS];

// ── Helpers internos ─────────────────────────────────────────────────────────

/**
 * Detecta se um pathname corresponde a uma página de detalhe de entidade.
 *
 * Páginas de detalhe têm 5+ segmentos: /[modulo]/:state/:city/:district/:slug
 * Ex: /gastronomia/ba/salvador/rio-vermelho/pizza-do-forno
 *     /empresas/ba/salvador/pituba/nome-do-negocio
 *
 * Páginas territoriais (listagem) têm no máximo 4 segmentos:
 * Ex: /gastronomia/ba/salvador           (3 segmentos)
 *     /gastronomia/ba/salvador/pituba    (4 segmentos)
 */
export function isEntityDetailRoute(pathname: string): boolean {
  const segments = pathname.split('/').filter(Boolean);
  return segments.length >= 5;
}

/**
 * Converte geographic_path interno (/br/ba/salvador/pituba)
 * para URL pública (/ba/salvador/pituba) removendo o country.
 */
export function geoPathToPublicUrl(geoPath: string): string {
  const parts = geoPath.split('/').filter(Boolean);
  return '/' + parts.slice(1).join('/');
}

/**
 * Normaliza caminhos territoriais internos ou públicos para o formato público:
 * - /br/ba/salvador/pituba -> /ba/salvador/pituba
 * - /ba/salvador/pituba -> /ba/salvador/pituba
 * - ba/salvador/pituba -> /ba/salvador/pituba
 */
export function normalizePublicTerritoryPath(path: string): string {
  const parts = path.split('/').filter(Boolean);
  if (!parts.length) return '/';

  const normalizedParts = parts[0] === 'br' ? parts.slice(1) : parts;
  return '/' + normalizedParts.join('/');
}

// ── Builders ─────────────────────────────────────────────────────────────────

/**
 * URL base de uma location (cidade ou bairro).
 * geographic_path: /br/ba/salvador/pituba → /ba/salvador/pituba
 */
export function buildLocationBaseUrl(location: Location): string {
  return geoPathToPublicUrl(location.geographic_path);
}

/**
 * URL base de um grupo territorial.
 * cityPath: geographic_path da cidade âncora (ex: /br/ba/salvador)
 */
export function buildGroupBaseUrl(group: TerritorialGroup, cityPath: string): string {
  const publicCity = geoPathToPublicUrl(cityPath);
  return `${publicCity}/${group.slug}`;
}

/**
 * URL de um módulo dentro de um bairro.
 */
export function buildLocationModuleUrl(location: Location, module: ModuleSlug): string {
  return `${buildLocationBaseUrl(location)}/${module}`;
}

/**
 * URL de um módulo dentro de um grupo territorial.
 */
export function buildGroupModuleUrl(
  group: TerritorialGroup,
  cityPath: string,
  module: ModuleSlug,
): string {
  return `${buildGroupBaseUrl(group, cityPath)}/${module}`;
}

/**
 * Constrói a URL base do território ativo.
 */
export function buildTerritoryBaseUrl(
  territory:
    | { kind: 'location'; location: Location }
    | { kind: 'group'; group: TerritorialGroup; cityPath: string },
): string {
  if (territory.kind === 'location') {
    return buildLocationBaseUrl(territory.location);
  }
  return buildGroupBaseUrl(territory.group, territory.cityPath);
}

/**
 * Constrói a URL de um módulo no território ativo.
 */
export function buildTerritoryModuleUrl(
  territory:
    | { kind: 'location'; location: Location }
    | { kind: 'group'; group: TerritorialGroup; cityPath: string },
  module: ModuleSlug,
): string {
  return `${buildTerritoryBaseUrl(territory)}/${module}`;
}

// ── Route Context Extraction ─────────────────────────────────────────────────

/**
 * Extrai o contexto da rota atual (módulo + sufixo após o território).
 * 
 * Exemplos:
 *   /empresas/ba/salvador/categoria/restaurantes → { module: 'empresas', suffix: '/categoria/restaurantes' }
 *   /empresas/ba/salvador/pituba/categoria/saude → { module: 'empresas', suffix: '/categoria/saude' }
 *   /empresas/ba/salvador → { module: 'empresas', suffix: '' }
 *   /comunidade/ba/salvador → { module: 'comunidade', suffix: '' }
 *   /ba/salvador → { module: null, suffix: '' }
 * 
 * @param pathname - pathname da URL atual (ex: location.pathname)
 * @returns Objeto com módulo e sufixo, ou null se não for uma rota territorial
 */
export function extractRouteContext(pathname: string): {
  module: ModuleSlug | null;
  suffix: string;
} {
  const parts = pathname.split('/').filter(Boolean);
  
  // Verifica se o primeiro segmento é um módulo conhecido
  const firstSegment = parts[0];
  const moduleValues = Object.values(MODULE_SLUGS);
  const isModule = moduleValues.includes(firstSegment as ModuleSlug);
  
  if (!isModule) {
    // Não é uma rota de módulo (ex: /ba/salvador)
    return { module: null, suffix: '' };
  }
  
  const module = firstSegment as ModuleSlug;
  
  // Encontra onde termina o território e começa o sufixo
  // Padrões possíveis:
  // /empresas/:state/:city → 3 segmentos, sem sufixo
  // /empresas/:state/:city/:district → 4 segmentos, sem sufixo
  // /empresas/:state/:city/categoria/:category → 5 segmentos, sufixo = /categoria/:category
  // /empresas/:state/:city/:district/categoria/:category → 6 segmentos, sufixo = /categoria/:category
  
  // Detecta se há um sufixo após o território
  // Sufixos conhecidos: /categoria/:slug
  let suffixStartIndex = -1;
  
  for (let i = 1; i < parts.length; i++) {
    // Se encontrar "categoria" ou outros sufixos conhecidos
    if (parts[i] === 'categoria') {
      suffixStartIndex = i;
      break;
    }
  }
  
  if (suffixStartIndex === -1) {
    // Sem sufixo
    return { module, suffix: '' };
  }
  
  // Constrói o sufixo
  const suffixParts = parts.slice(suffixStartIndex);
  const suffix = '/' + suffixParts.join('/');
  
  return { module, suffix };
}

