/**
 * Painel Administrativo de Detecção de Fraudes
 *
 * Exibe alertas de fraude detectados automaticamente e permite revisão.
 */

import { useState, useEffect } from "react";
import { Card } from "@/shared/components/ui/card";
import { Button } from "@/shared/components/ui/button";
import { Badge } from "@/shared/components/ui/badge";
import { Textarea } from "@/shared/components/ui/textarea";
import { profileService } from "@/core/profiles/services";
import { AdminFraudService } from "@/core/admin/services/AdminFraudService";
import type { FraudAlert } from "@/core/admin/services/AdminFraudService";
import {
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Clock,
  TrendingUp,
  Shield,
  Eye,
} from "lucide-react";
import { toast } from "sonner";
import { RIDE_STATUS, ALERT_STATUS } from "@/shared/types/constants";
import { logger } from "@/shared/utils/logger";
import { adminMobilityService } from "@/core/admin"; // ✅ MIGRADO - Usa AdminMobilityService do core

interface FraudEvidence {
  duration_minutes?: number;
  quick_rides_count?: number;
  zero_distance_count?: number;
  [key: string]: string | number | boolean | undefined;
}

export function FraudDetectionPanel() {
  const [alerts, setAlerts] = useState<(FraudAlert & { ride?: any; driver?: any })[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedAlert, setSelectedAlert] = useState<(FraudAlert & { ride?: any; driver?: any }) | null>(null);
  const [resolutionNotes, setResolutionNotes] = useState("");
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    critical: 0,
  });

  useEffect(() => {
    loadAlerts();
    loadStats();
  }, []);

  const loadAlerts = async () => {
    try {
      const rawAlerts = await AdminFraudService.getAlerts(50);

      const rideIds = [...new Set(rawAlerts.map((a) => a.ride_id).filter(Boolean))];
      const driverProfileIds = [...new Set(rawAlerts.map((a) => a.driver_profile_id).filter(Boolean))];

      const [ridesData, driversData] = await Promise.all([
        rideIds.length > 0
          ? adminMobilityService.getUserRides(driverProfileIds[0] || "").then((data) => ({ data }))
          : Promise.resolve({ data: [] as any[] }),
        profileService.getProfilesSummary(driverProfileIds as string[]),
      ]);

      const rideMap = new Map((ridesData.data || []).map((r) => [r.id, r]));
      const driverMap = new Map(driversData.map((d) => [d.id, { id: d.id, name: d.name }]));

      setAlerts(
        rawAlerts.map((alert) => ({
          ...alert,
          ride: alert.ride_id ? rideMap.get(alert.ride_id) : null,
          driver: alert.driver_profile_id ? { profile: driverMap.get(alert.driver_profile_id) } : null,
        })),
      );
    } catch (error) {
      logger.error("Error loading alerts:", error);
      toast.error("Erro ao carregar alertas");
    } finally {
      setLoading(false);
    }
  };

  const loadStats = async () => {
    try {
      const s = await AdminFraudService.getStats();
      setStats(s);
    } catch (error) {
      logger.error("Erro ao carregar estatísticas:", error);
    }
  };

  const updateAlertStatus = async (
    alertId: string,
    newStatus: FraudAlert["status"],
  ) => {
    try {
      await AdminFraudService.updateAlertStatus(alertId, newStatus, resolutionNotes || undefined);
      toast.success("Status atualizado");
      setSelectedAlert(null);
      setResolutionNotes("");
      loadAlerts();
      loadStats();
    } catch (error) {
      logger.error("Error updating alert status:", error);
      toast.error("Erro ao atualizar status");
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case "critical":
        return "bg-red-500/10 text-red-500 border-red-500/20";
      case "high":
        return "bg-orange-500/10 text-orange-500 border-orange-500/20";
      case "medium":
        return "bg-yellow-500/10 text-yellow-500 border-yellow-500/20";
      default:
        return "bg-blue-500/10 text-blue-500 border-blue-500/20";
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "confirmed":
        return "bg-red-500/10 text-red-500";
      case "false_positive":
        return "bg-green-500/10 text-green-500";
      case ALERT_STATUS.RESOLVED:
        return "bg-blue-500/10 text-blue-500";
      case "investigating":
        return "bg-yellow-500/10 text-yellow-500";
      default:
        return "bg-gray-500/10 text-gray-500";
    }
  };

  const getFraudTypeLabel = (type: string) => {
    const labels: Record<string, string> = {
      quick_ride: "⚡ Corrida Rápida",
      zero_distance: "📍 Distância Zero",
      pattern_quick_rides: "🔄 Padrão: Corridas Rápidas",
      pattern_zero_distance: "🔄 Padrão: Distância Zero",
      fake_completion: "🎭 Conclusão Falsa",
    };
    return labels[type] || type;
  };

  if (loading) {
    return <div className="p-8 text-center">Carregando...</div>;
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold text-foreground flex items-center gap-2">
          <Shield className="h-6 w-6 text-red-500" />
          Detecção de Fraudes
        </h2>
        <p className="text-sm text-muted-foreground mt-1">
          Sistema automático de detecção de padrões suspeitos
        </p>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card className="p-4 bg-card border-border">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-blue-500/10 flex items-center justify-center">
              <TrendingUp className="h-5 w-5 text-blue-500" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">
                {stats.total}
              </p>
              <p className="text-xs text-muted-foreground">Total de Alertas</p>
            </div>
          </div>
        </Card>

        <Card className="p-4 bg-card border-border">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-yellow-500/10 flex items-center justify-center">
              <Clock className="h-5 w-5 text-yellow-500" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">
                {stats.pending}
              </p>
              <p className="text-xs text-muted-foreground">Pendentes</p>
            </div>
          </div>
        </Card>

        <Card className="p-4 bg-card border-border">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-lg bg-red-500/10 flex items-center justify-center">
              <AlertTriangle className="h-5 w-5 text-red-500" />
            </div>
            <div>
              <p className="text-2xl font-bold text-foreground">
                {stats.critical}
              </p>
              <p className="text-xs text-muted-foreground">Críticos</p>
            </div>
          </div>
        </Card>
      </div>

      {/* Alerts List */}
      <div className="space-y-3">
        {alerts.length === 0 ? (
          <Card className="p-8 text-center bg-card border-border">
            <Shield className="h-12 w-12 text-green-500 mx-auto mb-3" />
            <p className="text-foreground font-semibold">
              Nenhum alerta de fraude
            </p>
            <p className="text-sm text-muted-foreground">
              Sistema funcionando normalmente
            </p>
          </Card>
        ) : (
          alerts.map((alert) => (
            <Card
              key={alert.id}
              className={`p-4 bg-card border ${
                alert.severity === "critical"
                  ? "border-red-500/30"
                  : "border-border"
              }`}
            >
              <div className="flex items-start justify-between gap-4">
                <div className="flex-1 space-y-2">
                  {/* Header */}
                  <div className="flex items-center gap-2 flex-wrap">
                    <Badge className={getSeverityColor(alert.severity)}>
                      {alert.severity.toUpperCase()}
                    </Badge>
                    <Badge className={getStatusColor(alert.status)}>
                      {alert.status}
                    </Badge>
                    <span className="text-sm font-semibold text-foreground">
                      {getFraudTypeLabel(alert.fraud_type)}
                    </span>
                  </div>

                  {/* Description */}
                  <p className="text-sm text-foreground">{alert.description}</p>

                  {/* Evidence */}
                  {alert.evidence && Object.keys(alert.evidence).length > 0 && (
                    <div className="p-3 rounded-lg bg-muted/50 text-xs space-y-1">
                      <p className="font-semibold text-foreground">
                        Evidências:
                      </p>
                      {alert.evidence.duration_minutes && (
                        <p className="text-muted-foreground">
                          • Duração: {alert.evidence.duration_minutes} minutos
                        </p>
                      )}
                      {alert.evidence.quick_rides_count && (
                        <p className="text-muted-foreground">
                          • Corridas rápidas: {alert.evidence.quick_rides_count}
                        </p>
                      )}
                      {alert.evidence.zero_distance_count && (
                        <p className="text-muted-foreground">
                          • Distância zero: {alert.evidence.zero_distance_count}
                        </p>
                      )}
                    </div>
                  )}

                  {/* Ride Info */}
                  {alert.ride && (
                    <div className="text-xs text-muted-foreground">
                      <p>
                        Corrida: {alert.ride.origin} → {alert.ride.destination}
                      </p>
                    </div>
                  )}

                  {/* Driver Info */}
                  {alert.driver && (
                    <div className="text-xs text-muted-foreground">
                      <p>Motorista: {alert.driver.profile?.name}</p>
                    </div>
                  )}

                  {/* Date */}
                  <p className="text-xs text-muted-foreground">
                    {new Date(alert.created_at).toLocaleString("pt-BR")}
                  </p>
                </div>

                {/* Actions */}
                {alert.status === RIDE_STATUS.PENDING && (
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => setSelectedAlert(alert)}
                    className="flex-shrink-0"
                  >
                    <Eye className="h-4 w-4 mr-1" />
                    Revisar
                  </Button>
                )}
              </div>

              {/* Review Panel */}
              {selectedAlert?.id === alert.id && (
                <div className="mt-4 pt-4 border-t border-border space-y-3">
                  <Textarea
                    placeholder="Notas da revisão (opcional)..."
                    value={resolutionNotes}
                    onChange={(e) => setResolutionNotes(e.target.value)}
                    className="min-h-[80px] bg-background"
                  />
                  <div className="flex gap-2 flex-wrap">
                    <Button
                      size="sm"
                      onClick={() => updateAlertStatus(alert.id, "confirmed")}
                      className="bg-red-500 hover:bg-red-600"
                    >
                      <XCircle className="h-4 w-4 mr-1" />
                      Confirmar Fraude
                    </Button>
                    <Button
                      size="sm"
                      onClick={() =>
                        updateAlertStatus(alert.id, "false_positive")
                      }
                      className="bg-green-500 hover:bg-green-600"
                    >
                      <CheckCircle2 className="h-4 w-4 mr-1" />
                      Falso Positivo
                    </Button>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() =>
                        updateAlertStatus(alert.id, "investigating")
                      }
                    >
                      Investigar
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => setSelectedAlert(null)}
                    >
                      Cancelar
                    </Button>
                  </div>
                </div>
              )}
            </Card>
          ))
        )}
      </div>
    </div>
  );
}

import React from "react";

import { useState } from "react";
import { Card, CardContent, CardHeader } from "@/shared/components/ui/card";
import { Button } from "@/shared/components/ui/button";
import { Badge } from "@/shared/components/ui/badge";
import {
  CheckCircle,
  XCircle,
  EyeOff,
  AlertTriangle,
  UserX,
  MessageSquare,
  Flag,
} from "lucide-react";
import { PendingComment } from "@/core/moderation/types";
import { PRIORITY_COLORS, REPORT_TYPE_LABELS } from "@/shared/types/moderation";
import { useModeration } from "@/core/moderation/hooks/useModeration";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";
interface PendingCommentCardProps {
  comment: PendingComment;
}

export function PendingCommentCard({ comment }: PendingCommentCardProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const { executeAction, isExecuting } = useModeration();

  const priorityLabel = comment.priority >= 3 ? 'high' : comment.priority === 2 ? 'medium' : 'low';
  const priorityColor = PRIORITY_COLORS[priorityLabel];

  const handleApprove = async () => {
    executeAction({
      targetId: comment.id,
      targetType: "comment",
      action: "approve",
      reason: "Comentário aprovado após análise",
    });
  };

  const handleRemove = async () => {
    executeAction({
      targetId: comment.id,
      targetType: "comment",
      action: "remove",
      reason: "Comentário removido por violar diretrizes",
    });
  };

  const handleHide = async () => {
    executeAction({
      targetId: comment.id,
      targetType: "comment",
      action: "hide",
      reason: "Comentário ocultado temporariamente",
    });
  };

  const handleBanAuthor = async () => {
    executeAction({
      targetId: comment.id,
      targetType: "comment",
      action: "ban_author",
      reason: "Usuário banido por comentário inadequado",
    });
  };

  const handleWarnAuthor = async () => {
    executeAction({
      targetId: comment.id,
      targetType: "comment",
      action: "warn_author",
      reason: "Advertência por comentário inadequado",
    });
  };

  return (
    <Card className="hover:shadow-lg transition-shadow">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between">
          <div className="flex items-start gap-3 flex-1">
            <img
              src={comment.author_avatar || "/default-avatar.png"}
              alt={comment.author_name}
              className="w-10 h-10 rounded-full"
            />
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <span className="font-semibold">
                  {comment.author_name}
                </span>
                <Badge variant="outline" className="text-xs">
                  Rep: {(comment as any).author?.reputation || 0}
                </Badge>
              </div>
              <p className="text-xs text-muted-foreground">
                {formatDistanceToNow(new Date(comment.created_at), {
                  addSuffix: true,
                  locale: ptBR,
                })}
              </p>
            </div>
          </div>

          <Badge
            style={{
              backgroundColor: priorityColor.bg,
              borderColor: priorityColor.border,
              color: priorityColor.text,
            }}
            className="ml-2"
          >
            {comment.priority >= 3 && "Alta"}
            {comment.priority === 2 && "Média"}
            {comment.priority <= 1 && "Baixa"}
          </Badge>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Conteúdo do Comentário */}
        <div>
          <h4 className="text-sm font-semibold mb-2 flex items-center gap-2">
            <MessageSquare className="w-4 h-4" />
            Comentário Denunciado
          </h4>
          <div className="p-3 bg-muted rounded-lg border-l-4 border-destructive">
            <p className="text-sm">{comment.content}</p>
          </div>
        </div>

        {/* Post Original */}
        <div>
          <h4 className="text-sm font-semibold mb-2">Post Original</h4>
          <div className="p-3 bg-muted/50 rounded-lg text-sm text-muted-foreground">
            {(comment as any).post?.content?.substring(0, 150) || comment.content.substring(0, 150)}
            {((comment as any).post?.content?.length || comment.content.length) > 150 && "..."}
          </div>
        </div>

        {/* Denúncias */}
        <div>
          <button
            onClick={() => setIsExpanded(!isExpanded)}
            className="text-sm font-semibold mb-2 flex items-center gap-2 hover:text-primary transition-colors"
          >
            <Flag className="w-4 h-4" />
            {comment.reports.length}{" "}
            {comment.reports.length === 1 ? "Denúncia" : "Denúncias"}
            <span className="text-xs text-muted-foreground ml-1">
              (clique para {isExpanded ? "ocultar" : "ver"})
            </span>
          </button>

          {isExpanded && (
            <div className="space-y-2">
              {comment.reports.map((report) => (
                <div
                  key={report.id}
                  className="p-3 bg-muted/50 rounded-lg text-sm"
                >
                  <div className="flex items-center gap-2 mb-1">
                    <Badge variant="outline" className="text-xs">
                      {REPORT_TYPE_LABELS[report.type]}
                    </Badge>
                    <span className="text-xs text-muted-foreground">
                      por {report.reporter.name_completo}
                    </span>
                  </div>
                  <p className="text-muted-foreground">{report.reason}</p>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Ações */}
        <div className="flex flex-wrap gap-2 pt-2 border-t">
          <Button
            variant="default"
            size="sm"
            onClick={handleApprove}
            disabled={isExecuting}
            className="bg-success hover:bg-success/90"
          >
            <CheckCircle className="w-4 h-4 mr-2" />
            Aprovar
          </Button>

          <Button
            variant="destructive"
            size="sm"
            onClick={handleRemove}
            disabled={isExecuting}
          >
            <XCircle className="w-4 h-4 mr-2" />
            Remover
          </Button>

          <Button
            variant="outline"
            size="sm"
            onClick={handleHide}
            disabled={isExecuting}
          >
            <EyeOff className="w-4 h-4 mr-2" />
            Ocultar
          </Button>

          <Button
            variant="outline"
            size="sm"
            onClick={handleWarnAuthor}
            disabled={isExecuting}
            className="border-warning text-warning hover:bg-warning/10"
          >
            <AlertTriangle className="w-4 h-4 mr-2" />
            Advertir
          </Button>

          <Button
            variant="outline"
            size="sm"
            onClick={handleBanAuthor}
            disabled={isExecuting}
            className="border-destructive text-destructive hover:bg-destructive/10"
          >
            <UserX className="w-4 h-4 mr-2" />
            Banir Autor
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import React from "react";
import { useState } from "react";
import { PendingPost } from "@/core/moderation/types";
import {
  REPORT_TYPE_LABELS,
  getPriorityLevel,
} from "@/shared/types/moderation";
import { Card, CardContent, CardHeader } from "@/shared/components/ui/card";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from "@/shared/components/ui/avatar";
import { Textarea } from "@/shared/components/ui/textarea";
import {
  AlertTriangle,
  CheckCircle,
  XCircle,
  EyeOff,
  Ban,
  AlertCircle,
  ChevronDown,
  ChevronUp,
  User,
  Calendar,
  Flag,
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";
import { useModeration } from "@/core/moderation/hooks/useModeration";
interface PendingPostCardProps {
  post: PendingPost;
}

export function PendingPostCard({ post }: PendingPostCardProps) {
  const [showReports, setShowReports] = useState(false);
  const [showActions, setShowActions] = useState(false);
  const [reason, setReason] = useState("");
  const { executeAction, isExecuting } = useModeration();

  const priorityLevel = getPriorityLevel(post.priority);
  const priorityColors = {
    high: "bg-destructive/10 text-destructive border-destructive/30",
    medium: "bg-warning/10 text-warning border-warning/30",
    low: "bg-accent/10 text-accent border-accent/30",
  };

  const handleAction = (
    action:
      | "approve"
      | "remove"
      | "hide"
      | "ban_author"
      | "warn_author"
      | "reject",
  ) => {
    if (
      (action === "remove" ||
        action === "ban_author" ||
        action === "warn_author") &&
      !reason.trim()
    ) {
      alert("Por favor, forneça um motivo para esta ação.");
      return;
    }

    executeAction({
      targetType: "post",
      targetId: post.id,
      action,
      reason: reason || "Ação de moderação",
    });

    setShowActions(false);
    setReason("");
  };

  return (
    <Card className="hover:shadow-lg transition-shadow">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between gap-4">
          {/* Autor */}
          <div className="flex items-center gap-3">
            <Avatar className="w-10 h-10">
              <AvatarImage src={post.author_avatar} />
              <AvatarFallback>
                <User className="w-5 h-5" />
              </AvatarFallback>
            </Avatar>
            <div>
              <p className="font-semibold">{post.author_name}</p>
              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <span>Reputação: {post.author_reputation}</span>
                {post.author_previous_reports > 0 && (
                  <span className="text-destructive">
                    • {post.author_previous_reports} denúncias anteriores
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Badges */}
          <div className="flex gap-2">
            <Badge variant="outline">{post.type}</Badge>
            <Badge className={priorityColors[priorityLevel]}>
              Prioridade:{" "}
              {priorityLevel === "high"
                ? "Alta"
                : priorityLevel === "medium"
                  ? "Média"
                  : "Baixa"}
            </Badge>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Conteúdo do Post */}
        <div className="p-4 bg-muted rounded-lg">
          <p className="text-sm whitespace-pre-wrap">{post.content}</p>
          {post.images && post.images.length > 0 && (
            <div className="mt-3 flex gap-2">
              {post.images.map((img, idx) => (
                <img
                  key={idx}
                  src={img}
                  alt={`Imagem ${idx + 1}`}
                  className="w-20 h-20 object-cover rounded"
                />
              ))}
            </div>
          )}
        </div>

        {/* Informações */}
        <div className="flex items-center gap-4 text-xs text-muted-foreground">
          <div className="flex items-center gap-1">
            <Calendar className="w-3 h-3" />
            {formatDistanceToNow(new Date(post.created_at), {
              addSuffix: true,
              locale: ptBR,
            })}
          </div>
          <div className="flex items-center gap-1">
            <Flag className="w-3 h-3" />
            {post.reports_count}{" "}
            {post.reports_count === 1 ? "denúncia" : "denúncias"}
          </div>
        </div>

        {/* Denúncias */}
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowReports(!showReports)}
            className="w-full justify-between"
          >
            <span>Ver Denúncias ({post.reports_count})</span>
            {showReports ? (
              <ChevronUp className="w-4 h-4" />
            ) : (
              <ChevronDown className="w-4 h-4" />
            )}
          </Button>

          {showReports && (
            <div className="mt-3 space-y-2">
              {post.reports.map((report) => (
                <div
                  key={report.id}
                  className="p-3 bg-muted rounded-lg text-sm"
                >
                  <div className="flex items-start justify-between mb-2">
                    <div className="flex items-center gap-2">
                      <Avatar className="w-6 h-6">
                        <AvatarImage src={report.reporter_avatar} />
                        <AvatarFallback>
                          {(report.reporter_name ?? '?')[0]}
                        </AvatarFallback>
                      </Avatar>
                      <span className="font-medium">
                        {report.reporter_name ?? 'Anônimo'}
                      </span>
                    </div>
                    <Badge variant="outline" className="text-xs">
                      {REPORT_TYPE_LABELS[report.type]}
                    </Badge>
                  </div>
                  <p className="text-muted-foreground">{report.reason}</p>
                  {report.description && (
                    <p className="text-xs text-muted-foreground mt-1">
                      {report.description}
                    </p>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Ações */}
        <div>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowActions(!showActions)}
            className="w-full"
          >
            {showActions ? "Ocultar Ações" : "Ações de Moderação"}
          </Button>

          {showActions && (
            <div className="mt-4 space-y-3">
              {/* Motivo */}
              <Textarea
                placeholder="Motivo da ação (obrigatório para remove, banir ou advertir)"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
                rows={2}
              />

              {/* Botões de Ação */}
              <div className="grid grid-cols-2 gap-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleAction("approve")}
                  disabled={isExecuting}
                  className="text-success hover:bg-success/10"
                >
                  <CheckCircle className="w-4 h-4 mr-2" />
                  Aprovar
                </Button>

                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleAction("reject")}
                  disabled={isExecuting}
                  className="text-accent hover:bg-accent/10"
                >
                  <XCircle className="w-4 h-4 mr-2" />
                  Rejeitar
                </Button>

                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleAction("hide")}
                  disabled={isExecuting}
                  className="text-warning hover:bg-warning/10"
                >
                  <EyeOff className="w-4 h-4 mr-2" />
                  Ocultar
                </Button>

                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleAction("warn_author")}
                  disabled={isExecuting}
                  className="text-warning hover:bg-warning/10"
                >
                  <AlertCircle className="w-4 h-4 mr-2" />
                  Advertir
                </Button>

                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleAction("remove")}
                  disabled={isExecuting}
                  className="text-destructive hover:bg-destructive/10"
                >
                  <AlertTriangle className="w-4 h-4 mr-2" />
                  Remover
                </Button>

                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => handleAction("ban_author")}
                  disabled={isExecuting}
                  className="text-destructive hover:bg-destructive/10"
                >
                  <Ban className="w-4 h-4 mr-2" />
                  Banir Autor
                </Button>
              </div>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

import React from "react";
import { Badge } from "@/shared/components/ui/badge";
import { formatDistanceToNow } from "date-fns";
import { ptBR } from "date-fns/locale";
import { usePricingAuditLog } from "../../hooks/usePricingAuditLog";

export function PricingAuditLog() {
  const { logs, loading } = usePricingAuditLog(20);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (logs.length === 0) {
    return (
      <div className="text-center py-8">
        <p className="text-sm text-muted-foreground">
          Nenhum registro de auditoria
        </p>
      </div>
    );
  }

  const getActionLabel = (action: string) => {
    const labels: Record<string, string> = {
      rule_created: "Criada",
      rule_updated: "Atualizada",
      rule_activated: "Ativada",
      rule_deactivated: "Desativada",
    };
    return labels[action] || action;
  };

  const getActionColor = (action: string) => {
    if (action === "rule_created") return "default";
    if (action === "rule_activated") return "success";
    if (action === "rule_deactivated") return "destructive";
    return "secondary";
  };

  return (
    <div className="space-y-3">
      <h3 className="font-semibold text-sm text-foreground">
        Histórico de Alterações
      </h3>
      <div className="space-y-2 max-h-96 overflow-y-auto">
        {logs.map((log) => (
          <div
            key={log.id}
            className="p-3 rounded-lg border bg-card text-sm space-y-1"
          >
            <div className="flex items-center justify-between">
              <Badge variant={getActionColor(log.action) as any}>
                {getActionLabel(log.action)}
              </Badge>
              <span className="text-xs text-muted-foreground">
                {formatDistanceToNow(new Date(log.created_at), {
                  addSuffix: true,
                  locale: ptBR,
                })}
              </span>
            </div>
            {log.new_values?.name && (
              <p className="text-foreground font-medium">
                {log.new_values.name}
              </p>
            )}
            {log.new_values?.mode && (
              <p className="text-xs text-muted-foreground capitalize">
                Modo: {log.new_values.mode}
              </p>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

import { useMemo, useState } from "react";
