} from "@/core/business/types"; // ✅ MIGRADO - Tipos movidos para core
import { ADMIN_BUSINESS_FIELDS } from "@/modules/admin/config/adminBusinessFields";
import { ADMIN_BUSINESS_ACTIONS } from "@/modules/admin/config/adminBusinessActions";
import { ADMIN_BUSINESS_FILTERS } from "@/modules/admin/config/adminBusinessFilters";
interface FieldConfig {
  key: string;
  label: string;
  type?: "text" | "number" | "boolean" | "textarea" | "select";
  options?: string[];
  required?: boolean;
  hideInTable?: boolean;
  placeholder?: string;
}

interface QuickAction {
  key: string;
  label: string;
  icon: any;
  activeColor?: string;
  inactiveColor?: string;
  getValue: (item: Business) => boolean;
  getNextValue?: (item: Business) => any;
}

interface FilterConfig {
  key: string;
  label: string;
  options?: string[];
}

export default function AdminBusinessPage() {
  const { canModerate, isChecking } = useAdminGuard();
  const { activeProfile } = useSessionContext();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // State
  const [businesses, setBusinesses] = useState<Business[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentPage, setCurrentPage] = useState(0);
  const [hasNextPage, setHasNextPage] = useState(false);
  const [totalLoaded, setTotalLoaded] = useState(0);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState<Business | null>(null);
  const [form, setForm] = useState<Record<string, any>>({});
  const [saving, setSaving] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [togglingId, setTogglingId] = useState<string | null>(null);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>(
    {},
  );

  const pageSize = 50; // Aumentado para admin
  const fields = ADMIN_BUSINESS_FIELDS;
  const quickActions = ADMIN_BUSINESS_ACTIONS;
  const filters = ADMIN_BUSINESS_FILTERS;

  // 🎯 LOAD DATA usando BusinessService com PAGINAÇÃO
  const loadBusinesses = async (pageParam = 0, append = false) => {
    if (!append) setLoading(true);

    try {
      const result = await BusinessService.getBusinessesList({
        pageParam,
        pageSize,
        category: activeFilters.category,
        searchQuery: searchQuery.trim() || undefined,
      });

      if (append) {
        setBusinesses((prev) => [...prev, ...result.businesses]);
      } else {
        setBusinesses(result.businesses);
      }

      setHasNextPage(!!result.nextPage);
      setCurrentPage(pageParam);
      setTotalLoaded(
        append
          ? totalLoaded + result.businesses.length
          : result.businesses.length,
      );
    } catch (error) {
      logger.error("Erro ao carregar empresas:", error);
      toast({
        title: "Erro ao carregar empresas",
        description:
          error instanceof Error ? error.message : "Erro desconhecido",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  // Load inicial
  useEffect(() => {
    if (!isChecking && canModerate) {
      loadBusinesses(0, false);
    }
  }, [searchQuery, activeFilters, canModerate, isChecking]);

  // 🎯 LOAD MORE para paginação
  const loadMore = () => {
    if (hasNextPage && !loading) {
      loadBusinesses(currentPage + 1, true);
    }
  };

  // 🎯 COMPUTED VALUES
  const tableFields = fields.filter((f) => !f.hideInTable);
  const visibleFields = tableFields.slice(0, 5);

  // Build filter options from data if not provided
  const filterOptions = useMemo(() => {
    if (!filters) return {};
    const opts: Record<string, string[]> = {};
    filters.forEach((f) => {
      if (f.options) {
        opts[f.key] = f.options;
      } else {
        const unique = [
          ...new Set(
            businesses
              .map((b) => String((b as any)[f.key] ?? ""))
              .filter(Boolean),
          ),
        ].sort();
        opts[f.key] = unique;
      }
    });
    return opts;
  }, [filters, businesses]);

  const hasActiveFilters = Object.values(activeFilters).some((v) => v !== "");

  const filtered = useMemo(() => {
    let result = businesses;
    // Apply filters
    Object.entries(activeFilters).forEach(([key, value]) => {
      if (value) {
        result = result.filter(
          (business) =>
            String((business as any)[key] ?? "").toLowerCase() ===
            value.toLowerCase(),
        );
      }
    });
    // Apply search
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter((business) =>
        fields.some((f) =>
          String((business as any)[f.key] ?? "")
            .toLowerCase()
            .includes(q),
        ),
      );
    }
    return result;
  }, [businesses, searchQuery, fields, activeFilters]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const paged = filtered.slice(0, pageSize); // Mostrar apenas primeira página localmente

  useEffect(() => {
    // Reset quando filtros mudam
    setCurrentPage(0);
  }, [searchQuery, activeFilters]);

  // 🎯 FORM HANDLERS - SEM MAPPER (BusinessService faz tudo)
  const openNew = () => {
    setEditing(null);
    const empty: Record<string, any> = {};
    fields.forEach((f) => {
      empty[f.key] =
        f.type === "boolean" ? false : f.type === "number" ? 0 : "";
    });
    setForm(empty);
    setDialogOpen(true);
  };

  const openEdit = (business: Business) => {
    setEditing(business);
    const filled: Record<string, any> = {};
    fields.forEach((f) => {
      filled[f.key] =
        (business as any)[f.key] ?? (f.type === "boolean" ? false : "");
    });
    setForm(filled);
    setDialogOpen(true);
  };

  // 🎯 SAVE usando BusinessService (sem mapper frontend)
  const handleSave = async () => {
    setSaving(true);
    try {
      // BusinessService faz sanitização + validação + transformação
      if (editing) {
        // Update
        const updated = await BusinessService.updateBusiness(
          editing.id,
          form as UpdateBusinessInput,
        );

        // 🔄 CACHE INVALIDATION
        queryClient.invalidateQueries({ queryKey: ["businesses"] });
        queryClient.setQueryData(["business", editing.id], updated);

        toast({ title: "Empresa atualizada com sucesso" });
      } else {
        // Create - precisa de userId (usar admin atual)
        const created = await BusinessService.createBusiness(
          form as CreateBusinessInput,
          activeProfile?.id || "",
        );

        // 🔄 CACHE INVALIDATION
        queryClient.invalidateQueries({ queryKey: ["businesses"] });

        toast({ title: "Empresa criada com sucesso" });
      }

      setDialogOpen(false);
      await loadBusinesses(0, false); // Reload data
    } catch (error) {
      logger.error("Erro ao salvar empresa:", error);
      toast({
        title: "Erro ao salvar empresa",
        description:
          error instanceof Error ? error.message : "Erro desconhecido",
        variant: "destructive",
      });
    } finally {
      setSaving(false);
    }
  };

  // 🎯 DELETE usando BusinessService
  const handleDelete = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir esta empresa?")) return;

    try {
      await BusinessService.deleteBusiness(id);

      // 🔄 CACHE INVALIDATION
      queryClient.invalidateQueries({ queryKey: ["businesses"] });
      queryClient.removeQueries({ queryKey: ["business", id] });

      toast({ title: "Empresa excluída com sucesso" });
      await loadBusinesses(0, false); // Reload data
    } catch (error) {
      logger.error("Erro ao excluir empresa:", error);
      toast({
        title: "Erro ao excluir empresa",
        description:
          error instanceof Error ? error.message : "Erro desconhecido",
        variant: "destructive",
      });
    }
  };

  // 🎯 QUICK TOGGLE usando BusinessService
  const handleQuickToggle = async (business: Business, action: QuickAction) => {
    setTogglingId(`${business.id}-${action.key}`);
    try {
      // Use custom getNextValue if provided, otherwise toggle boolean
      const newValue = action.getNextValue
        ? action.getNextValue(business)
        : !action.getValue(business);

      // Create update input with only the changed field
      const updateInput: UpdateBusinessInput = {
        [action.key]: newValue,
      } as any;

      const updated = await BusinessService.updateBusiness(
        business.id,
        updateInput,
      );

      // Update local state
      setBusinesses((prev) =>
        prev.map((b) => (b.id === business.id ? updated : b)),
      );

      // 🔄 CACHE INVALIDATION
      queryClient.invalidateQueries({ queryKey: ["businesses"] });
      queryClient.setQueryData(["business", business.id], updated);

      toast({
        title: `${action.label}: ${action.getNextValue ? String(newValue) : newValue ? "Ativado" : "Desativado"}`,
      });
    } catch (error) {
      logger.error("Erro ao atualizar empresa:", error);
      toast({
        title: "Erro ao atualizar empresa",
        description:
          error instanceof Error ? error.message : "Erro desconhecido",
        variant: "destructive",
      });
    } finally {
      setTogglingId(null);
    }
  };

  // 🎯 RENDER CELL VALUE
  const renderCellValue = (business: Business, f: FieldConfig) => {
    const val = (business as any)[f.key];
    if (f.type === "boolean") {
      return val ? (
        <Badge
          variant="secondary"
          className="bg-emerald-500/10 text-emerald-600 text-[10px]"
        >
          Sim
        </Badge>
      ) : (
        <Badge variant="secondary" className="text-[10px]">
          Não
        </Badge>
      );
    }
    if (f.key === "category" || f.key === "status" || f.key === "tipo") {
      return (
        <Badge variant="outline" className="text-[10px] font-normal">
          {String(val ?? "-")}
        </Badge>
      );
    }
    if (f.type === "number")
      return <span className="font-mono text-xs">{val ?? 0}</span>;
    return (
      <span className="truncate block max-w-[180px]">{String(val ?? "-")}</span>
    );
  };

  return (
    <div>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-5">
        <div>
          <h1 className="text-2xl font-bold font-display">Empresas</h1>
          <p className="text-sm text-muted-foreground">
            Gerencie todas as empresas cadastradas na plataforma · {totalLoaded}{" "}
            registros carregados
            {hasNextPage && " (mais disponíveis)"}
          </p>
        </div>
        <Button onClick={openNew} size="sm" className="shrink-0">
          <Plus className="h-4 w-4 mr-1" /> Nova Empresa
        </Button>
      </div>

      <div className="flex flex-col sm:flex-row gap-2 mb-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar empresas..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9 h-9"
          />
        </div>
        {filters &&
          filters.map((f) => (
            <select
              key={f.key}
              value={activeFilters[f.key] ?? ""}
              onChange={(e) =>
                setActiveFilters((prev) => ({
                  ...prev,
                  [f.key]: e.target.value,
                }))
              }
              className="h-9 rounded-md border bg-background px-3 text-sm text-foreground min-w-[140px]"
            >
              <option value="">{f.label}: Todos</option>
              {(filterOptions[f.key] ?? []).map((o) => (
                <option key={o} value={o}>
                  {o}
                </option>
              ))}
            </select>
          ))}
        {hasActiveFilters && (
          <Button
            variant="ghost"
            size="sm"
            className="h-9 text-xs gap-1"
            onClick={() => setActiveFilters({})}
          >
            <X className="h-3.5 w-3.5" /> Limpar
          </Button>
        )}
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16">
          <p className="text-sm text-muted-foreground">
            {searchQuery
              ? "Nenhum resultado encontrado."
              : "Nenhuma empresa encontrada."}
          </p>
        </div>
      ) : (
        <>
          <div className="bg-card rounded-xl border overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b bg-muted/50">
                    {visibleFields.map((f) => (
                      <th
                        key={f.key}
                        className="text-left px-4 py-3 font-medium text-muted-foreground text-xs uppercase tracking-wider"
                      >
                        {f.label}
                      </th>
                    ))}
                    {quickActions && quickActions.length > 0 && (
                      <th className="text-center px-2 py-3 font-medium text-muted-foreground text-xs uppercase tracking-wider">
                        Rápidas
                      </th>
                    )}
                    <th className="text-right px-4 py-3 font-medium text-muted-foreground text-xs uppercase tracking-wider w-24">
                      Ações
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {paged.map((business) => (
                    <tr
                      key={business.id}
                      className="border-b last:border-0 hover:bg-muted/30 transition-colors"
                    >
                      {visibleFields.map((f) => (
                        <td key={f.key} className="px-4 py-3 text-sm">
                          {renderCellValue(business, f)}
                        </td>
                      ))}
                      {quickActions && quickActions.length > 0 && (
                        <td className="px-2 py-3 text-center">
                          <div className="flex items-center justify-center gap-0.5">
                            {quickActions.map((action) => {
                              const isActive = action.getValue(business);
                              const isToggling =
                                togglingId === `${business.id}-${action.key}`;
                              const Icon = action.icon;
                              return (
                                <Button
                                  key={action.key}
                                  variant="ghost"
                                  size="icon"
                                  className={cn(
                                    "h-7 w-7 transition-colors",
                                    isActive
                                      ? action.activeColor ||
                                          "text-emerald-600 bg-emerald-500/10 hover:bg-emerald-500/20"
                                      : action.inactiveColor ||
                                          "text-muted-foreground hover:text-foreground",
                                  )}
                                  title={`${action.label}: ${isActive ? "Ativo" : "Inativo"}`}
                                  onClick={() =>
                                    handleQuickToggle(business, action)
                                  }
                                  disabled={isToggling}
                                >
                                  {isToggling ? (
                                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                                  ) : (
                                    <Icon className="h-3.5 w-3.5" />
                                  )}
                                </Button>
                              );
                            })}
                          </div>
                        </td>
                      )}
                      <td className="px-4 py-3 text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            onClick={() => openEdit(business)}
                          >
                            <Pencil className="h-3.5 w-3.5" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 text-destructive hover:text-destructive"
                            onClick={() => handleDelete(business.id)}
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {totalPages > 1 && (
            <div className="flex items-center justify-between mt-4 text-sm">
              <span className="text-muted-foreground text-xs">
                {totalLoaded} registros carregados
                {hasNextPage && " · Mais disponíveis"}
              </span>
              <div className="flex gap-2">
                {hasNextPage && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={loadMore}
                    disabled={loading}
                  >
                    {loading ? (
                      <Loader2 className="h-4 w-4 animate-spin mr-1" />
                    ) : null}
                    Carregar Mais
                  </Button>
                )}
              </div>
            </div>
          )}
        </>
      )}

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-lg max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editing ? "Editar" : "Nova"} Empresa</DialogTitle>
          </DialogHeader>
          <DialogDescription className="sr-only">
            Gerenciar empresas do sistema
          </DialogDescription>
          <div className="space-y-3 mt-2">
            {fields.map((f) => (
              <div key={f.key}>
                <label className="text-xs font-medium text-muted-foreground mb-1 block">
                  {f.label}{" "}
                  {f.required && <span className="text-destructive">*</span>}
                </label>
                {f.type === "boolean" ? (
                  <button
                    type="button"
                    onClick={() =>
                      setForm((prev) => ({ ...prev, [f.key]: !prev[f.key] }))
                    }
                    className={cn(
                      "px-3 py-1.5 rounded-md text-xs font-medium border transition-colors",
                      form[f.key]
                        ? "bg-emerald-500/10 text-emerald-600 border-emerald-500/30"
                        : "bg-muted text-muted-foreground",
                    )}
                  >
                    {form[f.key] ? "Sim" : "Não"}
                  </button>
                ) : f.type === "select" && f.options ? (
                  <select
                    value={form[f.key] ?? ""}
                    onChange={(e) =>
                      setForm((prev) => ({ ...prev, [f.key]: e.target.value }))
                    }
                    className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                  >
                    <option value="">Selecione...</option>
                    {f.options.map((o) => (
                      <option key={o} value={o}>
                        {o}
                      </option>
                    ))}
                  </select>
                ) : f.type === "textarea" ? (
                  <textarea
                    value={form[f.key] ?? ""}
                    onChange={(e) =>
                      setForm((prev) => ({ ...prev, [f.key]: e.target.value }))
                    }
                    placeholder={f.placeholder}
                    className="w-full rounded-md border bg-background px-3 py-2 text-sm min-h-[80px] resize-y"
                  />
                ) : (
                  <Input
                    type={f.type === "number" ? "number" : "text"}
                    value={form[f.key] ?? ""}
                    placeholder={f.placeholder}
                    onChange={(e) =>
                      setForm((prev) => ({
                        ...prev,
                        [f.key]:
                          f.type === "number"
                            ? Number(e.target.value)
                            : e.target.value,
                      }))
                    }
                  />
                )}
              </div>
            ))}
          </div>
          <div className="flex justify-end gap-2 mt-4">
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSave} disabled={saving}>
              {saving && <Loader2 className="h-4 w-4 mr-1 animate-spin" />}
              {editing ? "Salvar" : "Criar"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

// Validação de admin - renderizar no final
function AdminBusinessPageWrapper() {
  const { canModerate, isChecking } = useAdminGuard();

  if (!isChecking && !canModerate) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center p-4">
        <div className="text-center">
          <Shield className="h-16 w-16 text-destructive mx-auto mb-4" />
          <h1 className="text-2xl font-bold mb-2">Acesso Negado</h1>
          <p className="text-muted-foreground">
            Apenas administradores podem acessar esta página.
          </p>
        </div>
      </div>
    );
  }

  return <AdminBusinessPage />;
}

/**
 * AdminCommunityAlerts - Gestão administrativa de alertas comunitários
 * 
 * SSOT: Usa adminCommunityAlertsService
 * 
 * Funcionalidades:
 * - Listagem de todos os alertas com filtros
 * - Moderação de alertas reportados
 * - Gestão de termos bloqueados
 * - Analytics e estatísticas
 */

import React, { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { adminCommunityAlertsService } from "@/core/admin";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/shared/components/ui/dialog";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/shared/components/ui/tabs";
import { Badge } from "@/shared/components/ui/badge";
import { Textarea } from "@/shared/components/ui/textarea";
import {
  AlertTriangle,
  CheckCircle,
  XCircle,
  Eye,
  Trash2,
  Shield,
  TrendingUp,
  Filter,
  Search,
  Plus,
  Ban,
} from "lucide-react";
import { toast } from "sonner";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import {
  ALERT_CATEGORY_LABELS,
  ALERT_REPORT_REASON_LABELS,
} from "@/shared/services/communityAlerts";
import type { AlertCategory, AlertStatus } from "@/shared/services/communityAlerts";

export default function AdminCommunityAlerts() {
  const queryClient = useQueryClient();
  const [activeTab, setActiveTab] = useState("all");
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<AlertStatus | "">("");
  const [categoryFilter, setCategoryFilter] = useState<AlertCategory | "">("");
  
  // Dialogs
  const [selectedAlert, setSelectedAlert] = useState<any>(null);
  const [showRemoveDialog, setShowRemoveDialog] = useState(false);
  const [removalReason, setRemovalReason] = useState("");
  const [showBlockedTermsDialog, setShowBlockedTermsDialog] = useState(false);
  const [newBlockedTerm, setNewBlockedTerm] = useState("");

  // Buscar estatísticas
  const { data: stats } = useQuery({
    queryKey: ["admin-community-alerts-stats"],
    queryFn: () => adminCommunityAlertsService.getStats(),
  });

  // Buscar alertas
  const { data: alertsData, isLoading } = useQuery({
    queryKey: ["admin-community-alerts", page, search, statusFilter, categoryFilter, activeTab],
    queryFn: () =>
      adminCommunityAlertsService.getAllAlerts({
        page,
        limit: 20,
        search: search || undefined,
        status: statusFilter || undefined,
        category: categoryFilter || undefined,
        underReview: activeTab === "review" ? true : undefined,
      }),
  });

  // Buscar alertas sob revisão
  const { data: reviewAlerts } = useQuery({
    queryKey: ["admin-community-alerts-review"],
    queryFn: () => adminCommunityAlertsService.getAlertsUnderReview(),
    enabled: activeTab === "review",
  });

  // Buscar alertas mais reportados
  const { data: topReported } = useQuery({
    queryKey: ["admin-community-alerts-top-reported"],
    queryFn: () => adminCommunityAlertsService.getTopReportedAlerts(10),
    enabled: activeTab === "analytics",
  });

  // Buscar estatísticas por categoria
  const { data: categoryStats } = useQuery({
    queryKey: ["admin-community-alerts-category-stats"],
    queryFn: () => adminCommunityAlertsService.getStatsByCategory(),
    enabled: activeTab === "analytics",
  });

  // Buscar termos bloqueados
  const { data: blockedTerms } = useQuery({
    queryKey: ["admin-community-alerts-blocked-terms"],
    queryFn: () => adminCommunityAlertsService.getBlockedTerms(),
    enabled: activeTab === "blocked-terms",
  });

  // Mutations
  const removeMutation = useMutation({
    mutationFn: ({ id, reason }: { id: string; reason: string }) =>
      adminCommunityAlertsService.removeAlert(id, reason),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts"] });
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts-stats"] });
      toast.success("Alerta removido com sucesso");
      setShowRemoveDialog(false);
      setSelectedAlert(null);
      setRemovalReason("");
    },
    onError: () => {
      toast.error("Erro ao remover alerta");
    },
  });

  const clearReviewMutation = useMutation({
    mutationFn: (id: string) => adminCommunityAlertsService.clearUnderReview(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts"] });
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts-review"] });
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts-stats"] });
      toast.success("Alerta aprovado");
    },
    onError: () => {
      toast.error("Erro ao aprovar alerta");
    },
  });

  const endAlertMutation = useMutation({
    mutationFn: (id: string) => adminCommunityAlertsService.endAlert(id),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts"] });
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts-stats"] });
      toast.success("Alerta encerrado");
    },
    onError: () => {
      toast.error("Erro ao encerrar alerta");
    },
  });

  const addBlockedTermMutation = useMutation({
    mutationFn: (term: string) => adminCommunityAlertsService.addBlockedTerm(term),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts-blocked-terms"] });
      toast.success("Termo bloqueado adicionado");
      setNewBlockedTerm("");
    },
    onError: () => {
      toast.error("Erro ao adicionar termo bloqueado");
    },
  });

  const removeBlockedTermMutation = useMutation({
    mutationFn: (termId: string) => adminCommunityAlertsService.removeBlockedTerm(termId),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts-blocked-terms"] });
      toast.success("Termo bloqueado removido");
    },
    onError: () => {
      toast.error("Erro ao remover termo bloqueado");
    },
  });

  const toggleBlockedTermMutation = useMutation({
    mutationFn: ({ termId, isActive }: { termId: string; isActive: boolean }) =>
      adminCommunityAlertsService.toggleBlockedTerm(termId, isActive),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin-community-alerts-blocked-terms"] });
      toast.success("Status do termo atualizado");
    },
    onError: () => {
      toast.error("Erro ao atualizar termo");
    },
  });

  const handleRemoveAlert = () => {
    if (!selectedAlert || !removalReason.trim()) {
      toast.error("Informe o motivo da remoção");
      return;
    }
    removeMutation.mutate({ id: selectedAlert.id, reason: removalReason });
  };

  const getStatusBadge = (status: AlertStatus) => {
    const variants: Record<AlertStatus, { variant: any; label: string }> = {
      ativo: { variant: "default", label: "Ativo" },
      encerrado: { variant: "secondary", label: "Encerrado" },
      expirado: { variant: "outline", label: "Expirado" },
      removido: { variant: "destructive", label: "Removido" },
    };
    const config = variants[status] || variants.ativo;
    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold font-display flex items-center gap-2">
          <AlertTriangle className="h-8 w-8" />
          Gestão de Alertas Comunitários
        </h1>
        <p className="text-muted-foreground mt-1">
          Gerencie alertas, moderação e termos bloqueados
        </p>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              Total de Alertas
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats?.total || 0}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              Alertas Ativos
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">
              {stats?.active || 0}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              Sob Revisão
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-orange-600">
              {stats?.underReview || 0}
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">
              Total de Reports
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-600">
              {stats?.totalReports || 0}
            </div>
            <p className="text-xs text-muted-foreground mt-1">
              Média: {stats?.avgReportsPerAlert || 0} por alerta
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="all">Todos os Alertas</TabsTrigger>
          <TabsTrigger value="review">
            Sob Revisão
            {stats?.underReview ? (
              <Badge variant="destructive" className="ml-2">
                {stats.underReview}
              </Badge>
            ) : null}
          </TabsTrigger>
          <TabsTrigger value="analytics">Analytics</TabsTrigger>
          <TabsTrigger value="blocked-terms">Termos Bloqueados</TabsTrigger>
        </TabsList>

        {/* Todos os Alertas Tab */}
        <TabsContent value="all" className="space-y-4">
          {/* Filtros */}
          <Card>
            <CardContent className="pt-6">
              <div className="flex flex-col md:flex-row gap-4">
                <div className="flex-1">
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                      placeholder="Buscar por descrição ou bairro..."
                      value={search}
                      onChange={(e) => setSearch(e.target.value)}
                      className="pl-10"
                    />
                  </div>
                </div>

                <Select value={statusFilter || "all"} onValueChange={(value) => setStatusFilter(value === "all" ? "" : value as AlertStatus)}>
                  <SelectTrigger className="w-[180px]">
                    <SelectValue placeholder="Status" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Todos</SelectItem>
                    <SelectItem value="ativo">Ativo</SelectItem>
                    <SelectItem value="encerrado">Encerrado</SelectItem>
                    <SelectItem value="expirado">Expirado</SelectItem>
                    <SelectItem value="removido">Removido</SelectItem>
                  </SelectContent>
                </Select>

                <Select value={categoryFilter || "all"} onValueChange={(value) => setCategoryFilter(value === "all" ? "" : value as AlertCategory)}>
                  <SelectTrigger className="w-[220px]">
                    <SelectValue placeholder="Categoria" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">Todas</SelectItem>
                    {Object.entries(ALERT_CATEGORY_LABELS).map(([key, label]) => (
                      <SelectItem key={key} value={key}>
                        {label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </CardContent>
          </Card>

          {/* Tabela de Alertas */}
          <Card>
            <CardContent className="pt-6">
              {isLoading ? (
                <div className="text-center py-8">
                  <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto" />
                </div>
              ) : (
                <>
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Categoria</TableHead>
                        <TableHead>Localização</TableHead>
                        <TableHead>Descrição</TableHead>
                        <TableHead>Status</TableHead>
                        <TableHead>Reports</TableHead>
                        <TableHead>Data</TableHead>
                        <TableHead className="text-right">Ações</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {alertsData?.data?.map((alert: any) => (
                        <TableRow key={alert.id}>
                          <TableCell className="font-medium">
                            {ALERT_CATEGORY_LABELS[alert.category as AlertCategory]}
                          </TableCell>
                          <TableCell>
                            <div className="text-sm">
                              <div>{alert.neighborhood_display}</div>
                              <div className="text-muted-foreground">{alert.city}</div>
                            </div>
                          </TableCell>
                          <TableCell className="max-w-xs truncate">
                            {alert.description}
                          </TableCell>
                          <TableCell>
                            {getStatusBadge(alert.status)}
                            {alert.under_review && (
                              <Badge variant="outline" className="ml-2">
                                Em Revisão
                              </Badge>
                            )}
                          </TableCell>
                          <TableCell>
                            {alert.report_count > 0 ? (
                              <Badge variant="destructive">{alert.report_count}</Badge>
                            ) : (
                              <span className="text-muted-foreground">0</span>
                            )}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground">
                            {format(new Date(alert.created_at), "dd/MM/yyyy HH:mm", {
                              locale: ptBR,
                            })}
                          </TableCell>
                          <TableCell className="text-right">
                            <div className="flex items-center justify-end gap-2">
                              {alert.under_review && alert.status === "ativo" && (
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => clearReviewMutation.mutate(alert.id)}
                                  disabled={clearReviewMutation.isPending}
                                >
                                  <CheckCircle className="h-4 w-4" />
                                </Button>
                              )}
                              
                              {alert.status === "ativo" && (
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => endAlertMutation.mutate(alert.id)}
                                  disabled={endAlertMutation.isPending}
                                >
                                  <XCircle className="h-4 w-4" />
                                </Button>
                              )}

                              <Button
                                size="sm"
                                variant="destructive"
                                onClick={() => {
                                  setSelectedAlert(alert);
                                  setShowRemoveDialog(true);
                                }}
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>

                  {/* Paginação */}
                  {alertsData && alertsData.totalPages > 1 && (
                    <div className="flex items-center justify-between mt-4">
                      <p className="text-sm text-muted-foreground">
                        Página {alertsData.page} de {alertsData.totalPages}
                      </p>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          disabled={page === 1}
                          onClick={() => setPage(page - 1)}
                        >
                          Anterior
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          disabled={page === alertsData.totalPages}
                          onClick={() => setPage(page + 1)}
                        >
                          Próxima
                        </Button>
                      </div>
                    </div>
                  )}
                </>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Sob Revisão Tab */}
        <TabsContent value="review" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Alertas Sob Revisão</CardTitle>
              <CardDescription>
                Alertas que atingiram o limite de reports e precisam de análise
              </CardDescription>
            </CardHeader>
            <CardContent>
              {reviewAlerts && reviewAlerts.length > 0 ? (
                <div className="space-y-4">
                  {reviewAlerts.map((alert: any) => (
                    <div key={alert.id} className="border rounded-lg p-4">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <Badge>{ALERT_CATEGORY_LABELS[alert.category as AlertCategory]}</Badge>
                            <Badge variant="destructive">{alert.report_count} reports</Badge>
                          </div>
                          <p className="text-sm font-medium mb-1">
                            {alert.neighborhood_display}, {alert.city}
                          </p>
                          <p className="text-sm text-muted-foreground mb-3">
                            {alert.description}
                          </p>
                          
                          {alert.reports && alert.reports.length > 0 && (
                            <div className="mt-3 pt-3 border-t">
                              <p className="text-sm font-medium mb-2">Motivos dos Reports:</p>
                              <div className="flex flex-wrap gap-2">
                                {alert.reports.map((report: any) => (
                                  <Badge key={report.id} variant="outline">
                                    {ALERT_REPORT_REASON_LABELS[report.reason]}
                                  </Badge>
                                ))}
                              </div>
                            </div>
                          )}
                        </div>
                        
                        <div className="flex gap-2 ml-4">
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => clearReviewMutation.mutate(alert.id)}
                            disabled={clearReviewMutation.isPending}
                          >
                            <CheckCircle className="h-4 w-4 mr-2" />
                            Aprovar
                          </Button>
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => {
                              setSelectedAlert(alert);
                              setShowRemoveDialog(true);
                            }}
                          >
                            <Trash2 className="h-4 w-4 mr-2" />
                            Remover
                          </Button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-center text-muted-foreground py-8">
                  Nenhum alerta sob revisão no momento
                </p>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Analytics Tab */}
        <TabsContent value="analytics" className="space-y-4">
          <div className="grid gap-4 md:grid-cols-2">
            {/* Alertas Mais Reportados */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <TrendingUp className="h-5 w-5" />
                  Alertas Mais Reportados
                </CardTitle>
              </CardHeader>
              <CardContent>
                {topReported && topReported.length > 0 ? (
                  <div className="space-y-3">
                    {topReported.map((alert: any, index: number) => (
                      <div key={alert.id} className="flex items-center justify-between">
                        <div className="flex-1">
                          <p className="text-sm font-medium">
                            #{index + 1} - {ALERT_CATEGORY_LABELS[alert.category as AlertCategory]}
                          </p>
                          <p className="text-xs text-muted-foreground truncate">
                            {alert.neighborhood_display}
                          </p>
                        </div>
                        <Badge variant="destructive">{alert.report_count} reports</Badge>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p className="text-center text-muted-foreground py-4">
                    Nenhum alerta reportado
                  </p>
                )}
              </CardContent>
            </Card>

            {/* Estatísticas por Categoria */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Filter className="h-5 w-5" />
                  Alertas por Categoria
                </CardTitle>
              </CardHeader>
              <CardContent>
                {categoryStats && Object.keys(categoryStats).length > 0 ? (
                  <div className="space-y-3">
                    {Object.entries(categoryStats)
                      .sort(([, a], [, b]) => (b as number) - (a as number))
                      .map(([category, count]) => (
                        <div key={category} className="flex items-center justify-between">
                          <p className="text-sm">
                            {ALERT_CATEGORY_LABELS[category as AlertCategory]}
                          </p>
                          <Badge variant="outline">{count as number}</Badge>
                        </div>
                      ))}
                  </div>
                ) : (
                  <p className="text-center text-muted-foreground py-4">
                    Nenhum dado disponível
                  </p>
                )}
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        {/* Termos Bloqueados Tab */}
        <TabsContent value="blocked-terms" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Ban className="h-5 w-5" />
                Termos Bloqueados
              </CardTitle>
              <CardDescription>
                Gerencie termos que não podem ser usados em alertas
              </CardDescription>
            </CardHeader>
            <CardContent>
              {/* Adicionar Termo */}
              <div className="flex gap-2 mb-4">
                <Input
                  placeholder="Novo termo bloqueado..."
                  value={newBlockedTerm}
                  onChange={(e) => setNewBlockedTerm(e.target.value)}
                />
                <Button
                  onClick={() => {
                    if (newBlockedTerm.trim()) {
                      addBlockedTermMutation.mutate(newBlockedTerm);
                    }
                  }}
                  disabled={addBlockedTermMutation.isPending || !newBlockedTerm.trim()}
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Adicionar
                </Button>
              </div>

              {/* Lista de Termos */}
              {blockedTerms && blockedTerms.length > 0 ? (
                <div className="space-y-2">
                  {blockedTerms.map((term: any) => (
                    <div
                      key={term.id}
                      className="flex items-center justify-between p-3 border rounded-lg"
                    >
                      <div className="flex items-center gap-3">
                        <code className="text-sm font-mono bg-muted px-2 py-1 rounded">
                          {term.term}
                        </code>
                        {!term.is_active && (
                          <Badge variant="outline">Inativo</Badge>
                        )}
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() =>
                            toggleBlockedTermMutation.mutate({
                              termId: term.id,
                              isActive: !term.is_active,
                            })
                          }
                          disabled={toggleBlockedTermMutation.isPending}
                        >
                          {term.is_active ? "Desativar" : "Ativar"}
                        </Button>
                        <Button
                          size="sm"
                          variant="destructive"
                          onClick={() => removeBlockedTermMutation.mutate(term.id)}
                          disabled={removeBlockedTermMutation.isPending}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-center text-muted-foreground py-8">
                  Nenhum termo bloqueado cadastrado
                </p>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Dialog de Remoção */}
      <Dialog open={showRemoveDialog} onOpenChange={setShowRemoveDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Remover Alerta</DialogTitle>
            <DialogDescription>
              Informe o motivo da remoção. Esta ação não pode ser desfeita.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <Textarea
              placeholder="Motivo da remoção..."
              value={removalReason}
              onChange={(e) => setRemovalReason(e.target.value)}
              rows={4}
            />
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setShowRemoveDialog(false);
                setSelectedAlert(null);
                setRemovalReason("");
              }}
            >
              Cancelar
            </Button>
            <Button
              variant="destructive"
              onClick={handleRemoveAlert}
              disabled={removeMutation.isPending || !removalReason.trim()}
            >
              Remover Alerta
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React from "react";
import { useState, useEffect, useMemo } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  Loader2,
  Plus,
  Pencil,
  Trash2,
  Search,
  ChevronLeft,
  ChevronRight,
  Filter,
  X,
  Shield,
} from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/shared/components/ui/dialog";
import { useToast } from "@/shared/hooks/use-toast";
import { Badge } from "@/shared/components/ui/badge";
import { cn } from "@/shared/utils/cn";
import { USER_ROLE, ALERT_STATUS, RIDE_STATUS } from "@/shared/types/constants";
import { useAuth } from "@/core/auth/hooks/useAuth";
import { logger } from "@/shared/utils/logger";
import { adminCrudService } from "@/core/admin/services/AdminCrudService";

/**
 * @deprecated
 * AdminCrudPage is deprecated. Use domain-specific admin pages instead:
 * - AdminClassificados for classifieds (uses AdminClassifiedsService)
 * - AdminEventos for events (uses AdminEventsService)
 * - AdminCupons for coupons (uses AdminCouponsService)
 * - AdminMensagens for messaging (uses AdminMessagingService)
 * 
 * This generic CRUD page violates SSOT principles by using AdminCrudService.
 * Migration to domain-specific pages is complete.
 */

export interface FieldConfig {
  key: string;
  label: string;
  type?: "text" | "number" | "boolean" | "textarea" | "select";
  options?: string[];
  required?: boolean;
  hideInTable?: boolean;
  placeholder?: string;
}

export interface QuickAction {
  key: string;
  label: string;
  icon: any;
  activeColor?: string;
  inactiveColor?: string;
  getValue: (item: any) => boolean;
  getNextValue?: (item: any) => any;
}

export interface FilterConfig {
  key: string;
  label: string;
  options?: string[];
}

interface AdminCrudPageProps {
  title: string;
  description?: string;
  table: string;
  fields: FieldConfig[];
  nameField: string;
  pageSize?: number;
  quickActions?: QuickAction[];
  filters?: FilterConfig[];
  disableCreate?: boolean; // Desabilita criação de novos registros
}

export default function AdminCrudPage({
  title,
  description,
  table,
  fields,
  nameField,
  pageSize = 15,
  quickActions,
  filters,
  disableCreate = false,
}: AdminCrudPageProps) {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editing, setEditing] = useState<any | null>(null);
  const [form, setForm] = useState<Record<string, any>>({});
  const [saving, setSaving] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [page, setPage] = useState(0);
  const [togglingId, setTogglingId] = useState<string | null>(null);
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>(
    {},
  );
  const { toast } = useToast();

  const load = async () => {
    setLoading(true);
    try {
      const data = await adminCrudService.list(table);
      setItems(data || []);
    } catch (error: any) {
      logger.error("Error loading data:", error);
      toast({
        title: "Erro ao carregar dados",
        description: error?.message ?? "Falha ao carregar registros.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, [table]);

  const tableFields = fields.filter((f) => !f.hideInTable);
  const visibleFields = tableFields.slice(0, 5);

  // Build filter options from date if not provided
  const filterOptions = useMemo(() => {
    if (!filters) return {};
    const opts: Record<string, string[]> = {};
    filters.forEach((f) => {
      if (f.options) {
        opts[f.key] = f.options;
      } else {
        const unique = [
          ...new Set(items.map((i) => String(i[f.key] ?? "")).filter(Boolean)),
        ].sort();
        opts[f.key] = unique;
      }
    });
    return opts;
  }, [filters, items]);

  const hasActiveFilters = Object.values(activeFilters).some((v) => v !== "");

  const filtered = useMemo(() => {
    let result = items;
    // Apply filters
    Object.entries(activeFilters).forEach(([key, value]) => {
      if (value) {
        result = result.filter(
          (item) =>
            String(item[key] ?? "").toLowerCase() === value.toLowerCase(),
        );
      }
    });
    // Apply search
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter((item) =>
        fields.some((f) =>
          String(item[f.key] ?? "")
            .toLowerCase()
            .includes(q),
        ),
      );
    }
    return result;
  }, [items, searchQuery, fields, activeFilters]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const paged = filtered.slice(page * pageSize, (page + 1) * pageSize);

  useEffect(() => {
    setPage(0);
  }, [searchQuery, activeFilters]);

  const openNew = () => {
    setEditing(null);
    const empty: Record<string, any> = {};
    fields.forEach((f) => {
      empty[f.key] =
        f.type === "boolean" ? false : f.type === "number" ? 0 : "";
    });
    setForm(empty);
    setDialogOpen(true);
  };

  const openEdit = (item: any) => {
    setEditing(item);
    const filled: Record<string, any> = {};
    fields.forEach((f) => {
      filled[f.key] = item[f.key] ?? (f.type === "boolean" ? false : "");
    });
    setForm(filled);
    setDialogOpen(true);
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      if (editing) {
        await adminCrudService.update(table, editing.id, form);
        toast({ title: "Atualizado com sucesso" });
      } else {
        await adminCrudService.create(table, form);
        toast({ title: "Criado com sucesso" });
      }
      setDialogOpen(false);
      await load();
    } catch (e: any) {
      toast({ title: "Erro", description: e.message, variant: "destructive" });
    }
    setSaving(false);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Tem certeza que deseja excluir?")) return;
    try {
      await adminCrudService.delete(table, id);
      toast({ title: "Excluído com sucesso" });
      await load();
    } catch (e: any) {
      toast({ title: "Erro", description: e.message, variant: "destructive" });
    }
  };

  const handleQuickToggle = async (item: any, action: QuickAction) => {
    setTogglingId(`${item.id}-${action.key}`);
    try {
      // Use custom getNextValue if provided, otherwise toggle boolean
      const newValue = action.getNextValue
        ? action.getNextValue(item)
        : !action.getValue(item);

      await adminCrudService.update(table, item.id, { [action.key]: newValue });
      setItems((prev) =>
        prev.map((i) =>
          i.id === item.id ? { ...i, [action.key]: newValue } : i,
        ),
      );
      toast({
        title: `${action.label}: ${action.getNextValue ? String(newValue) : newValue ? "Ativado" : "Desativado"}`,
      });
    } catch (e: any) {
      toast({ title: "Erro", description: e.message, variant: "destructive" });
    }
    setTogglingId(null);
  };

  const renderCellValue = (item: any, f: FieldConfig) => {
    const val = item[f.key];
    if (f.type === "boolean") {
      return val ? (
        <Badge
          variant="secondary"
          className="bg-emerald-500/10 text-emerald-600 text-[10px]"
        >
          Sim
        </Badge>
      ) : (
        <Badge variant="secondary" className="text-[10px]">
          Não
        </Badge>
      );
    }
    if (f.key === "category" || f.key === "status" || f.key === "tipo") {
      return (
        <Badge variant="outline" className="text-[10px] font-normal">
          {String(val ?? "-")}
        </Badge>
      );
    }
    if (f.type === "number")
      return <span className="font-mono text-xs">{val ?? 0}</span>;
    return (
      <span className="truncate block max-w-[180px]">{String(val ?? "-")}</span>
    );
  };

  return (
    <div>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-5">
        <div>
          <h1 className="text-2xl font-bold font-display">{title}</h1>
          <p className="text-sm text-muted-foreground">
            {description || `${filtered.length} de ${items.length} registros`}
          </p>
        </div>
        {!disableCreate && (
          <Button onClick={openNew} size="sm" className="shrink-0">
            <Plus className="h-4 w-4 mr-1" /> Novo
          </Button>
        )}
      </div>

      <div className="flex flex-col sm:flex-row gap-2 mb-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder={`Buscar em ${title.toLowerCase()}...`}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9 h-9"
          />
        </div>
        {filters &&
          filters.map((f) => (
            <select
              key={f.key}
              value={activeFilters[f.key] ?? ""}
              onChange={(e) =>
                setActiveFilters((prev) => ({
                  ...prev,
                  [f.key]: e.target.value,
                }))
              }
              className="h-9 rounded-md border bg-background px-3 text-sm text-foreground min-w-[140px]"
            >
              <option value="">{f.label}: Todos</option>
              {(filterOptions[f.key] ?? []).map((o) => (
                <option key={o} value={o}>
                  {o}
                </option>
              ))}
            </select>
          ))}
        {hasActiveFilters && (
          <Button
            variant="ghost"
            size="sm"
            className="h-9 text-xs gap-1"
            onClick={() => setActiveFilters({})}
          >
            <X className="h-3.5 w-3.5" /> Limpar
          </Button>
        )}
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </div>
      ) : filtered.length === 0 ? (
        <div className="text-center py-16">
          <p className="text-sm text-muted-foreground">
            {searchQuery
              ? "Nenhum resultado encontrado."
              : "Nenhum registro encontrado."}
          </p>
        </div>
      ) : (
        <>
          <div className="bg-card rounded-xl border overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b bg-muted/50">
                    {visibleFields.map((f) => (
                      <th
                        key={f.key}
                        className="text-left px-4 py-3 font-medium text-muted-foreground text-xs uppercase tracking-wider"
                      >
                        {f.label}
                      </th>
                    ))}
                    {quickActions && quickActions.length > 0 && (
                      <th className="text-center px-2 py-3 font-medium text-muted-foreground text-xs uppercase tracking-wider">
                        Rápidas
                      </th>
                    )}
                    <th className="text-right px-4 py-3 font-medium text-muted-foreground text-xs uppercase tracking-wider w-24">
                      Ações
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {paged.map((item) => (
                    <tr
                      key={item.id}
                      className="border-b last:border-0 hover:bg-muted/30 transition-colors"
                    >
                      {visibleFields.map((f) => (
                        <td key={f.key} className="px-4 py-3 text-sm">
                          {renderCellValue(item, f)}
                        </td>
                      ))}
                      {quickActions && quickActions.length > 0 && (
                        <td className="px-2 py-3 text-center">
                          <div className="flex items-center justify-center gap-0.5">
                            {quickActions.map((action) => {
                              const isActive = action.getValue(item);
                              const isToggling =
                                togglingId === `${item.id}-${action.key}`;
                              const Icon = action.icon;
                              return (
                                <Button
                                  key={action.key}
                                  variant="ghost"
                                  size="icon"
                                  className={cn(
                                    "h-7 w-7 transition-colors",
                                    isActive
                                      ? action.activeColor ||
                                          "text-emerald-600 bg-emerald-500/10 hover:bg-emerald-500/20"
                                      : action.inactiveColor ||
                                          "text-muted-foreground hover:text-foreground",
                                  )}
                                  title={`${action.label}: ${isActive ? "Ativo" : "Inactive"}`}
                                  onClick={() =>
                                    handleQuickToggle(item, action)
                                  }
                                  disabled={isToggling}
                                >
                                  {isToggling ? (
                                    <Loader2 className="h-3.5 w-3.5 animate-spin" />
                                  ) : (
                                    <Icon className="h-3.5 w-3.5" />
                                  )}
                                </Button>
                              );
                            })}
                          </div>
                        </td>
                      )}
                      <td className="px-4 py-3 text-right">
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            onClick={() => openEdit(item)}
                          >
                            <Pencil className="h-3.5 w-3.5" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7 text-destructive hover:text-destructive"
                            onClick={() => handleDelete(item.id)}
                          >
                            <Trash2 className="h-3.5 w-3.5" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          {totalPages > 1 && (
            <div className="flex items-center justify-between mt-4 text-sm">
              <span className="text-muted-foreground text-xs">
                Página {page + 1} de {totalPages} · {filtered.length} registros
              </span>
              <div className="flex gap-1">
                <Button
                  variant="outline"
                  size="icon"
                  className="h-8 w-8"
                  onClick={() => setPage((p) => p - 1)}
                  disabled={page === 0}
                >
                  <ChevronLeft className="h-4 w-4" />
                </Button>
                <Button
                  variant="outline"
                  size="icon"
                  className="h-8 w-8"
                  onClick={() => setPage((p) => p + 1)}
                  disabled={page >= totalPages - 1}
                >
                  <ChevronRight className="h-4 w-4" />
                </Button>
              </div>
            </div>
          )}
        </>
      )}

      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-lg max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editing ? `Editar` : `Novo`} {title.replace(/s$/, "")}
            </DialogTitle>
          </DialogHeader>
          <DialogDescription className="sr-only">
            Gerenciar registros do sistema
          </DialogDescription>
          <div className="space-y-3 mt-2">
            {fields.map((f) => (
              <div key={f.key}>
                <label className="text-xs font-medium text-muted-foreground mb-1 block">
                  {f.label}{" "}
                  {f.required && <span className="text-destructive">*</span>}
                </label>
                {f.type === "boolean" ? (
                  <button
                    type="button"
                    onClick={() =>
                      setForm((prev) => ({ ...prev, [f.key]: !prev[f.key] }))
                    }
                    className={cn(
                      "px-3 py-1.5 rounded-md text-xs font-medium border transition-colors",
                      form[f.key]
                        ? "bg-emerald-500/10 text-emerald-600 border-emerald-500/30"
                        : "bg-muted text-muted-foreground",
                    )}
                  >
                    {form[f.key] ? "Sim" : "Não"}
                  </button>
                ) : f.type === "select" && f.options ? (
                  <select
                    value={form[f.key] ?? ""}
                    onChange={(e) =>
                      setForm((prev) => ({ ...prev, [f.key]: e.target.value }))
                    }
                    className="w-full rounded-md border bg-background px-3 py-2 text-sm"
                  >
                    <option value="">Selecione...</option>
                    {f.options.map((o) => (
                      <option key={o} value={o}>
                        {o}
                      </option>
                    ))}
                  </select>
                ) : f.type === "textarea" ? (
                  <textarea
                    value={form[f.key] ?? ""}
                    onChange={(e) =>
                      setForm((prev) => ({ ...prev, [f.key]: e.target.value }))
                    }
                    placeholder={f.placeholder}
                    className="w-full rounded-md border bg-background px-3 py-2 text-sm min-h-[80px] resize-y"
                  />
                ) : (
                  <Input
                    type={f.type === "number" ? "number" : "text"}
                    value={form[f.key] ?? ""}
                    placeholder={f.placeholder}
                    onChange={(e) =>
                      setForm((prev) => ({
                        ...prev,
                        [f.key]:
                          f.type === "number"
                            ? Number(e.target.value)
                            : e.target.value,
                      }))
                    }
                  />
                )}
              </div>
            ))}
          </div>
          <div className="flex justify-end gap-2 mt-4">
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancelar
            </Button>
            <Button onClick={handleSave} disabled={saving}>
              {saving && <Loader2 className="h-4 w-4 mr-1 animate-spin" />}
              {editing ? "Salvar" : "Criar"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useEffect, useState } from "react";
import { adminStatsService } from "@/core/admin/services/AdminStatsService";
import { TrendIndicator, TrendData } from "../components/TrendIndicator";
import {
  Building2,
  Wrench,
  Tag,
  Calendar,
  FileText,
  Users,
  Loader2,
  MessageSquare,
  TrendingUp,
  ArrowUpRight,
  Crown,
  AlertCircle,
  RefreshCw,
  Car,
  Navigation,
} from "lucide-react";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";
import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/shared/components/ui/chart";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  BarChart,
  Bar,
} from "recharts";
import { Badge } from "@/shared/components/ui/badge";
import { cn } from "@/shared/utils/cn";
import { useNavigate } from "react-router-dom";
import { logger } from "@/shared/utils/logger";
const statConfig: {
  key: string;
  label: string;
  icon: any;
  color: string;
  route?: string;
}[] = [
  {
    key: "businesses",
    label: "Empresas",
    icon: Building2,
    color: "bg-primary/10 text-primary",
    route: "/admin/empresas",
  },
  {
    key: "professionals",
    label: "Profissionais",
    icon: Wrench,
    color: "bg-amber-500/10 text-amber-600",
    route: "/admin/services",
  },
  {
    key: "classifieds",
    label: "Classificados",
    icon: Tag,
    color: "bg-emerald-500/10 text-emerald-600",
    route: "/admin/classificados",
  },
  {
    key: "events",
    label: "Eventos",
    icon: Calendar,
    color: "bg-violet-500/10 text-violet-600",
    route: "/admin/eventos",
  },
  {
    key: "posts",
    label: "Posts",
    icon: FileText,
    color: "bg-rose-500/10 text-rose-600",
    route: "/admin/moderacao",
  },
  {
    key: "profiles",
    label: "Usuários",
    icon: Users,
    color: "bg-sky-500/10 text-sky-600",
    route: "/admin/users",
  },
  {
    key: "comments",
    label: "Comentários",
    icon: MessageSquare,
    color: "bg-orange-500/10 text-orange-600",
    route: "/admin/moderacao",
  },
  {
    key: "drivers",
    label: "Motoristas",
    icon: Car,
    color: "bg-blue-500/10 text-blue-600",
    route: "/admin/motoristas",
  },
  {
    key: "ride_requests",
    label: "Corridas",
    icon: Navigation,
    color: "bg-indigo-500/10 text-indigo-600",
    route: "/admin/analytics-mobilidade",
  },
];

const chartConfig = {
  posts: { label: "Posts", color: "hsl(var(--destructive))" },
  users: { label: "Usuários", color: "hsl(var(--primary))" },
  businesses: { label: "Empresas", color: "hsl(45 93% 47%)" },
  eventos: { label: "Eventos", color: "hsl(262 83% 58%)" },
  classificados: { label: "Classificados", color: "hsl(160 60% 45%)" },
};

const activityIcons: Record<string, { icon: any; color: string }> = {
  post: { icon: FileText, color: "text-rose-500" },
  business: { icon: Building2, color: "text-primary" },
  event: { icon: Calendar, color: "text-violet-500" },
  classified: { icon: Tag, color: "text-emerald-500" },
  user: { icon: Users, color: "text-sky-500" },
  service: { icon: Wrench, color: "text-amber-500" },
  comment: { icon: MessageSquare, color: "text-orange-500" },
};

export default function AdminDashboard() {
  const [stats, setStats] = useState<Record<string, number>>({});
  const [trends, setTrends] = useState<Record<string, TrendData>>({});
  const [activity, setActivity] = useState<any[]>([]);
  const [recent, setRecent] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [days, setDays] = useState(30);
  const [premiumStats, setPremiumStats] = useState({ total: 0, percentage: 0 });
  const navigate = useNavigate();

  const loadData = async () => {
    setLoading(true);
    setError(null);

    try {
      // ✅ SSOT AAA - Usa AdminStatsService diretamente
      const [activityData, recentData, statsWithTrends] = await Promise.all([
        adminStatsService.getActivity(days),
        adminStatsService.getRecentActivity(10),
        adminStatsService.getTableStatsWithTrends(days),
      ]);

      setStats(statsWithTrends.stats);
      setTrends(
        Object.entries(statsWithTrends.trends).reduce((acc, [key, trend]) => {
          acc[key] = {
            ...trend,
            period: days === 7 ? "vs semana passada" : days === 30 ? "vs mês passado" : "vs período anterior",
          };
          return acc;
        }, {} as Record<string, TrendData>)
      );
      setActivity(activityData);
      setRecent(Array.isArray(recentData) ? recentData : []);

      // Buscar estatísticas premium
      const totalBusinesses = statsWithTrends.stats.businesses || 0;
      const premiumData = await adminStatsService.getPremiumBusinessStats(totalBusinesses);
      setPremiumStats(premiumData);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : "Erro desconhecido";
      setError(errorMessage);
      logger.error("Erro ao carregar dados do dashboard", err as Error, {
        component: "AdminDashboard",
        action: "loadData",
        days,
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [days]);

  const formatDate = (d: string) => {
    const [, m, day] = d.split("-");
    return `${day}/${m}`;
  };

  const formatRelative = (dateStr: string) => {
    const diff = Date.now() - new Date(dateStr).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 1) return "agora";
    if (mins < 60) return `${mins}min`;
    const hrs = Math.floor(mins / 60);
    if (hrs < 24) return `${hrs}h`;
    return `${Math.floor(hrs / 24)}d`;
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-4">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
        <p className="text-sm text-muted-foreground">Carregando dashboard...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-col items-center justify-center py-20 space-y-4">
        <div className="rounded-full bg-destructive/10 p-4">
          <AlertCircle className="h-8 w-8 text-destructive" />
        </div>
        <div className="text-center space-y-2">
          <h3 className="font-semibold text-lg">Erro ao carregar dados</h3>
          <p className="text-sm text-muted-foreground max-w-md">{error}</p>
          <button
            onClick={loadData}
            className="inline-flex items-center gap-2 px-4 py-2 bg-primary text-primary-foreground rounded-lg hover:bg-primary/90 transition-colors mt-4"
          >
            <RefreshCw className="h-4 w-4" />
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  const totalRecords = Object.values(stats).reduce((a, b) => a + b, 0);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="text-2xl font-bold font-display mb-0.5">Dashboard Administrativo</h1>
          <p className="text-sm text-muted-foreground">
            Visão geral da plataforma ·{" "}
            <span className="font-medium text-foreground">{totalRecords.toLocaleString('pt-BR')}</span>{" "}
            registros totais
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-muted-foreground mr-1">Período:</span>
          <div className="flex gap-1 bg-muted rounded-lg p-0.5">
            {[7, 30, 90].map((d) => (
              <button
                key={d}
                onClick={() => setDays(d)}
                aria-label={`Filtrar por ${d} dias`}
                aria-pressed={days === d}
                className={cn(
                  "px-3 py-1 rounded-md text-xs font-medium transition-colors",
                  days === d
                    ? "bg-card text-foreground shadow-sm"
                    : "text-muted-foreground hover:text-foreground hover:bg-card/50",
                )}
              >
                {d}d
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3">
        {statConfig.map((s) => (
          <button
            key={s.key}
            onClick={() => s.route && navigate(s.route)}
            aria-label={`Ver detalhes de ${s.label}`}
            className="bg-card rounded-xl border p-4 text-left hover:shadow-lg hover:border-primary/20 transition-all group focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2"
          >
            <div className="flex items-center justify-between mb-2">
              <div
                className={cn(
                  "h-9 w-9 rounded-lg flex items-center justify-center transition-transform group-hover:scale-110",
                  s.color,
                )}
              >
                <s.icon className="h-4 w-4" />
              </div>
              <ArrowUpRight className="h-3.5 w-3.5 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>
            <p className="text-2xl font-bold mb-0.5">{(stats[s.key] ?? 0).toLocaleString('pt-BR')}</p>
            <span className="text-xs text-muted-foreground">{s.label}</span>
            {trends[s.key] && (
              <div className="mt-2">
                <TrendIndicator trend={trends[s.key]} size="sm" />
              </div>
            )}
          </button>
        ))}

        {/* Card Premium Stats */}
        <button
          onClick={() => navigate("/admin/empresas")}
          aria-label="Ver empresas premium"
          className="bg-gradient-to-br from-amber-500/10 to-orange-500/10 rounded-xl border border-amber-500/20 p-4 text-left hover:shadow-lg hover:border-amber-500/40 transition-all group focus:outline-none focus:ring-2 focus:ring-amber-500 focus:ring-offset-2"
        >
          <div className="flex items-center justify-between mb-2">
            <div className="h-9 w-9 rounded-lg flex items-center justify-center bg-gradient-to-br from-amber-500 to-orange-500 text-white transition-transform group-hover:scale-110">
              <Crown className="h-4 w-4" />
            </div>
            <Badge className="bg-amber-500/20 text-amber-700 border-0 text-[10px] font-semibold">
              {premiumStats.percentage}%
            </Badge>
          </div>
          <p className="text-2xl font-bold text-amber-700 mb-0.5">
            {premiumStats.total.toLocaleString('pt-BR')}
          </p>
          <span className="text-xs text-amber-600/80">Empresas Premium</span>
        </button>
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        {/* Charts - takes 2 cols */}
        <div className="lg:col-span-2 space-y-6">
          {/* Area Chart */}
          <Card>
            <CardHeader className="pb-2">
              <div className="flex items-center gap-2">
                <TrendingUp className="h-4 w-4 text-muted-foreground" />
                <CardTitle className="text-sm font-medium">Atividade</CardTitle>
              </div>
            </CardHeader>
            <CardContent>
              <ChartContainer config={chartConfig} className="h-[260px] w-full">
                <AreaChart
                  data={activity}
                  margin={{ top: 5, right: 10, left: -20, bottom: 0 }}
                >
                  <defs>
                    <linearGradient id="fillPosts" x1="0" y1="0" x2="0" y2="1">
                      <stop
                        offset="5%"
                        stopColor="hsl(var(--destructive))"
                        stopOpacity={0.3}
                      />
                      <stop
                        offset="95%"
                        stopColor="hsl(var(--destructive))"
                        stopOpacity={0}
                      />
                    </linearGradient>
                    <linearGradient
                      id="fillUsuarios"
                      x1="0"
                      y1="0"
                      x2="0"
                      y2="1"
                    >
                      <stop
                        offset="5%"
                        stopColor="hsl(var(--primary))"
                        stopOpacity={0.3}
                      />
                      <stop
                        offset="95%"
                        stopColor="hsl(var(--primary))"
                        stopOpacity={0}
                      />
                    </linearGradient>
                  </defs>
                  <CartesianGrid
                    strokeDasharray="3 3"
                    className="stroke-border/50"
                  />
                  <XAxis
                    dataKey="date"
                    tickFormatter={formatDate}
                    tick={{ fontSize: 10 }}
                    interval="preserveStartEnd"
                  />
                  <YAxis allowDecimals={false} tick={{ fontSize: 10 }} />
                  <ChartTooltip
                    content={
                      <ChartTooltipContent
                        labelFormatter={(v) => formatDate(v as string)}
                      />
                    }
                  />
                  <Area
                    type="monotone"
                    dataKey="posts"
                    stroke="hsl(var(--destructive))"
                    fill="url(#fillPosts)"
                    strokeWidth={2}
                  />
                  <Area
                    type="monotone"
                    dataKey="users"
                    stroke="hsl(var(--primary))"
                    fill="url(#fillUsuarios)"
                    strokeWidth={2}
                  />
                </AreaChart>
              </ChartContainer>
            </CardContent>
          </Card>

          {/* Bar Chart */}
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium">
                Cadastros por tipo
              </CardTitle>
            </CardHeader>
            <CardContent>
              <ChartContainer config={chartConfig} className="h-[220px] w-full">
                <BarChart
                  data={activity}
                  margin={{ top: 5, right: 10, left: -20, bottom: 0 }}
                >
                  <CartesianGrid
                    strokeDasharray="3 3"
                    className="stroke-border/50"
                  />
                  <XAxis
                    dataKey="date"
                    tickFormatter={formatDate}
                    tick={{ fontSize: 10 }}
                    interval="preserveStartEnd"
                  />
                  <YAxis allowDecimals={false} tick={{ fontSize: 10 }} />
                  <ChartTooltip
                    content={
                      <ChartTooltipContent
                        labelFormatter={(v) => formatDate(v as string)}
                      />
                    }
                  />
                  <Bar
                    dataKey="businesses"
                    fill="hsl(45 93% 47%)"
                    radius={[3, 3, 0, 0]}
                  />
                  <Bar
                    dataKey="eventos"
                    fill="hsl(262 83% 58%)"
                    radius={[3, 3, 0, 0]}
                  />
                  <Bar
                    dataKey="classificados"
                    fill="hsl(160 60% 45%)"
                    radius={[3, 3, 0, 0]}
                  />
                </BarChart>
              </ChartContainer>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar */}
        <div className="lg:col-span-1 space-y-6">
          {/* Resumo Rápido */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium flex items-center gap-2">
                <TrendingUp className="h-4 w-4 text-primary" />
                Resumo Rápido
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="flex items-center justify-between p-3 bg-primary/5 rounded-lg">
                <div className="flex items-center gap-2">
                  <Users className="h-4 w-4 text-primary" />
                  <span className="text-sm font-medium">Total Usuários</span>
                </div>
                <span className="text-lg font-bold text-primary">
                  {(stats.profiles ?? 0).toLocaleString('pt-BR')}
                </span>
              </div>
              
              <div className="flex items-center justify-between p-3 bg-amber-500/5 rounded-lg">
                <div className="flex items-center gap-2">
                  <Building2 className="h-4 w-4 text-amber-600" />
                  <span className="text-sm font-medium">Empresas</span>
                </div>
                <span className="text-lg font-bold text-amber-600">
                  {(stats.businesses ?? 0).toLocaleString('pt-BR')}
                </span>
              </div>

              <div className="flex items-center justify-between p-3 bg-rose-500/5 rounded-lg">
                <div className="flex items-center gap-2">
                  <FileText className="h-4 w-4 text-rose-600" />
                  <span className="text-sm font-medium">Posts</span>
                </div>
                <span className="text-lg font-bold text-rose-600">
                  {(stats.posts ?? 0).toLocaleString('pt-BR')}
                </span>
              </div>
            </CardContent>
          </Card>

          {/* Recent Activity Feed */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium">
                Atividade recente
              </CardTitle>
            </CardHeader>
            <CardContent className="px-4">
              {recent.length === 0 ? (
                <div className="text-center py-8">
                  <div className="rounded-full bg-muted w-12 h-12 flex items-center justify-center mx-auto mb-3">
                    <MessageSquare className="h-5 w-5 text-muted-foreground" />
                  </div>
                  <p className="text-sm text-muted-foreground">
                    Nenhuma atividade recente
                  </p>
                </div>
              ) : (
                <div className="space-y-3">
                  {recent.map((item, i) => {
                    const config =
                      activityIcons[item.type] || activityIcons.post;
                    const Icon = config.icon;
                    return (
                      <div key={i} className="flex items-start gap-3 p-2 rounded-lg hover:bg-muted/50 transition-colors">
                        <div
                          className={cn(
                            "mt-0.5 h-7 w-7 rounded-full flex items-center justify-center bg-muted shrink-0",
                            config.color,
                          )}
                        >
                          <Icon className="h-3.5 w-3.5" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-xs leading-relaxed line-clamp-2">
                            {item.label}
                          </p>
                          <span className="text-[10px] text-muted-foreground">
                            {formatRelative(item.date)}
                          </span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

/**
 * AdminDashboardPage — Dashboard administrativo
 *
 * Visão geral da plataforma.
 * Consome hooks (SSOT).
 */

import { Card, CardContent, CardHeader, CardTitle } from '@/shared/components/ui/card';
import { usePlatformStats } from '@/modules/admin/hooks/useAdmin';
import { Building2, Users, ShoppingCart, DollarSign, Bike, TrendingUp } from 'lucide-react';
import { Skeleton } from '@/shared/components/ui/skeleton';

export function AdminDashboardPage() {
  const { data: stats, isLoading } = usePlatformStats();

  if (isLoading) {
    return (
      <div className="container mx-auto p-6 space-y-6">
        <h1 className="text-3xl font-bold">Dashboard Administrativo</h1>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[...Array(6)].map((_, i) => (
            <Skeleton key={i} className="h-32" />
          ))}
        </div>
      </div>
    );
  }

  if (!stats) {
    return (
      <div className="container mx-auto p-6">
        <p className="text-muted-foreground">Erro ao carregar estatísticas</p>
      </div>
    );
  }

  const mainStats = [
    {
      icon: Building2,
      label: 'Total de Empresas',
      value: stats.total_businesses,
      subValue: `${stats.active_businesses} ativas`,
      color: 'text-blue-600',
      bgColor: 'bg-blue-100',
    },
    {
      icon: Users,
      label: 'Total de Usuários',
      value: stats.total_users,
      color: 'text-purple-600',
      bgColor: 'bg-purple-100',
    },
    {
      icon: ShoppingCart,
      label: 'Pedidos Concluídos',
      value: stats.total_orders,
      color: 'text-green-600',
      bgColor: 'bg-green-100',
    },
    {
      icon: DollarSign,
      label: 'Receita Total',
      value: `R$ ${stats.total_revenue.toFixed(2)}`,
      color: 'text-emerald-600',
      bgColor: 'bg-emerald-100',
    },
    {
      icon: Bike,
      label: 'Entregas Concluídas',
      value: stats.total_deliveries,
      color: 'text-indigo-600',
      bgColor: 'bg-indigo-100',
    },
    {
      icon: TrendingUp,
      label: 'Taxa de Ativação',
      value: `${((stats.active_businesses / stats.total_businesses) * 100).toFixed(1)}%`,
      subValue: 'empresas ativas',
      color: 'text-orange-600',
      bgColor: 'bg-orange-100',
    },
  ];

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold">Dashboard Administrativo</h1>
        <p className="text-muted-foreground">
          Visão geral da plataforma
        </p>
      </div>

      {/* Estatísticas Principais */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {mainStats.map((stat) => {
          const Icon = stat.icon;
          return (
            <Card key={stat.label}>
              <CardContent className="pt-6">
                <div className="flex items-start gap-4">
                  <div className={`p-3 rounded-lg ${stat.bgColor}`}>
                    <Icon className={`h-6 w-6 ${stat.color}`} />
                  </div>
                  <div className="flex-1">
                    <p className="text-sm text-muted-foreground">{stat.label}</p>
                    <p className="text-2xl font-bold mt-1">{stat.value}</p>
                    {stat.subValue && (
                      <p className="text-xs text-muted-foreground mt-1">
                        {stat.subValue}
                      </p>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Distribuição de Planos */}
      <Card>
        <CardHeader>
          <CardTitle>Distribuição de Planos</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {Object.entries(stats.plan_distribution).map(([plan, count]) => {
              const percentage = (count / stats.total_businesses) * 100;
              const planLabels: Record<string, string> = {
                free: 'Free',
                pro: 'Pro',
                delivery: 'Delivery',
              };

              return (
                <div key={plan}>
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium">
                      {planLabels[plan] || plan}
                    </span>
                    <span className="text-sm text-muted-foreground">
                      {count} empresas ({percentage.toFixed(1)}%)
                    </span>
                  </div>
                  <div className="w-full bg-muted rounded-full h-2">
                    <div
                      className="bg-primary h-2 rounded-full transition-all"
                      style={{ width: `${percentage}%` }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </CardContent>
      </Card>

      {/* Insights */}
      <Card>
        <CardHeader>
          <CardTitle>💡 Insights</CardTitle>
        </CardHeader>
        <CardContent className="space-y-2 text-sm text-muted-foreground">
          <p>
            • Ticket médio: R${' '}
            {stats.total_orders > 0
              ? (stats.total_revenue / stats.total_orders).toFixed(2)
              : '0.00'}
          </p>
          <p>
            • Pedidos por empresa ativa:{' '}
            {stats.active_businesses > 0
              ? (stats.total_orders / stats.active_businesses).toFixed(1)
              : '0'}
          </p>
          <p>
            • Taxa de entrega:{' '}
            {stats.total_orders > 0
              ? ((stats.total_deliveries / stats.total_orders) * 100).toFixed(1)
              : '0'}
            % dos pedidos
          </p>
        </CardContent>
      </Card>
    </div>
  );
}

export default AdminDashboardPage;

/**
 * AdminMotoboyOperations — Console operacional de entregas motoboy
 *
 * Superfície admin para:
 * - Fila operacional de entregas (ride_requests com ride_mode='motoboy')
 * - Filtros por status, território, source_type, motoboy, SLA
 * - Ações: cancelar operacional, reencaminhar dispatch, bloquear
 * - Painel de saúde (SLA, tempo médio aceite, taxa falha/cancelamento)
 *
 * SSOT: ride_requests (ride_mode='motoboy')
 */

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  AdminPageHeader,
  AdminSectionCard,
  AdminStatsCard,
  AdminStatsGrid,
  AdminTable,
  AdminDataState,
  AdminErrorState,
} from "@/modules/admin/components";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/shared/components/ui/select";
import {
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/shared/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/components/ui/alert-dialog";
import { useToast } from "@/shared/hooks/use-toast";
import { useAdminGuard } from "@/modules/admin/hooks/useAdminGuard";
import { logger } from "@/shared/utils/logger";
import { AdminMotoboyOperationsService } from "@/core/admin/services/AdminMotoboyOperationsService";
import {
  Package,
  RefreshCw,
  AlertTriangle,
  Clock,
  CheckCircle2,
  XCircle,
  Loader2,
  Search,
  Filter,
} from "lucide-react";

// ============================================
// TIPOS
// ============================================

interface MotoboyDelivery {
  id: string;
  status: string;
  source_type: string | null;
  source_id: string | null;
  recipient_name: string | null;
  package_size: string | null;
  suggested_price: number | null;
  created_at: string;
  updated_at: string;
  driver_profile_id: string | null;
  pickup_location_id: string | null;
  delivery_notes: string | null;
  failed_delivery_reason: string | null;
}

interface OperationalStats {
  total: number;
  pending: number;
  active: number;
  completed: number;
  failed: number;
  cancelled: number;
  avgAcceptTimeMinutes: number | null;
  failureRate: number;
}

type StatusFilter =
  | "all"
  | "searching_driver"
  | "driver_assigned"
  | "driver_accepted"
  | "pickup_confirmed"
  | "in_delivery"
  | "delivered"
  | "completed"
  | "failed_delivery"
  | "cancelled_by_passenger"
  | "cancelled_by_driver";

type SourceTypeFilter = "all" | "passenger" | "business" | "gastronomy" | "service";

// ============================================
// HELPERS
// ============================================

function statusBadge(status: string) {
  const map: Record<string, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
    searching_driver: { label: "Buscando motoboy", variant: "secondary" },
    driver_assigned: { label: "Motoboy atribuído", variant: "secondary" },
    driver_accepted: { label: "Motoboy a caminho", variant: "default" },
    pickup_confirmed: { label: "Coleta confirmada", variant: "default" },
    in_delivery: { label: "Em entrega", variant: "default" },
    delivered: { label: "Entregue", variant: "default" },
    completed: { label: "Concluída", variant: "default" },
    failed_delivery: { label: "Falha na entrega", variant: "destructive" },
    cancelled_by_passenger: { label: "Cancelada (solicitante)", variant: "outline" },
    cancelled_by_driver: { label: "Cancelada (motoboy)", variant: "outline" },
  };
  const config = map[status] ?? { label: status, variant: "outline" as const };
  return <Badge variant={config.variant}>{config.label}</Badge>;
}

function sourceTypeBadge(sourceType: string | null) {
  const map: Record<string, string> = {
    passenger: "Passageiro",
    business: "Empresa",
    gastronomy: "Gastronomia",
    service: "Serviço",
  };
  return (
    <Badge variant="outline" className="text-xs">
      {map[sourceType ?? ""] ?? sourceType ?? "—"}
    </Badge>
  );
}

function slaMinutes(createdAt: string): number {
  return Math.floor((Date.now() - new Date(createdAt).getTime()) / 60000);
}

function slaBadge(minutes: number, status: string) {
  const isActive = !["completed", "failed_delivery", "cancelled_by_passenger", "cancelled_by_driver"].includes(status);
  if (!isActive) return null;
  if (minutes > 30) return <Badge variant="destructive" className="text-xs">{minutes}min</Badge>;
  if (minutes > 15) return <Badge variant="secondary" className="text-xs">{minutes}min</Badge>;
  return <Badge variant="outline" className="text-xs">{minutes}min</Badge>;
}

// ============================================
// COMPONENTE PRINCIPAL
// ============================================

export default function AdminMotoboyOperations() {
  const { canModerate, isChecking } = useAdminGuard();
  const { toast } = useToast();

  const [deliveries, setDeliveries] = useState<MotoboyDelivery[]>([]);
  const [stats, setStats] = useState<OperationalStats | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [pageError, setPageError] = useState<string | null>(null);

  // Filtros
  const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
  const [sourceTypeFilter, setSourceTypeFilter] = useState<SourceTypeFilter>("all");
  const [searchQuery, setSearchQuery] = useState("");

  // Ação de cancelamento
  const [cancelDialogOpen, setCancelDialogOpen] = useState(false);
  const [selectedDeliveryId, setSelectedDeliveryId] = useState<string | null>(null);
  const [cancelReason, setCancelReason] = useState("");
  const [isCancelling, setIsCancelling] = useState(false);

  // ── Carregar dados ──────────────────────────────────────────────────────────

  const loadDeliveries = useCallback(async () => {
    try {
      const data = await AdminMotoboyOperationsService.listDeliveries({
        status: statusFilter,
        sourceType: sourceTypeFilter,
      });
      setDeliveries((data as MotoboyDelivery[]) || []);
    } catch (error) {
      logger.error("AdminMotoboyOperations.loadDeliveries", error as Error);
      setPageError("Erro ao carregar entregas.");
    }
  }, [statusFilter, sourceTypeFilter]);

  const loadStats = useCallback(async () => {
    try {
      const rows = await AdminMotoboyOperationsService.listStatsRows();

      const total = rows.length;
      const pending = rows.filter((r) =>
        ["searching_driver", "driver_assigned"].includes(r.status),
      ).length;
      const active = rows.filter((r) =>
        ["driver_accepted", "pickup_confirmed", "in_delivery"].includes(r.status),
      ).length;
      const completed = rows.filter((r) => r.status === "completed").length;
      const failed = rows.filter((r) => r.status === "failed_delivery").length;
      const cancelled = rows.filter((r) =>
        ["cancelled_by_passenger", "cancelled_by_driver"].includes(r.status),
      ).length;

      const failureRate = total > 0 ? Math.round((failed / total) * 100) : 0;

      setStats({
        total,
        pending,
        active,
        completed,
        failed,
        cancelled,
        avgAcceptTimeMinutes: null, // Calculado via audit quando disponível
        failureRate,
      });
    } catch (error) {
      logger.error("AdminMotoboyOperations.loadStats", error as Error);
    }
  }, []);

  const refresh = useCallback(
    async (silent = false) => {
      if (!silent) setIsRefreshing(true);
      await Promise.all([loadDeliveries(), loadStats()]);
      if (!silent) setIsRefreshing(false);
    },
    [loadDeliveries, loadStats],
  );

  useEffect(() => {
    if (!canModerate || isChecking) return;
    setIsLoading(true);
    Promise.all([loadDeliveries(), loadStats()]).finally(() => setIsLoading(false));
  }, [canModerate, isChecking, loadDeliveries, loadStats]);

  // ── Filtro local por busca ──────────────────────────────────────────────────

  const filteredDeliveries = useMemo(() => {
    if (!searchQuery.trim()) return deliveries;
    const q = searchQuery.toLowerCase();
    return deliveries.filter(
      (d) =>
        d.id.toLowerCase().includes(q) ||
        d.recipient_name?.toLowerCase().includes(q) ||
        d.source_id?.toLowerCase().includes(q) ||
        d.driver_profile_id?.toLowerCase().includes(q),
    );
  }, [deliveries, searchQuery]);

  // ── Ação: cancelar operacional ──────────────────────────────────────────────

  const handleCancelClick = (id: string) => {
    setSelectedDeliveryId(id);
    setCancelReason("");
    setCancelDialogOpen(true);
  };

  const handleCancelConfirm = async () => {
    if (!selectedDeliveryId) return;
    setIsCancelling(true);

    try {
      const usedStateMachine = await AdminMotoboyOperationsService.cancelOperational(
        selectedDeliveryId,
        cancelReason || "Cancelamento operacional pelo admin",
      );

      if (usedStateMachine) {
        toast({ title: "Entrega cancelada", description: "Cancelamento operacional registrado." });
      } else {
        toast({ title: "Entrega cancelada (override)", description: "Status forçado pelo admin." });
      }
      await refresh(true);
    } catch (error) {
      logger.error("AdminMotoboyOperations.handleCancelConfirm", error as Error);
      toast({ title: "Erro", description: "Não foi possível cancelar a entrega.", variant: "destructive" });
    } finally {
      setIsCancelling(false);
      setCancelDialogOpen(false);
      setSelectedDeliveryId(null);
    }
  };

  // ── Ação: reencaminhar dispatch ─────────────────────────────────────────────

  const handleRedispatch = async (deliveryId: string) => {
    try {
      await AdminMotoboyOperationsService.redispatch(deliveryId);

      toast({ title: "Reencaminhado", description: "Entrega voltou para fila de dispatch." });
      await refresh(true);
    } catch (error) {
      logger.error("AdminMotoboyOperations.handleRedispatch", error as Error);
      toast({ title: "Erro", description: "Não foi possível reencaminhar.", variant: "destructive" });
    }
  };

  // ── Guards ──────────────────────────────────────────────────────────────────

  if (isChecking) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!canModerate) {
    return <AdminErrorState description="Acesso restrito a administradores." />;
  }

  if (pageError) {
    return <AdminErrorState description={pageError} />;
  }

  // ── Render ──────────────────────────────────────────────────────────────────

  return (
    <div className="space-y-6">
      <AdminPageHeader
        title="Operações Motoboy"
        description="Console operacional de entregas via rede de motoboys"
        actions={
          <Button
            variant="outline"
            size="sm"
            onClick={() => refresh()}
            disabled={isRefreshing}
            className="gap-2"
          >
            <RefreshCw className={`h-4 w-4 ${isRefreshing ? "animate-spin" : ""}`} />
            Atualizar
          </Button>
        }
      />

      {/* Stats */}
      {stats && (
        <AdminStatsGrid>
          <AdminStatsCard
            title="Total"
            value={stats.total}
            icon={Package}
          />
          <AdminStatsCard
            title="Aguardando"
            value={stats.pending}
            icon={Clock}
            iconColor={stats.pending > 10 ? "text-orange-500" : "text-primary"}
          />
          <AdminStatsCard
            title="Em andamento"
            value={stats.active}
            icon={RefreshCw}
          />
          <AdminStatsCard
            title="Concluídas"
            value={stats.completed}
            icon={CheckCircle2}
            iconColor="text-green-600"
          />
          <AdminStatsCard
            title="Falhas"
            value={stats.failed}
            icon={XCircle}
            iconColor={stats.failed > 0 ? "text-orange-500" : "text-primary"}
          />
          <AdminStatsCard
            title="Taxa de falha"
            value={`${stats.failureRate}%`}
            icon={AlertTriangle}
            iconColor={stats.failureRate > 10 ? "text-orange-500" : "text-primary"}
          />
        </AdminStatsGrid>
      )}

      {/* Filtros */}
      <AdminSectionCard title="Filtros">
        <div className="flex flex-wrap gap-3">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Buscar por ID, destinatário, motoboy..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9"
            />
          </div>

          <Select value={statusFilter} onValueChange={(v) => setStatusFilter(v as StatusFilter)}>
            <SelectTrigger className="w-[200px]">
              <Filter className="h-4 w-4 mr-2" />
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todos os status</SelectItem>
              <SelectItem value="searching_driver">Buscando motoboy</SelectItem>
              <SelectItem value="driver_assigned">Motoboy atribuído</SelectItem>
              <SelectItem value="driver_accepted">Motoboy a caminho</SelectItem>
              <SelectItem value="pickup_confirmed">Coleta confirmada</SelectItem>
              <SelectItem value="in_delivery">Em entrega</SelectItem>
              <SelectItem value="completed">Concluída</SelectItem>
              <SelectItem value="failed_delivery">Falha na entrega</SelectItem>
              <SelectItem value="cancelled_by_passenger">Cancelada (solicitante)</SelectItem>
              <SelectItem value="cancelled_by_driver">Cancelada (motoboy)</SelectItem>
            </SelectContent>
          </Select>

          <Select
            value={sourceTypeFilter}
            onValueChange={(v) => setSourceTypeFilter(v as SourceTypeFilter)}
          >
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Origem" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todas as origens</SelectItem>
              <SelectItem value="passenger">Passageiro</SelectItem>
              <SelectItem value="business">Empresa</SelectItem>
              <SelectItem value="gastronomy">Gastronomia</SelectItem>
              <SelectItem value="service">Serviço</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </AdminSectionCard>

      {/* Tabela operacional */}
      <AdminSectionCard
        title={`Entregas (${filteredDeliveries.length})`}
        description="Clique em uma ação para intervir operacionalmente"
      >
        {isLoading ? (
          <AdminDataState loading emptyTitle="">
            <></>
          </AdminDataState>
        ) : filteredDeliveries.length === 0 ? (
          <AdminDataState isEmpty emptyTitle="Nenhuma entrega encontrada" emptyDescription="Nenhuma entrega encontrada com os filtros aplicados.">
            <></>
          </AdminDataState>
        ) : (
          <AdminTable>
            <TableHeader>
              <TableRow>
                <TableHead>ID</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Origem</TableHead>
                <TableHead>Destinatário</TableHead>
                <TableHead>Pacote</TableHead>
                <TableHead>Valor</TableHead>
                <TableHead>SLA</TableHead>
                <TableHead>Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredDeliveries.map((delivery) => {
                const sla = slaMinutes(delivery.created_at);
                const isActive = !["completed", "failed_delivery", "cancelled_by_passenger", "cancelled_by_driver"].includes(delivery.status);
                const canRedispatch = ["driver_assigned", "driver_accepted"].includes(delivery.status);

                return (
                  <TableRow key={delivery.id}>
                    <TableCell className="font-mono text-xs">
                      {delivery.id.slice(0, 8)}…
                    </TableCell>
                    <TableCell>{statusBadge(delivery.status)}</TableCell>
                    <TableCell>{sourceTypeBadge(delivery.source_type)}</TableCell>
                    <TableCell className="max-w-[120px] truncate">
                      {delivery.recipient_name ?? "—"}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className="text-xs capitalize">
                        {delivery.package_size ?? "—"}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {delivery.suggested_price != null
                        ? `R$ ${delivery.suggested_price.toFixed(2)}`
                        : "—"}
                    </TableCell>
                    <TableCell>{slaBadge(sla, delivery.status) ?? <span className="text-xs text-muted-foreground">{sla}min</span>}</TableCell>
                    <TableCell>
                      <div className="flex gap-2">
                        {isActive && (
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => handleCancelClick(delivery.id)}
                          >
                            Cancelar
                          </Button>
                        )}
                        {canRedispatch && (
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleRedispatch(delivery.id)}
                          >
                            Reencaminhar
                          </Button>
                        )}
                        {!isActive && !canRedispatch && (
                          <span className="text-xs text-muted-foreground">—</span>
                        )}
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </AdminTable>
        )}
      </AdminSectionCard>

      {/* Dialog de cancelamento operacional */}
      <AlertDialog open={cancelDialogOpen} onOpenChange={setCancelDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancelar Entrega (Admin)</AlertDialogTitle>
            <AlertDialogDescription>
              Esta ação cancela a entrega operacionalmente e registra auditoria. Informe o motivo.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="py-4">
            <Input
              placeholder="Motivo do cancelamento operacional"
              value={cancelReason}
              onChange={(e) => setCancelReason(e.target.value)}
            />
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isCancelling}>Voltar</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleCancelConfirm}
              disabled={isCancelling}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isCancelling ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              Confirmar Cancelamento
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

