        <div>
          <h2 className="text-2xl font-bold">Cupons e Promoções</h2>
          <p className="text-muted-foreground">
            Crie cupons para atrair e fidelizar clientes
          </p>
        </div>

        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
          <DialogTrigger asChild>
            <Button onClick={() => resetForm()} disabled={!podeAdicionar}>
              <Plus className="h-4 w-4 mr-2" />
              Novo Cupom
            </Button>
          </DialogTrigger>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>
                {editingCoupon ? "Editar Cupom" : "Criar Novo Cupom"}
              </DialogTitle>
            </DialogHeader>
            <DialogDescription className="sr-only">
              Gerenciar cupons de desconto
            </DialogDescription>

            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Código do Cupom *</Label>
                  <Input
                    placeholder="Ex: BEMVINDO20"
                    value={formData.codigo}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        codigo: e.target.value.toUpperCase(),
                      })
                    }
                  />
                </div>
                <div>
                  <Label>Tipo de Desconto *</Label>
                  <Select
                    value={formData.tipo}
                    onValueChange={(v: string) =>
                      setFormData({ ...formData, tipo: v })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="porcentagem">
                        Porcentagem (%)
                      </SelectItem>
                      <SelectItem value="valor">Valor Fixo (R$)</SelectItem>
                      <SelectItem value="brinde">Brinde/Benefício</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div>
                <Label>Título do Cupom *</Label>
                <Input
                  placeholder="Ex: 20% OFF na primeira compra"
                  value={formData.titulo}
                  onChange={(e) =>
                    setFormData({ ...formData, titulo: e.target.value })
                  }
                />
              </div>

              <div>
                <Label>Descrição</Label>
                <Textarea
                  placeholder="Descreva as condições do cupom..."
                  value={formData.description}
                  onChange={(e) =>
                    setFormData({ ...formData, description: e.target.value })
                  }
                  rows={3}
                />
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div>
                  <Label>Desconto *</Label>
                  <Input
                    placeholder={
                      formData.tipo === "porcentagem"
                        ? "20"
                        : formData.tipo === "valor"
                          ? "50.00"
                          : "Frete grátis"
                    }
                    value={formData.desconto}
                    onChange={(e) =>
                      setFormData({ ...formData, desconto: e.target.value })
                    }
                  />
                </div>
                <div>
                  <Label>Validade *</Label>
                  <Input
                    type="date"
                    value={formData.validade}
                    onChange={(e) =>
                      setFormData({ ...formData, validade: e.target.value })
                    }
                  />
                </div>
                <div>
                  <Label>Máx. Usos</Label>
                  <Input
                    type="number"
                    value={formData.maxUsos}
                    onChange={(e) =>
                      setFormData({ ...formData, maxUsos: e.target.value })
                    }
                  />
                </div>
              </div>

              <div className="flex gap-2 justify-end">
                <Button variant="outline" onClick={() => setDialogOpen(false)}>
                  Cancelar
                </Button>
                <Button onClick={handleSubmit}>
                  {editingCoupon ? "Atualizar" : "Criar Cupom"}
                </Button>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      </div>

      {/* Limite do Plano */}
      {limite !== -1 && (
        <Card className="p-4 bg-blue-50 border-blue-200">
          <p className="text-sm text-blue-900">
            <strong>
              Plano{" "}
              {planType === SUBSCRIPTION_PLAN.BASICO
                ? "Básico"
                : "Profissional"}
              :
            </strong>{" "}
            Você pode ter até {limite} cupom(ns) active(s).
            {cuponsAtivos >= limite && " Faça upgrade para create mais cupons!"}
          </p>
        </Card>
      )}

      {/* Lista de Cupons */}
      <div className="grid md:grid-cols-2 gap-4">
        {cupons
          .filter((c) => c.active)
          .map((cupom) => {
            const Icon = getTipoIcon(cupom.tipo);
            const percentualUso = (cupom.usos / cupom.maxUsos) * 100;

            return (
              <Card key={cupom.id} className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <div className="flex items-center gap-3">
                    <div
                      className={`p-2 rounded-lg ${getTipoColor(cupom.tipo)}`}
                    >
                      <Icon className="h-5 w-5" />
                    </div>
                    <div>
                      <h3 className="font-bold">{cupom.titulo}</h3>
                      <p className="text-sm text-muted-foreground">
                        {cupom.description}
                      </p>
                    </div>
                  </div>
                  <div className="flex gap-1">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => handleEdit(cupom)}
                    >
                      <Edit className="h-4 w-4" />
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => handleDelete(cupom.id)}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>

                <div className="space-y-3">
                  <div className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                    <code className="font-mono font-bold text-lg">
                      {cupom.codigo}
                    </code>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => copiarCodigo(cupom.codigo)}
                    >
                      <Copy className="h-4 w-4 mr-1" />
                      Copiar
                    </Button>
                  </div>

                  <div className="grid grid-cols-3 gap-2 text-sm">
                    <div>
                      <p className="text-muted-foreground flex items-center gap-1">
                        <TrendingUp className="h-3 w-3" />
                        Desconto
                      </p>
                      <p className="font-bold">{cupom.desconto}</p>
                    </div>
                    <div>
                      <p className="text-muted-foreground flex items-center gap-1">
                        <Calendar className="h-3 w-3" />
                        Validade
                      </p>
                      <p className="font-bold">
                        {new Date(cupom.validade).toLocaleDateString("pt-BR")}
                      </p>
                    </div>
                    <div>
                      <p className="text-muted-foreground flex items-center gap-1">
                        <Users className="h-3 w-3" />
                        Usos
                      </p>
                      <p className="font-bold">
                        {cupom.usos}/{cupom.maxUsos}
                      </p>
                    </div>
                  </div>

                  <div>
                    <div className="flex justify-between text-xs mb-1">
                      <span className="text-muted-foreground">Progresso</span>
                      <span className="font-medium">
                        {percentualUso.toFixed(0)}%
                      </span>
                    </div>
                    <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
                      <div
                        className="h-full bg-primary transition-all"
                        style={{ width: `${percentualUso}%` }}
                      />
                    </div>
                  </div>
                </div>
              </Card>
            );
          })}
      </div>

      {cupons.filter((c) => c.active).length === 0 && (
        <Card className="p-12 text-center">
          <Gift className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
          <h3 className="font-bold mb-2">Nenhum cupom created</h3>
          <p className="text-muted-foreground mb-4">
            Crie cupons para atrair novos clientes e aumentar suas vendas
          </p>
          <Button onClick={() => setDialogOpen(true)} disabled={!podeAdicionar}>
            <Plus className="h-4 w-4 mr-2" />
            Criar Primeiro Cupom
          </Button>
        </Card>
      )}
    </div>
  );
}

import React from "react";
import { Card } from "@/shared/components/ui/card";
import { Badge } from "@/shared/components/ui/badge";
import { Button } from "@/shared/components/ui/button";
import { Sparkles, Tag, Clock, ArrowRight } from "lucide-react";
import { motion } from "framer-motion";
interface PromoBannerProps {
  title: string;
  description: string;
  discount?: string;
  validUntil?: string;
  ctaText?: string;
  onCtaClick?: () => void;
  variant?: "default" | "gradient" | "minimal";
}

export default function PromoBanner({
  title,
  description,
  discount,
  validUntil,
  ctaText = "Ver Promoção",
  onCtaClick,
  variant = "gradient",
}: PromoBannerProps) {
  const variants = {
    default: "bg-primary text-primary-foreground",
    gradient:
      "bg-gradient-to-r from-orange-500 via-red-500 to-pink-500 text-white",
    minimal: "bg-secondary border-2 border-primary",
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
      <Card
        className={`p-6 mb-6 overflow-hidden relative ${variants[variant]}`}
      >
        {/* Background Pattern */}
        <div className="absolute inset-0 opacity-10">
          <div className="absolute top-0 right-0 w-64 h-64 bg-white rounded-full -translate-y-1/2 translate-x-1/2" />
          <div className="absolute bottom-0 left-0 w-48 h-48 bg-white rounded-full translate-y-1/2 -translate-x-1/2" />
        </div>

        <div className="relative z-10 flex items-center justify-between gap-4 flex-wrap">
          <div className="flex-1 min-w-[250px]">
            <div className="flex items-center gap-2 mb-2">
              <Sparkles className="h-5 w-5 animate-pulse" />
              <Badge
                variant="secondary"
                className="bg-white/20 text-white border-white/30"
              >
                <Tag className="h-3 w-3 mr-1" />
                Promoção Especial
              </Badge>
            </div>

            <h3 className="text-2xl font-bold font-display mb-2 flex items-center gap-2">
              {title}
              {discount && (
                <span className="inline-flex items-center px-3 py-1 rounded-full bg-white/20 text-lg">
                  {discount}
                </span>
              )}
            </h3>

            <p className="text-sm opacity-90 mb-3">{description}</p>

            {validUntil && (
              <div className="flex items-center gap-2 text-xs opacity-80">
                <Clock className="h-4 w-4" />
                <span>Válido até {validUntil}</span>
              </div>
            )}
          </div>

          {onCtaClick && (
            <Button
              onClick={onCtaClick}
              size="lg"
              variant={variant === "minimal" ? "default" : "secondary"}
              className="gap-2 font-semibold shadow-lg hover:shadow-xl transition-all"
            >
              {ctaText}
              <ArrowRight className="h-4 w-4" />
            </Button>
          )}
        </div>
      </Card>
    </motion.div>
  );
}

 
import React from "react";
import { useState } from "react";
import { Card } from "@/shared/components/ui/card";
import { Label } from "@/shared/components/ui/label";
import { Switch } from "@/shared/components/ui/switch";
import { Button } from "@/shared/components/ui/button";
import {
  Save,
  Package,
  ShoppingBag,
  Award,
  Sparkles,
  Briefcase,
} from "lucide-react";
import { toast } from "sonner";
import { BusinessService } from '@/core/business';

interface SecoesConfig {
  services: boolean;
  products: boolean;
  cardapio: boolean;
  portfolio: boolean;
  promocoes: boolean;
}

interface Props {
  businessId: string;
  currentConfig: SecoesConfig;
  onSaved: (config: SecoesConfig) => void;
}

const SECOES = [
  {
    id: "services" as const,
    label: "Serviços",
    icon: Briefcase,
    description: "Lista de serviços oferecidos pela empresa",
    color: "text-blue-500",
  },
  {
    id: "products" as const,
    label: "Produtos",
    icon: Package,
    description: "Catálogo de produtos para venda",
    color: "text-green-500",
  },
  {
    id: "cardapio" as const,
    label: "Cardápio",
    icon: ShoppingBag,
    description: "Cardápio completo com pratos e bebidas",
    color: "text-orange-500",
  },
  {
    id: "portfolio" as const,
    label: "Portfólio",
    icon: Award,
    description: "Galeria de trabalhos e projetos realizados",
    color: "text-purple-500",
  },
  {
    id: "promocoes" as const,
    label: "Promoções",
    icon: Sparkles,
    description: "Ofertas e descontos especiais",
    color: "text-yellow-500",
  },
];

export default function SecoesAtivasManager({
  businessId,
  currentConfig,
  onSaved,
}: Props) {
  const [config, setConfig] = useState<SecoesConfig>(currentConfig);
  const [saving, setSaving] = useState(false);

  const toggleSecao = (secao: keyof SecoesConfig) => {
    setConfig((prev) => ({ ...prev, [secao]: !prev[secao] }));
  };

  const handleSave = async () => {
    setSaving(true);

    try {
      await BusinessService.updateActiveSections(businessId, config);
    } catch (error) {
      setSaving(false);
      toast.error("Erro ao salvar configurações");
      return;
    }
    setSaving(false);

    toast.success("Seções atualizadas com sucesso!");
    onSaved(config);
  };

  const hasChanges = JSON.stringify(config) !== JSON.stringify(currentConfig);

  return (
    <div className="space-y-4">
      <div>
        <h3 className="text-lg font-bold mb-1">Gerenciar Seções</h3>
        <p className="text-sm text-muted-foreground">
          Ative ou desative seções conforme o tipo do seu negócio
        </p>
      </div>

      <div className="space-y-3">
        {SECOES.map((secao) => {
          const Icon = secao.icon;
          const isActive = config[secao.id];

          return (
            <Card
              key={secao.id}
              className={`p-4 border-2 transition-all ${
                isActive ? "border-primary/30 bg-primary/5" : "border-border"
              }`}
            >
              <div className="flex items-start gap-3">
                <div className={`p-2 rounded-lg bg-secondary ${secao.color}`}>
                  <Icon className="h-5 w-5" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between mb-1">
                    <h4 className="font-semibold text-sm">{secao.label}</h4>
                    <Switch
                      checked={isActive}
                      onCheckedChange={() => toggleSecao(secao.id)}
                    />
                  </div>
                  <p className="text-xs text-muted-foreground">
                    {secao.description}
                  </p>
                </div>
              </div>
            </Card>
          );
        })}
      </div>

      {hasChanges && (
        <Button onClick={handleSave} disabled={saving} className="w-full gap-2">
          {saving ? (
            <>
              <div className="h-4 w-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
              Salvando...
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              Salvar Alterações
            </>
          )}
        </Button>
      )}
    </div>
  );
}

﻿import { ArrowRight, Clock3, MapPin, Phone } from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/shared/components/ui/card";
import { Checkbox } from "@/shared/components/ui/checkbox";
import { TerritorialSelector } from "@/core/location/components/TerritorialSelector";

interface DayHoursValue {
  open: string;
  close: string;
  closed?: boolean;
}

interface SelectedLocationData {
  stateId: string;
  cityId: string;
  neighborhoodId: string;
  stateName: string;
  cityName: string;
  neighborhoodName: string;
}

interface ContactLocationStepProps {
  phone: string;
  whatsapp: string;
  email: string;
  locationId: string | null;
  locationData: SelectedLocationData | null;
  addressStreet: string;
  addressNumber: string;
  addressComplement: string;
  postalCode: string;
  hours: Record<string, DayHoursValue>;
  selectedModos: string[];
  errors: Record<string, string>;
  onPhoneChange: (value: string) => void;
  onWhatsappChange: (value: string) => void;
  onEmailChange: (value: string) => void;
  onLocationChange: (locationId: string | null, locationData: SelectedLocationData | null) => void;
  onAddressStreetChange: (value: string) => void;
  onAddressNumberChange: (value: string) => void;
  onAddressComplementChange: (value: string) => void;
  onPostalCodeChange: (value: string) => void;
  onHoursChange: (hours: Record<string, DayHoursValue>) => void;
  onModosChange: (modos: string[]) => void;
  onBack: () => void;
  onNext: () => void;
}

const MODOS_ATENDIMENTO = [
  { id: "presencial", label: "Atendimento presencial", hint: "Cliente vai ate a empresa." },
  { id: "delivery", label: "Delivery", hint: "Entrega de pedidos no endereco do cliente." },
  { id: "domicilio", label: "A domicilio", hint: "Servico prestado no local do cliente." },
  { id: "online", label: "Online", hint: "Atendimento remoto ou digital." },
];

const DAY_LABELS: Array<{ key: string; label: string }> = [
  { key: "segunda", label: "Segunda-feira" },
  { key: "terca", label: "Terca-feira" },
  { key: "quarta", label: "Quarta-feira" },
  { key: "quinta", label: "Quinta-feira" },
  { key: "sexta", label: "Sexta-feira" },
  { key: "sabado", label: "Sabado" },
  { key: "domingo", label: "Domingo" },
];

export function ContactLocationStep({
  phone,
  whatsapp,
  email,
  locationId,
  locationData,
  addressStreet,
  addressNumber,
  addressComplement,
  postalCode,
  hours,
  selectedModos,
  errors,
  onPhoneChange,
  onWhatsappChange,
  onEmailChange,
  onLocationChange,
  onAddressStreetChange,
  onAddressNumberChange,
  onAddressComplementChange,
  onPostalCodeChange,
  onHoursChange,
  onModosChange,
  onBack,
  onNext,
}: ContactLocationStepProps) {
  const handleModoToggle = (modoId: string, checked: boolean) => {
    if (checked) {
      onModosChange(Array.from(new Set([...selectedModos, modoId])));
      return;
    }

    onModosChange(selectedModos.filter((modo) => modo !== modoId));
  };

  const updateDay = (day: string, patch: Partial<DayHoursValue>) => {
    onHoursChange({
      ...hours,
      [day]: {
        ...hours[day],
        ...patch,
      },
    });
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <MapPin className="h-5 w-5 text-primary" />
          Territorio, contato e operacao
        </CardTitle>
        <CardDescription>
          Defina como a empresa aparece territorialmente, onde ela opera e como o cliente entra em contato.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="space-y-4 rounded-xl border p-4">
          <div className="flex items-center gap-2">
            <MapPin className="h-4 w-4 text-primary" />
            <h3 className="font-medium">Territorio principal</h3>
          </div>
          <TerritorialSelector
            initialLocationId={locationId}
            onLocationChange={onLocationChange}
          />
          {errors.location_id && <p className="text-xs text-destructive">{errors.location_id}</p>}
          {locationData && (
            <div className="rounded-lg bg-muted/40 p-3 text-sm text-muted-foreground">
              Exibicao publica principal em <span className="font-medium text-foreground">{locationData.neighborhoodName}</span>, {locationData.cityName} - {locationData.stateName}.
            </div>
          )}
        </div>

        <div className="space-y-4 rounded-xl border p-4">
          <div className="flex items-center gap-2">
            <Phone className="h-4 w-4 text-primary" />
            <h3 className="font-medium">Canais de contato</h3>
          </div>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="phone">Telefone</Label>
              <Input
                id="phone"
                value={phone}
                onChange={(event) => onPhoneChange(event.target.value)}
                placeholder="(71) 3333-3333"
              />
              {errors.phone && <p className="text-xs text-destructive">{errors.phone}</p>}
            </div>

            <div className="space-y-2">
              <Label htmlFor="whatsapp">WhatsApp</Label>
              <Input
                id="whatsapp"
                value={whatsapp}
                onChange={(event) => onWhatsappChange(event.target.value)}
                placeholder="(71) 99999-9999"
              />
              {errors.whatsapp && <p className="text-xs text-destructive">{errors.whatsapp}</p>}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="email">Email comercial</Label>
            <Input
              id="email"
              type="email"
              value={email}
              onChange={(event) => onEmailChange(event.target.value)}
              placeholder="contato@empresa.com"
            />
            {errors.email && <p className="text-xs text-destructive">{errors.email}</p>}
            <p className="text-xs text-muted-foreground">
              Informe pelo menos um canal de contato entre telefone, WhatsApp ou email.
            </p>
          </div>
        </div>

        <div className="space-y-4 rounded-xl border p-4">
          <div className="flex items-center gap-2">
            <MapPin className="h-4 w-4 text-primary" />
            <h3 className="font-medium">Endereco fisico</h3>
          </div>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
            <div className="space-y-2 md:col-span-2">
              <Label htmlFor="address_street">Rua</Label>
              <Input
                id="address_street"
                value={addressStreet}
                onChange={(event) => onAddressStreetChange(event.target.value)}
                placeholder="Ex: Rua das Flores"
              />
              {errors.address_street && <p className="text-xs text-destructive">{errors.address_street}</p>}
            </div>

            <div className="space-y-2">
              <Label htmlFor="address_number">Numero</Label>
              <Input
                id="address_number"
                value={addressNumber}
                onChange={(event) => onAddressNumberChange(event.target.value)}
                placeholder="123"
              />
            </div>

            <div className="space-y-2 md:col-span-2">
              <Label htmlFor="address_complement">Complemento</Label>
              <Input
                id="address_complement"
                value={addressComplement}
                onChange={(event) => onAddressComplementChange(event.target.value)}
                placeholder="Sala, loja, referencia ou bloco"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="postal_code">CEP</Label>
              <Input
                id="postal_code"
                value={postalCode}
                onChange={(event) => onPostalCodeChange(event.target.value)}
                placeholder="40000-000"
              />
              {errors.postal_code && <p className="text-xs text-destructive">{errors.postal_code}</p>}
            </div>
          </div>
        </div>

        <div className="space-y-4 rounded-xl border p-4">
          <div className="flex items-center gap-2">
            <Clock3 className="h-4 w-4 text-primary" />
            <h3 className="font-medium">Horario de funcionamento</h3>
          </div>
          <div className="space-y-3">
            {DAY_LABELS.map((day) => {
              const dayValue = hours[day.key];
              const isClosed = Boolean(dayValue?.closed);

              return (
                <div key={day.key} className="grid grid-cols-1 gap-3 rounded-lg border p-3 md:grid-cols-[160px_1fr_1fr_140px] md:items-center">
                  <div className="font-medium text-sm">{day.label}</div>
                  <Input
                    type="time"
                    value={dayValue?.open || "09:00"}
                    onChange={(event) => updateDay(day.key, { open: event.target.value })}
                    disabled={isClosed}
                  />
                  <Input
                    type="time"
                    value={dayValue?.close || "18:00"}
                    onChange={(event) => updateDay(day.key, { close: event.target.value })}
                    disabled={isClosed}
                  />
                  <label className="flex items-center gap-2 text-sm text-muted-foreground">
                    <Checkbox
                      checked={isClosed}
                      onCheckedChange={(checked) => updateDay(day.key, { closed: Boolean(checked) })}
                    />
                    Fechado
                  </label>
                </div>
              );
            })}
          </div>
        </div>

        <div className="space-y-4 rounded-xl border p-4">
          <h3 className="font-medium">Modos de atendimento</h3>
          <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
            {MODOS_ATENDIMENTO.map((modo) => (
              <label key={modo.id} className="flex items-start gap-3 rounded-lg border p-3 text-sm">
                <Checkbox
                  checked={selectedModos.includes(modo.id)}
                  onCheckedChange={(checked) => handleModoToggle(modo.id, Boolean(checked))}
                />
                <div>
                  <div className="font-medium text-foreground">{modo.label}</div>
                  <div className="text-muted-foreground">{modo.hint}</div>
                </div>
              </label>
            ))}
          </div>
        </div>

        <div className="flex gap-3">
          <Button type="button" variant="outline" onClick={onBack} className="flex-1">
            Voltar
          </Button>
          <Button type="button" onClick={onNext} className="flex-1 gap-2">
            Continuar
            <ArrowRight className="h-4 w-4" />
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

