  const fileInputRef = useRef<HTMLInputElement>(null);

  const [rating, setRating] = useState(initialRating);
  const [hoveredRating, setHoveredRating] = useState(0);
  const [comment, setComment] = useState(initialComment);
  const [photos, setPhotos] = useState<string[]>(initialPhotos);
  const [isUploadingPhotos, setIsUploadingPhotos] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (rating === 0) {
      toast.error('Selecione uma avaliação de 1 a 5 estrelas');
      return;
    }

    if (!comment.trim()) {
      toast.error('Escreva um comentário sobre sua experiência');
      return;
    }

    await onSubmit({ rating, comment: comment.trim(), photos });
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    if (!files.length) return;

    if (photos.length + files.length > MAX_PHOTOS) {
      toast.error(`Você pode adicionar no máximo ${MAX_PHOTOS} fotos`);
      return;
    }

    if (!user?.id) {
      toast.error('Faça login para adicionar fotos');
      return;
    }

    setIsUploadingPhotos(true);

    try {
      const uploadResults = await Promise.all(
        files.map((file) => mediaService.uploadPostImage(user.id, file)),
      );

      const urls = uploadResults.map((r) => r.url);
      setPhotos((prev) => [...prev, ...urls]);
    } catch (error) {
      toast.error('Erro ao enviar fotos. Tente novamente.');
    } finally {
      setIsUploadingPhotos(false);
      // Limpar input para permitir re-upload do mesmo arquivo
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const removePhoto = (index: number) => {
    setPhotos((prev) => prev.filter((_, i) => i !== index));
  };

  const activeRating = hoveredRating || rating;

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      {/* Rating */}
      <div className="space-y-2">
        <Label>Sua avaliação *</Label>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-1">
            {Array.from({ length: 5 }).map((_, index) => {
              const starValue = index + 1;
              const isActive = starValue <= activeRating;

              return (
                <button
                  key={starValue}
                  type="button"
                  onClick={() => setRating(starValue)}
                  onMouseEnter={() => setHoveredRating(starValue)}
                  onMouseLeave={() => setHoveredRating(0)}
                  className="transition-transform hover:scale-110"
                  aria-label={`${starValue} estrelas`}
                >
                  <Star
                    className={`h-8 w-8 ${
                      isActive ? 'fill-amber-400 text-amber-400' : 'fill-muted text-muted'
                    }`}
                  />
                </button>
              );
            })}
          </div>
          {activeRating > 0 && (
            <span className="text-sm font-medium text-muted-foreground">
              {RATING_LABELS[activeRating]}
            </span>
          )}
        </div>
      </div>

      {/* Comentário */}
      <div className="space-y-2">
        <Label htmlFor="review-comment">Conte sobre sua experiência *</Label>
        <Textarea
          id="review-comment"
          placeholder="O que você achou da comida, atendimento e entrega?"
          value={comment}
          onChange={(e) => setComment(e.target.value)}
          rows={5}
          maxLength={1000}
          className="resize-none"
        />
        <p className="text-xs text-muted-foreground">{comment.length}/1000 caracteres</p>
      </div>

      {/* Fotos */}
      <div className="space-y-2">
        <Label>Adicionar fotos (opcional)</Label>
        <p className="text-xs text-muted-foreground">
          Compartilhe fotos do seu pedido (máximo {MAX_PHOTOS})
        </p>

        {photos.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {photos.map((photo, index) => (
              <div key={photo} className="group relative">
                <img
                  src={photo}
                  alt={`Foto ${index + 1}`}
                  className="h-20 w-20 rounded-lg object-cover"
                />
                <button
                  type="button"
                  onClick={() => removePhoto(index)}
                  className="absolute -right-2 -top-2 rounded-full bg-destructive p-1 text-destructive-foreground opacity-0 transition-opacity group-hover:opacity-100"
                  aria-label={`Remover foto ${index + 1}`}
                >
                  <X className="h-3 w-3" />
                </button>
              </div>
            ))}
          </div>
        )}

        {photos.length < MAX_PHOTOS && (
          <>
            <input
              ref={fileInputRef}
              type="file"
              accept="image/jpeg,image/png,image/webp"
              multiple
              onChange={handlePhotoUpload}
              className="hidden"
              aria-label="Selecionar fotos"
            />
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={isUploadingPhotos}
              onClick={() => fileInputRef.current?.click()}
            >
              {isUploadingPhotos ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Enviando...
                </>
              ) : (
                <>
                  <Upload className="mr-2 h-4 w-4" />
                  Adicionar fotos
                </>
              )}
            </Button>
          </>
        )}
      </div>

      {/* Ações */}
      <div className="flex gap-3">
        <Button
          type="submit"
          className="flex-1"
          disabled={isSubmitting || isUploadingPhotos || rating === 0 || !comment.trim()}
        >
          {isSubmitting ? 'Publicando...' : submitLabel}
        </Button>
        {onCancel && (
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            disabled={isSubmitting || isUploadingPhotos}
          >
            Cancelar
          </Button>
        )}
      </div>
    </form>
  );
}

/**
 * ReviewsSection - Seção completa de avaliações
 */

import { useState } from 'react';
import { Star, MessageSquarePlus } from 'lucide-react';

import { Button } from '@/shared/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/shared/components/ui/dialog';
import { Progress } from '@/shared/components/ui/progress';
import { Separator } from '@/shared/components/ui/separator';
import { ReviewCard } from './ReviewCard';
import { ReviewForm } from './ReviewForm';
import { useReviewsManager } from '../hooks/useGastronomyReviews';
import { useUserReviewVote } from '../hooks/useGastronomyReviews';
import type { Review } from '../services/review.queries';

interface ReviewsSectionProps {
  businessProfileId: string;
  businessName: string;
}

export function ReviewsSection({
  businessProfileId,
  businessName,
}: ReviewsSectionProps) {
  const [showReviewForm, setShowReviewForm] = useState(false);

  const {
    reviews,
    stats,
    canReview,
    isLoadingReviews,
    isLoadingStats,
    createReview,
    deleteReview,
    reportReview,
    voteReview,
    isCreating,
    user,
    activeProfile,
  } = useReviewsManager(businessProfileId);

  const handleCreateReview = async (data: {
    rating: number;
    comment: string;
    photos: string[];
  }) => {
    if (!activeProfile?.id) {
      return;
    }

    await createReview({
      reviewed_profile_id: businessProfileId,
      reviewer_profile_id: activeProfile.id,
      rating: data.rating,
      comment: data.comment,
      photos: data.photos,
    });

    setShowReviewForm(false);
  };

  const handleVote = async (reviewId: string, isHelpful: boolean) => {
    if (!activeProfile?.id) {
      return;
    }

    await voteReview({
      review_id: reviewId,
      voter_profile_id: activeProfile.id,
      is_helpful: isHelpful,
    });
  };

  if (isLoadingStats) {
    return (
      <div className="space-y-4">
        <div className="h-8 w-48 animate-pulse rounded bg-muted" />
        <div className="h-32 animate-pulse rounded-xl bg-muted" />
      </div>
    );
  }

  const distribution = stats?.distribution || {};
  const total = stats?.total || 0;
  const average = stats?.average || 0;

  return (
    <section className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-semibold">Avaliações</h2>
          <p className="text-sm text-muted-foreground">
            {total === 0
              ? 'Seja o primeiro a avaliar'
              : `${total} ${total === 1 ? 'avaliação' : 'avaliações'}`}
          </p>
        </div>

        {canReview && (
          <Button onClick={() => setShowReviewForm(true)}>
            <MessageSquarePlus className="mr-2 h-4 w-4" />
            Avaliar
          </Button>
        )}
      </div>

      {/* Estatísticas */}
      {total > 0 && (
        <div className="rounded-xl border bg-card p-6">
          <div className="grid gap-6 md:grid-cols-2">
            {/* Média geral */}
            <div className="flex items-center gap-4">
              <div className="text-center">
                <div className="text-4xl font-bold">{average.toFixed(1)}</div>
                <div className="mt-1 flex items-center justify-center gap-0.5">
                  {Array.from({ length: 5 }).map((_, index) => (
                    <Star
                      key={index}
                      className={`h-4 w-4 ${
                        index < Math.round(average)
                          ? 'fill-amber-400 text-amber-400'
                          : 'fill-muted text-muted'
                      }`}
                    />
                  ))}
                </div>
                <p className="mt-1 text-xs text-muted-foreground">
                  {total} {total === 1 ? 'avaliação' : 'avaliações'}
                </p>
              </div>

              <Separator orientation="vertical" className="h-24" />

              {/* Distribuição */}
              <div className="flex-1 space-y-2">
                {[5, 4, 3, 2, 1].map((stars) => {
                  const count = distribution[stars] || 0;
                  const percentage = total > 0 ? (count / total) * 100 : 0;

                  return (
                    <div key={stars} className="flex items-center gap-2">
                      <span className="w-8 text-xs text-muted-foreground">
                        {stars} ★
                      </span>
                      <Progress value={percentage} className="h-2 flex-1" />
                      <span className="w-8 text-right text-xs text-muted-foreground">
                        {count}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Lista de avaliações */}
      {isLoadingReviews ? (
        <div className="space-y-4">
          {Array.from({ length: 3 }).map((_, index) => (
            <div key={index} className="h-40 animate-pulse rounded-xl bg-muted" />
          ))}
        </div>
      ) : reviews.length > 0 ? (
        <div className="space-y-4">
          {reviews.map((review) => (
            <ReviewCardWithVote
              key={review.id}
              review={review}
              canEdit={review.reviewer_profile_id === activeProfile?.id}
              onDelete={() => deleteReview(review.id)}
              onReport={() =>
                activeProfile &&
                reportReview({
                  review_id: review.id,
                  reporter_profile_id: activeProfile.id,
                  reason: 'inappropriate',
                })
              }
              onVote={(isHelpful) => handleVote(review.id, isHelpful)}
              voterProfileId={activeProfile?.id}
            />
          ))}
        </div>
      ) : (
        <div className="rounded-xl border border-dashed p-12 text-center">
          <MessageSquarePlus className="mx-auto h-12 w-12 text-muted-foreground" />
          <h3 className="mt-4 font-semibold">Nenhuma avaliação ainda</h3>
          <p className="mt-2 text-sm text-muted-foreground">
            Seja o primeiro a compartilhar sua experiência com {businessName}
          </p>
          {canReview && (
            <Button onClick={() => setShowReviewForm(true)} className="mt-4">
              Escrever avaliação
            </Button>
          )}
        </div>
      )}

      {/* Dialog de criar avaliação */}
      <Dialog open={showReviewForm} onOpenChange={setShowReviewForm}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Avaliar {businessName}</DialogTitle>
            <DialogDescription>
              Compartilhe sua experiência para ajudar outros clientes
            </DialogDescription>
          </DialogHeader>
          <ReviewForm
            onSubmit={handleCreateReview}
            onCancel={() => setShowReviewForm(false)}
            isSubmitting={isCreating}
          />
        </DialogContent>
      </Dialog>
    </section>
  );
}

// Componente auxiliar para gerenciar voto individual
function ReviewCardWithVote({
  review,
  canEdit,
  onDelete,
  onReport,
  onVote,
  voterProfileId,
}: {
  review: Review;
  canEdit: boolean;
  onDelete: () => void;
  onReport: () => void;
  onVote: (isHelpful: boolean) => void;
  voterProfileId?: string;
}) {
  const { data: userVote } = useUserReviewVote({
    reviewId: review.id,
    voterProfileId: voterProfileId || '',
    enabled: !!voterProfileId,
  });

  return (
    <ReviewCard
      review={review}
      canEdit={canEdit}
      userVote={userVote}
      onDelete={onDelete}
      onReport={onReport}
      onVote={onVote}
    />
  );
}

/**
 * BusinessHoursForm — Formulário de horários da semana
 *
 * Permite configurar horário de abertura/fechamento para cada dia.
 * SSOT: Usa useBusinessHours hook
 */

import { useState } from 'react';
import { useBusinessHours } from '../../hooks';
import { DAY_NAMES } from '@/core/business';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/shared/components/ui/card';
import { Button } from '@/shared/components/ui/button';
import { Input } from '@/shared/components/ui/input';
import { Label } from '@/shared/components/ui/label';
import { Switch } from '@/shared/components/ui/switch';
import { Clock, Save } from 'lucide-react';

interface DayHours {
  day_of_week: number;
  opens_at: string;
  closes_at: string;
  is_closed: boolean;
}

interface BusinessHoursFormProps {
  businessId: string;
}

export function BusinessHoursForm({ businessId }: BusinessHoursFormProps) {
  const { hours, isLoading, setBulkHours, isSettingHours } = useBusinessHours(businessId);

  // Estado local para edição
  const [editedHours, setEditedHours] = useState<DayHours[]>(() => {
    // Inicializa com horários existentes ou padrão
    return Array.from({ length: 7 }, (_, i) => {
      const existing = hours?.find((h) => h.day_of_week === i);
      return {
        day_of_week: i,
        opens_at: existing?.opens_at || '08:00',
        closes_at: existing?.closes_at || '18:00',
        is_closed: existing?.is_closed || false,
      };
    });
  });

  // Atualiza estado quando dados carregam
  if (hours && editedHours.every((h) => !hours.find((existing) => existing.day_of_week === h.day_of_week))) {
    setEditedHours(
      Array.from({ length: 7 }, (_, i) => {
        const existing = hours.find((h) => h.day_of_week === i);
        return {
          day_of_week: i,
          opens_at: existing?.opens_at || '08:00',
          closes_at: existing?.closes_at || '18:00',
          is_closed: existing?.is_closed || false,
        };
      })
    );
  }

  const handleDayChange = (dayIndex: number, field: keyof DayHours, value: string | boolean) => {
    setEditedHours((prev) =>
      prev.map((day) =>
        day.day_of_week === dayIndex ? { ...day, [field]: value } : day
      )
    );
  };

  const handleSave = () => {
    setBulkHours(editedHours);
  };

  const handleCopyToAll = (dayIndex: number) => {
    const source = editedHours[dayIndex];
    setEditedHours((prev) =>
      prev.map((day) => ({
        ...day,
        opens_at: source.opens_at,
        closes_at: source.closes_at,
        is_closed: source.is_closed,
      }))
    );
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent className="py-8">
          <p className="text-center text-muted-foreground">Carregando horários...</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Clock className="w-5 h-5" />
          Horários da Semana
        </CardTitle>
        <CardDescription>
          Configure os horários de funcionamento para cada dia
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        {editedHours.map((day) => (
          <div key={day.day_of_week} className="space-y-3 pb-4 border-b last:border-0">
            <div className="flex items-center justify-between">
              <Label className="text-base font-medium">
                {DAY_NAMES[day.day_of_week]}
              </Label>
              <div className="flex items-center gap-2">
                <Label htmlFor={`closed-${day.day_of_week}`} className="text-sm text-muted-foreground">
                  Fechado
                </Label>
                <Switch
                  id={`closed-${day.day_of_week}`}
                  checked={day.is_closed}
                  onCheckedChange={(checked) =>
                    handleDayChange(day.day_of_week, 'is_closed', checked)
                  }
                />
              </div>
            </div>

            {!day.is_closed && (
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor={`opens-${day.day_of_week}`} className="text-sm">
                    Abre às
                  </Label>
                  <Input
                    id={`opens-${day.day_of_week}`}
                    type="time"
                    value={day.opens_at}
                    onChange={(e) =>
                      handleDayChange(day.day_of_week, 'opens_at', e.target.value)
                    }
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor={`closes-${day.day_of_week}`} className="text-sm">
                    Fecha às
                  </Label>
                  <Input
                    id={`closes-${day.day_of_week}`}
                    type="time"
                    value={day.closes_at}
                    onChange={(e) =>
                      handleDayChange(day.day_of_week, 'closes_at', e.target.value)
                    }
                  />
                </div>
              </div>
            )}

            <Button
              variant="ghost"
              size="sm"
              onClick={() => handleCopyToAll(day.day_of_week)}
              className="text-xs"
            >
              Copiar para todos os dias
            </Button>
          </div>
        ))}

        <Button
          onClick={handleSave}
          disabled={isSettingHours}
          className="w-full"
        >
          <Save className="w-4 h-4 mr-2" />
          {isSettingHours ? 'Salvando...' : 'Salvar Horários'}
        </Button>
      </CardContent>
    </Card>
  );
}

/**
 * CategoryList — Lista de categorias com drag & drop
 *
 * Permite reordenar categorias arrastando
 */

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/components/ui/card';
import { Button } from '@/shared/components/ui/button';
import { Badge } from '@/shared/components/ui/badge';
import { GripVertical, Pencil, Trash2, Plus } from 'lucide-react';
import type { MenuCategory } from '@/modules/business/gastronomy/services/MenuService';

interface CategoryListProps {
  categories: MenuCategory[];
  onEdit: (category: MenuCategory) => void;
  onDelete: (categoryId: string) => void;
  onCreate: () => void;
  onReorder: (updates: Array<{ id: string; display_order: number }>) => void;
  canCreate?: boolean;
  createDisabledReason?: string;
}

export function CategoryList({
  categories,
  onEdit,
  onDelete,
  onCreate,
  onReorder,
  canCreate = true,
  createDisabledReason,
}: CategoryListProps) {
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  const handleDragStart = (index: number) => {
    setDraggedIndex(index);
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;

    const newCategories = [...categories];
    const draggedItem = newCategories[draggedIndex];
    newCategories.splice(draggedIndex, 1);
    newCategories.splice(index, 0, draggedItem);

    // Atualizar ordem
    const updates = newCategories.map((cat, idx) => ({
      id: cat.id,
      display_order: idx,
    }));

    onReorder(updates);
    setDraggedIndex(index);
  };

  const handleDragEnd = () => {
    setDraggedIndex(null);
  };

  if (categories.length === 0) {
    return (
      <Card>
        <CardContent className="py-12 text-center">
          <p className="text-muted-foreground mb-4">
            Nenhuma categoria criada ainda
          </p>
          <Button onClick={onCreate}>
            <Plus className="w-4 h-4 mr-2" />
            Criar Primeira Categoria
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-medium">Categorias</h3>
        <Button onClick={onCreate} size="sm" disabled={!canCreate}>
          <Plus className="w-4 h-4 mr-2" />
          Nova Categoria
        </Button>
      </div>

      {!canCreate && createDisabledReason && (
        <div className="rounded-md border border-amber-200 bg-amber-50 p-3 text-sm text-amber-700">
          {createDisabledReason}
        </div>
      )}

      <div className="space-y-2">
        {categories.map((category, index) => (
          <Card
            key={category.id}
            draggable
            onDragStart={() => handleDragStart(index)}
            onDragOver={(e) => handleDragOver(e, index)}
            onDragEnd={handleDragEnd}
            className={`cursor-move transition-all ${
              draggedIndex === index ? 'opacity-50' : ''
            }`}
          >
            <CardContent className="p-4">
              <div className="flex items-center gap-4">
                <GripVertical className="w-5 h-5 text-muted-foreground flex-shrink-0" />
                
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <h4 className="font-medium">{category.name}</h4>
                    {!category.is_active && (
                      <Badge variant="outline">Inativa</Badge>
                    )}
                  </div>
                  {category.description && (
                    <p className="text-sm text-muted-foreground mt-1">
                      {category.description}
                    </p>
                  )}
                </div>

                <div className="flex items-center gap-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => onEdit(category)}
                  >
                    <Pencil className="w-4 h-4" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => onDelete(category.id)}
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

