                <Input
                  placeholder="Cupom"
                  value={couponCode}
                  onChange={(event) => setCouponCode(event.target.value)}
                />
                <Textarea
                  rows={3}
                  placeholder="Observações do pedido"
                  value={orderNotes}
                  onChange={(event) => setOrderNotes(event.target.value)}
