 */

export type PostType =
  | "pergunta"
  | "discussao"
  | "recomendacao"
  | "enquete"
  | "achados_e_perdidos";

interface PostBadgeProps {
  type: PostType;
  isVerified?: boolean; // Para alertas com 5+ confirmações
