function StatusBadge({ status, label }: { status: CommunityIssuePublic["status"]; label: string }) {
  const classMap: Record<string, string> = {
    aberto:       "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-300",
    em_analise:   "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-300",
    em_andamento: "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-300",
    resolvido:    "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300",
    rejeitado:    "bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-400",
  };

  return (
    <span className={cn("text-xs font-bold px-2 py-0.5 rounded-full", classMap[status] ?? classMap.aberto)}>
      {label.toUpperCase()}
    </span>
  );
}

/**
 * ProblemasPage - Pagina dedicada a problemas urbanos
 * Rota: /comunidade/problemas
 */

import { useState } from "react";
import { Wrench } from "lucide-react";
import { TooltipProvider } from "@/shared/components/ui/tooltip";
import { useSessionContext } from "@/core/session";
import { useLocationContext } from "@/core/location";
import { useTerritoryFilter } from "@/core/location/hooks/useTerritoryFilter";
import { buildCommunityTerritoryPresentation } from "@/core/community/utils/communityTerritoryPresentation";
import { IssueCard } from "../components/IssueCard";
import { IssueCardSkeleton } from "../components/IssueCardSkeleton";
import { CreateIssueModal } from "../components/CreateIssueModal";
import { useIssues } from "../hooks/useIssues";
import { Button } from "@/shared/components/ui/button";
import type { IssueStatus } from "../domain/types";
import { ISSUE_STATUS_LABELS } from "../config/issueConfig";
import type { ResolvedTerritory } from "@/core/routing/hooks/useResolveTerritoryFromUrl";

interface ProblemasPageProps {
  resolved?: ResolvedTerritory;
}

export default function ProblemasPage({ resolved }: ProblemasPageProps) {
  const { activeProfile: profile } = useSessionContext();
  const { activeLocation } = useLocationContext();
  const territoryFilter = useTerritoryFilter(resolved);
  const [modalOpen, setModalOpen] = useState(false);
  const [filterStatus, setFilterStatus] = useState<IssueStatus | undefined>("aberto");

  const resolvedLocation =
    resolved?.kind === "location"
      ? resolved.location
      : resolved?.kind === "group"
      ? resolved.group.members[0]
      : null;
  const territoryPresentation = buildCommunityTerritoryPresentation({
    resolvedLocation,
    activeLocation,
    profile,
  });

  const { data: issues = [], isLoading } = useIssues({
    territoryFilter,
    status: filterStatus,
    limit: 30,
  });

  return (
    <TooltipProvider>
      <div className="min-h-screen bg-[#12181B]" role="main">
        <div className="container mx-auto max-w-2xl px-4 py-6 space-y-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Wrench className="h-5 w-5 text-amber-500" aria-hidden />
              <h1 className="text-lg font-semibold text-foreground">Problemas urbanos</h1>
            </div>
            <Button
              size="sm"
              onClick={() => setModalOpen(true)}
              disabled={!profile || !territoryPresentation.locationId}
              aria-label="Reportar novo problema"
            >
              Reportar
            </Button>
          </div>

          <div className="flex gap-2 flex-wrap" role="group" aria-label="Filtrar por status">
            {([undefined, "aberto", "em_analise", "em_andamento", "resolvido"] as const).map((s) => (
              <button
                key={s ?? "todos"}
                onClick={() => setFilterStatus(s)}
                className={`text-xs px-3 py-1 rounded-full border transition-colors ${
                  filterStatus === s
                    ? "bg-amber-500 text-white border-amber-500"
                    : "border-border text-muted-foreground hover:border-amber-400"
                }`}
                aria-pressed={filterStatus === s}
              >
                {s ? ISSUE_STATUS_LABELS[s] : "Todos"}
              </button>
            ))}
          </div>

          <div className="space-y-4" role="feed" aria-label="Lista de problemas urbanos">
            {isLoading ? (
              Array.from({ length: 3 }).map((_, i) => <IssueCardSkeleton key={i} />)
            ) : territoryFilter.scope === "none" ? (
              <div className="text-center py-12 text-muted-foreground">
                <Wrench className="h-8 w-8 mx-auto mb-3 opacity-30" />
                <p className="text-sm">Territorio nao resolvido para carregar problemas.</p>
              </div>
            ) : issues.length === 0 ? (
              <div className="text-center py-12 text-muted-foreground">
                <Wrench className="h-8 w-8 mx-auto mb-3 opacity-30" />
                <p className="text-sm">Nenhum problema encontrado nesta regiao.</p>
              </div>
            ) : (
              issues.map((issue) => <IssueCard key={issue.id} issue={issue} profileId={profile?.id} />)
            )}
          </div>
        </div>

        <CreateIssueModal
          open={modalOpen}
          onClose={() => setModalOpen(false)}
          city={territoryPresentation.city}
          neighborhood={territoryPresentation.neighborhood}
          locationId={territoryPresentation.locationId}
        />
      </div>
    </TooltipProvider>
  );
}

/**
 * AdminTouristPointsPage — Listagem admin de pontos turísticos
 *
 * Rota: /admin/guia/pontos-turisticos
 */

import { useState } from 'react';
import { Link } from 'react-router-dom';
import { Plus, Loader2, Pencil, Trash2, Star, Search, Camera, MapPin } from 'lucide-react';
import { Button } from '@/shared/components/ui/button';
import { Input } from '@/shared/components/ui/input';
import { Badge } from '@/shared/components/ui/badge';
import { Card, CardContent } from '@/shared/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/components/ui/select';
import { useToast } from '@/shared/components/ui/use-toast';
import { useSessionContext } from '@/core/session';
import {
  useAdminTouristPoints,
  useDeleteTouristPoint,
  useSetTouristPointStatus,
  useSetTouristPointFeatured,
} from '../hooks/useAdminTouristPoints';
import { TOURIST_POINT_STATUS_LABELS, PRICE_TYPE_LABELS } from '../types';
import type { TouristPoint, TouristPointStatus } from '../types';

// Locations de Salvador para filtro piloto
const SALVADOR_LOCATION_IDS = [
  // Serão preenchidos dinamicamente via LocationRepository em produção
  // Por ora, o admin lista todos os pontos sem filtro de location
];

export default function AdminTouristPointsPage() {
  const { toast } = useToast();
  const { user } = useSessionContext();
  const [search, setSearch] = useState('');
  const [filterStatus, setFilterStatus] = useState<TouristPointStatus | ''>('');

  // Para o admin, listamos com location_ids vazio = sem filtro territorial
  // Em produção, o admin pode selecionar o território
  const { data: points = [], isLoading } = useAdminTouristPoints(SALVADOR_LOCATION_IDS);

  const deleteMutation = useDeleteTouristPoint();
  const statusMutation = useSetTouristPointStatus(user?.id);
  const featuredMutation = useSetTouristPointFeatured(user?.id);

  const filtered = points.filter((p) => {
    const matchSearch =
      !search ||
      p.title.toLowerCase().includes(search.toLowerCase()) ||
      p.summary.toLowerCase().includes(search.toLowerCase());
    const matchStatus = !filterStatus || p.status === filterStatus;
    return matchSearch && matchStatus;
  });

  const handleDelete = async (point: TouristPoint) => {
    if (!confirm(`Remover "${point.title}"? Esta ação não pode ser desfeita.`)) return;
    try {
      await deleteMutation.mutateAsync(point.id);
      toast({ title: 'Removido', description: `"${point.title}" foi removido.` });
    } catch (err: unknown) {
      toast({
        title: 'Erro ao remover',
        description: err instanceof Error ? err.message : 'Erro desconhecido',
        variant: 'destructive',
      });
    }
  };

  const handleToggleFeatured = async (point: TouristPoint) => {
    try {
      await featuredMutation.mutateAsync({ id: point.id, is_featured: !point.is_featured });
    } catch (err: unknown) {
      toast({
        title: 'Erro',
        description: err instanceof Error ? err.message : 'Erro desconhecido',
        variant: 'destructive',
      });
    }
  };

  const handleStatusChange = async (point: TouristPoint, status: TouristPointStatus) => {
    try {
      await statusMutation.mutateAsync({ id: point.id, status });
      toast({ title: 'Status atualizado', description: TOURIST_POINT_STATUS_LABELS[status] });
    } catch (err: unknown) {
      toast({
        title: 'Erro',
        description: err instanceof Error ? err.message : 'Erro desconhecido',
        variant: 'destructive',
      });
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground flex items-center gap-2">
            <Camera className="h-6 w-6 text-warning" />
            Pontos Turísticos
          </h1>
          <p className="text-sm text-muted-foreground">Módulo Guide — vertical tourism</p>
        </div>
        <Button asChild>
          <Link to="/admin/guia/pontos-turisticos/novo">
            <Plus className="h-4 w-4 mr-2" />
            Novo ponto
          </Link>
        </Button>
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="pt-4 pb-3">
          <div className="flex flex-col sm:flex-row gap-3">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Buscar por título..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="pl-10"
              />
            </div>
            <Select
              value={filterStatus}
              onValueChange={(v) => setFilterStatus(v as TouristPointStatus | '')}
            >
              <SelectTrigger className="w-[160px]">
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="">Todos</SelectItem>
                {Object.entries(TOURIST_POINT_STATUS_LABELS).map(([val, label]) => (
                  <SelectItem key={val} value={val}>{label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-3">
        <Card>
          <CardContent className="pt-4 pb-3 text-center">
            <p className="text-2xl font-bold">{points.length}</p>
            <p className="text-xs text-muted-foreground">Total</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4 pb-3 text-center">
            <p className="text-2xl font-bold text-success">
              {points.filter((p) => p.status === 'published').length}
            </p>
            <p className="text-xs text-muted-foreground">Publicados</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4 pb-3 text-center">
            <p className="text-2xl font-bold text-warning">
              {points.filter((p) => p.is_featured).length}
            </p>
            <p className="text-xs text-muted-foreground">Destaques</p>
          </CardContent>
        </Card>
      </div>

      {/* List */}
      {isLoading ? (
        <div className="flex items-center justify-center py-20">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
        </div>
      ) : filtered.length === 0 ? (
        <Card>
          <CardContent className="py-12 text-center">
            <Camera className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
            <h3 className="font-bold text-foreground mb-1">Nenhum ponto turístico</h3>
            <p className="text-sm text-muted-foreground">
              {search ? 'Nenhum resultado para a busca.' : 'Clique em "Novo ponto" para cadastrar.'}
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-3">
          {filtered.map((point) => {
            const cover = point.media?.find((m) => m.is_cover) ?? point.media?.[0];
            return (
              <Card key={point.id} className="hover:shadow-md transition-shadow">
                <CardContent className="p-4">
                  <div className="flex items-center gap-4">
                    {/* Thumbnail */}
                    <div className="h-14 w-14 rounded-xl bg-muted flex items-center justify-center flex-shrink-0 overflow-hidden">
                      {cover ? (
                        <img src={cover.url} alt={point.title} className="w-full h-full object-cover" />
                      ) : (
                        <MapPin className="h-6 w-6 text-muted-foreground" />
                      )}
                    </div>

                    {/* Info */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-0.5">
                        <h3 className="font-bold text-foreground truncate">{point.title}</h3>
                        {point.is_featured && (
                          <Star className="h-4 w-4 text-warning fill-warning flex-shrink-0" />
                        )}
                      </div>
                      <div className="flex items-center gap-2 flex-wrap">
                        <Badge
                          variant={
                            point.status === 'published'
                              ? 'default'
                              : point.status === 'draft'
                              ? 'secondary'
                              : 'outline'
                          }
                          className="text-[10px]"
                        >
                          {TOURIST_POINT_STATUS_LABELS[point.status]}
                        </Badge>
                        <Badge variant="outline" className="text-[10px]">
                          {PRICE_TYPE_LABELS[point.price_type]}
                        </Badge>
                        {point.location && (
                          <span className="text-xs text-muted-foreground truncate">
                            {point.location.full_name}
                          </span>
                        )}
                      </div>
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-1 flex-shrink-0">
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleToggleFeatured(point)}
                        title={point.is_featured ? 'Remover destaque' : 'Destacar'}
                      >
                        <Star
                          className={`h-4 w-4 ${
                            point.is_featured ? 'text-warning fill-warning' : 'text-muted-foreground'
                          }`}
                        />
                      </Button>
                      <Button asChild variant="ghost" size="icon">
                        <Link to={`/admin/guia/pontos-turisticos/${point.id}/editar`}>
                          <Pencil className="h-4 w-4 text-muted-foreground" />
                        </Link>
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleDelete(point)}
                      >
                        <Trash2 className="h-4 w-4 text-destructive" />
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

