interface PostToRideModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onPublish: (
    data: Omit<
      CommunityRidePostData,
      | "id"
      | "authorName"
      | "authorAvatar"
      | "createdAt"
      | "interestedCount"
      | "hasJoined"
    >,
  ) => void;
  authorName?: string;
}

export function PostToRideModal({
  open,
  onOpenChange,
  onPublish,
  authorName,
}: PostToRideModalProps) {
  const [intent, setIntent] = useState<CommunityRideIntent>("offering");
  const [content, setContent] = useState("");
  const [origin, setOrigin] = useState("");
  const [destination, setDestination] = useState("");
  const [departureTime, setDepartureTime] = useState("");
  const [seats, setSeats] = useState("1");
  const [price, setPrice] = useState("");
  const [rideType, setRideType] = useState<"viagem" | "carona_compartilhada">(
    "carona_compartilhada",
  );
  const [shareToFeed, setShareToFeed] = useState(true);

  const reset = () => {
    setContent("");
    setOrigin("");
    setDestination("");
    setDepartureTime("");
    setSeats("1");
    setPrice("");
    setIntent("offering");
    setRideType("carona_compartilhada");
    setShareToFeed(true);
  };

  const handleSuggestedMessage = (msg: string) => setContent(msg);

  const handlePublish = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() || !destination) return;
    onPublish({
      content: content.trim(),
      intent,
      origin: origin || undefined,
      destination,
      departureTime: departureTime
        ? new Date(departureTime).toISOString()
        : undefined,
      seatsAvailable: intent === "offering" ? parseInt(seats) : undefined,
      rideType,
      price: price ? parseFloat(price) : undefined,
      authorNeighborhood: "Nordeste de Amaralina",
      isVerified: false,
    });
    reset();
    onOpenChange(false);
  };

  return (
    <Dialog
      open={open}
      onOpenChange={(v) => {
        onOpenChange(v);
        if (!v) reset();
      }}
