import { useEffect, useState } from "react";
import { Button } from "@/shared/components/ui/button";
import { Input } from "@/shared/components/ui/input";
import { Label } from "@/shared/components/ui/label";
import {
  BRAZIL_STATE_OPTIONS,
  createDriverRegistrationFormValues,
  DRIVER_LICENSE_CATEGORIES,
  DRIVER_MAX_VEHICLE_YEAR,
  DRIVER_VEHICLE_TYPES,
  parseDriverRegistrationForm,
  type DriverRegistrationDefaults,
  type DriverRegistrationInput,
  type DriverRegistrationFormValues,
} from "@/modules/mobility/utils/driverRegistration";

interface DriverRegistrationFormProps {
  defaultValues?: DriverRegistrationDefaults;
  loading?: boolean;
  submitLabel?: string;
  onSubmit: (input: DriverRegistrationInput) => void | Promise<void>;
}

const VEHICLE_TYPE_LABELS: Record<(typeof DRIVER_VEHICLE_TYPES)[number], string> = {
  car: "Carro",
  motorcycle: "Moto",
  van: "Van",
  truck: "Caminhão",
};

export function DriverRegistrationForm({
  defaultValues,
  loading = false,
  submitLabel = "Enviar Cadastro",
  onSubmit,
}: DriverRegistrationFormProps) {
  const defaultName = defaultValues?.name ?? null;
  const defaultCity = defaultValues?.city ?? null;
  const defaultAvatarUrl = defaultValues?.avatarUrl ?? null;
  const defaultState = defaultValues?.state ?? null;

  const [form, setForm] = useState<DriverRegistrationFormValues>(() =>
    createDriverRegistrationFormValues(defaultValues),
  );

  useEffect(() => {
    setForm(
      createDriverRegistrationFormValues({
        name: defaultName,
        city: defaultCity,
        avatarUrl: defaultAvatarUrl,
        state: defaultState,
      }),
    );
  }, [defaultAvatarUrl, defaultCity, defaultName, defaultState]);

  const updateField = <K extends keyof DriverRegistrationFormValues>(
    field: K,
    value: DriverRegistrationFormValues[K],
  ) => {
    setForm((current) => ({ ...current, [field]: value }));
  };

  const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    await onSubmit(parseDriverRegistrationForm(form, defaultValues));
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div className="space-y-1.5">
        <Label className="text-xs">Nome completo</Label>
        <Input
          value={form.name}
          onChange={(event) => updateField("name", event.target.value)}
          placeholder="Seu nome completo"
          required
          disabled={loading}
        />
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label className="text-xs">Número da CNH</Label>
          <Input
            value={form.licenseNumber}
            onChange={(event) => updateField("licenseNumber", event.target.value)}
            placeholder="12345678900"
            maxLength={11}
            required
            disabled={loading}
          />
        </div>
        <div className="space-y-1.5">
          <Label className="text-xs">Categoria</Label>
          <select
            value={form.licenseCategory}
            onChange={(event) =>
              updateField("licenseCategory", event.target.value as DriverRegistrationFormValues["licenseCategory"])
            }
            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            required
            disabled={loading}
          >
            {DRIVER_LICENSE_CATEGORIES.map((category) => (
              <option key={category} value={category}>
                {category}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label className="text-xs">Validade da CNH</Label>
          <Input
            type="date"
            value={form.licenseExpiry}
            onChange={(event) => updateField("licenseExpiry", event.target.value)}
            required
            disabled={loading}
          />
        </div>
        <div className="space-y-1.5">
          <Label className="text-xs">UF da CNH</Label>
          <select
            value={form.licenseState}
            onChange={(event) => updateField("licenseState", event.target.value)}
            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            required
            disabled={loading}
          >
            <option value="">Selecione</option>
            {BRAZIL_STATE_OPTIONS.map((state) => (
              <option key={state} value={state}>
                {state}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label className="text-xs">Tipo de veículo</Label>
          <select
            value={form.vehicleType}
            onChange={(event) =>
              updateField("vehicleType", event.target.value as DriverRegistrationFormValues["vehicleType"])
            }
            className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            required
            disabled={loading}
          >
            {DRIVER_VEHICLE_TYPES.map((vehicleType) => (
              <option key={vehicleType} value={vehicleType}>
                {VEHICLE_TYPE_LABELS[vehicleType]}
              </option>
            ))}
          </select>
        </div>
        <div className="space-y-1.5">
          <Label className="text-xs">Placa do veículo</Label>
          <Input
            value={form.vehiclePlate}
            onChange={(event) => updateField("vehiclePlate", event.target.value.toUpperCase())}
            placeholder="ABC1D23"
            maxLength={8}
            className="uppercase"
            required
            disabled={loading}
          />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div className="space-y-1.5">
          <Label className="text-xs">Ano</Label>
          <Input
            type="number"
            min="2000"
            max={String(DRIVER_MAX_VEHICLE_YEAR)}
            value={form.vehicleYear}
            onChange={(event) => updateField("vehicleYear", event.target.value)}
            placeholder={String(new Date().getFullYear())}
            required
            disabled={loading}
          />
        </div>
        <div className="space-y-1.5">
          <Label className="text-xs">Cor do veículo</Label>
          <Input
            value={form.vehicleColor}
            onChange={(event) => updateField("vehicleColor", event.target.value)}
            placeholder="Ex: Preto"
            required
            disabled={loading}
          />
        </div>
      </div>

      <div className="space-y-1.5">
        <Label className="text-xs">Modelo do veículo</Label>
        <Input
          value={form.vehicleModel}
          onChange={(event) => updateField("vehicleModel", event.target.value)}
          placeholder="Ex: Honda Civic"
          required
          disabled={loading}
        />
      </div>

      <div className="rounded-xl border border-warning/20 bg-warning/10 p-3">
        <p className="text-xs text-warning-foreground">
          Sua documentação será verificada pela equipe. Você receberá uma notificação
          quando o perfil estiver aprovado para operar.
        </p>
      </div>

      <Button type="submit" className="w-full" disabled={loading}>
        {submitLabel}
      </Button>
    </form>
  );
}

import React, { useState } from "react";
import {
  Car,
  Package,
  Clock,
  DollarSign,
  Star,
  MapPin,
  Phone,
  MessageCircle,
  Play,
  CheckCircle2,
  XCircle,
  Loader2,
  User,
  Ban,
} from "lucide-react";
import { Button } from "@/shared/components/ui/button";
import { Avatar, AvatarFallback } from "@/shared/components/ui/avatar";
import { Badge } from "@/shared/components/ui/badge";
import { Skeleton } from "@/shared/components/ui/skeleton";
import { PassengerTrustBadge } from "../../../../shared/components/badges/PassengerTrustBadge";
import { RideChatDialog } from "../RideChatDialog";
import { cn } from "@/shared/utils/cn";
import type { MobilityRide } from "./DriverRidesTab";
import { useSessionContext } from "@/core/session";
import { RIDE_STATUS, PAYMENT_METHOD } from "@/shared/types/constants";
import { toast } from "sonner";
import { logger } from "@/shared/utils/logger";
import { profileService } from "@/core/profiles/services";
import { mobilityService } from "@/modules/mobility/services/MobilityService";

interface DriverRidesListProps {
  rides: MobilityRide[];
  type: "available" | "accepted" | "history";
  onAccept?: (id: string) => void;
  onStart?: (id: string) => void;
  onComplete?: (id: string, ride?: MobilityRide) => void;
  onCancel?: (id: string) => void;
  loading: boolean;
  isSuspended?: boolean;
}

export function DriverRidesList({
  rides,
  type,
  onAccept,
  onStart,
  onComplete,
  onCancel,
  loading,
  isSuspended = false,
}: DriverRidesListProps) {
  const { activeProfile } = useSessionContext();
  const [loadingAction, setLoadingAction] = useState<string | null>(null);
  const [chatOpen, setChatOpen] = useState(false);
  const [selectedRide, setSelectedRide] = useState<MobilityRide | null>(null);

  const formatTime = (iso: string) =>
    new Date(iso).toLocaleTimeString("pt-BR", {
      hour: "2-digit",
      minute: "2-digit",
    });
  const formatRelative = (iso: string) => {
    const mins = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
    if (mins < 1) return "agora";
    if (mins < 60) return `${mins}min atrás`;
    return `${Math.floor(mins / 60)}h atrás`;
  };
  const formatDate = (iso: string) =>
    new Date(iso).toLocaleDateString("pt-BR", {
      day: "2-digit",
      month: "short",
    });

  const handleAction = async (
    actionFn: ((id: string, ride?: MobilityRide) => void) | undefined,
    rideId: string,
    ride?: MobilityRide,
  ) => {
    if (!actionFn || loadingAction) return;

    // SSOT: Validar motorista verificado antes de aceitar corrida
    if (actionFn === onAccept && activeProfile) {
      try {
        // SSOT: Buscar profile_id do motorista usando ProfileService
        const driverProfile = await profileService.getProfileByType(
          activeProfile.id,
          "driver",
        );

        if (!driverProfile) {
          toast.error("Perfil de motorista não encontrado");
          return;
        }

        // SSOT: Buscar dados de driver_data via MobilityService
        const driver = await mobilityService.getDriverVerificationStatus(
          driverProfile.id,
        );

        if (!driver.is_verified) {
          toast.error("❌ Motorista não verificado", {
            description:
              "Complete o processo de verificação para aceitar corridas.",
          });
          return;
        }

        if (!driver.is_online) {
          toast.error("❌ Você está offline", {
            description: "Ative o modo online para aceitar corridas.",
          });
          return;
        }

        if (!driver.subscription_active) {
          toast.error("❌ Assinatura inativa", {
            description: "Renove sua assinatura para aceitar corridas.",
          });
          return;
        }
      } catch (err) {
        logger.error("Erro ao validar motorista:", err);
        toast.error("Erro ao validar motorista");
        return;
      }
    }

    setLoadingAction(rideId);
    try {
      await actionFn(rideId, ride);
    } finally {
      setLoadingAction(null);
    }
  };

  // U7: Skeleton loading
  if (loading) {
    return (
      <div className="space-y-3">
        {[1, 2, 3].map((i) => (
          <div key={i} className="rounded-2xl border border-border p-4 bg-card">
            <div className="flex items-center gap-3 mb-3">
              <Skeleton className="h-10 w-10 rounded-full" />
              <div className="flex-1 space-y-2">
                <Skeleton className="h-4 w-32" />
                <Skeleton className="h-3 w-24" />
              </div>
              <Skeleton className="h-5 w-16 rounded-full" />
            </div>
            <Skeleton className="h-16 w-full rounded-lg mb-3" />
            <Skeleton className="h-10 w-full rounded-xl" />
          </div>
        ))}
      </div>
    );
  }

  if (rides.length === 0) {
    const emptyConfig = {
      available: {
        icon: isSuspended ? Ban : MapPin,
        title: isSuspended ? "Conta Suspensa" : "Nenhum pedido disponível",
        desc: isSuspended
          ? "Você não pode aceitar corridas durante a suspensão"
          : "Fique online para receber novos pedidos",
      },
      accepted: {
        icon: Car,
        title: "Nenhuma corrida ativa",
        desc: "Aceite um pedido para começar",
      },
      history: {
        icon: Clock,
        title: "Sem histórico",
        desc: "Suas corridas concluídas aparecerão aqui",
      },
    };
    const config = emptyConfig[type];
    return (
      <div className="flex flex-col items-center justify-center py-4 text-center">
        <div
          className={cn(
            "w-8 h-8 rounded-lg flex items-center justify-center mb-1.5",
            isSuspended && type === "available"
              ? "bg-destructive/10"
              : "bg-secondary/50",
          )}
        >
          <config.icon
            className={cn(
              "h-4 w-4",
              isSuspended && type === "available"
                ? "text-destructive"
                : "text-muted-foreground",
            )}
          />
        </div>
        <h3 className="text-xs font-bold text-foreground mb-0.5">
          {config.title}
        </h3>
        <p className="text-[0.6rem] text-muted-foreground">{config.desc}</p>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {rides.map((ride) => {
        const isEntrega = ride.type === "entrega";
        const isActionLoading = loadingAction === ride.id;
        return (
          <div
            key={ride.id}
            className={cn(
              "rounded-2xl border p-3 transition-all bg-card",
              type === "available"
                ? "border-primary/20 hover:border-primary/40"
                : "border-border",
            )}
          >
            {/* Header */}
            <div className="flex items-center gap-2 mb-2">
              <Avatar className="h-9 w-9 border-2 border-primary/30">
                <AvatarFallback className="bg-gradient-to-br from-primary to-accent text-primary-foreground text-xs font-bold">
                  {ride.passenger?.name?.charAt(0) || "?"}
                </AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-sm font-semibold text-foreground truncate">
                    {ride.passenger?.name}
                  </span>
                  {ride.passenger?.pontos && (ride.passenger.pontos as number) > 1000 && (
                    <div className="flex items-center gap-0.5">
                      <Star className="h-3 w-3 text-warning fill-warning" />
                      <span className="text-[0.6rem] text-warning">
                        {ride.passenger.pontos as number}
                      </span>
                    </div>
                  )}
                  {type === "available" &&
                    (ride.passenger as any)?.passenger_trust_level && (
                      <PassengerTrustBadge
                        trustLevel={
                          (ride.passenger as any).passenger_trust_level
                        }
                        rating={(ride.passenger as any).passenger_rating}
                        totalRides={
                          (ride.passenger as any).passenger_completed_rides
                        }
                        className="text-[0.6rem]"
                      />
                    )}
                </div>
                <span className="text-xs text-muted-foreground">
                  {(ride.passenger?.neighborhood as string | undefined) ?? (ride.origin as string | undefined)} ·{" "}
                  {type === "history"
                    ? formatDate(ride.updated_at ?? ride.created_at ?? new Date().toISOString())
                    : formatRelative(ride.created_at ?? new Date().toISOString())}
                </span>
              </div>
              <Badge
                className={cn(
                  "text-[0.6rem] font-semibold px-2 py-0.5 rounded-full",
                  isEntrega
                    ? "bg-warning/20 text-warning border border-warning/30"
                    : "bg-primary/20 text-primary border border-primary/30",
                )}
              >
                {isEntrega ? (
                  <Package className="h-3 w-3 mr-1" />
                ) : (
                  <Car className="h-3 w-3 mr-1" />
                )}
                {isEntrega ? "Entrega" : "Viagem"}
              </Badge>
            </div>

            {/* Route */}
            <div className="flex items-start gap-2 mb-2">
              <div className="mt-1 flex flex-col items-center">
                <div className="w-2 h-2 rounded-full bg-primary" />
                <div className="w-0.5 h-5 bg-gradient-to-b from-primary/50 to-warning/50" />
                <div className="w-2 h-2 rounded-full bg-warning" />
              </div>
              <div className="flex-1 space-y-1.5">
                <div>
                  <p className="text-[0.6rem] text-muted-foreground">Origem</p>
                  <p className="text-sm text-foreground font-medium">
                    {ride.origin}
                  </p>
                </div>
                <div>
                  <p className="text-[0.6rem] text-muted-foreground">Destino</p>
                  <p className="text-sm text-foreground font-medium">
                    {ride.destination}
                  </p>
                </div>
              </div>
            </div>

            {/* Info */}
            <div className="flex items-center gap-3 mb-2 text-xs text-muted-foreground">
              <div className="flex items-center gap-1">
                <Clock className="h-3.5 w-3.5 text-primary" />
                {ride.departure_time ? formatTime(ride.departure_time as string) : formatRelative(ride.created_at ?? new Date().toISOString())}
              </div>
              <div className="flex items-center gap-1">
                <DollarSign className="h-3.5 w-3.5 text-success" />
                <span className="text-success font-bold text-sm">
                  R$ {((ride.final_price ?? ride.suggested_price) != null ? (ride.final_price ?? ride.suggested_price) : 0).toFixed(2)}
                </span>
              </div>
              {ride.payment_method && (
                <Badge className="bg-secondary/50 text-muted-foreground text-[0.6rem] px-2 rounded-full border border-border">
                  {ride.payment_method === PAYMENT_METHOD.PIX
                    ? "💳 Pix"
                    : "💵 Dinheiro"}
                </Badge>
              )}
            </div>

            {ride.observation && (
              <div className="mb-2 px-2 py-1.5 rounded-lg bg-secondary/50 border border-border">
                <p className="text-xs text-muted-foreground italic">
                  "{ride.observation as string}"
                </p>
              </div>
            )}

            {/* Actions — U1: Loading states */}
            {type === "available" && onAccept && (
              <Button
                onClick={() => handleAction(onAccept, ride.id)}
                disabled={isActionLoading}
                className="w-full bg-gradient-to-r from-primary to-accent hover:from-primary/90 hover:to-accent/90 text-primary-foreground font-semibold rounded-xl h-10 shadow-lg shadow-primary/20"
              >
                {isActionLoading ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <Car className="h-4 w-4 mr-2" />
                )}
                {isActionLoading ? "Aceitando..." : "Aceitar Corrida"}
              </Button>
            )}

            {type === RIDE_STATUS.ACCEPTED && (
              <div className="space-y-2">
                <div className="grid grid-cols-2 gap-2">
                  <Button
                    size="sm"
                    onClick={() => {
                      setSelectedRide(ride);
                      setChatOpen(true);
                    }}
                    className="bg-primary/15 text-primary hover:bg-primary/25 rounded-xl text-xs h-9"
                  >
                    <MessageCircle className="h-3.5 w-3.5 mr-1.5" /> Chat
                  </Button>
                  {ride.passenger?.phone && (
                    <Button
                      size="sm"
                      onClick={() =>
                        window.open(`tel:${ride.passenger?.phone as string}`, "_self")
                      }
                      className="bg-success/15 text-success hover:bg-success/25 rounded-xl text-xs h-9"
                    >
                      <Phone className="h-3.5 w-3.5 mr-1.5" /> Ligar
                    </Button>
                  )}
                </div>
                <div className="grid grid-cols-2 gap-2">
                  {ride.status === RIDE_STATUS.DRIVER_ASSIGNED && onStart && (
                    <Button
                      onClick={() => handleAction(onStart, ride.id)}
                      disabled={isActionLoading}
                      className="bg-success/15 text-success hover:bg-success/25 rounded-xl text-xs h-9"
                    >
                      {isActionLoading ? (
                        <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                      ) : (
                        <Play className="h-3.5 w-3.5 mr-1.5" />
                      )}
                      Iniciar
                    </Button>
                  )}
                  {ride.status === RIDE_STATUS.IN_PROGRESS && onComplete && (
                    <Button
                      onClick={() => handleAction(onComplete, ride.id, ride)}
                      disabled={isActionLoading}
                      className="bg-success/15 text-success hover:bg-success/25 rounded-xl text-xs h-9"
                    >
                      {isActionLoading ? (
                        <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                      ) : (
                        <CheckCircle2 className="h-3.5 w-3.5 mr-1.5" />
                      )}
                      Concluir
                    </Button>
                  )}
                  {onCancel && (
                    <Button
                      onClick={() => handleAction(onCancel, ride.id)}
                      disabled={isActionLoading}
                      variant="outline"
                      className="border-destructive/30 text-destructive hover:bg-destructive/10 rounded-xl text-xs h-9"
                    >
                      {isActionLoading ? (
                        <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                      ) : (
                        <XCircle className="h-3.5 w-3.5 mr-1.5" />
                      )}
                      Cancelar
                    </Button>
                  )}
                </div>
              </div>
            )}

            {type === "history" && ride.status === RIDE_STATUS.COMPLETED && (
              <div className="flex items-center justify-center gap-2 py-2 rounded-xl bg-success/10 border border-success/20">
                <CheckCircle2 className="h-3.5 w-3.5 text-success" />
                <span className="text-xs text-success font-semibold">
                  Concluída
                </span>
              </div>
            )}
          </div>
        );
      })}

      {/* Chat Dialog */}
      {selectedRide && activeProfile && (
        <RideChatDialog
          open={chatOpen}
          onOpenChange={setChatOpen}
          rideId={selectedRide.id}
          userId={activeProfile.id}
          otherUserName={(selectedRide.passenger?.name as string | undefined) || "Passageiro"}
          isDriver={true}
        />
      )}
    </div>
  );
}

﻿/**
 * AUTO DISPATCH SERVICE - Dispatch Automático de Corridas
 * 
 * Responsabilidades:
 * - Buscar motoristas elegíveis automaticamente
 * - Oferecer corrida sequencialmente (não broadcast)
 * - Timeout por motorista
 * - Retry para próximo motorista
 * - Expiração se ninguém aceitar
 * - Auditoria completa do processo
 */

import { logger } from "@/shared/utils/logger";
import { realtimeService } from "@/core/realtime/services/RealtimeService";
import { RIDE_STATE, type RideState } from "./RideStateMachine";
import { RideDispatchService } from "./RideDispatchService";
import {
  getRideDispatchData,
  getRideById,
} from "../services/mobility.queries";
import { updateRideIfStatusIn } from "../services/mobility.mutations";
import { mobilityAuditService } from "../services/MobilityAuditService";
import { TIMEOUTS, BUSINESS_RULES, REALTIME_CHANNELS } from "../constants";

// ============================================
// CONFIGURAÇÕES (Migradas para constants)
// ============================================

const CONFIG = {
  OFFER_TIMEOUT_SECONDS: TIMEOUTS.OFFER_TIMEOUT_SECONDS,
  MAX_RETRY_ATTEMPTS: BUSINESS_RULES.MAX_RETRY_ATTEMPTS,
  TOTAL_TIMEOUT_MINUTES: TIMEOUTS.TOTAL_TIMEOUT_MINUTES,
  SEARCH_RADIUS_KM: BUSINESS_RULES.SEARCH_RADIUS_KM,
};

// ============================================
// TIPOS
// ============================================

interface DispatchAttempt {
  rideId: string;
  driverProfileId: string;
  attemptNumber: number;
  offeredAt: string;
  timeoutAt: string;
  status: 'pending' | 'accepted' | 'timeout' | 'rejected';
  respondedAt?: string;
}

interface DispatchResult {
  success: boolean;
  rideId: string;
  driverProfileId?: string;
  totalAttempts: number;
  reason?: 'accepted' | 'expired' | 'no_drivers' | 'error';
  error?: string;
}

interface DispatchRideData {
  id: string;
  status: string;
  passenger_profile_id?: string | null;
  pickup_address_id?: string | null;
  pickup_location_id?: string | null;
  ride_mode?: string | null;
  created_at: string;
  pickup_address?: {
    latitude?: number | null;
    longitude?: number | null;
  } | null;
}

// ============================================
// AUTO DISPATCH SERVICE
// ============================================

export class AutoDispatchService {
  private static activeDispatches = new Map<string, NodeJS.Timeout>();

  /**
   * Inicia dispatch automático para uma corrida
   */
  static async startDispatch(rideId: string): Promise<DispatchResult> {
    try {
      logger.info('AutoDispatch: Starting', { rideId });

      // Buscar dados da corrida via SSOT
      const ride = await getRideDispatchData(rideId) as DispatchRideData | null;
      if (!ride) {
        throw new Error('Ride not found');
      }

      // Validar estado
      if (ride.status !== RIDE_STATE.SEARCHING_DRIVER) {
        return {
          success: false,
          rideId,
          totalAttempts: 0,
          reason: 'error',
          error: `Invalid state for dispatch: ${ride.status}`,
        };
      }

      // Verificar timeout total
      const createdAt = new Date(ride.created_at);
      const now = new Date();
      const minutesElapsed = (now.getTime() - createdAt.getTime()) / (1000 * 60);
      
      if (minutesElapsed > CONFIG.TOTAL_TIMEOUT_MINUTES) {
        await this.expireRide(rideId, 'Total timeout exceeded');
        return {
          success: false,
          rideId,
          totalAttempts: 0,
          reason: 'expired',
        };
      }

      // Buscar coordenadas de origem
      const pickupLat = ride.pickup_address?.latitude;
      const pickupLng = ride.pickup_address?.longitude;

      if (!pickupLat || !pickupLng) {
        throw new Error('Pickup coordinates not found');
      }

      const rideMode = ride.ride_mode === 'motoboy' ? 'motoboy' : 'ride';

      // Buscar motoristas elegíveis
      const eligibleDrivers = await RideDispatchService.findEligibleDrivers(
        rideId,
        pickupLat,
        pickupLng,
        CONFIG.SEARCH_RADIUS_KM,
        rideMode,
        ride.pickup_location_id ?? null
      );

      if (eligibleDrivers.length === 0) {
        await this.expireRide(rideId, 'No eligible drivers found');
        return {
          success: false,
          rideId,
          totalAttempts: 0,
          reason: 'no_drivers',
        };
      }

      logger.info('AutoDispatch: Found eligible drivers', {
        rideId,
        count: eligibleDrivers.length,
      });

      // Tentar oferecer para motoristas sequencialmente
      const maxAttempts = Math.min(eligibleDrivers.length, CONFIG.MAX_RETRY_ATTEMPTS);
      
      for (let i = 0; i < maxAttempts; i++) {
        const driver = eligibleDrivers[i];
        const attemptNumber = i + 1;

        logger.info('AutoDispatch: Offering to driver', {
          rideId,
          driverProfileId: driver.profileId,
          attemptNumber,
          distance: driver.distance,
        });

        // Registrar tentativa
        await this.logDispatchAttempt({
          rideId,
          driverProfileId: driver.profileId,
          attemptNumber,
          offeredAt: new Date().toISOString(),
          timeoutAt: new Date(Date.now() + CONFIG.OFFER_TIMEOUT_SECONDS * 1000).toISOString(),
          status: 'pending',
        });

        // Atribuir motorista
        const assignResult = await RideDispatchService.assignDriver(
          rideId,
          driver.profileId,
          RIDE_STATE.SEARCHING_DRIVER
        );

        if (!assignResult.success) {
          logger.warn('AutoDispatch: Failed to assign driver', {
            rideId,
            driverProfileId: driver.profileId,
            error: assignResult.error,
          });
          continue;
        }

        // Enviar notificação realtime para motorista
        await this.notifyDriver(rideId, driver.profileId);

        // Aguardar aceite ou timeout
        const accepted = await this.waitForAcceptance(
          rideId,
          driver.profileId,
          CONFIG.OFFER_TIMEOUT_SECONDS
        );

        if (accepted) {
          // Sucesso!
          await this.updateDispatchAttempt(rideId, driver.profileId, {
            status: 'accepted',
            respondedAt: new Date().toISOString(),
          });

          logger.info('AutoDispatch: Driver accepted', {
            rideId,
            driverProfileId: driver.profileId,
            attemptNumber,
          });

          return {
            success: true,
            rideId,
            driverProfileId: driver.profileId,
            totalAttempts: attemptNumber,
            reason: 'accepted',
          };
        }

        // Timeout - tentar próximo motorista
        await this.updateDispatchAttempt(rideId, driver.profileId, {
          status: 'timeout',
          respondedAt: new Date().toISOString(),
        });

        logger.info('AutoDispatch: Driver timeout, trying next', {
          rideId,
          driverProfileId: driver.profileId,
          attemptNumber,
        });

        // Voltar para searching_driver para tentar próximo
        await updateRideIfStatusIn(
          rideId,
          {
            status: RIDE_STATE.SEARCHING_DRIVER,
            driver_profile_id: null,
            updated_at: new Date().toISOString(),
          },
          [RIDE_STATE.DRIVER_ASSIGNED],
        );
      }

      // Nenhum motorista aceitou
      await this.expireRide(rideId, 'No driver accepted after all attempts');
      
      return {
        success: false,
        rideId,
        totalAttempts: maxAttempts,
        reason: 'expired',
      };
    } catch (error) {
      logger.error('AutoDispatch: Error', error as Error, { rideId });
      return {
        success: false,
        rideId,
        totalAttempts: 0,
        reason: 'error',
        error: (error as Error).message,
      };
    }
  }

  /**
   * Aguarda aceite do motorista ou timeout
   */
  private static async waitForAcceptance(
    rideId: string,
    driverProfileId: string,
    timeoutSeconds: number
  ): Promise<boolean> {
    const startTime = Date.now();
    const timeoutMs = timeoutSeconds * 1000;

    while (Date.now() - startTime < timeoutMs) {
      // Verificar se motorista aceitou
      const ride = await getRideById(rideId) as {
        status?: string;
        driver_profile_id?: string | null;
      } | null;

      if (ride?.status === RIDE_STATE.DRIVER_ACCEPTED && 
          ride?.driver_profile_id === driverProfileId) {
        return true;
      }

      // Verificar se corrida foi cancelada ou mudou de estado
      if (ride?.status !== RIDE_STATE.DRIVER_ASSIGNED) {
        return false;
      }

      // Aguardar antes de verificar novamente
      await new Promise(resolve => setTimeout(resolve, 1000));
    }

    return false;
  }

  /**
   * Expira corrida por falta de motorista
   */
  private static async expireRide(rideId: string, reason: string): Promise<void> {
    try {
      await updateRideIfStatusIn(
        rideId,
        {
          status: RIDE_STATE.EXPIRED,
          updated_at: new Date().toISOString(),
        },
        [RIDE_STATE.SEARCHING_DRIVER, RIDE_STATE.DRIVER_ASSIGNED],
      );

      await mobilityAuditService.logRideStateChange({
        rideId,
        fromState: RIDE_STATE.SEARCHING_DRIVER,
        toState: RIDE_STATE.EXPIRED,
        changedBy: 'system',
        reason,
      });

      // Notificar passageiro
      await this.notifyPassenger(rideId, 'expired');

      logger.info('AutoDispatch: Ride expired', { rideId, reason });
    } catch (error) {
      logger.error('AutoDispatch: Error expiring ride', error as Error, { rideId });
    }
  }

  /**
   * Registra tentativa de dispatch
   */
  private static async logDispatchAttempt(attempt: DispatchAttempt): Promise<void> {
    try {
      await mobilityAuditService.logDispatchAttempt({
        rideId: attempt.rideId,
        driverProfileId: attempt.driverProfileId,
        attemptNumber: attempt.attemptNumber,
        offeredAt: attempt.offeredAt,
        timeoutAt: attempt.timeoutAt,
        status: attempt.status,
      });
    } catch (error) {
      logger.error('AutoDispatch: Error logging attempt', error as Error, attempt);
    }
  }

  /**
   * Atualiza tentativa de dispatch
   */
  private static async updateDispatchAttempt(
    rideId: string,
    driverProfileId: string,
    updates: Partial<DispatchAttempt>
  ): Promise<void> {
    try {
      await mobilityAuditService.updateLatestDispatchAttempt(rideId, driverProfileId, {
        status: updates.status,
        respondedAt: updates.respondedAt,
      });
    } catch (error) {
      logger.error('AutoDispatch: Error updating attempt', error as Error, {
        rideId,
        driverProfileId,
      });
    }
  }

  /**
   * Notifica motorista sobre nova corrida
   */
  private static async notifyDriver(rideId: string, driverProfileId: string): Promise<void> {
    try {
      await realtimeService.sendBroadcast(
        REALTIME_CHANNELS.driver(driverProfileId),
        "ride_offered",
        { rideId, offeredAt: new Date().toISOString() },
      );
    } catch (error) {
      logger.error('AutoDispatch: Error notifying driver', error as Error, {
        rideId,
        driverProfileId,
      });
    }
  }

  /**
   * Notifica passageiro sobre mudança de estado
   */
  private static async notifyPassenger(rideId: string, event: string): Promise<void> {
    try {
      const ride = await getRideDispatchData(rideId) as DispatchRideData | null;

      if (ride?.passenger_profile_id) {
        await realtimeService.sendBroadcast(
          REALTIME_CHANNELS.passenger(ride.passenger_profile_id),
          `ride_${event}`,
          { rideId, timestamp: new Date().toISOString() },
        );
      }
    } catch (error) {
      logger.error('AutoDispatch: Error notifying passenger', error as Error, { rideId });
    }
  }

  /**
   * Cancela dispatch ativo
   */
  static cancelDispatch(rideId: string): void {
    const timer = this.activeDispatches.get(rideId);
    if (timer) {
      clearTimeout(timer);
      this.activeDispatches.delete(rideId);
      logger.info('AutoDispatch: Cancelled', { rideId });
    }
  }
}

﻿/**
 * Mobility Rollout Service
 *
 * Verifica se o modulo mobility esta ativo no territorio corrente.
 */

import { RolloutService } from '@/core/rollout/services/RolloutService';
import { createRolloutRepository } from '@/core/rollout/repositories/createRolloutRepository';
import { createLocationRepository } from '@/core/location/repositories/createLocationRepository';
import { mobilityLocationService } from './MobilityLocationService';
import { ModuleKey, RolloutStatus } from '@/core/rollout/types';
import type { EffectiveRollout } from '@/core/rollout/types';

const MOTOBOY_ENABLED_CONFIG_KEY = 'motoboy_enabled';
const DEFAULT_MOTOBOY_ENABLED = true;

function isObjectRecord(
  value: Record<string, unknown> | null
): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

export class MobilityRolloutService {
  private rolloutService: RolloutService;

  constructor() {
    this.rolloutService = new RolloutService(
      createRolloutRepository(),
      createLocationRepository()
    );
  }

  /**
   * Verifica se o modulo mobility esta ativo para o location informado.
   * Se nao for informado, usa o contexto de localizacao ativo.
   */
  async isMobilityActive(locationId?: string | null): Promise<boolean> {
    const targetLocationId = locationId ?? mobilityLocationService.getActiveLocationId();

    if (!targetLocationId) {
      return false;
    }

    try {
      const result = await this.rolloutService.isModuleActive({
        module_key: ModuleKey.MOBILITY,
        location_id: targetLocationId,
      });

      return result.is_active;
    } catch {
      return false;
    }
  }

  /**
   * Obtem rollout efetivo do mobility na localizacao atual.
   */
  async getMobilityRollout(): Promise<EffectiveRollout | null> {
    const locationId = mobilityLocationService.getActiveLocationId();
    return this.getMobilityRolloutForLocation(locationId);
  }

  /**
   * Obtem rollout efetivo do mobility para uma localizacao explicita.
   */
  async getMobilityRolloutForLocation(
    locationId: string | null | undefined
  ): Promise<EffectiveRollout | null> {
    if (!locationId) {
      return null;
    }

    try {
      const result = await this.rolloutService.getEffectiveRollout({
        module_key: ModuleKey.MOBILITY,
        location_id: locationId,
      });

      return result.effective_rollout;
    } catch {
      return null;
    }
  }

  /**
   * Verifica acesso ao modulo mobility.
   */
  async checkAccess(): Promise<{ blocked: boolean; reason?: string }> {
    if (!mobilityLocationService.hasActiveLocation()) {
      return {
        blocked: true,
        reason: 'Localizacao nao selecionada',
      };
    }

    const isActive = await this.isMobilityActive();
    if (!isActive) {
      return {
        blocked: true,
        reason: 'Mobilidade nao esta disponivel nesta localizacao',
      };
    }

    return { blocked: false };
  }

  /**
   * Obtem configuracao do mobility para a localizacao atual.
   */
  async getMobilityConfig(): Promise<Record<string, unknown> | null> {
    const locationId = mobilityLocationService.getActiveLocationId();
    return this.getMobilityConfigForLocation(locationId);
  }

  /**
   * Obtem configuracao do mobility para uma localizacao explicita.
   */
  async getMobilityConfigForLocation(
    locationId: string | null | undefined
  ): Promise<Record<string, unknown> | null> {
    if (!locationId) {
      return null;
    }

    try {
      const result = await this.rolloutService.getModuleConfig({
        module_key: ModuleKey.MOBILITY,
        location_id: locationId,
      });

      return isObjectRecord(result.config) ? result.config : null;
    } catch {
      return null;
    }
  }

  /**
   * Verifica se o modo motoboy esta habilitado para a localizacao.
   */
  async isMotoboyEnabled(locationId?: string | null): Promise<boolean> {
    const targetLocationId = locationId ?? mobilityLocationService.getActiveLocationId();

    if (!targetLocationId) {
      return false;
    }

    const config = await this.getMobilityConfigForLocation(targetLocationId);
    if (!config) {
      return DEFAULT_MOTOBOY_ENABLED;
    }

    const rawValue = config[MOTOBOY_ENABLED_CONFIG_KEY];
    if (typeof rawValue !== 'boolean') {
      return DEFAULT_MOTOBOY_ENABLED;
    }

    return rawValue;
  }

  /**
   * Define o toggle de motoboy no config oficial do rollout mobility.
   */
  async setMotoboyEnabled(locationId: string, enabled: boolean): Promise<void> {
    const effective = await this.rolloutService.getEffectiveRollout({
      module_key: ModuleKey.MOBILITY,
      location_id: locationId,
    });

    const currentConfig = isObjectRecord(effective.effective_rollout.config)
      ? effective.effective_rollout.config
      : {};

    const nextConfig = {
      ...currentConfig,
      [MOTOBOY_ENABLED_CONFIG_KEY]: enabled,
    };

    await this.rolloutService.setModuleRollout({
      module_key: ModuleKey.MOBILITY,
      location_id: locationId,
      status: effective.effective_rollout.status,
      config: nextConfig,
    });
  }

  /**
   * Liga/desliga o modulo de mobilidade para uma localizacao.
   */
  async setMobilityEnabled(locationId: string, enabled: boolean): Promise<void> {
    const effective = await this.rolloutService.getEffectiveRollout({
      module_key: ModuleKey.MOBILITY,
      location_id: locationId,
    });

    const currentConfig = isObjectRecord(effective.effective_rollout.config)
      ? effective.effective_rollout.config
      : {};

    await this.rolloutService.setModuleRollout({
      module_key: ModuleKey.MOBILITY,
      location_id: locationId,
      status: enabled ? RolloutStatus.ACTIVE : RolloutStatus.INACTIVE,
      config: currentConfig,
    });
  }
}

