interface ProfileHeaderCompactProps {
  activeProfile: MultiProfileRecord | null;
  profile: MultiProfileRecord | null;
  allProfiles?: MultiProfileRecord[];
  userEmail: string;
  accountSnapshot: ProfileAccountSnapshot;
  identity: any;
  context: any;
