/**
 * HeroBannerCarousel - Carrossel de banners promocionais para hero section
 * 
 * Features:
 * - Auto-play com intervalo configurável
 * - Navegação por dots
 * - Navegação por setas (opcional)
 * - Transições suaves
 * - Responsivo
 * - Suporte a imagem + texto
 */

import { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Button } from '@/shared/components/ui/button';

export interface HeroBanner {
  id: string;
  image: string;
  title: string;
  subtitle?: string;
  cta?: {
    label: string;
    onClick: () => void;
  };
  textPosition?: 'left' | 'center' | 'right';
  overlayOpacity?: number;
}

export interface HeroBannerCarouselProps {
  banners: HeroBanner[];
  autoPlayInterval?: number;
  showArrows?: boolean;
  showDots?: boolean;
  height?: string;
  heightMd?: string;
  heightLg?: string;
}

const slideVariants = {
  enter: (direction: number) => ({
    x: direction > 0 ? 1000 : -1000,
    opacity: 0,
  }),
  center: {
    zIndex: 1,
    x: 0,
    opacity: 1,
  },
  exit: (direction: number) => ({
    zIndex: 0,
    x: direction < 0 ? 1000 : -1000,
    opacity: 0,
  }),
};

export function HeroBannerCarousel({
  banners,
  autoPlayInterval = 5000,
  showArrows = true,
  showDots = true,
  height = '400px',
  heightMd,
  heightLg,
}: HeroBannerCarouselProps) {
  const [[page, direction], setPage] = useState([0, 0]);
  const [isPaused, setIsPaused] = useState(false);

  const currentBanner = banners[page];

  const paginate = useCallback((newDirection: number) => {
    setPage([
      (page + newDirection + banners.length) % banners.length,
      newDirection,
    ]);
  }, [page, banners.length]);

  const goToSlide = useCallback((index: number) => {
    const newDirection = index > page ? 1 : -1;
    setPage([index, newDirection]);
  }, [page]);

  // Auto-play
  useEffect(() => {
    if (isPaused || banners.length <= 1) return;

    const interval = setInterval(() => {
      paginate(1);
    }, autoPlayInterval);

    return () => clearInterval(interval);
  }, [page, isPaused, autoPlayInterval, banners.length, paginate]);

  if (banners.length === 0) return null;

  const textAlignClass = 
    currentBanner.textPosition === 'center' ? 'items-center text-center' :
    currentBanner.textPosition === 'right' ? 'items-end text-right' :
    'items-start text-left';

  // Estilo responsivo para altura
  const heightStyle = {
    '--height-base': height,
    '--height-md': heightMd || height,
    '--height-lg': heightLg || heightMd || height,
  } as React.CSSProperties;

  return (
    <div
      className="relative w-full overflow-hidden rounded-xl [height:var(--height-base)] md:[height:var(--height-md)] lg:[height:var(--height-lg)]"
      style={heightStyle}
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      <AnimatePresence initial={false} custom={direction}>
        <motion.div
          key={page}
          custom={direction}
          variants={slideVariants}
          initial="enter"
          animate="center"
          exit="exit"
          transition={{
            x: { type: 'spring', stiffness: 300, damping: 30 },
            opacity: { duration: 0.2 },
          }}
          className="absolute inset-0"
        >
          {/* Background Image */}
          <div className="absolute inset-0">
            <img
              src={currentBanner.image}
              alt={currentBanner.title}
              className="w-full h-full object-cover"
            />
            {/* Overlay mais claro */}
            <div className="absolute inset-0 bg-gradient-to-r from-background/60 via-background/40 to-background/60" />
            <div className="absolute inset-0 bg-gradient-to-t from-background/50 via-transparent to-background/30" />
          </div>

          {/* Content */}
          <div className="relative h-full flex flex-col justify-center items-center px-6 md:px-12 lg:px-16">
            <div className={`flex flex-col ${textAlignClass} max-w-3xl w-full`}>
              <motion.h2
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="text-2xl sm:text-3xl md:text-4xl lg:text-5xl font-bold text-foreground mb-3 leading-tight drop-shadow-2xl [text-shadow:_0_2px_12px_rgb(0_0_0_/_80%)]"
              >
                {currentBanner.title}
              </motion.h2>

              {currentBanner.subtitle && (
                <motion.p
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.3 }}
                  className="text-sm md:text-base text-muted-foreground mb-6 drop-shadow-xl [text-shadow:_0_1px_8px_rgb(0_0_0_/_70%)]"
                >
                  {currentBanner.subtitle}
                </motion.p>
              )}

              {currentBanner.cta && (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.4 }}
                >
                  <Button
                    onClick={currentBanner.cta.onClick}
                    size="lg"
                    className="h-12 px-8 rounded-xl font-semibold shadow-lg shadow-primary/20 hover:shadow-primary/30 hover:scale-105 transition-all duration-300"
                  >
                    {currentBanner.cta.label}
                  </Button>
                </motion.div>
              )}
            </div>
          </div>
        </motion.div>
      </AnimatePresence>

      {/* Navigation Arrows */}
      {showArrows && banners.length > 1 && (
        <>
          <button
            onClick={() => paginate(-1)}
            className="absolute left-4 top-1/2 -translate-y-1/2 z-10 bg-background/90 backdrop-blur-md hover:bg-background text-foreground rounded-full p-3 transition-all shadow-xl hover:scale-110 hover:shadow-2xl"
            aria-label="Banner anterior"
          >
            <ChevronLeft className="h-6 w-6" />
          </button>
          <button
            onClick={() => paginate(1)}
            className="absolute right-4 top-1/2 -translate-y-1/2 z-10 bg-background/90 backdrop-blur-md hover:bg-background text-foreground rounded-full p-3 transition-all shadow-xl hover:scale-110 hover:shadow-2xl"
            aria-label="Próximo banner"
          >
            <ChevronRight className="h-6 w-6" />
          </button>
        </>
      )}

      {/* Dots Navigation */}
      {showDots && banners.length > 1 && (
        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-10 flex gap-2">
          {banners.map((_, index) => (
            <button
              key={index}
              onClick={() => goToSlide(index)}
              className={`h-2 rounded-full transition-all ${
                index === page
                  ? 'w-8 bg-primary'
                  : 'w-2 bg-background/60 hover:bg-background/80'
              }`}
              aria-label={`Ir para banner ${index + 1}`}
            />
          ))}
        </div>
      )}
    </div>
  );
}

import React from "react";
import { useEffect, useState } from "react";
import { WifiOff, Wifi, Download } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { DRIVER_STATUS } from "@/shared/types/constants";
import { logger } from "@/shared/utils/logger";

export function OfflineIndicator() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [showIndicator, setShowIndicator] = useState(false);

  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      setShowIndicator(true);

      // Esconder após 3 segundos
      setTimeout(() => setShowIndicator(false), 3000);
    };

    const handleOffline = () => {
      setIsOnline(false);
      setShowIndicator(true);
    };

    window.addEventListener(DRIVER_STATUS.ONLINE, handleOnline);
    window.addEventListener(DRIVER_STATUS.OFFLINE, handleOffline);

    // Mostrar indicador se já estiver offline
    if (!navigator.onLine) {
      setShowIndicator(true);
    }

    return () => {
      window.removeEventListener(DRIVER_STATUS.ONLINE, handleOnline);
      window.removeEventListener(DRIVER_STATUS.OFFLINE, handleOffline);
    };
  }, []);

  return (
    <AnimatePresence>
      {showIndicator && (
        <motion.div
          initial={{ y: -100, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: -100, opacity: 0 }}
          transition={{ type: "spring", stiffness: 300, damping: 30 }}
          className={`fixed top-4 left-1/2 -translate-x-1/2 z-50 px-4 py-2 rounded-full shadow-lg flex items-center gap-2 ${
            isOnline ? "bg-green-500 text-white" : "bg-red-500 text-white"
          }`}
        >
          {isOnline ? (
            <>
              <Wifi className="w-4 h-4" />
              <span className="text-sm font-medium">Conexão restaurada</span>
            </>
          ) : (
            <>
              <WifiOff className="w-4 h-4" />
              <span className="text-sm font-medium">Você está offline</span>
            </>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

export function OfflineBanner() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener(DRIVER_STATUS.ONLINE, handleOnline);
    window.addEventListener(DRIVER_STATUS.OFFLINE, handleOffline);

    return () => {
      window.removeEventListener(DRIVER_STATUS.ONLINE, handleOnline);
      window.removeEventListener(DRIVER_STATUS.OFFLINE, handleOffline);
    };
  }, []);

  if (isOnline) return null;

  return (
    <div className="bg-yellow-500/10 border-b border-yellow-500/30 px-4 py-2">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <div className="flex items-center gap-2">
          <WifiOff className="w-4 h-4 text-yellow-500" />
          <span className="text-sm text-yellow-500 font-medium">
            Modo Offline - Alguns recursos podem estar limitados
          </span>
        </div>
        <button
          onClick={() => window.location.reload()}
          className="text-xs text-yellow-500 hover:text-yellow-400 underline"
        >
          Tentar reconectar
        </button>
      </div>
    </div>
  );
}

export function OfflineDataStatus() {
  const [hasCachedData, setHasCachedData] = useState(false);
  const [cacheSize, setCacheSize] = useState<string>("0 KB");

  useEffect(() => {
    checkCachedData();
  }, []);

  const checkCachedData = async () => {
    try {
      const cache = await caches.open("localconnect-critical-v1");
      const keys = await cache.keys();

      setHasCachedData(keys.length > 0);

      // Estimar tamanho do cache
      if ("storage" in navigator && "estimate" in navigator.storage) {
        const estimate = await navigator.storage.estimate();
        const usage = estimate.usage || 0;
        setCacheSize(formatBytes(usage));
      }
    } catch (error) {
      logger.error("Error verify cache:", error);
    }
  };

  const formatBytes = (bytes: number): string => {
    if (bytes === 0) return "0 KB";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + " " + sizes[i];
  };

  return (
    <div className="flex items-center gap-2 text-sm text-muted-foreground">
      <Download className="w-4 h-4" />
      <span>
        {hasCachedData ? (
          <>Dados offline: {cacheSize}</>
        ) : (
          <>Nenhum dado offline salvo</>
        )}
      </span>
    </div>
  );
}

