/**
 * Constantes para Tipos de Posts da Comunidade
 *
 * Centraliza todos os tipos de posts e suas configurações
 * para evitar magic strings e facilitar manutenção
 *
 * @version 1.0.0
 */

// Tipos de Posts
export const POST_TYPES = {
  DISCUSSAO: "discussao",
  RECOMENDACAO: "recomendacao",
  ENQUETE: "enquete",
  PERGUNTA: "pergunta",
} as const;

export type PostType = (typeof POST_TYPES)[keyof typeof POST_TYPES];

// Labels dos Tipos de Posts
export const POST_TYPE_LABELS: Record<PostType, string> = {
  [POST_TYPES.DISCUSSAO]: "Discussão",
  [POST_TYPES.RECOMENDACAO]: "Recomendação",
  [POST_TYPES.ENQUETE]: "Enquete",
  [POST_TYPES.PERGUNTA]: "Pergunta",
};

// Ícones dos Tipos de Posts (emoji)
export const POST_TYPE_ICONS: Record<PostType, string> = {
  [POST_TYPES.DISCUSSAO]: "💬",
  [POST_TYPES.RECOMENDACAO]: "⭐",
  [POST_TYPES.ENQUETE]: "📊",
  [POST_TYPES.PERGUNTA]: "❓",
};

// Cores dos Tipos de Posts
export const POST_TYPE_COLORS: Record<PostType, string> = {
  [POST_TYPES.DISCUSSAO]: "#3B82F6", // blue-500
  [POST_TYPES.RECOMENDACAO]: "#10B981", // green-500
  [POST_TYPES.ENQUETE]: "#8B5CF6", // purple-500
  [POST_TYPES.PERGUNTA]: "#06B6D4", // cyan-500
};

// Prefixos de Conteúdo
export const POST_CONTENT_PREFIXES = {
  PET_PERDIDO: "PET PERDIDO",
  ENQUETE: "ENQUETE",
  SUGESTAO: "SUGESTÃO",
  DISCUSSAO: "DISCUSSÃO",
  ACHADOS_PERDIDOS: "ACHADOS E PERDIDOS",
  EMERGENCIA: "EMERGÊNCIA",
} as const;

// Regex para detectar prefixos
export const POST_PREFIX_PATTERN = new RegExp(
  `^(${Object.values(POST_CONTENT_PREFIXES).join("|")}):\\s*`,
  "i",
);

// Limites de Conteúdo
export const POST_LIMITS = {
  MIN_CONTENT_LENGTH: 10,
  MAX_CONTENT_LENGTH: 5000,
  MAX_IMAGES: 4,
  MAX_TAGS: 5,
  MAX_TAG_LENGTH: 30,
} as const;

// Tipos de Ordenação
export const POST_SORT_TYPES = {
  RECENT: "recent",
  POPULAR: "popular",
  MOST_COMMENTED: "most_commented",
} as const;

export type PostSortType =
  (typeof POST_SORT_TYPES)[keyof typeof POST_SORT_TYPES];

// Labels de Ordenação
export const POST_SORT_LABELS: Record<PostSortType, string> = {
  [POST_SORT_TYPES.RECENT]: "Mais Recentes",
  [POST_SORT_TYPES.POPULAR]: "Mais Populares",
  [POST_SORT_TYPES.MOST_COMMENTED]: "Mais Comentados",
};

// Validação de Tipo de Post
export function isValidPostType(type: string): type is PostType {
  return Object.values(POST_TYPES).includes(type as PostType);
}

// Validação de Tipo de Ordenação
export function isValidSortType(type: string): type is PostSortType {
  return Object.values(POST_SORT_TYPES).includes(type as PostSortType);
}

import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import { logger } from "@/shared/utils/logger";

type AppointmentStatus = "pending" | "confirmed" | "cancelled" | "completed";

interface Appointment {
  id: string;
  client_name: string;
  client_phone: string;
  client_email?: string;
  service_name: string;
  appointment_date: string;
  appointment_time: string;
  status: AppointmentStatus;
  notes?: string;
  created_at: string;
}

interface UseAppointmentsProps {
  businessId: string;
  businessName: string;
}

export const useAppointments = ({ businessId }: UseAppointmentsProps) => {
  const [appointments, setAppointments] = useState<Appointment[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");

  useEffect(() => {
    const timer = setTimeout(() => {
      setAppointments([]);
      setLoading(false);
    }, 800);

    return () => clearTimeout(timer);
  }, [businessId]);

  const filteredAppointments = appointments.filter((appointment) => {
    const matchesSearch =
      appointment.client_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      appointment.client_phone.includes(searchTerm) ||
      appointment.service_name.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesStatus =
      statusFilter === "all" || appointment.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const updateAppointmentStatus = useCallback(
    async (appointmentId: string, newStatus: Appointment["status"]) => {
      const appointment = appointments.find((apt) => apt.id === appointmentId);
      if (!appointment) {
        logger.warn("Appointment not found", { appointmentId });
        return;
      }

      setAppointments((prev) =>
        prev.map((apt) =>
          apt.id === appointmentId ? { ...apt, status: newStatus } : apt,
        ),
      );

      const statusLabels = {
        pending: "pendente",
        confirmed: "confirmado",
        cancelled: "cancelado",
        completed: "concluido",
      };

      toast.success(`Agendamento ${statusLabels[newStatus]} com sucesso!`);
    },
    [appointments],
  );

  const contactClient = useCallback(
    (appointment: Appointment, method: "whatsapp" | "phone") => {
      if (method === "whatsapp") {
        const message = `Ola ${appointment.client_name}! Sobre seu agendamento de ${appointment.service_name} para ${appointment.appointment_date} as ${appointment.appointment_time}.`;
        window.open(
          `https://wa.me/${appointment.client_phone.replace(/\D/g, "")}?text=${encodeURIComponent(message)}`,
          "_blank",
        );
      } else {
        window.location.href = `tel:${appointment.client_phone}`;
      }
    },
    [],
  );

  return {
    appointments: filteredAppointments,
    loading,
    searchTerm,
    statusFilter,
    setSearchTerm,
    setStatusFilter,
    updateAppointmentStatus,
    contactClient,
  };
};

/**
 * HOOK PROFISSIONAL PARA LOADING STATES
 *
 * Gerenciamento consistente de estados de carregamento.
 * Integrado com error handling e feedback visual.
 */

import { useState, useCallback, useRef, useEffect } from "react";
import { useAsyncError } from "./useAsyncError";

interface LoadingStateOptions {
  minDuration?: number; // Duração mínima do loading (evita flash)
  showToast?: boolean;
  errorMessage?: string;
}

/**
 * Hook para gerenciar loading state
 *
 * @example
 * ```tsx
 * const { loading, withLoading } = useLoadingState();
 *
 * const fetchData = async () => {
 *   const data = await withLoading(async () => {
 *     const posts = await postService.getFeed();
 *     return posts;
 *   });
 *
 *   if (data) {
 *     setPosts(data);
 *   }
 * };
 *
 * return loading ? <Skeleton /> : <Content />;
 * ```
 */
export function useLoadingState(options: LoadingStateOptions = {}) {
  const { minDuration = 0, showToast = true, errorMessage } = options;

  const [loading, setLoading] = useState(false);
  const { handleAsync } = useAsyncError();
  const startTimeRef = useRef<number>(0);

  const withLoading = useCallback(
    async <T>(fn: () => Promise<T>): Promise<T | null> => {
      startTimeRef.current = Date.now();
      setLoading(true);

      try {
        const result = await handleAsync(fn, {
          showToast,
          toastMessage: errorMessage,
        });

        // Garantir duração mínima do loading
        if (minDuration > 0) {
          const elapsed = Date.now() - startTimeRef.current;
          const remaining = minDuration - elapsed;

          if (remaining > 0) {
            await new Promise((resolve) => setTimeout(resolve, remaining));
          }
        }

        return result;
      } finally {
        setLoading(false);
      }
    },
    [handleAsync, minDuration, showToast, errorMessage],
  );

  return {
    loading,
    withLoading,
    setLoading,
  };
}

/**
 * Hook para múltiplos loading states
 *
 * @example
 * ```tsx
 * const { isLoading, startLoading, stopLoading } = useMultipleLoadingStates();
 *
 * const fetchUsers = async () => {
 *   startLoading('users');
 *   const users = await getUsers();
 *   stopLoading('users');
 * };
 *
 * const fetchPosts = async () => {
 *   startLoading('posts');
 *   const posts = await getPosts();
 *   stopLoading('posts');
 * };
 *
 * return (
 *   <>
 *     {isLoading('users') && <UsersSkeleton />}
 *     {isLoading('posts') && <PostsSkeleton />}
 *   </>
 * );
 * ```
 */
export function useMultipleLoadingStates() {
  const [loadingStates, setLoadingStates] = useState<Record<string, boolean>>(
    {},
  );

  const startLoading = useCallback((key: string) => {
    setLoadingStates((prev) => ({ ...prev, [key]: true }));
  }, []);

  const stopLoading = useCallback((key: string) => {
    setLoadingStates((prev) => ({ ...prev, [key]: false }));
  }, []);

  const isLoading = useCallback(
    (key: string) => loadingStates[key] === true,
    [loadingStates],
  );

  const isAnyLoading = useCallback(
    () => Object.values(loadingStates).some((loading) => loading),
    [loadingStates],
  );

  return {
    isLoading,
    isAnyLoading,
    startLoading,
    stopLoading,
    loadingStates,
  };
}

/**
 * Hook para loading state com timeout
 *
 * @example
 * ```tsx
 * const { loading, withLoadingTimeout } = useLoadingTimeout(5000);
 *
 * const fetchData = async () => {
 *   const data = await withLoadingTimeout(async () => {
 *     return await slowAPI();
 *   }, {
 *     onTimeout: () => {
 *       toast.warning('Operação está demorando mais que o esperado...');
 *     }
 *   });
 * };
 * ```
 */
export function useLoadingTimeout(timeoutMs: number = 10000) {
  const [loading, setLoading] = useState(false);
  const [timedOut, setTimedOut] = useState(false);
  const { handleAsync } = useAsyncError();
  const timeoutIdRef = useRef<NodeJS.Timeout | null>(null);

  const withLoadingTimeout = useCallback(
    async <T>(
      fn: () => Promise<T>,
      options?: {
        onTimeout?: () => void;
        showToast?: boolean;
      },
    ): Promise<T | null> => {
      setLoading(true);
      setTimedOut(false);

      // Configurar timeout
      timeoutIdRef.current = setTimeout(() => {
        setTimedOut(true);
        if (options?.onTimeout) {
          options.onTimeout();
        }
      }, timeoutMs);

      try {
        const result = await handleAsync(fn, {
          showToast: options?.showToast ?? true,
        });
        return result;
      } finally {
        if (timeoutIdRef.current) {
          clearTimeout(timeoutIdRef.current);
        }
        setLoading(false);
        setTimedOut(false);
      }
    },
    [handleAsync, timeoutMs],
  );

  // Cleanup
  useEffect(() => {
    return () => {
      if (timeoutIdRef.current) {
        clearTimeout(timeoutIdRef.current);
      }
    };
  }, []);

  return {
    loading,
    timedOut,
    withLoadingTimeout,
  };
}

/**
 * Hook para loading state com progresso
 *
 * @example
 * ```tsx
 * const { loading, progress, withProgress } = useLoadingProgress();
 *
 * const uploadFiles = async (files: File[]) => {
 *   await withProgress(async (updateProgress) => {
 *     for (let i = 0; i < files.length; i++) {
 *       await uploadFile(files[i]);
 *       updateProgress((i + 1) / files.length * 100);
 *     }
 *   });
 * };
 *
 * return (
 *   <>
 *     {loading && <ProgressBar value={progress} />}
 *   </>
 * );
 * ```
 */
export function useLoadingProgress() {
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const { handleAsync } = useAsyncError();

  const withProgress = useCallback(
    async <T>(
      fn: (updateProgress: (value: number) => void) => Promise<T>,
    ): Promise<T | null> => {
      setLoading(true);
      setProgress(0);

      try {
        const result = await handleAsync(
          () => fn((value) => setProgress(Math.min(100, Math.max(0, value)))),
          { showToast: true },
        );

        // Garantir que chegue a 100%
        setProgress(100);

        return result;
      } finally {
        setTimeout(() => {
          setLoading(false);
          setProgress(0);
        }, 300); // Pequeno delay para mostrar 100%
      }
    },
    [handleAsync],
  );

  return {
    loading,
    progress,
    withProgress,
  };
}

import { useState, useEffect, useCallback } from "react";
import { SSOTValidators } from "@/shared/types/constants";
interface SSOTViolation {
  table: string;
  column: string;
  value: string;
  recordId: string;
  timestamp: string;
}

interface SSOTMonitoringData {
  violations: SSOTViolation[];
  totalRecords: number;
  complianceRate: number;
  lastCheck: string;
}

/**
 * Hook para monitoramento SSOT em tempo real
 * Verifica conformidade de dados retornados por queries
 */
export function useSSOTMonitoring() {
  const [data, setData] = useState<SSOTMonitoringData>({
    violations: [],
    totalRecords: 0,
    complianceRate: 100,
    lastCheck: new Date().toISOString(),
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  /**
   * Valida um conjunto de registros contra regras SSOT
   */
  const validateRecords = useCallback(
    (
      records: Record<string, unknown>[],
      table: string,
      validations: { column: string; validator: (val: string) => boolean }[],
    ): SSOTViolation[] => {
      const violations: SSOTViolation[] = [];

      for (const record of records) {
        for (const { column, validator } of validations) {
          const value = record[column];
          if (value && typeof value === "string" && !validator(value)) {
            violations.push({
              table,
              column,
              value,
              recordId: String(record.id || "unknown"),
              timestamp: new Date().toISOString(),
            });
          }
        }
      }

      return violations;
    },
    [],
  );

  /**
   * Analisa dados já carregados para detectar violações SSOT
   * Não faz queries diretas — recebe dados de Services
   */
  const analyzeData = useCallback(
    (
      datasets: {
        table: string;
        records: Record<string, unknown>[];
        validations: { column: string; validator: (val: string) => boolean }[];
      }[],
    ) => {
      setLoading(true);
      setError(null);

      try {
        const allViolations: SSOTViolation[] = [];
        let totalRecords = 0;

        for (const dataset of datasets) {
          totalRecords += dataset.records.length;
          const violations = validateRecords(
            dataset.records,
            dataset.table,
            dataset.validations,
          );
          allViolations.push(...violations);
        }

        const complianceRate =
          totalRecords > 0
            ? Math.round(
                ((totalRecords - allViolations.length) / totalRecords) * 100,
              )
            : 100;

        setData({
          violations: allViolations,
          totalRecords,
          complianceRate,
          lastCheck: new Date().toISOString(),
        });
      } catch (err) {
        setError(err instanceof Error ? err.message : "Erro desconhecido");
      } finally {
        setLoading(false);
      }
    },
    [validateRecords],
  );

  /**
   * Atalho: validações padrão SSOT
   */
  const defaultValidations = {
    rideRequests: [
      { column: "status", validator: SSOTValidators.isValidRideStatus },
      {
        column: "payment_method",
        validator: SSOTValidators.isValidPaymentMethod,
      },
    ],
    profiles: [{ column: "role", validator: SSOTValidators.isValidUserRole }],
    reports: [
      { column: "status", validator: SSOTValidators.isValidReportStatus },
    ],
  };

  return {
    data,
    loading,
    error,
    analyzeData,
    validateRecords,
    defaultValidations,
  };
}

