// Deploy: supabase functions deploy auto-dispatch-ride

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { getAllSecurityHeaders, isOriginAllowed, errorResponse } from '../_shared/security.ts';
import { validateBody, dispatchRideSchema, validationErrorResponse, type DispatchRideBody } from '../_shared/validation.ts';

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

/**
 * CRON_SECRET: segredo dedicado para autenticação de chamadas internas/cron.
 *
 * SSOT: mesmo padrão de `process-timeouts/index.ts`.
 *
 * NUNCA use SUPABASE_SERVICE_ROLE_KEY como token de autenticação HTTP —
 * essa chave tem acesso irrestrito ao banco e não deve trafegar em headers.
 * Configure CRON_SECRET como variável de ambiente separada no Supabase Dashboard.
 */
const CRON_SECRET = Deno.env.get('CRON_SECRET') || '';

// Configurações
const CONFIG = {
  OFFER_TIMEOUT_SECONDS: 30,
  MAX_RETRY_ATTEMPTS: 5,
  TOTAL_TIMEOUT_MINUTES: 10,
  SEARCH_RADIUS_KM: 10,
};

interface DriverEligibility {
  profileId: string;
  distance: number;
  rating: number;
}

function extractBearerToken(req: Request): string | null {
  const authHeader = req.headers.get('authorization');
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null;
  }
  return authHeader.slice(7).trim();
}

/**
 * Valida autenticação da requisição.
 *
 * Aceita:
 * 1. Header `x-cron-secret` com o valor de CRON_SECRET (preferencial)
 * 2. Bearer token igual a CRON_SECRET (compatibilidade com schedulers que
 *    só suportam Authorization header)
 *
 * SSOT: mesmo padrão de `process-timeouts/index.ts`.
 */
function isAuthorized(req: Request): boolean {
  if (!CRON_SECRET) return false;

  const cronHeader = req.headers.get('x-cron-secret') || '';
  const bearerToken = extractBearerToken(req);

  return cronHeader === CRON_SECRET || bearerToken === CRON_SECRET;
}

serve(async (req: Request) => {
  const origin = req.headers.get('origin');
  if (origin && !isOriginAllowed(origin)) {
    return new Response(
      JSON.stringify({ error: 'Origin not allowed' }),
      {
        status: 403,
        headers: {
          ...getAllSecurityHeaders('POST, OPTIONS'),
          'Content-Type': 'application/json',
        },
      },
    );
  }

  if (req.method === 'OPTIONS') {
    return new Response('ok', {
      status: 204,
      headers: getAllSecurityHeaders('POST, OPTIONS'),
    });
  }

  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    return new Response(
      JSON.stringify({ error: 'Function misconfigured: missing Supabase credentials' }),
      { status: 500, headers: getAllSecurityHeaders('POST, OPTIONS') },
    );
  }

  if (!CRON_SECRET) {
    console.error('[AutoDispatch] CRON_SECRET não configurado — requisição bloqueada');
    return new Response(
      JSON.stringify({ error: 'Function misconfigured: CRON_SECRET not set' }),
      { status: 500, headers: getAllSecurityHeaders('POST, OPTIONS') },
    );
  }

  if (!isAuthorized(req)) {
    return new Response(
      JSON.stringify({ error: 'Unauthorized' }),
      {
        status: 401,
        headers: {
          ...getAllSecurityHeaders('POST, OPTIONS'),
          'Content-Type': 'application/json',
        },
      },
    );
  }

  try {
    const rawBody = await req.json();
    const validation = validateBody<DispatchRideBody>(rawBody, dispatchRideSchema);
    if (!validation.ok) {
      return new Response(
        JSON.stringify({ error: 'Validation failed', details: validation.errors }),
        { status: 400, headers: getAllSecurityHeaders() }
      );
    }
    const { rideId } = validation.data!;

    console.log(`[AutoDispatch] Starting for ride: ${rideId}`);

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // Buscar dados da corrida
    const { data: ride, error: rideError } = await supabase
      .from('ride_requests')
      .select(`
        id,
        status,
        created_at,
        ride_mode,
        pickup_address_id,
        addresses!pickup_address_id(latitude, longitude)
      `)
      .eq('id', rideId)
      .single();

    if (rideError || !ride) {
      console.error('[AutoDispatch] Ride not found:', rideError);
      return new Response(
        JSON.stringify({ error: 'Ride not found' }),
        { status: 404, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Validar estado
    if (ride.status !== 'searching_driver') {
      console.log(`[AutoDispatch] Invalid state: ${ride.status}`);
      return new Response(
        JSON.stringify({ error: `Invalid state: ${ride.status}` }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Verificar timeout total
    const createdAt = new Date(ride.created_at);
    const now = new Date();
    const minutesElapsed = (now.getTime() - createdAt.getTime()) / (1000 * 60);
    
    if (minutesElapsed > CONFIG.TOTAL_TIMEOUT_MINUTES) {
      await expireRide(supabase, rideId, 'Total timeout exceeded');
      return new Response(
        JSON.stringify({ success: false, reason: 'expired' }),
        { status: 200, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Buscar coordenadas - addresses é um array, pegar o primeiro elemento
    const addressData = Array.isArray(ride.addresses) ? ride.addresses[0] : ride.addresses;
    const pickupLat = addressData?.latitude;
    const pickupLng = addressData?.longitude;

    if (!pickupLat || !pickupLng) {
      console.error('[AutoDispatch] Missing coordinates');
      return new Response(
        JSON.stringify({ error: 'Missing pickup coordinates' }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Buscar motoristas elegíveis
    const eligibleDrivers = await findEligibleDrivers(
      supabase,
      rideId,
      pickupLat,
      pickupLng,
      ride.ride_mode || 'ride' // Passar ride_mode para filtrar motoristas
    );

    if (eligibleDrivers.length === 0) {
      await expireRide(supabase, rideId, 'No eligible drivers found');
      return new Response(
        JSON.stringify({ success: false, reason: 'no_drivers' }),
        { status: 200, headers: { 'Content-Type': 'application/json' } }
      );
    }

    console.log(`[AutoDispatch] Found ${eligibleDrivers.length} eligible drivers`);

    // Tentar oferecer para motoristas sequencialmente
    const maxAttempts = Math.min(eligibleDrivers.length, CONFIG.MAX_RETRY_ATTEMPTS);
    
    for (let i = 0; i < maxAttempts; i++) {
      const driver = eligibleDrivers[i];
      const attemptNumber = i + 1;

      console.log(`[AutoDispatch] Attempt ${attemptNumber}: offering to ${driver.profileId}`);

      // Registrar tentativa
      await logDispatchAttempt(supabase, {
        rideId,
        driverProfileId: driver.profileId,
        attemptNumber,
        offeredAt: new Date().toISOString(),
        timeoutAt: new Date(Date.now() + CONFIG.OFFER_TIMEOUT_SECONDS * 1000).toISOString(),
        status: 'pending',
      });

      // Atribuir motorista
      const assigned = await assignDriver(supabase, rideId, driver.profileId);

      if (!assigned) {
        console.log(`[AutoDispatch] Failed to assign driver ${driver.profileId}`);
        continue;
      }

      // Aguardar aceite ou timeout
      const accepted = await waitForAcceptance(
        supabase,
        rideId,
        driver.profileId,
        CONFIG.OFFER_TIMEOUT_SECONDS
      );

      if (accepted) {
        // Sucesso!
        await updateDispatchAttempt(supabase, rideId, driver.profileId, {
          status: 'accepted',
          respondedAt: new Date().toISOString(),
        });

        console.log(`[AutoDispatch] Driver ${driver.profileId} accepted`);

        return new Response(
          JSON.stringify({
            success: true,
            driverProfileId: driver.profileId,
            totalAttempts: attemptNumber,
            reason: 'accepted',
          }),
          { status: 200, headers: { 'Content-Type': 'application/json' } }
        );
      }

      // Timeout - tentar próximo
      await updateDispatchAttempt(supabase, rideId, driver.profileId, {
        status: 'timeout',
        respondedAt: new Date().toISOString(),
      });

      console.log(`[AutoDispatch] Driver ${driver.profileId} timeout, trying next`);

      // Voltar para searching_driver
      await supabase
        .from('ride_requests')
        .update({
          status: 'searching_driver',
          driver_profile_id: null,
          updated_at: new Date().toISOString(),
        })
        .eq('id', rideId);
    }

    // Nenhum motorista aceitou
    await expireRide(supabase, rideId, 'No driver accepted after all attempts');
    
    return new Response(
      JSON.stringify({
        success: false,
        totalAttempts: maxAttempts,
        reason: 'expired',
      }),
      { status: 200, headers: { 'Content-Type': 'application/json' } }
    );

  } catch (error) {
    console.error('[AutoDispatch] Error:', error);
    return errorResponse('Internal server error', 500, error);
  }
});

// ============================================
// HELPER FUNCTIONS
// ============================================

async function findEligibleDrivers(
  supabase: any,
  rideId: string,
  originLat: number,
  originLng: number,
  rideMode: string = 'ride'
): Promise<DriverEligibility[]> {
  // Buscar motoristas online e disponíveis
  // Se ride_mode = 'motoboy', filtrar apenas motoristas com can_do_delivery = true
  let query = supabase
    .from('driver_availability')
    .select(`
      profile_id,
      current_lat,
      current_lng,
      profiles!inner(rating),
      driver_data!inner(can_do_delivery)
    `)
    .eq('is_online', true)
    .eq('is_available', true);
  
  // Filtrar por tipo de corrida
  if (rideMode === 'motoboy') {
    query = query.eq('driver_data.can_do_delivery', true);
  }

  const { data: drivers, error } = await query;

  if (error || !drivers) {
    console.error('[AutoDispatch] Error finding drivers:', error);
    return [];
  }

  // Verificar motoristas com corrida ativa
  const profileIds = drivers.map((d: any) => d.profile_id);
  const { data: activeRides } = await supabase
    .from('ride_requests')
    .select('driver_profile_id')
    .in('driver_profile_id', profileIds)
    .in('status', ['driver_accepted', 'driver_arriving', 'passenger_boarded', 'in_progress']);

  const busyDrivers = new Set(activeRides?.map((r: any) => r.driver_profile_id) || []);

  // Calcular distância e filtrar
  const eligible: DriverEligibility[] = drivers
    .filter((d: any) => !busyDrivers.has(d.profile_id))
    .map((d: any) => {
      const distance = calculateDistance(
        originLat,
        originLng,
        d.current_lat || 0,
        d.current_lng || 0
      );

      return {
        profileId: d.profile_id,
        distance,
        rating: d.profiles?.rating || 0,
      };
    })
    .filter((d: DriverEligibility) => d.distance <= CONFIG.SEARCH_RADIUS_KM)
    .sort((a: DriverEligibility, b: DriverEligibility) => a.distance - b.distance);

  return eligible;
}

async function assignDriver(
  supabase: any,
  rideId: string,
  driverProfileId: string
): Promise<boolean> {
  const { error } = await supabase
    .from('ride_requests')
    .update({
      driver_profile_id: driverProfileId,
      status: 'driver_assigned',
      updated_at: new Date().toISOString(),
    })
    .eq('id', rideId)
    .eq('status', 'searching_driver');

  if (error) {
    console.error('[AutoDispatch] Error assigning driver:', error);
    return false;
  }

  // Registrar auditoria de estado
  await supabase.from('ride_state_audit').insert({
    ride_id: rideId,
    from_state: 'searching_driver',
    to_state: 'driver_assigned',
    changed_by: 'system',
    reason: 'Driver assigned by auto-dispatch',
    created_at: new Date().toISOString(),
  });

  return true;
}

async function waitForAcceptance(
  supabase: any,
  rideId: string,
  driverProfileId: string,
  timeoutSeconds: number
): Promise<boolean> {
  const startTime = Date.now();
  const timeoutMs = timeoutSeconds * 1000;

  while (Date.now() - startTime < timeoutMs) {
    const { data: ride } = await supabase
      .from('ride_requests')
      .select('status, driver_profile_id')
      .eq('id', rideId)
      .single();

    if (ride?.status === 'driver_accepted' && ride?.driver_profile_id === driverProfileId) {
      return true;
    }

    if (ride?.status !== 'driver_assigned') {
      return false;
    }

    // Aguardar 1 segundo antes de verificar novamente
    await new Promise(resolve => setTimeout(resolve, 1000));
  }

  return false;
}

async function expireRide(supabase: any, rideId: string, reason: string): Promise<void> {
  await supabase
    .from('ride_requests')
    .update({
      status: 'expired',
      updated_at: new Date().toISOString(),
    })
    .eq('id', rideId)
    .in('status', ['searching_driver', 'driver_assigned']);

  await supabase.from('ride_state_audit').insert({
    ride_id: rideId,
    from_state: 'searching_driver',
    to_state: 'expired',
    changed_by: 'system',
    reason,
    created_at: new Date().toISOString(),
  });

  console.log(`[AutoDispatch] Ride expired: ${reason}`);
}

async function logDispatchAttempt(supabase: any, attempt: any): Promise<void> {
  await supabase.from('ride_dispatch_audit').insert({
    ride_id: attempt.rideId,
    driver_profile_id: attempt.driverProfileId,
    attempt_number: attempt.attemptNumber,
    offered_at: attempt.offeredAt,
    timeout_at: attempt.timeoutAt,
    status: attempt.status,
    created_at: new Date().toISOString(),
  });
}

async function updateDispatchAttempt(
  supabase: any,
  rideId: string,
  driverProfileId: string,
  updates: any
): Promise<void> {
  const { data: attempts } = await supabase
    .from('ride_dispatch_audit')
    .select('id')
    .eq('ride_id', rideId)
    .eq('driver_profile_id', driverProfileId)
    .order('created_at', { ascending: false })
    .limit(1);

  if (attempts && attempts.length > 0) {
    await supabase
      .from('ride_dispatch_audit')
      .update(updates)
      .eq('id', attempts[0].id);
  }
}

function calculateDistance(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
): number {
  const R = 6371; // Raio da Terra em km
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(lat1)) *
      Math.cos(toRad(lat2)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

function toRad(degrees: number): number {
  return degrees * (Math.PI / 180);
}

// ══════════════════════════════════════════════════════════════════════════
// EDGE FUNCTION: billing-webhook (SSOT-Compliant)
// ══════════════════════════════════════════════════════════════════════════
//
// Processa webhooks do Stripe para sincronizar assinaturas e pagamentos.
// SSOT: Única fonte de verdade para ingestão de eventos Stripe.
//
// Eventos processados:
// - customer.subscription.created
// - customer.subscription.updated
// - customer.subscription.deleted
// - invoice.paid
// - invoice.payment_failed
//
// Auth: Validação de assinatura do Stripe
//
// FASE: 4 - Webhooks e Billing Runtime
// REFERÊNCIA: F4_WEBHOOKS_CONSOLIDATION.md
//
// REGRAS SSOT:
// - Idempotência obrigatória via event_id
// - Snapshot imutável de contrato na contratação
// - Status v2 alinhado com Stripe
// - Suporte a multi-vertical (user_id + business_id)
// - Logging estruturado para auditoria
//
// ══════════════════════════════════════════════════════════════════════════

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import Stripe from 'https://esm.sh/stripe@14.21.0'
import { getAllSecurityHeaders, errorResponse, auditLog, getAuditInfo } from '../_shared/security.ts'

serve(async (req: Request) => {
  // ════════════════════════════════════════════════════════════════════════
  // 1. CORS — Webhooks do Stripe não enviam Origin, mas preflight pode ocorrer
  // ════════════════════════════════════════════════════════════════════════
  if (req.method === 'OPTIONS') {
    return new Response('ok', { status: 204, headers: getAllSecurityHeaders('POST, OPTIONS') })
  }

  try {
    // ════════════════════════════════════════════════════════════════════════
    // 2. VALIDAR MÉTODO
    // ════════════════════════════════════════════════════════════════════════
    if (req.method !== 'POST') {
      return new Response(
        JSON.stringify({ error: 'Method not allowed' }),
        { status: 405, headers: getAllSecurityHeaders() }
      )
    }

    // ════════════════════════════════════════════════════════════════════════
    // 3. VALIDAR ASSINATURA DO STRIPE
    // ════════════════════════════════════════════════════════════════════════
    const signature = req.headers.get('stripe-signature')
    if (!signature) {
      return errorResponse('Missing stripe-signature header', 401)
    }

    const body = await req.text()
    const stripe = new Stripe(Deno.env.get('STRIPE_SECRET_KEY') ?? '', {
      apiVersion: '2023-10-16',
    })

    let event: Stripe.Event

    try {
      event = stripe.webhooks.constructEvent(
        body,
        signature,
        Deno.env.get('STRIPE_WEBHOOK_SECRET') ?? ''
      )
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      console.error('Webhook signature verification failed:', errorMessage)
      return errorResponse('Invalid signature', 401)
    }

    // ════════════════════════════════════════════════════════════════════════
    // 4. REGISTRAR WEBHOOK
    // ════════════════════════════════════════════════════════════════════════
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    )

    const { data: webhookId } = await supabaseAdmin.rpc('register_stripe_webhook_event', {
      p_stripe_event_id: event.id,
      p_event_type: event.type,
      p_event_data: event.data,
    })

    // Se webhook já foi processado (idempotência), retornar sucesso
    if (!webhookId) {
      return new Response(
        JSON.stringify({ received: true, message: 'Event already processed' }),
        { status: 200, headers: getAllSecurityHeaders() }
      )
    }

    // ════════════════════════════════════════════════════════════════════════
    // 5. PROCESSAR EVENTO
    // ════════════════════════════════════════════════════════════════════════
    try {
      switch (event.type) {
        case 'customer.subscription.created':
        case 'customer.subscription.updated':
          await handleSubscriptionChange(event, supabaseAdmin)
          break

        case 'customer.subscription.deleted':
          await handleSubscriptionDeleted(event, supabaseAdmin)
          break

        case 'invoice.paid':
          await handleInvoicePaid(event, supabaseAdmin)
          break

        case 'invoice.payment_failed':
          await handleInvoicePaymentFailed(event, supabaseAdmin)
          break

        default:
          console.log(`Unhandled event type: ${event.type}`)
      }

      // Marcar webhook como processado
      await supabaseAdmin.rpc('mark_webhook_processed', {
        p_event_id: webhookId,
        p_success: true,
        p_error_message: null,
      })

      return new Response(
        JSON.stringify({ received: true }),
        { status: 200, headers: getAllSecurityHeaders() }
      )
    } catch (error) {
      // Marcar webhook como erro
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      await supabaseAdmin.rpc('mark_webhook_processed', {
        p_event_id: webhookId,
        p_success: false,
        p_error_message: errorMessage,
      })

      throw error
    }
  } catch (error) {
    console.error('Error in billing-webhook:', error)
    return errorResponse('Internal server error', 500, error)
  }
})

// ══════════════════════════════════════════════════════════════════════════
// HANDLERS (SSOT-Compliant)
// ══════════════════════════════════════════════════════════════════════════

/**
 * Handle subscription created/updated
 * 
 * SSOT Rules:
 * - Create snapshot of catalog at contract time
 * - Use status_v2 aligned with Stripe
 * - Support business_id (scope = 'business')
 * - Fetch catalog item by plan_code
 */
async function handleSubscriptionChange(event: Stripe.Event, supabase: any) {
  const subscription = event.data.object as Stripe.Subscription
  const userId = subscription.metadata.supabase_user_id
  const businessId = subscription.metadata.business_id
  const planCode = subscription.metadata.plan_code
  const subscriptionScope = businessId ? 'business' : 'user'

  if (!userId || !planCode) {
    console.error('[billing-webhook] Missing metadata in subscription:', subscription.id)
    return
  }

  console.log(`[billing-webhook] Processing ${event.type} for user ${userId}, plan ${planCode}`)

  // Fetch catalog item by plan_code
  const { data: catalogItem, error: catalogError } = await supabase
    .from('catalog_item')
    .select(`
      id,
      item_code,
      item_name,
      item_type,
      plan_tier,
      entity_family,
      vertical,
      pricing_model,
      catalog_entitlement_policy (
        can_use_premium_public_page,
        can_use_short_premium_link,
        can_use_custom_qr_code,
        can_use_advanced_menu,
        can_receive_internal_orders,
        can_use_motoboy_network,
        can_use_promotions,
        can_use_basic_analytics,
        can_use_advanced_analytics,
        max_menu_items,
        max_promotions,
        max_images,
        max_categories
      ),
      catalog_pricing_policy (
        price_cents,
        currency,
        billing_period,
        stripe_price_id
      )
    `)
    .eq('item_code', planCode)
    .eq('status', 'published')
    .maybeSingle()

  if (catalogError || !catalogItem) {
    console.error('[billing-webhook] Catalog item not found:', planCode, catalogError)
    // Fallback: continue without snapshot (legacy compatibility)
  }

  // Create contract snapshot (immutable)
  const contractSnapshot = catalogItem ? {
    catalog_item: catalogItem,
    contracted_at: new Date().toISOString(),
    terms_version: '1.0.0',
    stripe_subscription_id: subscription.id,
    stripe_price_id: subscription.items.data[0]?.price.id,
  } : null

  // Map Stripe status to status_v2
  const statusV2 = mapStripeStatus(subscription.status)

  // Get price from subscription
  const priceId = subscription.items.data[0]?.price.id
  const priceCents = subscription.items.data[0]?.price.unit_amount || 0

  // Upsert subscription
  const { error } = await supabase
    .from('user_subscriptions')
    .upsert({
      user_id: userId,
      business_id: businessId || null,
      plan_code: planCode,
      subscription_scope: subscriptionScope,
      entity_family: catalogItem?.entity_family || null,
      vertical: catalogItem?.vertical || null,
      status_v2: statusV2,
      price_cents: priceCents,
      billing_period: subscription.items.data[0]?.price.recurring?.interval || 'month',
      current_period_start: new Date(subscription.current_period_start * 1000).toISOString(),
      current_period_end: new Date(subscription.current_period_end * 1000).toISOString(),
      cancel_at_period_end: subscription.cancel_at_period_end,
      canceled_at: subscription.canceled_at ? new Date(subscription.canceled_at * 1000).toISOString() : null,
      trial_ends_at: subscription.trial_end ? new Date(subscription.trial_end * 1000).toISOString() : null,
      stripe_subscription_id: subscription.id,
      stripe_customer_id: subscription.customer as string,
      stripe_price_id: priceId,
      catalog_item_id: catalogItem?.id || null,
      contract_snapshot: contractSnapshot || {},
      updated_at: new Date().toISOString(),
    }, {
      onConflict: subscriptionScope === 'business' ? 'business_id' : 'user_id',
    })

  if (error) {
    console.error('[billing-webhook] Error upserting subscription:', error)
    throw error
  }

  console.log(`[billing-webhook] Subscription ${subscription.id} processed successfully`)

  // Log transaction
  await supabase.rpc('log_billing_transaction', {
    p_user_id: userId,
    p_business_id: businessId || null,
    p_subscription_id: null,
    p_transaction_type: event.type === 'customer.subscription.created' ? 'subscription_created' : 'subscription_updated',
    p_amount_cents: priceCents,
    p_currency: 'BRL',
    p_stripe_invoice_id: null,
    p_stripe_payment_intent_id: null,
    p_status: 'succeeded',
    p_metadata: {
      subscription_id: subscription.id,
      plan_code: planCode,
      status_v2: statusV2,
      has_snapshot: !!contractSnapshot,
    },
  })
}

/**
 * Handle subscription deleted
 * 
 * SSOT Rules:
 * - Update status_v2 to 'canceled'
 * - Keep snapshot immutable (don't delete)
 * - Don't downgrade to free (keep history)
 */
async function handleSubscriptionDeleted(event: Stripe.Event, supabase: any) {
  const subscription = event.data.object as Stripe.Subscription
  const userId = subscription.metadata.supabase_user_id

  if (!userId) {
    console.error('[billing-webhook] Missing user_id in subscription:', subscription.id)
    return
  }

  console.log(`[billing-webhook] Processing subscription.deleted for user ${userId}`)

  // Update status to canceled (keep snapshot)
  const { error } = await supabase
    .from('user_subscriptions')
    .update({
      status_v2: 'canceled',
      canceled_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq('stripe_subscription_id', subscription.id)

  if (error) {
    console.error('[billing-webhook] Error updating subscription to canceled:', error)
    throw error
  }

  console.log(`[billing-webhook] Subscription ${subscription.id} canceled successfully`)

  // Log transaction
  await supabase.rpc('log_billing_transaction', {
    p_user_id: userId,
    p_business_id: subscription.metadata.business_id || null,
    p_subscription_id: null,
    p_transaction_type: 'subscription_canceled',
    p_amount_cents: null,
    p_currency: 'BRL',
    p_stripe_invoice_id: null,
    p_stripe_payment_intent_id: null,
    p_status: 'succeeded',
    p_metadata: {
      subscription_id: subscription.id,
    },
  })
}

/**
 * Handle invoice paid
 * 
 * SSOT Rules:
 * - Update status_v2 to 'active'
 * - Register transaction in ledger
 */
async function handleInvoicePaid(event: Stripe.Event, supabase: any) {
  const invoice = event.data.object as Stripe.Invoice
  const subscription = invoice.subscription as string
  const customerId = invoice.customer as string

  console.log(`[billing-webhook] Processing invoice.paid for customer ${customerId}`)

  // Buscar usuário pelo customer_id
  const { data: userSub } = await supabase
    .from('user_subscriptions')
    .select('user_id, business_id')
    .eq('stripe_customer_id', customerId)
    .single()

  if (!userSub) {
    console.error('[billing-webhook] User not found for customer:', customerId)
    return
  }

  // Update status to active
  await supabase
    .from('user_subscriptions')
    .update({
      status_v2: 'active',
      updated_at: new Date().toISOString(),
    })
    .eq('stripe_customer_id', customerId)

  console.log(`[billing-webhook] Invoice ${invoice.id} paid, subscription activated`)

  // Log transaction
  await supabase.rpc('log_billing_transaction', {
    p_user_id: userSub.user_id,
    p_business_id: userSub.business_id || null,
    p_subscription_id: null,
    p_transaction_type: 'payment_succeeded',
    p_amount_cents: invoice.amount_paid,
    p_currency: invoice.currency.toUpperCase(),
    p_stripe_invoice_id: invoice.id,
    p_stripe_payment_intent_id: invoice.payment_intent as string,
    p_status: 'succeeded',
    p_metadata: {
      subscription_id: subscription,
      invoice_number: invoice.number,
    },
  })
}

/**
 * Handle invoice payment failed
 * 
 * SSOT Rules:
 * - Update status_v2 to 'past_due'
 * - Register failed attempt in ledger
 */
async function handleInvoicePaymentFailed(event: Stripe.Event, supabase: any) {
  const invoice = event.data.object as Stripe.Invoice
  const subscription = invoice.subscription as string
  const customerId = invoice.customer as string

  console.log(`[billing-webhook] Processing invoice.payment_failed for customer ${customerId}`)

  // Buscar usuário pelo customer_id
  const { data: userSub } = await supabase
    .from('user_subscriptions')
    .select('user_id, business_id')
    .eq('stripe_customer_id', customerId)
    .single()

  if (!userSub) {
    console.error('[billing-webhook] User not found for customer:', customerId)
    return
  }

  // Atualizar status para past_due
  await supabase
    .from('user_subscriptions')
    .update({
      status_v2: 'past_due',
      updated_at: new Date().toISOString(),
    })
    .eq('stripe_customer_id', customerId)

  console.log(`[billing-webhook] Invoice ${invoice.id} payment failed, subscription marked as past_due`)

  // Log transaction
  await supabase.rpc('log_billing_transaction', {
    p_user_id: userSub.user_id,
    p_business_id: userSub.business_id || null,
    p_subscription_id: null,
    p_transaction_type: 'payment_failed',
    p_amount_cents: invoice.amount_due,
    p_currency: invoice.currency.toUpperCase(),
    p_stripe_invoice_id: invoice.id,
    p_stripe_payment_intent_id: invoice.payment_intent as string,
    p_status: 'failed',
    p_metadata: {
      subscription_id: subscription,
      invoice_number: invoice.number,
      attempt_count: invoice.attempt_count,
    },
  })
}

/**
 * Map Stripe status to status_v2
 */
function mapStripeStatus(stripeStatus: string): string {
  const statusMap: Record<string, string> = {
    'active': 'active',
    'trialing': 'trialing',
    'past_due': 'past_due',
    'incomplete': 'incomplete',
    'incomplete_expired': 'incomplete_expired',
    'unpaid': 'unpaid',
    'canceled': 'canceled',
  }
  
  return statusMap[stripeStatus] || 'canceled'
}

/**
 * Send Email Edge Function
 * 
 * Sends emails using Resend API.
 * Respects user preferences and quiet hours.
 * 
 * Rate Limit: 50 requests per minute per user
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { validateBody, sendEmailSchema, validationErrorResponse, type SendEmailBody } from '../_shared/validation.ts';
import { getAllSecurityHeaders, rateLimitMiddleware, errorResponse } from '../_shared/security.ts';

const RESEND_API_KEY = Deno.env.get('RESEND_API_KEY');
const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const FROM_EMAIL = Deno.env.get('FROM_EMAIL') || 'noreply@yourdomain.com';

serve(async (req: Request) => {
  // Handle CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { status: 204, headers: getAllSecurityHeaders('POST, OPTIONS') });
  }

  // Rate limiting
  const rateLimitResponse = await rateLimitMiddleware(req, 50, 60000);
  if (rateLimitResponse) return rateLimitResponse;

  // 1. Validate HTTP method
  if (req.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: getAllSecurityHeaders(),
    });
  }

  try {
    // 2. Validate authentication
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return errorResponse('Missing authorization header', 401);
    }

    // Create Supabase client
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // Get user from token
    const token = authHeader.replace('Bearer ', '');
    const { data: { user }, error: authError } = await supabase.auth.getUser(token);

    if (authError || !user) {
      return errorResponse('Invalid token', 401);
    }

    // 3. Parse and validate input
    const rawBody = await req.json();
    const validation = validateBody<SendEmailBody>(rawBody, sendEmailSchema);
    if (!validation.ok) {
      return validationErrorResponse(validation.errors);
    }
    const { to, subject, html, text, userId, category = 'transactional' } = validation.data!;

    // 4. Check user preferences (if userId provided)
    if (userId) {
      const { data: preferences } = await supabase
        .from('notification_preferences')
        .select('*')
        .eq('user_id', userId)
        .single();

      if (preferences) {
        // Check if email is enabled
        if (!preferences.email_enabled) {
          return errorResponse('Email notifications disabled by user', 403);
        }

        // Check category preferences
        const categoryKey = `${category}_enabled`;
        if (preferences[categoryKey] === false && category !== 'transactional') {
          return errorResponse(`${category} emails disabled by user`, 403);
        }

        // Check quiet hours
        if (preferences.quiet_hours_start && preferences.quiet_hours_end) {
          const now = new Date();
          const currentHour = now.getHours();
          const currentMinute = now.getMinutes();
          const currentTime = currentHour * 60 + currentMinute;

          const [startHour, startMinute] = preferences.quiet_hours_start.split(':').map(Number);
          const [endHour, endMinute] = preferences.quiet_hours_end.split(':').map(Number);
          const startTime = startHour * 60 + startMinute;
          const endTime = endHour * 60 + endMinute;

          const currentDay = now.getDay() || 7;
          const isQuietDay = preferences.quiet_hours_days?.includes(currentDay);

          if (isQuietDay && currentTime >= startTime && currentTime <= endTime) {
            if (category !== 'transactional') {
              return errorResponse('User is in quiet hours', 403);
            }
          }
        }
      }
    }

    // 5. Send email via Resend
    let emailStatus: 'sent' | 'failed' = 'sent';
    let errorMessage: string | null = null;
    let emailId: string | null = null;

    if (RESEND_API_KEY) {
      try {
        const resendResponse = await fetch('https://api.resend.com/emails', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${RESEND_API_KEY}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            from: FROM_EMAIL,
            to: [to],
            subject,
            html,
            text: text || undefined,
          }),
        });

        const resendData = await resendResponse.json();

        if (!resendResponse.ok) {
          emailStatus = 'failed';
          errorMessage = resendData.message || 'Failed to send email';
          console.error('Resend API error:', resendData);
        } else {
          emailId = resendData.id;
        }
      } catch (error) {
        emailStatus = 'failed';
        errorMessage = String(error);
        console.error('Error sending email via Resend:', error);
      }
    } else {
      // Development mode: log email instead of sending
      console.log('📧 Email (dev mode):', { to, subject, html: html.substring(0, 100) });
      emailStatus = 'sent';
    }

    // 6. Log email
    const { error: logError } = await supabase.from('email_logs').insert({
      user_id: userId || null,
      recipient_email: to,
      subject,
      category,
      status: emailStatus,
      error_message: errorMessage,
      metadata: {
        email_id: emailId,
        has_text: !!text,
        html_length: html.length,
      },
    });

    if (logError) {
      console.error('Error logging email:', logError);
    }

    // 7. Return response
    if (emailStatus === 'failed') {
      return errorResponse('Failed to send email', 500);
    }

    return new Response(
      JSON.stringify({
        success: true,
        message: 'Email sent successfully',
        emailId,
      }),
      {
        status: 200,
        headers: getAllSecurityHeaders(),
      }
    );
  } catch (error) {
    console.error('Exception in send-email function:', error);
    return errorResponse('Internal server error', 500, error);
  }
});

// Supabase Edge Function - Send Emergency Email
// Deploy: supabase functions deploy send-emergency-email

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { jsonSecurityResponse, requireAuthenticatedUser } from '../_shared/businessAuth.ts';
import {
  checkRateLimit,
  getAllSecurityHeaders,
  rateLimitMiddleware,
  auditLog,
  getAuditInfo,
  errorResponse,
  isValidUUID,
  isOriginAllowed,
  sanitizeString,
} from '../_shared/security.ts';

const RESEND_API_KEY = Deno.env.get('RESEND_API_KEY');
const EMAIL_FROM_DOMAIN = Deno.env.get('EMAIL_FROM_DOMAIN') || 'onboarding@resend.dev';
const EMAIL_FROM_NAME = Deno.env.get('EMAIL_FROM_NAME') || 'Alerta de Emergencia';
const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

const RATE_LIMIT_MAX = 5;
const RATE_LIMIT_WINDOW_MINUTES = 5;

const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
  auth: { persistSession: false },
});

interface EmailRequest {
  contactId: string;
  alertId: string;
  alertType?: string;
  alertCreatedAt?: string;
  alertDescription?: string;
  alertLocation?: {
    latitude: number;
    longitude: number;
  };
}

interface EmailResponse {
  success: boolean;
  contactId: string;
  channel: 'email';
  timestamp: string;
  status: 'sent' | 'failed';
  error?: string;
  metadata?: Record<string, unknown>;
}

interface UserProfileRecord {
  id: string;
  name: string | null;
  phone: string | null;
}

interface AlertRecord {
  id: string;
  profile_id: string | null;
  created_at: string | null;
}

interface ContactRecord {
  id: string;
  profile_id: string | null;
  name: string | null;
  phone: string | null;
  is_active?: boolean | null;
}

serve(async (req: Request) => {
  const auditInfo = getAuditInfo(req);
  const origin = req.headers.get('origin');

  if (origin && !isOriginAllowed(origin)) {
    return jsonSecurityResponse({ error: 'Origin not allowed' }, 403);
  }

  if (req.method === 'OPTIONS') {
    return new Response('ok', {
      status: 204,
      headers: getAllSecurityHeaders('POST, OPTIONS'),
    });
  }

  if (req.method !== 'POST') {
    return jsonSecurityResponse({ error: 'Method not allowed' }, 405);
  }

  const rateLimitResponse = await rateLimitMiddleware(req, 100, 60000);
  if (rateLimitResponse) return rateLimitResponse;

  if (!RESEND_API_KEY) {
    return errorResponse('Email service not configured', 500, {
      code: 'MISSING_RESEND_API_KEY',
    });
  }

  const authResult = await requireAuthenticatedUser(req, supabase);
  if (authResult instanceof Response) {
    auditLog({
      timestamp: new Date().toISOString(),
      action: 'emergency_email_auth_failed',
      resource: 'emergency_alerts',
      status: 'failure',
      details: { reason: 'invalid_or_missing_token' },
      ...auditInfo,
    });
    return authResult;
  }

  const userId = authResult.user.id;
  const userRateLimit = await checkRateLimit(`emergency-email:${userId}`, 30, 5 * 60 * 1000);
  if (!userRateLimit.allowed) {
    return jsonSecurityResponse(
      { error: 'Rate limit exceeded. Try again later.' },
      429,
    );
  }

  try {
    let emailRequest: EmailRequest;
    try {
      emailRequest = await req.json();
    } catch {
      return jsonSecurityResponse({ error: 'Invalid JSON body' }, 400);
    }

    if (!emailRequest.alertId || !isValidUUID(emailRequest.alertId)) {
      return jsonSecurityResponse({ error: 'Valid alertId is required' }, 400);
    }
    if (!emailRequest.contactId || !isValidUUID(emailRequest.contactId)) {
      return jsonSecurityResponse({ error: 'Valid contactId is required' }, 400);
    }

    const { data: userProfiles, error: profileError } = await supabase
      .from('profiles')
      .select('id, name, phone')
      .eq('user_id', userId);

    if (profileError) {
      return errorResponse('Failed to validate user profile', 500, profileError);
    }
    if (!userProfiles || userProfiles.length === 0) {
      return jsonSecurityResponse({ error: 'User profile not found' }, 403);
    }

    const userProfileIds = new Set(userProfiles.map((profile: UserProfileRecord) => profile.id));

    const { data: alertData, error: alertError } = await supabase
      .from('emergency_alerts')
      .select('id, profile_id, created_at')
      .eq('id', emailRequest.alertId)
      .maybeSingle();

    if (alertError) {
      return errorResponse('Failed to validate alert', 500, alertError);
    }
    if (!alertData) {
      return jsonSecurityResponse({ error: 'Alert not found' }, 404);
    }

    const alert = alertData as AlertRecord;
    if (!alert.profile_id || !userProfileIds.has(alert.profile_id)) {
      auditLog({
        timestamp: new Date().toISOString(),
        userId,
        action: 'emergency_email_forbidden',
        resource: 'emergency_alerts',
        status: 'failure',
        details: { reason: 'alert_not_owned_by_user', alertId: emailRequest.alertId },
        ...auditInfo,
      });
      return jsonSecurityResponse({ error: 'Forbidden' }, 403);
    }

    const { data: contactData, error: contactError } = await supabase
      .from('emergency_contacts')
      .select('id, profile_id, name, phone, is_active')
      .eq('id', emailRequest.contactId)
      .maybeSingle();

    if (contactError) {
      return errorResponse('Failed to validate emergency contact', 500, contactError);
    }
    if (!contactData) {
      return jsonSecurityResponse({ error: 'Emergency contact not found' }, 404);
    }

    const contact = contactData as ContactRecord;
    if (contact.profile_id !== alert.profile_id) {
      auditLog({
        timestamp: new Date().toISOString(),
        userId,
        action: 'emergency_email_forbidden',
        resource: 'emergency_contacts',
        status: 'failure',
        details: {
          reason: 'contact_not_linked_to_alert_profile',
          alertId: emailRequest.alertId,
          contactId: emailRequest.contactId,
        },
        ...auditInfo,
      });
      return jsonSecurityResponse({ error: 'Forbidden' }, 403);
    }
    if (contact.is_active === false) {
      return jsonSecurityResponse({ error: 'Emergency contact is inactive' }, 403);
    }

    const contactEmail = extractEmail(contact.phone || '');
    if (!contactEmail) {
      return jsonSecurityResponse(
        { error: 'Emergency contact email is not configured' },
        400,
      );
    }

    const windowStart = new Date(
      Date.now() - RATE_LIMIT_WINDOW_MINUTES * 60 * 1000,
    ).toISOString();

    const { count: recentCount, error: logsError } = await supabase
      .from('emergency_delivery_log')
      .select('id', { count: 'exact', head: true })
      .eq('alert_id', emailRequest.alertId)
      .eq('contact_id', emailRequest.contactId)
      .eq('channel', 'email')
      .gte('created_at', windowStart);

    if (logsError) {
      return errorResponse('Failed to validate rate limit', 500, logsError);
    }

    if ((recentCount || 0) >= RATE_LIMIT_MAX) {
      await supabase.from('emergency_delivery_log').insert({
        alert_id: emailRequest.alertId,
        contact_id: emailRequest.contactId,
        channel: 'email',
        status: 'failed',
        target: contactEmail,
        error_message: `Rate limit exceeded: ${RATE_LIMIT_MAX} emails per ${RATE_LIMIT_WINDOW_MINUTES} minutes`,
        metadata: {
          rate_limit_blocked: true,
          recent_count: recentCount || 0,
          window_minutes: RATE_LIMIT_WINDOW_MINUTES,
        },
        created_at: new Date().toISOString(),
      });

      auditLog({
        timestamp: new Date().toISOString(),
        userId,
        action: 'emergency_email_rate_limited',
        resource: 'emergency_alerts',
        status: 'failure',
        details: { alertId: emailRequest.alertId, contactId: emailRequest.contactId },
        ...auditInfo,
      });

      return jsonSecurityResponse(
        { error: `Rate limit exceeded. Max ${RATE_LIMIT_MAX} attempts per ${RATE_LIMIT_WINDOW_MINUTES} minutes.` },
        429,
      );
    }

    const ownerProfile = userProfiles.find(
      (profile: UserProfileRecord) => profile.id === alert.profile_id,
    );

    const sanitizedContactName = sanitizeString(contact.name || 'Contato', 100);
    const sanitizedUserName = sanitizeString(ownerProfile?.name || 'Usuario', 100);
    const sanitizedUserPhone = sanitizeString(ownerProfile?.phone || 'Nao informado', 50);
    const sanitizedDescription =
      typeof emailRequest.alertDescription === 'string' && emailRequest.alertDescription.trim().length > 0
        ? sanitizeString(emailRequest.alertDescription, 500)
        : undefined;

    const alertType = translateAlertType(
      sanitizeString(emailRequest.alertType || 'sos', 50).toLowerCase(),
    );

    const alertCreatedAt =
      normalizeIsoDatetime(emailRequest.alertCreatedAt) ||
      normalizeIsoDatetime(alert.created_at) ||
      new Date().toISOString();

    const location = normalizeLocation(emailRequest.alertLocation);

    const subject = 'ALERTA DE EMERGENCIA';
    const htmlBody = buildEmailHtml(
      sanitizedContactName,
      sanitizedUserName,
      sanitizedUserPhone,
      alertType,
      alertCreatedAt,
      location,
      sanitizedDescription,
    );

    const textBody = buildEmailText(
      sanitizedContactName,
      sanitizedUserName,
      sanitizedUserPhone,
      alertType,
      alertCreatedAt,
      location,
      sanitizedDescription,
    );

    const resendResponse = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${RESEND_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        from: `${EMAIL_FROM_NAME} <${EMAIL_FROM_DOMAIN}>`,
        to: [contactEmail],
        subject,
        html: htmlBody,
        text: textBody,
      }),
    });

    const resendRaw = await resendResponse.text();
    if (!resendResponse.ok) {
      console.error('Resend API error', {
        status: resendResponse.status,
        body: resendRaw.slice(0, 1000),
      });
      return errorResponse('Failed to send emergency email', 502, {
        status: resendResponse.status,
      });
    }

    let resendResult: Record<string, unknown> = {};
    try {
      resendResult = resendRaw ? JSON.parse(resendRaw) : {};
    } catch {
      resendResult = {};
    }

    await supabase.from('emergency_delivery_log').insert({
      alert_id: emailRequest.alertId,
      contact_id: emailRequest.contactId,
      channel: 'email',
      status: 'sent',
      target: contactEmail,
      metadata: {
        emailId: resendResult.id,
        subject,
        alertType,
      },
      created_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
    });

    auditLog({
      timestamp: new Date().toISOString(),
      userId,
      action: 'emergency_email_sent',
      resource: 'emergency_alerts',
      status: 'success',
      details: {
        alertId: emailRequest.alertId,
        contactId: emailRequest.contactId,
        emailId: resendResult.id,
      },
      ...auditInfo,
    });

    const response: EmailResponse = {
      success: true,
      contactId: emailRequest.contactId,
      channel: 'email',
      timestamp: new Date().toISOString(),
      status: 'sent',
      metadata: {
        to: contactEmail,
        subject,
        alertId: emailRequest.alertId,
        alertType,
        emailId: resendResult.id,
      },
    };

    return new Response(JSON.stringify(response), {
      headers: getAllSecurityHeaders('POST, OPTIONS'),
    });
  } catch (error) {
    auditLog({
      timestamp: new Date().toISOString(),
      userId,
      action: 'emergency_email_failed',
      resource: 'emergency_alerts',
      status: 'failure',
      details: { error: error instanceof Error ? error.message : 'Unknown error' },
      ...auditInfo,
    });

    return errorResponse('Failed to send emergency email', 500, error);
  }
});

function normalizeIsoDatetime(value: string | null | undefined): string | null {
  if (!value) return null;
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return null;
  return parsed.toISOString();
}

function normalizeLocation(
  location: { latitude: number; longitude: number } | undefined,
): string {
  if (!location) return 'Nao disponivel';
  const latitude = Number(location.latitude);
  const longitude = Number(location.longitude);

  if (Number.isNaN(latitude) || Number.isNaN(longitude)) {
    return 'Nao disponivel';
  }

  if (latitude < -90 || latitude > 90 || longitude < -180 || longitude > 180) {
    return 'Nao disponivel';
  }

  return `${latitude}, ${longitude}`;
}

function extractEmail(value: string): string | null {
  const candidate = value.trim().toLowerCase();
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!candidate || !emailRegex.test(candidate)) {
    return null;
  }
  return candidate;
}

function escapeHtml(input: string): string {
  return input
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function translateAlertType(type: string): string {
  const translations: Record<string, string> = {
    sos: 'SOS',
    emergency_button: 'Botao de Emergencia',
    automatic: 'Alerta Automatico',
    manual: 'Alerta Manual',
    panic: 'Panico',
  };
  return translations[type] || type;
}

